//! Newer SQL checked against Postgres itself: each script runs statement by statement on Chronos
//! and on a real Postgres, and every statement must give the same rows (or fail on both, with
//! the same SQLSTATE class). Needs a Postgres at host=/tmp; skipped when there's none, unless `CHRONOS_REQUIRE_ORACLE` is set (then it fails).
//!
//! Cells compare as text, except that numbers compare as numbers (1 and 1.0, Postgres's numeric
//! output) and t/f as true/false.

use chronos::Db;
use chronos::sql::{Session, Type, Value};
use postgres::{Client, NoTls, SimpleQueryMessage};

/// The reference Postgres: its socket in /tmp, on the port PGPORT names (as psql takes it), else 5432.
fn oracle(dbname: &str) -> String {
    let port = std::env::var("PGPORT").unwrap_or_else(|_| "5432".into());
    format!("host=/tmp port={port} dbname={dbname}")
}

type Rows = Result<Vec<Vec<Option<String>>>, String>;

fn chronos(db: &Db, s: &mut Session, q: &str) -> Rows {
    let o = s.run(db, q, &[]).map_err(|e| e.code.to_string())?.pop().unwrap();
    let types: Vec<Type> = o.columns.iter().flatten().map(|(_, t)| *t).collect();
    Ok(o.rows
        .iter()
        .map(|r| r.iter().enumerate().map(|(i, v)| (*v != Value::Null).then(|| text(v, types.get(i)))).collect())
        .collect())
}

/// A cell as a client reads it in text: a real and an xml value as their output functions write them, as the
/// server sends them (src/pg.rs), not as the double and the text they are held as.
fn text(v: &Value, ty: Option<&Type>) -> String {
    match (v, ty) {
        (Value::Float(f), Some(Type::Float4)) => chronos::sql::fmt_float4(*f),
        (Value::Text(t), Some(Type::Xml)) => chronos::sql::xml_out(t),
        _ => v.to_text(),
    }
}

fn postgres(c: &mut Client, q: &str) -> Rows {
    let msgs = c.simple_query(q).map_err(|e| e.code().map_or("?".into(), |c| c.code().to_string()))?;
    Ok(msgs
        .iter()
        .filter_map(|m| match m {
            SimpleQueryMessage::Row(r) => Some((0..r.len()).map(|i| r.get(i).map(String::from)).collect()),
            _ => None,
        })
        .collect())
}

fn same_cell(a: &Option<String>, b: &Option<String>, exact: bool) -> bool {
    match (a, b) {
        (Some(a), Some(b)) if exact => {
            a == b || (a.as_str(), b.as_str()) == ("true", "t") || (a.as_str(), b.as_str()) == ("false", "f")
        }
        (Some(a), Some(b)) => {
            let bool_of = |s: &str| match s {
                "t" | "true" => Some(true),
                "f" | "false" => Some(false),
                _ => None,
            };
            a == b
                || matches!((a.parse::<f64>(), b.parse::<f64>()), (Ok(x), Ok(y)) if (x - y).abs() <= 1e-9 * x.abs().max(1.0))
                || bool_of(a).is_some_and(|x| bool_of(b) == Some(x))
        }
        (None, None) => true,
        _ => false,
    }
}

fn same(a: &Rows, b: &Rows, exact: bool) -> bool {
    match (a, b) {
        (Ok(a), Ok(b)) => {
            a.len() == b.len()
                && a.iter()
                    .zip(b)
                    .all(|(x, y)| x.len() == y.len() && x.iter().zip(y).all(|(p, q)| same_cell(p, q, exact)))
        }
        (Err(a), Err(b)) => a[..2] == b[..2], // the same class of error
        _ => false,
    }
}

/// Runs each script on a fresh Chronos database and a fresh Postgres schema, comparing statement by statement.
fn check(scripts: &[&[&str]]) {
    compare(scripts, false)
}

/// `check`, with every cell's text exactly as Postgres prints it (for exact numbers).
fn check_text(scripts: &[&[&str]]) {
    compare(scripts, true)
}

/// `check`, against a database with PostGIS installed (`create database chronos_gis;` then
/// `create extension postgis` in it).
fn check_gis(scripts: &[&[&str]]) {
    compare_in("chronos_gis", scripts, false)
}

fn compare(scripts: &[&[&str]], exact: bool) {
    compare_in("postgres", scripts, exact)
}

fn compare_in(dbname: &str, scripts: &[&[&str]], exact: bool) {
    static ONE: std::sync::Mutex<()> = std::sync::Mutex::new(()); // one Postgres schema for all
    let _one = ONE.lock().unwrap_or_else(|e| e.into_inner());
    let Ok(mut pg) = Client::connect(&oracle(dbname), NoTls) else {
        // a dead oracle must not read as a pass: CHRONOS_REQUIRE_ORACLE=1 makes it a failure
        // (the PostGIS database stays optional)
        assert!(
            dbname != "postgres" || std::env::var_os("CHRONOS_REQUIRE_ORACLE").is_none(),
            "CHRONOS_REQUIRE_ORACLE is set but there is no Postgres database {dbname} at host=/tmp"
        );
        eprintln!("skipped: no Postgres database {dbname} at host=/tmp");
        return;
    };
    // a schema of this process's own: test runs sharing one Postgres (CI jobs at once) don't collide
    let schema = format!("pgdiff_{}", std::process::id());
    let mut failures = vec![];
    for (n, script) in scripts.iter().enumerate() {
        pg.batch_execute(&format!("drop schema if exists {schema} cascade; create schema {schema}; set search_path = {schema}, public; set timezone = 'UTC'")).unwrap();
        let db = Db::new();
        let mut s = Session::new(chronos::MAIN);
        for q in *script {
            let (a, b) = (chronos(&db, &mut s, q), postgres(&mut pg, q));
            if !same(&a, &b, exact) {
                failures.push(format!("script {n}: {q}\n  chronos:    {a:?}\n  postgres: {b:?}"));
            }
        }
    }
    let _ = pg.batch_execute(&format!("drop schema if exists {schema} cascade"));
    assert!(failures.is_empty(), "{} differences:\n{}", failures.len(), failures.join("\n"));
}

#[test]
fn upserts_on_several_columns() {
    check(&[&[
        "create table seat (id int primary key, room text, num int, who text, unique (room, num))",
        "insert into seat values (1, 'a', 1, 'Ada'), (2, 'a', 2, 'Bo')",
        "insert into seat values (3, 'a', 1, 'Cy') on conflict (num, room) do update set who = excluded.who",
        "insert into seat values (4, 'a', 2, 'Di') on conflict on constraint seat_room_num_key do update set who = seat.who || '+'",
        "insert into seat values (5, 'b', 1, 'Ed') on conflict (room, num) do nothing",
        "insert into seat values (6, 'a', 1, 'Fay') on conflict (room) do nothing",
        "insert into seat values (1, 'z', 9, 'Gus') on conflict on constraint seat_pkey do update set who = excluded.who",
        "select * from seat order by id",
    ]]);
}

/// `ON CONFLICT (cols) WHERE pred`: the partial unique index whose WHERE the predicate implies is the arbiter
/// (issue #11); one it doesn't imply is 42P10.
#[test]
fn upserts_on_a_partial_unique_index() {
    check(&[
        &[
            "create table t (id int primary key, n text, v int, st text)",
            "create unique index t_live on t (n) where st = 'a'",
            "create unique index t_two on t (v, n) where st = 'b' and v > 0",
            "insert into t values (1, 'x', 1, 'a'), (2, 'x', 2, 'z'), (3, 'y', 3, 'b')",
            "insert into t (id, n, v, st) values (9, 'x', 9, 'a') on conflict (n) where st = 'a' do nothing",
            "insert into t (id, n, v, st) values (9, 'x', 9, 'a') on conflict (n) where st = 'a' do update set v = excluded.v",
            "insert into t (id, n, v, st) values (10, 'x', 10, 'a') on conflict (n) where st = 'a' and v > 5 do update set v = t.v + 100",
            "insert into t (id, n, v, st) values (11, 'y', 3, 'b') on conflict (n, v) where v > 0 and st = 'b' do update set st = 'b2'",
            "insert into t (id, n, v, st) values (12, 'w', 1, 'a') on conflict (n) where st = 'a' do nothing returning id",
            "insert into t (id, n, v, st) values (13, 'x', 13, 'a') on conflict (n) where st = 'b' do nothing",
            "insert into t (id, n, v, st) values (14, 'y', 3, 'b') on conflict (n, v) where st = 'b' do nothing",
            "select * from t order by id",
            // a WHERE on a column the table hasn't, or not a boolean
            "insert into t (id, n, v, st) values (15, 'x', 1, 'a') on conflict (n) where missing = 1 do nothing",
            "insert into t (id, n, v, st) values (15, 'x', 1, 'a') on conflict (n) where v do nothing",
        ],
        &[
            // every index the WHERE implies is an arbiter, not just the first
            "create table f (id int primary key, n text, a bool, b bool)",
            "create unique index f_a on f (n) where a",
            "create unique index f_b on f (n) where b",
            "insert into f values (1, 'x', false, true)",
            "insert into f values (2, 'x', true, true) on conflict (n) where a and b do nothing",
            "insert into f values (3, 'x', true, true) on conflict (n) where b and a do update set n = f.n || '+'",
            "select * from f order by id",
        ],
    ]);
}

#[test]
fn any_some_all() {
    check(&[&[
        "create table n (id int primary key, v int)",
        "insert into n values (1, 10), (2, 20), (3, 30), (4, null)",
        "select id from n where v = any (select v from n where id <= 2) order by id",
        "select id from n where v > all (select v from n where id <= 2) order by id",
        "select id from n where v >= some (select v from n where id between 2 and 3) order by id",
        "select id from n where v <> all (select v from n where id = 1) order by id",
        "select id from n where v > all (select v from n) order by id",
        "select id from n where v < all (select v from n where id > 100) order by id",
        "select id from n where v = any (array[10, 30]) order by id",
        "select id from n where v < all (array[25, 40]) order by id",
        "select id from n where v = any ('{20,30}') order by id",
        "select id, v > any (select v from n where id > 2) from n order by id",
        "select 2 = any ('{1, NULL}'), 1 = any ('{1, NULL}'), 2 < all ('{}')",
    ]]);
}

#[test]
fn time_of_day() {
    check(&[&[
        "create table shift (id int primary key, starts time, ends time without time zone)",
        "insert into shift values (1, '09:00', '17:30'), (2, '22:00:00', '06:15:30.25'), (3, null, '00:00')",
        "select * from shift order by id",
        "select id from shift where starts > time '12:00' order by id",
        "select id from shift order by ends",
        "select ends - starts from shift where id = 1",
        "select starts + interval '3 hours', starts - interval '23 hours' from shift where id = 2",
        "select date '2026-09-24' + starts from shift where id = 1",
        "select extract(hour from ends), extract(minute from ends) from shift where id = 2",
        "select timestamp '2026-01-02 03:04:05'::time, '10:00'::time::interval",
        "insert into shift values (4, '25:00', null)",
        "select '24:00'::time",
        "select max(ends), min(starts) from shift",
    ]]);
}

#[test]
fn outer_joins_and_using() {
    check(&[&[
        "create table a (id int primary key, x int, name text)",
        "create table b (id int primary key, x int, note text)",
        "create table c (id int primary key, y int)",
        "insert into a values (1, 10, 'a1'), (2, 20, 'a2'), (3, null, 'a3')",
        "insert into b values (1, 10, 'b1'), (4, 40, 'b4'), (5, null, 'b5')",
        "insert into c values (1, 100), (6, 600)",
        "select a.id, b.id from a right join b on a.x = b.x order by b.id",
        "select a.id, b.id from a full join b on a.x = b.x order by a.id nulls last, b.id",
        "select a.id, b.id from a full outer join b on a.x = b.x and b.note <> 'b1' order by a.id, b.id",
        "select a.id, b.id from a right join b on a.x < b.x order by b.id, a.id",
        "select a.id, b.id from a full join b on a.x = b.x where a.id is null or b.id is null order by a.id, b.id",
        "select * from a join b using (id) order by id",
        "select * from a left join b using (id) order by id",
        "select * from a right join b using (id) order by id",
        "select * from a full join b using (id) order by id",
        "select id, a.x, b.x from a full join b using (id) order by id",
        "select * from a join b using (id, x)",
        "select * from a join b using (id) join c using (id)",
        "select count(*), sum(b.x) from a full join b using (id)",
        "select a.name, c.y from a full join c on a.id = c.id right join b on b.id = a.id order by b.id",
        "select * from a join b using (nope)",
        "select b.id, count(a.id) from a right join b on a.x = b.x group by b.id order by b.id",
        "select id, x from a order by x",
        "create index a_x on a (x)", // the index-order path must leave NULLS FIRST to the sort
        "select id, x from a order by x nulls first",
        "select id, x from a order by x desc",
        "select id, x from a order by x desc nulls last",
        "select id, row_number() over (order by x nulls first) from a order by id",
        "select id, x from a order by x asc nulls first limit 2",
        "select id, x from a order by x desc nulls last limit 2",
        "select id, x from a order by x limit 2",
    ]]);
}

#[test]
fn named_windows() {
    check(&[&[
        "create table s (id int primary key, team text, pts int)",
        "insert into s values (1, 'a', 10), (2, 'a', 30), (3, 'b', 20), (4, 'b', 20), (5, 'b', 5)",
        "select id, rank() over w, sum(pts) over w from s window w as (partition by team order by pts desc) order by id",
        "select id, row_number() over (w order by id) from s window w as (partition by team) order by id",
        "select id, avg(pts) over w, count(*) over w2 from s window w as (partition by team), w2 as (order by id rows between 1 preceding and current row) order by id",
        "select id, lag(pts) over w from s window w as (order by id) order by id desc",
        "select id, rank() over nope from s",
    ]]);
}

#[test]
fn text_math_and_null_functions() {
    check(&[&[
        "select concat('a', null, 1, true), concat_ws('-', 'a', null, 'b'), concat_ws(null, 'a')",
        "select substring('hello world', 7), substring('hello', 2, 3), substr('hello', 0, 3), substring('hello' from 2 for 2), substring('hello' from 3)",
        "select substring('hello', -2, 5), substring('hello', 10), substr('héllo', 2, 2)",
        "select substring('hello', 1, -1)",
        "select position('lo' in 'hello'), strpos('hello', 'z'), position('' in 'abc'), strpos('héllo', 'l')",
        "select replace('a-b-c', '-', '+'), replace('abc', '', 'x'), reverse('abc'), repeat('ab', 3), repeat('x', -1)",
        "select trim('  hi  '), trim(leading 'x' from 'xxhixx'), trim(trailing from '  hi  '), trim(both 'xy' from 'xyhiyx'), trim('xxhixx', 'x')",
        "select btrim('xxhixx', 'x'), ltrim('  hi'), rtrim('hi  '), ltrim('zzhi', 'z')",
        "select left('hello', 2), right('hello', 2), left('hello', -2), right('hello', -2), left('hi', 10)",
        "select lpad('7', 3, '0'), rpad('ab', 5, 'xy'), lpad('hello', 2), lpad('x', 4), rpad('x', 3, '')",
        "select split_part('a,b,c', ',', 2), split_part('a,b,c', ',', 5), split_part('a,b,c', ',', -1)",
        "select split_part('a,b', ',', 0)",
        "select initcap('hello wORLD-foo bar1x'), octet_length('héllo'), ascii('A'), ascii(''), chr(65), starts_with('hello', 'he')",
        "select ceil(1.2), ceil(-1.2), floor(-1.2), floor(7), ceiling(2.0001), trunc(1.99), trunc(-1.99), trunc(3.14159, 2)",
        "select sqrt(16), exp(0), ln(1), log(100), log(2, 8), power(2, 10), pow(9, 0.5), mod(10, 3), mod(-10, 3), mod(10.5, 3)",
        "select sign(-5), sign(0), sign(2.5), round(pi() * 1000)",
        "select sqrt(-1)",
        "select ln(0)",
        "select mod(1, 0)",
        "select greatest(1, 5, 3), least(1, 5, 3), greatest(null, 2), least('b', 'a', 'c'), greatest(null, null)",
        "select nullif(1, 1), nullif(1, 2), nullif(null, 1), nullif('a', null)",
        "select make_date(2026, 2, 28), to_timestamp(0), to_timestamp(1700000000.5)",
        "select make_date(2026, 2, 30)",
        "select random() >= 0 and random() < 1",
        "select upper(concat('a', 'b')), length(repeat('x', 5)), lower(null), concat()",
        "create table t (id int primary key, name text, n int)",
        "insert into t values (1, ' Ada ', 10), (2, 'bob', null), (3, null, -3)",
        "select id, trim(name), coalesce(upper(name), '?'), greatest(n, 0), nullif(n, 10) from t order by id",
        "select id from t where lower(trim(name)) like 'a%' or starts_with(name, 'b') order by id",
        "select no_such_function(1)",
    ]]);
}

#[test]
fn jsonb_operators_and_functions() {
    check(&[&[
        "create table d (id int primary key, doc jsonb)",
        r#"insert into d values (1, '{"name": "Ada", "tags": ["x", "y"], "n": 3, "addr": {"city": "London", "zip": null}}'), (2, '{"name": "Bo", "tags": [], "n": 5.5}'), (3, null)"#,
        "select id, doc from d order by id",
        "select id, doc -> 'name', doc ->> 'name', doc -> 'tags' -> 0, doc -> 'tags' ->> -1, doc -> 'nope' from d order by id",
        "select id, doc #> '{addr,city}', doc #>> '{addr,city}', doc #>> '{tags,1}', doc #> '{addr,zip}', doc #>> '{addr,zip}' from d order by id",
        "select id from d where doc ->> 'name' = 'Ada'",
        "select id from d where (doc ->> 'n')::float > 4",
        "select id from d where (doc -> 'n')::int = 3",
        r#"select id from d where doc @> '{"tags": ["y"]}' order by id"#,
        r#"select id from d where '{"name": "Bo"}' <@ doc"#,
        r#"select '{"a": 1}'::jsonb || '{"b": 2, "a": 3}'::jsonb, '[1, 2]'::jsonb || '[3]'::jsonb, '[1]'::jsonb || '2'::jsonb"#,
        r#"select '{"bb": 1, "a": {"z": [1, {"y": 2}]}, "c": "x"}'::jsonb"#,
        "select jsonb_build_object('a', 1, 'b', 'two', 'c', null, 'd', true), jsonb_build_array(1, 'x', null, false)",
        "select to_jsonb('hi'::text), to_jsonb(1), to_jsonb(true), jsonb_typeof(doc), jsonb_typeof(doc -> 'tags'), jsonb_typeof(doc -> 'n') from d where id = 1",
        "select id, jsonb_array_length(doc -> 'tags') from d order by id",
        "select jsonb_extract_path(doc, 'addr', 'city'), jsonb_extract_path_text(doc, 'tags', '0') from d where id = 1",
        r#"select jsonb_set('{"a": [1, 2], "b": 1}', '{a,1}', '9'), jsonb_set('{"a": 1}', '{c}', '"new"'), jsonb_set('{"a": 1}', '{c}', '2', false)"#,
        r#"select jsonb_strip_nulls('{"a": null, "b": {"c": null, "d": 1}, "e": [null]}')"#,
        "select doc -> 'name' from d where id = 1 and doc ->> 'n' <> '0'",
        "select jsonb_build_object('a')",
        "select jsonb_array_length('{}')",
        "select count(*) from d where doc ? 'name'",
        "select id, doc ? 'addr', doc -> 'tags' ? 'x', doc ?| '{addr,zzz}', doc ?& '{name,addr}' from d order by id",
    ]]);
}

#[test]
fn list_and_bool_aggregates() {
    check(&[&[
        "create table e (id int primary key, team text, name text, pts int, ok boolean)",
        "insert into e values (1, 'a', 'Ada', 10, true), (2, 'a', 'Bo', 30, false), (3, 'b', 'Cy', 20, true), (4, 'b', null, null, null), (5, 'b', 'Di e', 5, true)",
        "select team, string_agg(name, ', ' order by name) from e group by team order by team",
        "select string_agg(name, '-' order by pts desc nulls last, id) from e",
        "select team, count(*), bool_and(ok), bool_or(ok), every(ok) from e group by team order by team",
        "select team, jsonb_agg(pts order by id) from e group by team order by team",
        "select jsonb_agg(name order by id) from e where team = 'b'",
        "select team, jsonb_object_agg(name, pts order by id) from e where name is not null group by team order by team",
        "select team, array_agg(pts order by id) from e group by team order by team",
        "select array_agg(name order by id) from e",
        "select string_agg(distinct team, '/' order by team) from e",
        "select string_agg(name, ',') from e where id > 100",
        "select jsonb_agg(id) from e where id > 100, bool_and(ok) from e where id > 100",
        "select bool_and(ok) from e where id > 100",
        "select jsonb_object_agg(name, pts) from e",
        "select team, string_agg(name, ', ' order by name) filter_is_not_supported from e group by team order by 1",
    ]]);
}

#[test]
fn expression_and_partial_indexes() {
    check(&[&[
        "create table u (id int primary key, email text, deleted boolean, score int, doc jsonb)",
        r#"insert into u values (1, 'A@x.io', false, 5, '{"k": "a"}'), (2, 'b@X.io', true, 5, '{"k": "b"}'), (3, 'c@x.io', false, 7, null), (4, null, null, 5, '{}')"#,
        "create index u_lower on u (lower(email))",
        "create index u_live on u (score) where not deleted",
        "create index u_k on u ((doc ->> 'k'))",
        "select id from u where lower(email) = 'b@x.io'",
        "select id from u where score = 5 and not deleted order by id",
        "select id from u where score = 5 order by id",
        "select id from u where doc ->> 'k' = 'a'",
        "select id from u where lower(email) between 'a' and 'b~' order by id",
        "update u set deleted = false where id = 2",
        "select id from u where score = 5 and not deleted order by id",
        "alter table u rename column email to mail",
        "select id from u where lower(mail) = 'a@x.io'",
        "create index bad on u (score, (random()))",
    ]]);
}

