#[test]
fn exact_numeric() {
    check_text(&[&[
        "select 0.1 + 0.2, 0.1 + 0.2 = 0.3, 1.50 * 2, 1 / 3.0, 10 / 4.0, 2.00 / 3, 100.0 / 7, 1e3, 1.5e-2",
        "select 1.5 + 1, 7 % 2.5, -1.25, abs(-1.25), round(2.5), round(-2.5), round(1.2345, 2), round(1234.5, -2), round(1.5::float)",
        "select ceil(1.2), floor(-1.2), trunc(1.999, 2), trunc(-1.5), sign(-0.5), mod(7.5, 2)",
        "select 1.5 > 1, 1.5 = 1.50, 2 = 2.0, 0.1::float = 0.1",
        "select '12.3400'::numeric, '1e3'::numeric, 1.5::int, 2.5::int, (-2.5)::int, 12.5::float, 3::numeric",
        "create table m (id int primary key, price numeric, qty int)",
        "insert into m values (1, 9.99, 3), (2, 0.10, 7), (3, 100, 1), (4, null, 2), (5, 0.3333333333333333333333, 1)",
        "select id, price, price * qty from m order by id",
        "select sum(price), avg(price), min(price), max(price), sum(price * qty) from m",
        "select id from m where price > 5 order by id",
        "select id from m where price = 0.1",
        "select price, count(*) from m group by price order by price",
        "create index m_price on m (price)",
        "select id from m where price between 0.1 and 10 order by id",
        "select 1 / 0.0",
    ]]);
}

