#[test]
fn with_before_insert_update_delete() {
    check(&[&[
        "create table w (id int primary key, v int)",
        "create table log (id int primary key, note text)",
        "insert into w values (1, 10), (2, 20), (3, 30)",
        "with big as (select id from w where v > 15) delete from w where id in (select id from big) returning id",
        "select * from w order by id",
        "insert into w values (2, 20), (3, 30)",
        "with m as (select max(v) as top from w) update w set v = v + (select top from m) where id = 1 returning v",
        "with src as (select id, 'saw ' || v as note from w) insert into log select * from src order by id",
        "select * from log order by id",
        "with n as (select 9 as id) insert into log values ((select id from n), 'nine') returning *",
        "with x as (select 1) select * from x",
    ]]);
}

