#[test]
fn lateral_subqueries() {
    check(&[&[
        "create table c (id int primary key, name text)",
        "create table o (id int primary key, c int, amt int, at date)",
        "insert into c values (1, 'Ada'), (2, 'Bo'), (3, 'Cy')",
        "insert into o values (10, 1, 5, '2026-01-01'), (11, 1, 9, '2026-02-01'), (12, 1, 7, '2026-03-01'), (13, 2, 3, '2026-01-15')",
        "select c.name, top.amt from c, lateral (select amt from o where o.c = c.id order by amt desc limit 2) top order by c.name, top.amt desc",
        "select c.name, last.at from c cross join lateral (select at from o where o.c = c.id order by at desc limit 1) as last order by c.name",
        "select c.name, s.n, s.total from c left join lateral (select count(*) as n, sum(amt) as total from o where o.c = c.id and o.amt > 4) s on true order by c.name",
        "select c.name, x.amt from c left join lateral (select amt from o where o.c = c.id and amt > 100) x on true order by c.name",
        "select c.name, x.amt from c join lateral (select amt from o where o.c = c.id) x on x.amt > 6 order by x.amt",
        "select c.name, d.doubled from c, lateral (select c.id * 2 as doubled) d where d.doubled > 2 order by 1",
    ]]);
}

