#[test]
fn temporary_tables() {
    check(&[&[
        "create temp table tt (id int primary key, v text)",
        "insert into tt values (1, 'one'), (2, 'two')",
        "create table base (id int primary key, name text)",
        "insert into base values (1, 'x'), (3, 'z')",
        "insert into tt select id + 10, name from base",
        "select tt.v, base.name from tt join base on base.id = tt.id order by tt.id",
        "select * from tt order by id",
        "begin",
        "insert into tt values (3, 'three')",
        "rollback",
        "select count(*) from tt",
        "begin",
        "insert into tt values (4, 'four')",
        "commit",
        "update tt set v = upper(v) where id = 1",
        "delete from tt where id = 2",
        "select * from tt order by id",
        "insert into base select id, v from tt where id = 4",
        "select * from base order by id",
        "select id from base where id in (select id from tt) order by id",
        "create temporary table if not exists tt (id int)",
        "insert into tt values (1, 'dup')",
        "drop table tt",
        "select * from tt",
    ]]);
}

/// Writes to temporary tables made by functions a statement calls: kept once when it succeeds, not at all when it
/// fails, or when an EXCEPTION block they're in is caught (they once went to the world, where the temporary table
/// never saw them: Postgres's plpgsql.sql STRICT tests found foo with 2 rows, not 6).
#[test]
fn functions_write_temporary_tables() {
    check(&[&[
        "create temp table foo (f1 int, f2 int)",
        "insert into foo values (1,2), (3,4)",
        "create or replace function stricttest() returns void as $$ declare x record; begin \
           insert into foo values(5,6) returning * into x; end$$ language plpgsql",
        "select stricttest()",
        "create or replace function stricttest() returns void as $$ declare x record; begin \
           insert into foo values(7,8),(9,10) returning * into x; end$$ language plpgsql",
        "select stricttest()",
        "create or replace function stricttest() returns void as $$ declare x record; begin \
           execute 'insert into foo values(5,6) returning *' into x; end$$ language plpgsql",
        "select stricttest()",
        "create or replace function stricttest() returns void as $$ declare x record; begin \
           execute 'insert into foo values(7,8),(9,10) returning *' into x; end$$ language plpgsql",
        "select stricttest()",
        "select * from foo order by f1, f2",
        "create table fwt_bar (a int)",
        "create temp table fwt (a int)",
        "create function fwt_add(int) returns int language plpgsql as $$ begin insert into fwt values ($1); return $1; end $$",
        "create function fwt_sql(int) returns int language sql as $$ insert into fwt values ($1) returning a $$",
        "create function fwt_bad() returns int language plpgsql as $$ begin insert into fwt values (100); \
           raise exception 'boom'; end $$",
        "create function fwt_guard() returns bigint language plpgsql as $$ begin \
           insert into fwt values (1); \
           begin insert into fwt values (2); raise exception 'x'; exception when others then null; end; \
           begin insert into fwt values (3); exception when others then null; end; \
           return (select count(*) from fwt); end $$",
        "create function fwt_bar_add(int) returns int language plpgsql as $$ begin insert into fwt_bar values ($1); return $1; end $$",
        "select fwt_bad()",
        "select count(*) from fwt",
        "select fwt_guard()",
        "select a from fwt order by a",
        "select fwt_add(g) from generate_series(10, 12) g",
        "select fwt_sql(13)",
        "select a from fwt order by a",
        "insert into fwt_bar values (fwt_add(20))",
        "insert into fwt values (fwt_bar_add(7)), (fwt_add(21) + 100)",
        "insert into fwt select fwt_add(a + 30) from fwt_bar",
        "select * from fwt_bar order by a",
        "select a from fwt order by a",
        "begin",
        "select fwt_add(40)",
        "select count(*) from fwt where a = 40",
        "rollback",
        "select count(*) from fwt where a = 40",
        "begin",
        "select fwt_add(41)",
        "commit",
        "create function fwt_change() returns void language plpgsql as $$ begin \
           update fwt set a = a + 1000 where a = 41; delete from fwt where a = 1; \
           execute 'insert into fwt values (50)'; end $$",
        "select fwt_change()",
        "select a from fwt order by a",
        "create function fwt_stable() returns int language plpgsql stable as $$ begin insert into fwt values (0); return 0; end $$",
        "select fwt_stable()",
        "select count(*) from fwt where a = 0",
        "drop table fwt",
        "drop table foo",
        "select * from fwt",
        "select * from foo",
    ]]);
}

/// What functions write to temporary tables, from every statement that can call them: DML on permanent tables, a
/// trigger's function, DO and CALL, defaults; and what takes it back: a statement that fails, a transaction that
/// rolls back, a savepoint rolled back to, an EXCEPTION block caught. A function that isn't VOLATILE may not write.
#[test]
fn functions_write_temporary_tables_and_take_them_back() {
    check(&[&[
        "create temp table tt (x int, tag text)",
        "create table w (x int primary key, y int default 0)",
        "insert into w values (1), (2), (3)",
        "create function add(i int, t text) returns int language plpgsql as $$ begin insert into tt values (i, t); return i; end $$",
        "create function addsql(i int) returns int language sql as $$ insert into tt values (i, 'sql') returning x $$",
        // from DML on a permanent table
        "update w set y = add(x, 'upd') where x > 1",
        "insert into w values (add(10, 'ins'))",
        "delete from w where add(x, 'del') = 3",
        "select addsql(x) from w",
        "select * from tt order by x, tag",
        // from a trigger on a permanent table
        "create function trg() returns trigger language plpgsql as $$ begin insert into tt values (new.x, 'trg'); return new; end $$",
        "create trigger t1 after insert on w for each row execute function trg()",
        "insert into w values (20), (21)",
        "select x from tt where tag = 'trg' order by x",
        // DO, CALL
        "do $$ begin insert into tt values (30, 'do'); update tt set tag = 'do2' where x = 30; end $$",
        "create procedure pr() language plpgsql as $$ begin insert into tt values (31, 'call'); delete from tt where x = 30; end $$",
        "call pr()",
        "select x, tag from tt where x in (30, 31) order by x",
        // a rolled-back transaction, a savepoint rolled back to
        "begin",
        "select add(40, 'tx')",
        "select count(*) from tt where x = 40",
        "rollback",
        "select count(*) from tt where x = 40",
        "begin",
        "select add(50, 'a')",
        "savepoint s",
        "select add(51, 'b')",
        "update tt set tag = 'changed' where x = 50",
        "rollback to s",
        "select add(52, 'c')",
        "commit",
        "select x, tag from tt where x between 50 and 59 order by x",
        // a statement that fails takes its functions' writes with it
        "select add(60, 'e'), 1 / (x - 2) from w",
        "select count(*) from tt where x = 60",
        // an EXCEPTION block that catches takes back what its body wrote, and no more
        "create function ex() returns int language plpgsql as $$ begin \
           insert into tt values (70, 'outer'); \
           begin insert into tt values (71, 'inner'); raise exception 'x'; \
           exception when others then insert into tt values (72, 'handler'); end; \
           return (select count(*) from tt where x between 70 and 79)::int; end $$",
        "select ex()",
        "select x, tag from tt where x between 70 and 79 order by x",
        "create function iu(i int) returns text language plpgsql as $$ begin insert into tt values (i, 'iu'); \
           if i = 2 then raise unique_violation; end if; return 'ok'; \
           exception when unique_violation then return 'dup'; end $$",
        "select iu(1), iu(2), iu(3)",
        "select x from tt where tag = 'iu' order by x",
        // not VOLATILE: refused, and nothing is written
        "create function st() returns int language plpgsql stable as $$ begin insert into tt values (80, 's'); return 1; end $$",
        "select st()",
        "select count(*) from tt where x = 80",
        // a function reads what it and the functions before it wrote, in one statement
        "create function rw(i int) returns bigint language plpgsql as $$ begin insert into tt values (i, 'rw'); \
           return (select count(*) from tt where tag = 'rw'); end $$",
        "select rw(1), rw(2), rw(3)",
        // the statement's own write joins its functions'
        "insert into tt select add(x + 200, 'is'), 'isrc' from w where x < 3",
        "select x, tag from tt where x >= 200 order by x, tag",
        "update tt set x = add(x + 1000, 'self') where tag = 'rw'",
        "select x, tag from tt where tag in ('rw', 'self') order by x, tag",
        // a function's own UPDATE and DELETE
        "create function bump() returns void language plpgsql as $$ begin update tt set x = x + 5000 where tag = 'self'; \
           delete from tt where tag = 'rw'; end $$",
        "select bump()",
        "select x, tag from tt where tag in ('rw', 'self') order by x, tag",
    ]]);
}

/// Statements on a temporary table that call functions made with CREATE FUNCTION (which the temporary tables'
/// database has none of): UPDATE, DELETE, INSERT and a default, the function reading and writing the world's tables
/// and the temporary ones, and what each leaves.
#[test]
fn functions_called_by_statements_on_temporary_tables() {
    check(&[&[
        "create temp table tt (x int primary key, y int default 0)",
        "insert into tt values (1), (2), (3)",
        "create table w (x int)",
        "create function f(i int) returns int language sql as $$ select i * 10 $$",
        "create function g(i int) returns int language plpgsql as $$ begin insert into w values (i); return i; end $$",
        "update tt set y = f(x)",
        "select x, y from tt order by x",
        "delete from tt where g(x) = 3",
        "select x, y from tt order by x",
        "select x from w order by x",
        "insert into tt values (f(5))",
        "insert into tt select g(x) + 100 from w",
        "select x, y from tt order by x",
        "create function cnt() returns bigint language sql as $$ select count(*) from tt $$",
        "select cnt()",
        "update tt set y = cnt() where x = 1",
        "update tt set y = 1 where x = 1 returning f(y)",
        "create temp table td (a int default f(1), b int)",
        "insert into td (b) values (1)",
        "select a, b from td",
        // a function that writes the table the statement changes
        "create function bump(i int) returns int language plpgsql as $$ begin update tt set y = y + 1000 where x = i; return i; end $$",
        "select bump(2)",
        "select x, y from tt order by x",
        // a statement that fails takes what its functions wrote to the world with it
        "update tt set y = g(x) + 1 / (x - 2)",
        "select count(*) from w",
        "select x, y from tt order by x",
        "begin",
        "update tt set y = y + 1 where g(x) > 0",
        "rollback",
        "select count(*) from w",
        "select x, y from tt order by x",
    ]]);
}

/// A volatile function runs where Postgres runs it, so what it writes is kept as often: for each row of a
/// correlated subquery whatever the outer values, for each row a comparison is made for (not once, as a
/// key lookup would), and for the rows OFFSET skips.
#[test]
fn volatile_functions_write_as_often_as_postgres_runs_them() {
    check(&[&[
        "create table t (x int primary key)",
        "insert into t select generate_series(1, 6)",
        "create table u (x int)",
        "insert into u values (1), (2), (2), (3)",
        "create table log (x int)",
        "create function f(i int) returns int language sql as $$ insert into log values (i) returning i $$",
        "create function g(i int) returns int language plpgsql as $$ begin insert into log values (i); return i; end $$",
        // a correlated subquery, run for each outer row (two have the same values)
        "select x from u where exists (select 1 where f(u.x) > 0) order by x",
        "select count(*) from log",
        "select x, (select g(u.x)) from u order by x",
        "select count(*) from log",
        "select x from u where x in (select f(u.x)) order by x",
        "select count(*) from log",
        // by key: the function runs for each row, as an index can't be searched with a value that changes
        "select x from t where x = f(2)",
        "select count(*) from log",
        "select x from t where x in (g(1), g(2)) order by x",
        "select count(*) from log",
        // OFFSET: the rows it skips are projected
        "select f(x) from t offset 4",
        "select count(*) from log",
        "select g(x) from t offset 4 limit 1",
        "select count(*) from log",
        "select f(x) from t order by x desc limit 2 offset 3",
        "select count(*) from log",
        // not VOLATILE: run once for a comparison with a key
        "create function s(i int) returns int language sql stable as $$ select i $$",
        "select x from t where x = s(2)",
        "select count(*) from log",
    ]]);
}

#[test]
fn sql_functions() {
    check(&[&[
        "create function add1(int) returns int language sql as 'select $1 + 1'",
        "select add1(41), add1(add1(1)), add1(null)",
        "create function mul(a int, b int) returns int language sql immutable return a * b",
        "select mul(6, 7), mul(2, mul(3, 4))",
        "create function half(numeric) returns numeric language sql strict as $$ select $1 / 2 $$",
        "select half(5), half(null)",
        "create table t (id int primary key, name text, n int)",
        "insert into t values (1, 'a', 10), (2, 'b', 20), (3, 'c', 30)",
        "select id, add1(n), mul(id, n) from t where add1(n) > 15 order by id",
        "select sum(add1(n)) from t",
        "create function big(lim int) returns setof t language sql as 'select * from t where n > lim order by id'",
        "select * from big(15)",
        "select name from big(0) b where b.id <> 2 order by name desc",
        "create function pairs(k int) returns table (a int, b text) language sql as $$ select id, name from t where id <= k order by id $$",
        "select * from pairs(2)",
        "select a, b from pairs(3) where a > 1",
        "create function ids() returns setof int language sql as 'select id from t order by id'",
        "select * from ids()",
        "select ids from ids() order by ids desc",
        "create function bump(k int) returns int language sql as 'update t set n = n + 1 where id = k returning n'",
        "select bump(1)",
        "select n from t where id = 1",
        "create function two_steps(k int) returns int language sql begin atomic update t set n = n + 1 where id = k; select n from t where id = k; end",
        "select two_steps(2), two_steps(2)",
        "select n from t where id = 2",
        "create function g(int) returns text language sql as $$ select 'int' $$",
        "create function g(text) returns text language sql as $$ select 'text' $$",
        "select g(1), g('x'), g(null)",
        "select g(1, 2)",
        "select nosuch(1)",
        "create function add1(int) returns int language sql as 'select $1 + 2'",
        "create or replace function add1(int) returns int language sql as 'select $1 + 2'",
        "select add1(1)",
        "create or replace function add1(int) returns bigint language sql as 'select $1 + 2'",
        "drop function g",
        "drop function g(text)",
        "select g('x')",
        "drop function if exists nope",
        "drop function nope",
        "drop function add1(int), mul",
        "select add1(1)",
    ]]);
}

