#[test]
fn plpgsql_labels_slices_and_diagnostics() {
    check(&[&[
        // labels: EXIT and CONTINUE by label, END labels, and label-qualified variables a block further in hides
        "create function qual(param1 int) returns text language plpgsql as $$
         <<outerblock>>
         declare param1 int := 1; s text := '';
         begin
           <<innerblock>>
           declare param1 int := 2;
           begin
             s := param1 || ',' || qual.param1 || ',' || outerblock.param1 || ',' || innerblock.param1;
           end innerblock;
           return s || ',' || param1;
         end outerblock $$",
        "select qual(42)",
        "create function lab(n int) returns text language plpgsql as $$
         declare s text := '';
         begin
           <<outer>>
           for i in 1..n loop
             <<inner>>
             for j in 1..n loop
               continue outer when j > i;
               exit outer when i * j > 6;
               s := s || i || j || ' ';
             end loop inner;
           end loop outer;
           <<blk>>
           begin
             exit blk when n > 0;
             s := s || 'not here';
           end;
           return s;
         end $$",
        "select lab(4)",
        // FOREACH ... SLICE
        "create function sl(a int[], n int) returns text language plpgsql as $$
         declare x int[]; s text := '';
         begin
           if n = 1 then
             foreach x slice 1 in array a loop s := s || x::text || ';'; end loop;
           else
             foreach x slice 2 in array a loop s := s || x::text || ';'; end loop;
           end if;
           return s;
         end $$",
        "select sl(array[1,2,3,4], 1), sl(array[[1,2],[3,4]], 1), sl(array[[[1,2]],[[3,4]]], 2)",
        "select sl(array[1,2,3,4], 2)",
        "create function sl0(a int[]) returns int language plpgsql as $$
         declare x int; s int := 0;
         begin
           foreach x slice 1 in array a loop s := s + 1; end loop;
           return s;
         end $$",
        "select sl0(array[1,2])",
        // GET DIAGNOSTICS PG_CONTEXT down a call stack, and PG_ROUTINE_OID
        "create function inner_f(int) returns text language plpgsql as $$
         declare c text;
         begin
           get diagnostics c = pg_context;
           return c;
         end $$",
        "create function outer_f(int) returns text language plpgsql as $$
         declare r text;
         begin
           r := inner_f($1);
           return r;
         end $$",
        "select outer_f(1)",
        "create function me(text) returns regprocedure language plpgsql as $$
         declare o regprocedure;
         begin
           get diagnostics o = pg_routine_oid;
           return o;
         end $$",
        "select me('x')",
        // RAISE's fields, read back by GET STACKED DIAGNOSTICS; options given twice; the default message
        "create function fields() returns text language plpgsql as $$
         declare a text; b text; c text; d text; e text;
         begin
           raise exception using column = 'col', constraint = 'con', datatype = 'typ', table = 'tab', schema = 'sch';
         exception when others then
           get stacked diagnostics a = column_name, b = constraint_name, c = pg_datatype_name, d = table_name,
             e = schema_name;
           return concat_ws(' ', sqlstate, sqlerrm, a, b, c, d, e);
         end $$",
        "select fields()",
        "create function twice() returns void language plpgsql as $$
         begin
           raise division_by_zero using message = 'custom', errcode = '22012';
         end $$",
        "select twice()",
        // CASE with no match, ASSERT off, booleans in RAISE, a number assigned to a boolean
        "create function nocase(x int) returns int language plpgsql as $$
         begin
           case x when 1 then return 1; end case;
         end $$",
        "select nocase(2)",
        "set plpgsql.check_asserts = off",
        "do $$ begin assert 1 = 0; end $$",
        "reset plpgsql.check_asserts",
        "do $$ begin raise notice '% %', true, false; end $$",
        "create function asbool(x int) returns boolean language plpgsql as $$ begin return x; end $$",
        "select asbool(1), asbool(0)",
        // #variable_conflict
        "create table vc (q1 int)",
        "insert into vc values (7)",
        "create function vc_var() returns int language plpgsql as $$
         #variable_conflict use_variable
         declare q1 int := 42; r int;
         begin
           select q1 into r from vc;
           return r;
         end $$",
        "create function vc_col() returns int language plpgsql as $$
         #variable_conflict use_column
         declare q1 int := 42; r int;
         begin
           select q1 into r from vc;
           return r;
         end $$",
        "select vc_var(), vc_col()",
        // extra checks
        "set plpgsql.extra_errors to 'too_many_rows'",
        "do $$ declare x int; begin select v from generate_series(1,2) g(v) into x; end $$",
        "set plpgsql.extra_errors to 'strict_multi_assignment'",
        "do $$ declare x int; y int; begin select 1, 2 into x, y; select 1 into x, y; end $$",
        "reset plpgsql.extra_errors",
        // print_strict_params
        "create function sp() returns void language plpgsql as $$
         #print_strict_params on
         declare x int; p1 int := 2; p3 text := 'it''s';
         begin
           select 1 into strict x from vc where q1 = p1 and p3 = 'no';
         end $$",
        "select sp()",
        // OUT parameters by number, and RETURN QUERY of a SELECT INTO
        "create function rq(out int, out int) returns setof record language plpgsql as $$
         begin
           $1 := -1;
           $2 := -2;
           return next;
           return query select x, x * 10 from generate_series(1, 2) s (x);
         end $$",
        "select * from rq()",
        "create function rqi() returns setof int language plpgsql as $$
         begin
           return query select 10 into no_such_table;
         end $$",
        "select * from rqi()",
    ]]);
}

#[test]
fn plpgsql_control_flow() {
    check(&[&[
        "create function fact(n int) returns bigint language plpgsql as $$
         declare r bigint := 1;
         begin
           for i in 1..n loop r := r * i; end loop;
           return r;
         end $$",
        "select fact(0), fact(10), fact(20)",
        "create function classify(x int) returns text language plpgsql as $$
         begin
           if x is null then return 'none';
           elsif x < 0 then return 'negative';
           elseif x = 0 then return 'zero';
           else return 'positive';
           end if;
         end $$",
        "select classify(-5), classify(0), classify(7), classify(null)",
        "create function sum_to(n int) returns int language plpgsql as $$
         declare s int := 0; i int := 0;
         begin
           while i < n loop
             i := i + 1;
             continue when i % 2 = 0;
             s := s + i;
           end loop;
           return s;
         end $$",
        "select sum_to(10), sum_to(0)",
        "create function first_over(lim int) returns int language plpgsql as $$
         declare i int := 0;
         begin
           loop
             i := i + 7;
             exit when i > lim;
           end loop;
           return i;
         end $$",
        "select first_over(50)",
        "create function kind(x int) returns text language plpgsql as $$
         begin
           case x when 1, 2 then return 'small'; when 3 then return 'three'; else return 'other'; end case;
         end $$",
        "select kind(1), kind(3), kind(9)",
        "create function kind2(x int) returns text language plpgsql as $$
         begin
           case when x > 10 then return 'big'; when x > 5 then return 'mid'; end case;
           return 'unreachable';
         end $$",
        "select kind2(20), kind2(7)",
        "select kind2(1)",
        "create function down(n int) returns text language plpgsql as $$
         declare s text := '';
         begin
           for i in reverse n..1 by 2 loop s := s || i || ','; end loop;
           return s;
         end $$",
        "select down(9)",
        "create table acct (id int primary key, owner text, bal numeric)",
        "insert into acct values (1, 'ada', 100), (2, 'bo', 50), (3, 'cy', 0)",
        "create function total(who text) returns numeric language plpgsql as $$
         declare t numeric;
         begin
           select sum(bal) into t from acct where owner = who;
           if not found or t is null then return -1; end if;
           return t;
         end $$",
        "select total('ada'), total('zed')",
        "create function richest() returns text language plpgsql as $$
         declare r record; best text; top numeric := -1;
         begin
           for r in select owner, bal from acct order by id loop
             if r.bal > top then top := r.bal; best := r.owner; end if;
           end loop;
           return best || ':' || top;
         end $$",
        "select richest()",
        "create function one(k int) returns text language plpgsql as $$
         declare o text;
         begin
           select owner into strict o from acct where id = k;
           return o;
         end $$",
        "select one(2)",
        "select one(9)",
        "create function pay(src int, dst int, amt numeric) returns numeric language plpgsql as $$
         declare left_over numeric;
         begin
           update acct set bal = bal - amt where id = src returning bal into left_over;
           if left_over < 0 then raise exception 'insufficient funds: % left', left_over using errcode = '22003'; end if;
           update acct set bal = bal + amt where id = dst;
           return left_over;
         end $$",
        "select pay(1, 3, 30)",
        "select pay(2, 3, 80)",
        "select id, bal from acct order by id",
        "create function evens(n int) returns setof int language plpgsql as $$
         begin
           for i in 1..n loop
             if i % 2 = 0 then return next i; end if;
           end loop;
           return;
         end $$",
        "select * from evens(9)",
        "create function owners() returns table (who text, money numeric) language plpgsql as $$
         begin
           return query select owner, bal from acct where bal > 0 order by id;
           who := 'total'; money := (select sum(bal) from acct);
           return next;
         end $$",
        "select * from owners()",
        "create function touch() returns int language plpgsql as $$
         declare n int;
         begin
           perform 1 from acct where bal > 1000;
           if found then return -1; end if;
           update acct set bal = bal + 0 where bal >= 0;
           get diagnostics n = row_count;
           return n;
         end $$",
        "select touch()",
        "create function noreturn() returns int language plpgsql as $$ begin end $$",
        "select noreturn()",
        "create function nodest() returns int language plpgsql as $$ begin select 1; return 1; end $$",
        "select nodest()",
        "create function strictly(x int) returns int language plpgsql strict as $$ begin return x * 2; end $$",
        "select strictly(null), strictly(4)",
        "create function cond(x int) returns int language plpgsql as $$
         begin
           assert x > 0, 'x must be positive';
           return x;
         end $$",
        "select cond(3)",
        "select cond(-3)",
        "create function fib(n int) returns int language plpgsql immutable as $$
         begin if n < 2 then return n; end if; return fib(n - 1) + fib(n - 2); end $$",
        "select fib(12)",
        "create function shadows() returns text language plpgsql as $$
         declare i int := 100; s text := '';
         begin
           for i in 1..3 loop s := s || i; end loop;
           s := s || '/' || i;
           declare i text := 'inner';
           begin s := s || '/' || i; end;
           return s || '/' || i;
         end $$",
        "select shadows()",
        "create function ambiguous() returns int language plpgsql as $$
         declare id int;
         begin select id into id from acct where id = 1; return id; end $$",
        "select ambiguous()",
        "create function consts() returns numeric language plpgsql as $$
         declare rate constant numeric(6, 2) := 1.23456; n int not null := 1;
         begin return rate * n; end $$",
        "select consts()",
        "create function nn() returns int language plpgsql as $$
         declare n int not null := 1;
         begin n := null; return n; end $$",
        "select nn()",
    ]]);
}

