#[test]
fn triggers() {
    check(&[&[
        "create table item (id int primary key, name text, qty int, updated int default 0)",
        "create table audit (id serial primary key, op text, tbl text, item int, qty int)",
        "create function log_it() returns trigger language plpgsql as $$
         begin
           if tg_op = 'DELETE' then
             insert into audit (op, tbl, item, qty) values (tg_op, tg_table_name, old.id, old.qty);
             return old;
           end if;
           insert into audit (op, tbl, item, qty) values (tg_op, tg_table_name, new.id, new.qty);
           return new;
         end $$",
        "create trigger item_audit after insert or update or delete on item for each row execute function log_it()",
        "insert into item (id, name, qty) values (1, 'bolt', 10), (2, 'nut', 20)",
        "update item set qty = qty + 1 where id = 1",
        "delete from item where id = 2",
        "select op, tbl, item, qty from audit order by id",
        "create function tidy() returns trigger language plpgsql as $$
         begin
           new.name := lower(trim(new.name));
           if new.qty < 0 then return null; end if;
           if tg_op = 'UPDATE' then new.updated := old.updated + 1; end if;
           return new;
         end $$",
        "create trigger item_tidy before insert or update on item for each row execute function tidy()",
        "insert into item (id, name, qty) values (3, '  WASHER ', 5), (4, 'skip', -1) returning id, name",
        "update item set qty = 7 where id = 3 returning name, qty, updated",
        "update item set qty = -5 where id = 3",
        "select id, name, qty, updated from item order by id",
        "select count(*) from audit",
        "create function guard() returns trigger language plpgsql as $$
         begin raise exception 'qty % too big for %', new.qty, new.name using errcode = '22003'; end $$",
        "create trigger item_guard before insert on item for each row when (new.qty > 100) execute function guard()",
        "insert into item (id, name, qty) values (5, 'ok', 50)",
        "insert into item (id, name, qty) values (6, 'fine', 60), (7, 'huge', 500)",
        "select id from item order by id",
        "create function stamp() returns trigger language plpgsql as $$
         begin insert into audit (op, tbl) values ('stmt ' || tg_when || ' ' || tg_op, tg_argv[0]); return null; end $$",
        "create trigger item_stmt after update on item for each statement execute function stamp('items')",
        "update item set qty = qty where id > 100",
        "select op, tbl from audit where item is null order by id",
        "create trigger only_qty after update of qty on item for each row execute function stamp('qty')",
        "update item set name = 'x' where id = 1",
        "update item set qty = 1 where id = 1",
        "select op, tbl from audit where item is null order by id",
        "alter table item disable trigger item_audit",
        "delete from item where id = 5",
        "alter table item enable trigger all",
        "delete from item where id = 6",
        "select op, item from audit where op = 'DELETE' order by id",
        "drop trigger item_guard on item",
        "drop trigger if exists item_guard on item",
        "drop trigger item_guard on item",
        "drop function tidy",
        "drop trigger item_tidy on item",
        "drop function tidy",
        "create trigger bad after insert on item for each row execute function nosuch()",
        "create trigger bad after insert on item for each row execute function log_it()",
        "create trigger bad after insert on item for each row execute function log_it()",
    ]]);
}

/// Defaults Postgres works out for each row, set as pg_dump sets a serial's (ALTER TABLE ... SET
/// DEFAULT nextval after CREATE TABLE), and constant defaults written with operators.
