fn defaults_set_after_and_worked_out() {
    check(&[&[
        "create sequence u_id_seq",
        "create table u (id int not null, name text, secs int default 60 * 60, tag text default 'a' || 'b')",
        "alter table u alter column id set default nextval('u_id_seq'::regclass)",
        "insert into u (name) values ('a'), ('b')",
        "select id, name, secs, tag from u order by name",
        "alter table u alter column secs set default 2 * 30",
        "insert into u (name) values ('c') returning id, secs",
        "create table w (id int, n int default (select 1))",
    ]]);
}

