#[test]
fn update_from_and_delete_using_with_queries() {
    check(&[&[
        "create table lead (id int primary key, source text, status text, score int)",
        "insert into lead select g, 'src' || (g % 5), (array['new','won','lost'])[1 + g % 3], 0 from generate_series(1, 300) g",
        "with r as (select source, count(*) as n from lead group by source) update lead set score = r.n % 100 from r where r.source = lead.source and lead.id <= 120",
        "with w as (select source, sum(case when status = 'won' then 1 else 0 end)::float / count(*) as rate from lead group by source), m as (select 'new' as status, 10 as score union all select 'won', 90) update lead l set score = (m.score * (1 + w.rate))::int from m, w where l.status = m.status and l.source = w.source and l.id > 200",
        "select id, score from lead order by id",
        "with r as (select source from lead group by source having count(*) > 0 and source <> 'src0') delete from lead using r where r.source = lead.source and lead.id % 7 = 0",
        "select count(*), sum(score) from lead",
    ]]);
}

#[test]
fn literals_are_checked_with_no_rows() {
    // Postgres reads a string literal as the type it meets when planning, so a bad one fails on
    // an empty table too; and a column set twice in one SET is a syntax error
    check(&[&[
        "create table e (x int, d date, b bool)",
        "select 'hello' in (select x from e)",
        "select 'hello' not in (select * from e)",
        "select 'hello' = any (select x from e)",
        "select * from e where x = 'hello'",
        "select * from e where 'hello' < x",
        "select * from e where x in (1, 'hello')",
        "select * from e where d = 'soon'",
        "select * from e where b = 'maybe'",
        "select * from e where x = '3000000000'",
        "update e set x = 'hello' where false",
        "select * from e where x = '7' and d = '2026-01-02' and b = 'yes'",
        "insert into e values (1, '2026-01-02', true)",
        "select '1' in (select x from e), x in ('1', '2') from e",
        "update e set x = 3, x = 4",
        "update e set x = 2, d = d, b = 'no'",
        "insert into e values (1, '2026-01-03', true) on conflict do nothing",
        "select * from e order by x",
    ]]);
}

#[test]
fn aggregates_take_all() {
    check(&[&[
        "create table g (a int, b float, s text)",
        "insert into g values (1, 1.5, 'x'), (2, null, 'y'), (2, 2.5, null)",
        "select sum(all a), avg(all b), count(all a), min(all a), max(all - - a), count(all s) from g",
        "select sum(distinct a), count(distinct a), string_agg(all s, ',' order by s), array_agg(all a order by a) from g",
        "select count(all *) from g",
        "select a, sum(all a) over (), count(all b) over () from g order by a, b",
    ]]);
}

#[test]
fn parenthesized_joins() {
    check(&[&[
        "create table pa (id int primary key, x int)",
        "create table pb (id int primary key, y int)",
        "create table pc (id int primary key, z int)",
        "insert into pa values (1, 10), (2, 20), (3, 30)",
        "insert into pb values (1, 100), (2, 200)",
        "insert into pc values (1, 7), (3, 9)",
        "select * from (pa as r cross join pb) where r.x > 10 order by r.id, pb.id",
        "select r.id, pb.y from (pa r join pb on r.id = pb.id) order by r.id",
        "select * from ((pa r join pb on r.id = pb.id)) left join pc on pc.id = r.id order by r.id",
        "select pa.id, pb.id, pc.id from pa join (pb join pc on pc.id = pb.id) on pa.id = pb.id order by 1",
        "select pa.id, pb.id, pc.id from pa, (pb cross join pc) where pa.id = pb.id and pb.id = pc.id",
        "select count(*) from ((pa cross join pb) cross join (pc cross join pa as a2))",
        "select * from ((select 1 as k) s join pa on pa.id = s.k)",
    ]]);
}

#[test]
fn now_is_fixed_for_the_transaction() {
    // (the time a query burns is what tells a clock that moves from one that doesn't)
    let burn = "select count(*) from generate_series(1, 300000)";
    check(&[&[
        // one value for every spelling, in one statement
        "select now() = now(), now() = current_timestamp, now() = transaction_timestamp(), now()::timestamp = localtimestamp",
        "select age(now(), now())",
        "select now() <= statement_timestamp(), statement_timestamp() <= clock_timestamp()",
        "create table ts (n int, at timestamptz default now(), c timestamptz default clock_timestamp())",
        // outside a transaction, each statement is its own
        "insert into ts (n) values (1)",
        burn,
        "insert into ts (n) values (2)",
        "select count(distinct at), count(*) from ts",
        // inside one, now() and the default stay at BEGIN, the other clocks move on
        "delete from ts",
        "begin",
        "insert into ts (n) values (1)",
        burn,
        "insert into ts (n) values (2)",
        "select now() > statement_timestamp()",
        "select statement_timestamp() > now(), clock_timestamp() >= statement_timestamp()",
        "commit",
        "select count(distinct at), count(distinct c), count(*) from ts",
        "select count(*) from ts where c > at",
        // the next transaction begins later
        "begin",
        "insert into ts (n) values (3)",
        "commit",
        "select count(distinct at) from ts",
        "select (select at from ts where n = 3) > (select at from ts where n = 1)",
        // current_date follows now()
        "select current_date = now()::date",
    ]]);
}

#[test]
fn session_and_system_functions() {
    // (what these return depends on the server, so a script checks their shape, and what must agree)
    check(&[&[
        "select current_user = session_user, current_user = current_role, current_user is not null",
        "select current_catalog = current_database(), current_schema = current_schema()",
        "select version() like 'PostgreSQL 1_%', pg_backend_pid() > 0, pg_is_in_recovery()",
        "select txid_current() > 0, txid_current() = txid_current()",
        "select pg_postmaster_start_time() < now(), pg_postmaster_start_time() > now() - interval '1 year'",
        "select inet_server_addr() is null, inet_client_addr() is null, inet_server_port() is null, inet_client_port() is null",
        "select pg_typeof(pg_backend_pid()), pg_typeof(txid_current()), pg_typeof(pg_postmaster_start_time()), pg_typeof(pg_is_in_recovery()), pg_typeof(version())",
        "select pg_sleep(0), pg_sleep(0.001)",
        "select pg_sleep(null) is null",
        "select pg_encoding_to_char(0), pg_encoding_to_char(6), pg_encoding_to_char(8), pg_encoding_to_char(24), pg_encoding_to_char(41)",
        "select pg_encoding_to_char(42) = '', pg_encoding_to_char(-1) = '', pg_encoding_to_char(null) is null",
        "select num_nulls(1, null, null), num_nonnulls(1, null, 3), num_nulls(null::int), num_nonnulls('a'), num_nulls(null, null)",
        "select array_to_string(array[1, 2, 3], ','), array_to_string(array['a', null, 'c'], ','), array_to_string(array['a', null, 'c'], ',', '*')",
        "select array_to_string(array['a', 'b'], null) is null, array_to_string(null::text[], ',') is null, array_to_string('{}'::text[], ',') = ''",
        "select array_to_string(string_to_array('a,b,c', ','), '-'), array_to_string(array['a b', 'c,d'], '|'), array_to_string(array['a', 'b'], '')",
        "select array_to_string(array['a', null], ',', null), array_to_string(array[null, null]::text[], ',', 'x')",
        // privileges: everything is allowed, but what's asked about has to exist and make sense
        "create table t (id int primary key, v text)",
        "create sequence sq",
        "select has_table_privilege('t', 'select'), has_table_privilege('t', 'SELECT, insert'), has_table_privilege('t', 'select with grant option')",
        "select has_table_privilege(current_user, 't', 'update'), has_table_privilege('t', 'delete, truncate, references, trigger')",
        // pg_has_role (psql 17's \l+ asks it): a database user has every role's privileges here
        "select pg_has_role('pg_read_all_stats', 'member'), pg_has_role(current_user, 'usage')",
        "select pg_has_role(current_user, 'pg_read_all_stats', 'MEMBER'), pg_has_role(current_user, current_user, 'usage')",
        "select pg_has_role('nope_role', 'usage')",
        "select pg_has_role(current_user, 'frob')",
        "select has_table_privilege('nope', 'select')",
        "select has_table_privilege('t', 'frob')",
        "select has_table_privilege('t', 'select, frob')",
        "select has_table_privilege('nouser', 't', 'select')",
        "select has_table_privilege('t', null) is null, has_table_privilege(null, 'select') is null",
        "select has_schema_privilege('public', 'usage'), has_schema_privilege('public', 'create')",
        "select has_schema_privilege('nope', 'usage')",
        "select has_schema_privilege('public', 'select')",
        "select has_database_privilege(current_database(), 'connect'), has_database_privilege(current_database(), 'create, temp')",
        "select has_database_privilege('nope', 'connect')",
        "select has_column_privilege('t', 'id', 'select'), has_column_privilege('t', 'update')",
        "select has_any_column_privilege('t', 'select'), has_sequence_privilege('sq', 'usage'), has_sequence_privilege('sq', 'select, update')",
        "select has_function_privilege('now()', 'execute'), has_type_privilege('int4', 'usage')",
        "select has_sequence_privilege('sq', 'insert')",
    ]]);
}

#[test]
fn maintenance_statements() {
    // (they return nothing: what's compared is which succeed, and the class of the error of the rest;
    // a schema outlasts the script's own, so it's dropped first, in case a run died, and last)
    check(&[&[
        "drop schema if exists msch cascade",
        "create table mt (id int primary key, v int, w text)",
        "create index mt_v on mt (v)",
        "create sequence msq",
        "create view mv as select * from mt",
        "create schema msch",
        "vacuum",
        "vacuum mt",
        "vacuum (verbose, analyze) mt",
        "vacuum (analyze false, full) mt",
        "vacuum full freeze verbose analyze mt",
        "vacuum only mt",
        "vacuum mt, mt",
        "vacuum nope",
        "vacuum mt (v)",
        "vacuum analyze mt (v)",
        "vacuum (analyze) mt (v, w)",
        "vacuum analyze mt (nocol)",
        "vacuum (bogus) mt",
        "vacuum mv",
        "vacuum msq",
        "vacuum mt_v",
        "analyze",
        "analyze verbose",
        "analyze mt",
        "analyze mt (v, w)",
        "analyze mt (nocol)",
        "analyze nope",
        "analyze mv",
        "analyze msq",
        "analyze (verbose) mt",
        "analyze (bogus) mt",
        "analyse mt",
        "reindex table mt",
        "reindex index mt_v",
        "reindex index mt_pkey",
        "reindex table nope",
        "reindex index nope",
        "reindex index mt",
        "reindex table mt_v",
        "reindex table mv",
        "reindex schema public",
        "reindex schema msch",
        "reindex schema nope",
        "reindex table concurrently mt",
        "reindex (concurrently) table mt",
        "reindex (bogus) table mt",
        "reindex table",
        "cluster",
        "cluster mt using mt_pkey",
        "cluster mt using mt_v",
        "cluster mt using nope",
        "cluster verbose mt using mt_pkey",
        "cluster (verbose) mt using mt_pkey",
        "cluster nope",
        "cluster mv",
        // a transaction block: only VACUUM and REINDEX CONCURRENTLY refuse it
        "begin",
        "analyze mt",
        "reindex table mt",
        "reindex index mt_v",
        "cluster mt using mt_pkey",
        "rollback",
        "begin",
        "vacuum",
        "rollback",
        "begin",
        "vacuum mt",
        "rollback",
        "begin",
        "reindex table concurrently mt",
        "rollback",
        "begin",
        "reindex (concurrently) index mt_v",
        "rollback",
        "drop schema msch",
    ]]);
}

#[test]
fn discard_and_lock() {
    check(&[&[
        "create table lt (id int primary key, v int)",
        "create sequence lsq",
        "create view lv as select * from lt",
        "discard plans",
        "discard sequences",
        "discard temp",
        "discard temporary",
        "discard bogus",
        "discard",
        "begin",
        "discard plans",
        "discard sequences",
        "commit",
        "begin",
        "discard all",
        "rollback",
        // sequence memory: currval is gone after DISCARD SEQUENCES
        "select nextval('lsq')",
        "select currval('lsq')",
        "discard sequences",
        "select currval('lsq')",
        "select nextval('lsq')",
        "select lastval()",
        // LOCK needs a transaction block, and a relation it can lock
        "lock table lt",
        "lock table lt in access share mode",
        "lock lt",
        "begin",
        "lock table lt",
        "commit",
        "begin",
        "lock table lt in access share mode",
        "lock table lt in row share mode",
        "lock table lt in row exclusive mode",
        "lock table lt in share update exclusive mode",
        "lock table lt in share mode",
        "lock table lt in share row exclusive mode",
        "lock table lt in exclusive mode",
        "lock table lt in access exclusive mode",
        "lock table only lt",
        "lock table lt *",
        "lock table lt, lt in share mode nowait",
        "lock lv in access share mode",
        "commit",
        "begin",
        "lock table nope",
        "rollback",
        "begin",
        "lock table lt in bogus mode",
        "rollback",
        "begin",
        "lock table lsq",
        "rollback",
        // (last, because it puts search_path back, which is how each script keeps to its own schema)
        "discard all",
    ]]);
}

