#[test]
fn array_operators() {
    check(&[&[
        "create table ar (id int primary key, tags text[], nums int[])",
        "insert into ar values (1, '{a,b}', '{1,2}'), (2, '{b,c}', '{2,3}'), (3, '{}', '{}'), (4, null, null), (5, '{a,NULL}', '{1,NULL}'), (6, '{a,b,c}', '{3,2,1}')",
        "select id from ar where tags @> '{a}' order by id",
        "select id from ar where tags @> array['a', 'b'] order by id",
        "select id from ar where tags <@ '{a,b,c}' order by id",
        "select id from ar where tags && '{a,c}' order by id",
        "select id from ar where nums @> '{2}' order by id",
        "select id from ar where nums <@ '{1,2,3}' order by id",
        "select id from ar where nums && '{3,9}' order by id",
        "select id from ar where '{a}' <@ tags order by id",
        "select id, tags @> '{}', tags <@ '{}', tags && '{}' from ar order by id",
        "select id, tags @> '{a}', tags @> tags, tags && tags from ar order by id",
        "select array[1, 2] @> array[1], array[1, 2] <@ array[1], array[1, 2] && array[2, 3], array[1, 2] && array[3]",
        "select array[1, 2, 3] @> array[3, 1], array[3, 1] <@ array[1, 2, 3], array[1, 1] @> array[1], array[1] @> array[1, 1]",
        "select array[1, null] @> array[null::int], array[1, null] && array[null::int], array[1, null] <@ array[1, null]",
        "select '{1,2}'::int[] && '{2}'::int[], '{1,2}'::int[] @> '{}'::int[], '{}'::int[] && '{1}'::int[]",
        "select null::int[] @> array[1], array[1] && null::int[], array[1] <@ null::int[]",
        "select array['a', 'b'] @> array['a'], array['a b', 'c'] && array['c'], array['x,y'] @> array['x,y']",
        "select id from ar where tags @> array['a'] and nums @> array[1] order by id",
        "select id from ar where not tags && '{c}' order by id",
        "select id from ar where tags && array['b'] or nums @> array[3] order by id",
        // ARRAY(subquery)
        "select array(select id from ar order by id desc)",
        "select array(select id from ar order by id)",
        "select array(select id from ar where id > 99)",
        "select array(select id from ar where id > 99) = '{}'",
        "select array(values (1), (2), (3))",
        "select array(select id from ar order by id) @> array[1, 2], cardinality(array(select id from ar))",
        "select array_length(array(select id from ar where id < 4), 1), array(select tags[1] from ar where id < 3 order by id)",
        "select id, array(select a.id from ar a where a.id < ar.id order by a.id) from ar where id < 4 order by id",
        "select id from ar where id = any(array(select id from ar where id > 4)) order by id",
        "select id from ar where id in (select unnest(array(select id from ar where id < 3))) order by id",
        "select array(select id from ar order by id limit 2)",
        "select array(select 1 where false), array(select 'a' union all select 'b')",
        "select array(select id, tags from ar)",
        "select array(select) ",
    ]]);
}

