#[test]
fn serial_sequences_by_name() {
    check(&[&[
        "create table ss (id serial primary key, n int)",
        "create table sb (id bigserial primary key)",
        "create table si (id bigint generated by default as identity primary key, v text)",
        "create table \"Mixed\" (id serial primary key)",
        "create table \"Odd Name\" (\"Col\" serial primary key)",
        "create sequence own_seq",
        "create table so (id int primary key default nextval('own_seq'), v int)",
        "alter sequence own_seq owned by so.id",
        // the name is Postgres's (the schema differs between the two servers, so it's read in parts)
        "select split_part(pg_get_serial_sequence('ss', 'id'), '.', 2), split_part(pg_get_serial_sequence('sb', 'id'), '.', 2), split_part(pg_get_serial_sequence('si', 'id'), '.', 2)",
        "select split_part(pg_get_serial_sequence('\"Mixed\"', 'id'), '.', 2), split_part(pg_get_serial_sequence('\"Odd Name\"', 'Col'), '.', 2)",
        "select split_part(pg_get_serial_sequence('so', 'id'), '.', 2)",
        "select pg_get_serial_sequence('ss', 'n')",
        "select pg_get_serial_sequence('ss', null), pg_get_serial_sequence(null, 'id')",
        "select pg_get_serial_sequence('Mixed', 'id')",
        "select pg_get_serial_sequence('nope', 'id')",
        "select pg_get_serial_sequence('ss', 'nope')",
        "select pg_get_serial_sequence('ss', 'ID')",
        // what Django and Rails do after loading rows with their own ids
        "insert into ss (id, n) values (1, 1), (2, 2), (3, 3)",
        "select setval(pg_get_serial_sequence('ss', 'id'), coalesce(max(id), 1), max(id) is not null) from ss",
        "insert into ss (n) values (4) returning id",
        "select setval(pg_get_serial_sequence('ss', 'id'), 100)",
        "insert into ss (n) values (5) returning id",
        "select nextval(pg_get_serial_sequence('ss', 'id')), currval(pg_get_serial_sequence('ss', 'id'))",
        "select setval(pg_get_serial_sequence('ss', 'id'), 1, false)",
        "select nextval(pg_get_serial_sequence('ss', 'id'))",
        "select nextval('ss_id_seq'), currval('ss_id_seq'), lastval()",
        "select setval('ss_id_seq', 500, true)",
        "insert into ss (n) values (6) returning id",
        "insert into si (v) values ('a')",
        "select setval(pg_get_serial_sequence('si', 'id'), 10)",
        "insert into si (v) values ('b') returning id",
        "select setval(pg_get_serial_sequence('sb', 'id'), coalesce(max(id), 1), max(id) is not null) from sb",
        "insert into sb default values returning id",
        "insert into so (v) values (1) returning id",
        "select setval(pg_get_serial_sequence('so', 'id'), 50)",
        "insert into so (v) values (2) returning id",
        "select nextval('own_seq')",
        "truncate ss restart identity",
        "insert into ss (n) values (7) returning id",
        "select nextval('nope_id_seq')",
        "select nextval('ss_id_seqq')",
        "select setval(pg_get_serial_sequence('ss', 'id'), 0)",
    ]]);
}

