#[test]
fn alter_table_forms_migrations_write() {
    check(&[&[
        "drop schema if exists at_s1 cascade",
        "drop schema if exists at_s2 cascade",
        "create table at1 (id int primary key, name varchar(50), n int, c text)",
        "insert into at1 values (1, 'a', 1, 'x'), (2, 'b', 2, 'y')",
        // ONLY, and the table's own descendants (there are none)
        "alter table only at1 add column extra int",
        "alter table at1 * add column extra2 int",
        "alter table if exists only at1 add column extra3 int",
        "alter table only nope add column x int",
        // NOT VALID, and VALIDATE
        "alter table at1 add constraint at1_chk check (n > 0) not valid",
        "alter table at1 validate constraint at1_chk",
        "alter table at1 validate constraint nope",
        "alter table at1 add constraint at1_uq unique (name)",
        "alter table at1 validate constraint at1_uq",
        "alter table at1 add constraint at1_fk foreign key (n) references at1 (id) not valid",
        "alter table at1 validate constraint at1_fk",
        "alter table at1 add constraint at1_uq2 unique (nope)",
        "insert into at1 (id, name, n) values (3, 'c', -1)",
        // TYPE ... USING the column, or a cast of it
        "alter table at1 alter column name type varchar(120) using name::varchar(120)",
        "alter table at1 alter column n type bigint using n",
        "alter table at1 alter column n type bigint using n::bigint",
        "alter table at1 alter column c type varchar(20) using c",
        "select id, name, n, c from at1 order by id",
        // things that have no effect here
        "alter table at1 owner to current_user",
        "alter table at1 owner to session_user",
        "alter table at1 set (fillfactor = 70)",
        "alter table at1 set (fillfactor = 70, autovacuum_enabled = false)",
        "alter table at1 reset (fillfactor)",
        "alter table at1 set (toast.autovacuum_enabled = false)",
        "alter table at1 set tablespace pg_default",
        // SET SCHEMA
        "create schema at_s1",
        "create schema at_s2",
        "alter table at1 set schema at_s1",
        "select count(*) from at_s1.at1",
        "select count(*) from at1",
        "alter table at_s1.at1 set schema at_s2",
        "alter table at_s2.at1 set schema nope",
        "alter table at_s2.at1 set schema at_s2",
        "select count(*) from at_s2.at1",
        "select id, name from at_s2.at1 order by id",
        "insert into at_s2.at1 (id, name, n) values (9, 'z', 9)",
        "drop schema at_s1 cascade",
        "drop schema at_s2 cascade",
    ]]);
}

