#[test]
fn deferrable_foreign_keys() {
    check(&[&[
        "create table dfa (id int primary key)",
        "create table dfb1 (id int primary key, a int references dfa(id) initially deferred)",
        "select conname, condeferrable, condeferred, pg_get_constraintdef(oid) from pg_constraint where conrelid = 'dfb1'::regclass and contype = 'f'",
        "create table dfb2 (id int primary key, a int references dfa(id) not deferrable initially deferred)",
        "create table dfb3 (id int primary key, a int references dfa(id) initially immediate)",
        "select conname, condeferrable, condeferred, pg_get_constraintdef(oid) from pg_constraint where conrelid = 'dfb3'::regclass and contype = 'f'",
        "create table dfb4 (id int primary key, a int references dfa(id) on delete cascade deferrable initially deferred)",
        "select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'dfb4'::regclass and contype = 'f'",
        "create table dfb5 (id int primary key, a int, constraint dfb5_fk foreign key (a) references dfa(id) deferrable)",
        "select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'dfb5'::regclass and contype = 'f'",
        "create table dfb6 (id int primary key, a int references dfa(id) deferrable initially deferred not null)",
        "select is_deferrable, initially_deferred from information_schema.table_constraints where table_name = 'dfb5' and constraint_type = 'FOREIGN KEY'",
        // SET CONSTRAINTS outside a transaction only checks the names
        "set constraints all deferred",
        "set constraints nosuch deferred",
        "set constraints dfb1_a_fkey immediate",
        "set constraints dfb3_a_fkey deferred",
        "set constraints dfb1_pkey deferred",
        // outside a transaction a statement is its own commit: nothing is put off
        "insert into dfb1 values (9, 999)",
        // a violation that stands at COMMIT fails it and rolls the transaction back
        "begin",
        "set constraints dfb1_a_fkey deferred",
        "insert into dfb1 values (1, 99)",
        "commit",
        "select count(*) from dfb1",
        // initially deferred: no SET needed; the parent can come after
        "begin",
        "insert into dfb1 values (2, 100)",
        "insert into dfa values (100)",
        "commit",
        "select * from dfb1 order by id",
        // deferrable but initially immediate: at once, until SET CONSTRAINTS says otherwise
        "begin",
        "insert into dfb5 values (1, 101)",
        "rollback",
        "begin",
        "set constraints all deferred",
        "insert into dfb5 values (1, 101)",
        "set constraints all immediate",
        "rollback",
        "begin",
        "set constraints dfb5_fk deferred",
        "insert into dfb5 values (1, 101)",
        "insert into dfa values (101)",
        "set constraints dfb5_fk immediate",
        "commit",
        "select * from dfb5 order by id",
        // the parent's side: a delete a child still references is put off too
        "begin",
        "set constraints dfb5_fk deferred",
        "delete from dfa where id = 101",
        "commit",
        "select count(*) from dfa",
        "begin",
        "set constraints dfb5_fk deferred",
        "delete from dfa where id = 101",
        "delete from dfb5 where a = 101",
        "commit",
        "select (select count(*) from dfa), (select count(*) from dfb5)",
        // ON DELETE CASCADE deferrable still cascades
        "insert into dfa values (7)",
        "insert into dfb4 values (1, 7)",
        "begin",
        "delete from dfa where id = 7",
        "commit",
        "select count(*) from dfb4",
        // savepoints: what was rolled back to isn't checked, what wasn't is
        "begin",
        "insert into dfb1 values (3, 200)",
        "savepoint s",
        "insert into dfa values (200)",
        "rollback to savepoint s",
        "commit",
        "select count(*) from dfb1",
        "begin",
        "insert into dfb1 values (3, 200)",
        "savepoint s",
        "insert into dfb1 values (4, 201)",
        "rollback to savepoint s",
        "insert into dfa values (200)",
        "commit",
        "select id, a from dfb1 order by id",
        // ALTER CONSTRAINT
        "alter table dfb1 alter constraint dfb1_pkey deferrable",
        "alter table dfb1 alter constraint nosuch deferrable",
        "alter table dfb1 alter constraint dfb1_a_fkey not deferrable",
        "select conname, condeferrable, condeferred from pg_constraint where conrelid = 'dfb1'::regclass and contype = 'f'",
        "alter table dfb1 alter constraint dfb1_a_fkey deferrable initially deferred",
        "select conname, condeferrable, condeferred from pg_constraint where conrelid = 'dfb1'::regclass and contype = 'f'",
        "alter table dfb1 alter constraint dfb1_a_fkey not deferrable initially deferred",
        // adding one checks the rows there are at once, deferrable or not
        "alter table dfb6 add constraint dfb6_fk2 foreign key (a) references dfa(id) deferrable initially deferred",
        "insert into dfa values (300)",
        "insert into dfb6 values (1, 300)",
        "alter table dfb6 add constraint dfb6_fk3 foreign key (a) references dfa(id) deferrable initially deferred",
        "begin",
        "delete from dfb6",
        "insert into dfb6 values (2, 400)",
        "insert into dfa values (400)",
        "commit",
        "select id, a from dfb6 order by id",
    ]]);
}

#[test]
fn array_slices_and_small_operators() {
    check(&[&[
        "select (array[1,2,3])[1:2], (array[1,2,3])[2:], (array[1,2,3])[:2], (array[1,2,3])[:]",
        "select (array[1,2,3])[0:5], (array[1,2,3])[3:2], (array[1,2,3])[5:9], (array[1,2,3])[-2:1]",
        "select (array['a','b','c'])[2:3], (array[1,null,3])[1:2], (array[1,2,3])[null:2], (array[1,2,3])[1:null]",
        "select ('{4,5,6}'::int[])[2:3]",
        "select array_length((array[1,2,3,4])[2:3], 1), cardinality((array[1,2,3])[3:1])",
        "create table sl (id int primary key, tags text[])",
        "insert into sl values (1, '{a,b,c,d}'), (2, '{x}'), (3, null)",
        "select id, tags[1:2], tags[2:] from sl order by id",
        "select @ -1, @(-5.5), @ 3, @ -2 + 1",
        "select |/ 4, |/ 2.25, ||/ 8, |/ -1",
        "select 2 + @ -3 * 2, 10 - @ -3",
        "select 'x' ||/* comment */ 'y'",
        "select int4('1'), int8('2'), float8('1.5'), text(5), bool('t'), date('2020-01-02'), int2('7'), float4('1.5')",
        "select int4('x')",
        "select int4(2.7), int4(-2.5), text(true)",
        "select 'a' collate \"C\", 'a' collate \"default\", 'b' collate pg_catalog.\"default\" < 'c'",
        "select name from (values ('b'), ('A'), ('a')) v(name) order by name collate \"C\"",
        "select make_interval(days=>1), make_interval(1,2,3,4,5,6,7.5), make_interval(secs => 3.5, mins => 2)",
        "select make_interval(), make_interval(hours := 25), make_interval(weeks => 1, days => 2)",
        "select make_interval(weeks := 2, 3)",
        "select make_interval(days => 1, days => 2)",
        "select make_interval(bogus => 1)",
        "select make_interval(days => null), make_interval(years => 1) + make_interval(months => 2)",
        "select abs(x => 1)",
        "create function sub2(a int, b int) returns int language sql as 'select a - b'",
        "select sub2(5, 3), sub2(a => 5, b => 3), sub2(b => 3, a => 5), sub2(5, b => 3)",
        "select sub2(b => 3)",
        "select sub2(a => 1, c => 2)",
        "select sub2(a => 1, 2)",
        "select sub2(a => 1, a => 2)",
        "select sub2(a := 9, b := 4)",
        "create function pick(a int, b text) returns text language plpgsql as 'begin return b || a::text; end'",
        "select pick(b => 'x', a => 7)",
        "select pick(a => 7, b => 'y')",
    ]]);
}

#[test]
fn ordered_set_aggregates() {
    check(&[&[
        "create table pc (g text, v int, w float, n numeric)",
        "insert into pc values ('a',1,1.5,10),('a',2,2.5,20),('a',3,null,30),('a',4,4.5,40),('b',10,1,1),('b',10,2,2),('b',20,3,3),('c',null,null,null)",
        "select g, percentile_cont(0.5) within group (order by v) from pc group by g order by g",
        "select g, percentile_cont(0.25) within group (order by w desc) from pc group by g order by g",
        "select g, percentile_disc(0.5) within group (order by v), percentile_disc(0) within group (order by v), percentile_disc(1) within group (order by v) from pc group by g order by g",
        "select percentile_cont(0.9) within group (order by n), percentile_disc(0.9) within group (order by n) from pc",
        "select mode() within group (order by v) from pc",
        "select g, mode() within group (order by v) from pc group by g order by g",
        "select mode() within group (order by g), mode() within group (order by w) from pc",
        "select percentile_cont(1.5) within group (order by v) from pc",
        "select percentile_disc(-0.1) within group (order by v) from pc",
        "select percentile_cont(null) within group (order by v) from pc",
        "select percentile_cont(array[0.25,0.75]) within group (order by v) from pc",
        "select percentile_disc(array[0.25,0.75]) within group (order by v) from pc",
        "select percentile_cont(0.5) within group (order by v) filter (where g = 'b') from pc",
        "select percentile_cont(0.5) from pc",
        "select mode() from pc",
        "select percentile_cont(0.5) within group (order by v) over () from pc",
        "select percentile_cont(0.5) within group (order by v) from pc where g = 'zz'",
        "select percentile_cont(0.5) within group (order by v desc nulls last) from pc",
        "select g, percentile_cont(0.5) within group (order by v) + 1 as m from pc group by g having percentile_cont(0.5) within group (order by v) > 2 order by g",
        "select round(percentile_cont(0.5) within group (order by w)::numeric, 3) from pc",
    ]]);
}

#[test]
fn grouping_sets_rollup_and_cube() {
    check(&[&[
        "create table gs (id int primary key, region text, city text, prod text, qty int, price numeric)",
        "insert into gs values (1,'east','ny','a',1,10),(2,'east','ny','b',2,20),(3,'east','bos','a',3,30),(4,'west','sf','a',4,40),(5,'west','la','b',5,50),(6,'west','la','b',6,60),(7,'north','x','a',7,70)",
        "select region, sum(qty) from gs group by rollup(region) order by region nulls last",
        "select region, city, sum(qty), grouping(region, city) from gs group by rollup(region, city) order by 1 nulls last, 2 nulls last",
        "select region, prod, sum(qty) from gs group by cube(region, prod) order by 1 nulls last, 2 nulls last",
        "select region, prod, count(*) from gs group by grouping sets ((region), (prod), ()) order by 1 nulls last, 2 nulls last",
        "select region, prod, sum(qty) from gs group by region, rollup(prod) order by 1 nulls last, 2 nulls last",
        "select region, sum(qty) from gs group by grouping sets (region, ()) having sum(qty) > 10 order by 1 nulls last",
        "select region, city, grouping(region) g1, grouping(city) g2, grouping(region, city) g3 from gs group by grouping sets ((region, city), (region), ()) order by 1 nulls last, 2 nulls last",
        "select coalesce(region, 'ALL') r, sum(qty) from gs group by rollup(region) order by r",
        "select region, sum(qty) from gs group by rollup(region) order by sum(qty)",
        "select region, sum(qty) s from gs group by rollup(region) order by s desc limit 2",
        "select sum(qty), grouping(region) from gs group by rollup(region) order by 2, 1",
        "select region, sum(qty), grouping(city) from gs group by rollup(region)",
        "select grouping(region) from gs",
        "select region, sum(qty) from gs where qty > 100 group by rollup(region)",
        "select region, sum(qty) from gs where qty > 100 group by grouping sets ((region), ())",
        "select region, city, sum(qty) from gs group by rollup((region, city)) order by 1 nulls last, 2 nulls last",
        "select region || '!' as r, sum(qty) from gs group by rollup(region || '!') order by 1 nulls last",
        "select region, sum(qty) from gs group by rollup(region) union all select 'z', 1 order by 1 nulls last",
        "select region, sum(qty) from gs group by distinct rollup(region), rollup(region) order by 1 nulls last",
        "select region, sum(qty) from gs group by all rollup(region), rollup(region) order by 1 nulls last",
        "select region, city, sum(qty) from gs group by rollup(region, city) order by gs.region nulls last, gs.city nulls last",
        "select region, count(*) filter (where prod = 'a'), sum(qty) from gs group by cube(region) order by 1 nulls last",
        "select region, avg(price) from gs group by rollup(region) order by 1 nulls last",
        "select region, sum(qty) from gs group by region, () order by 1",
        "select region, prod, city, sum(qty) from gs group by rollup(region), cube(prod, city) order by 1 nulls last, 2 nulls last, 3 nulls last",
        "select count(*) from (select region from gs group by rollup(region)) x",
        "with t as (select region, sum(qty) q from gs group by rollup(region)) select * from t where q > 10 order by 1 nulls last",
        "select 1 from gs group by ()",
        "select count(*) from gs group by grouping sets ((), ())",
        "select region from gs group by grouping sets ((region), ()) order by 1 nulls last",
        "select region, sum(qty), grouping(region) from gs group by region order by 1",
        "select region, city from gs group by rollup(region)",
    ]]);
}

#[test]
fn window_frames_by_groups_and_with_exclusions() {
    check(&[&[
        "create table wf (id int primary key, g int, v int)",
        "insert into wf values (1,1,10),(2,1,10),(3,2,20),(4,2,30),(5,3,30),(6,3,40),(7,4,null),(8,5,50)",
        "select id, sum(v) over (order by g groups between 1 preceding and current row) from wf order by id",
        "select id, sum(v) over (order by g groups between current row and 1 following) from wf order by id",
        "select id, sum(v) over (order by g groups between 2 preceding and 1 preceding) from wf order by id",
        "select id, sum(v) over (order by g groups between 1 following and 2 following) from wf order by id",
        "select id, count(*) over (order by g groups unbounded preceding) from wf order by id",
        "select id, sum(v) over (order by v groups between 1 preceding and 1 following) from wf order by id",
        "select id, sum(v) over (order by g desc groups between 1 preceding and current row) from wf order by id",
        "select id, sum(v) over (order by g rows between 1 preceding and 1 following exclude current row) from wf order by id",
        "select id, sum(v) over (order by g rows between unbounded preceding and unbounded following exclude group) from wf order by id",
        "select id, sum(v) over (order by g rows between unbounded preceding and unbounded following exclude ties) from wf order by id",
        "select id, sum(v) over (order by g range between 1 preceding and 1 following exclude no others) from wf order by id",
        "select id, first_value(v) over (order by g rows between unbounded preceding and unbounded following exclude current row) from wf order by id",
        "select id, last_value(v) over (order by g rows between unbounded preceding and unbounded following exclude group) from wf order by id",
        "select id, nth_value(v, 2) over (order by id rows between unbounded preceding and unbounded following exclude ties) from wf order by id",
        "select id, count(*) over (order by g range between unbounded preceding and current row exclude ties) from wf order by id",
        "select id, avg(v) over (partition by g order by id groups between current row and current row exclude current row) from wf order by id",
        "select id, sum(v) over (groups between 1 preceding and current row) from wf",
        "select id, sum(v) over (order by g groups between -1 preceding and current row) from wf",
        "select id, sum(v) over (order by g groups between 1 preceding and current row exclude current row) from wf order by id",
        "select id, sum(v) over w from wf window w as (order by g groups 1 preceding) order by id",
        "select id, min(v) over (order by g rows between 1 preceding and 1 following exclude current row), max(v) over (order by g rows between 1 preceding and 1 following exclude current row) from wf order by id",
    ]]);
}

#[test]
fn do_blocks_and_procedures() {
    check(&[&[
        "create table dt (id int primary key, v text)",
        "do $$ begin insert into dt values (1, 'a'); end $$",
        "select * from dt",
        "do language plpgsql $$ begin insert into dt values (2, 'b'); end $$",
        "do $$ begin insert into dt values (2, 'dup'); end $$ language plpgsql",
        "select count(*) from dt",
        "do $$ declare n int; begin select count(*) into n from dt; if n <> 2 then raise exception 'wrong %', n; end if; end $$",
        "do $$ begin raise exception 'boom'; end $$",
        "do $$ begin null; end $$ language sql",
        "do 'begin null; end'",
        "do",
        "do $$ begin insert into dt values (9, 'x'); raise exception 'undo'; end $$",
        "select count(*) from dt where id = 9",
        "create procedure addrow(i int, s text) language plpgsql as $$ begin insert into dt values (i, s); end $$",
        "call addrow(3, 'c')",
        "call addrow(s => 'd', i => 4)",
        "select count(*) from dt",
        "call addrow(3, 'again')",
        "call nosuch(1)",
        "call addrow(1)",
        "create or replace procedure addrow(i int, s text) language plpgsql as $$ begin insert into dt values (i + 100, s); end $$",
        "call addrow(5, 'e')",
        "select max(id) from dt",
        "create procedure p_sql() language sql as 'delete from dt where id > 100'",
        "call p_sql()",
        "select count(*) from dt",
        "create procedure p_sql() language sql as 'select 1'",
        "drop procedure p_sql",
        "drop procedure p_sql",
        "drop procedure if exists p_sql",
        "drop procedure addrow(int, text)",
        "call addrow(1, 'x')",
        "create procedure pbad() returns int language sql as 'select 1'",
        "create procedure prc(i int) language sql as 'select 1'",
        "select prc(1)",
        "create function fvoid() returns void language sql as 'select 1'",
        "call fvoid()",
        "select fvoid()",
        "begin",
        "do $$ begin insert into dt values (50, 'in a transaction'); end $$",
        "rollback",
        "select count(*) from dt where id = 50",
    ]]);
}

