#[test]
fn functions_types_triggers_and_dependencies_in_the_catalog() {
    let ns = "(select oid from pg_namespace where nspname = current_schema())";
    let strip = |x: &str| format!("replace({x}, current_schema() || '.', 'S.')");
    let scripts: Vec<String> = vec![
        "create type mood as enum ('sad', 'ok', 'happy')".into(),
        "create function f1(a int, b text) returns text language sql immutable strict as 'select b'".into(),
        "create function f2(n int) returns table(x int, y text) language sql as $$ select n, 'y' $$".into(),
        "create function f3(n int) returns setof int language sql stable as 'select n'".into(),
        "create function tg() returns trigger language plpgsql as $$ begin return new; end $$".into(),
        "create function f0() returns void language plpgsql as $$ begin null; end $$".into(),
        "create procedure pr(n int) language sql as 'select 1'".into(),
        "create table tt (id serial primary key, m mood default 'ok', v varchar(20), c char(3), n numeric(10,2), x int, tags text[] default '{}', doc jsonb default '{}')".into(),
        "create trigger tt_trg before insert or update of x on tt for each row execute function tg()".into(),
        "create trigger tt_after after delete on tt for each statement execute function tg()".into(),
        "create view vv as select id, x from tt where x > 1".into(),
        "create table child (id int primary key, tt_id int references tt(id))".into(),
        format!("select proname, prokind, pronargs, prorettype::regtype::text, proretset, provolatile, proisstrict, proargnames::text, prosrc from pg_proc where pronamespace = {ns} order by proname"),
        format!("select proname, pg_get_function_arguments(oid), pg_get_function_identity_arguments(oid), pg_get_function_result(oid) from pg_proc where pronamespace = {ns} order by proname"),
        format!("select proname, {} from pg_proc where pronamespace = {ns} order by proname", strip("pg_get_functiondef(oid)")),
        format!("select proname, proargtypes::text, proallargtypes::text, proargmodes::text from pg_proc where pronamespace = {ns} order by proname"),
        "select enumlabel, enumsortorder from pg_enum where enumtypid = 'mood'::regtype order by enumsortorder".into(),
        format!("select typname, typtype, typcategory, typlen, typdelim, typalign, typstorage, typbyval from pg_type where typname in ('mood', '_mood') and typnamespace = {ns} order by 1"),
        "select 'mood'::regtype::text, 'mood[]'::regtype::text, format_type('mood'::regtype, null)".into(),
        "select a.attname, format_type(a.atttypid, a.atttypmod), a.atttypmod, a.attnotnull, a.atthasdef, a.attlen, a.attstorage, a.attalign, a.attcollation, a.attndims from pg_attribute a where attrelid = 'tt'::regclass and attnum > 0 order by attnum".into(),
        "select tgname, tgfoid::regproc::text, tgtype, tgenabled, tgisinternal, tgnargs from pg_trigger where tgrelid = 'tt'::regclass and not tgisinternal order by tgname".into(),
        format!("select tgname, {} from pg_trigger where tgrelid = 'tt'::regclass and not tgisinternal order by tgname", strip("pg_get_triggerdef(oid)")),
        format!("select relname, relkind, relhastriggers, relhasrules, relnatts, relhasindex, relispopulated from pg_class where relname in ('tt', 'vv', 'child', 'tt_id_seq', 'tt_pkey') and relnamespace = {ns} order by 1"),
        "select rulename, ev_type, is_instead, ev_enabled from pg_rewrite where ev_class = 'vv'::regclass".into(),
        "select pg_get_viewdef('vv'::regclass) ilike '% from %tt%'".into(),
        "select classid::regclass::text, objsubid, refclassid::regclass::text, refobjsubid, deptype from pg_depend where classid = 'pg_attrdef'::regclass and objid in (select oid from pg_attrdef where adrelid = 'tt'::regclass) and refclassid <> 'pg_class'::regclass order by 1, 2, 3, 4, 5".into(),
        "select classid::regclass::text, refobjsubid, deptype from pg_depend where classid = 'pg_class'::regclass and objid = 'tt_id_seq'::regclass and refclassid = 'pg_class'::regclass".into(),
        "select distinct classid::regclass::text, deptype, refobjid::regclass::text from pg_depend where classid = 'pg_rewrite'::regclass and objid = (select oid from pg_rewrite where ev_class = 'vv'::regclass) order by 3, 2".into(),
        "select classid::regclass::text, deptype, refclassid::regclass::text from pg_depend where classid = 'pg_trigger'::regclass and objid in (select oid from pg_trigger where tgrelid = 'tt'::regclass and not tgisinternal) order by 1, 2, 3".into(),
        "select pg_get_function_result(0), pg_get_functiondef(0)".into(),
    ];
    let refs: Vec<&str> = scripts.iter().map(String::as_str).collect();
    check(&[&refs]);
}

#[test]
fn set_returning_functions_joined_to_derived_tables() {
    check(&[&[
        "select * from unnest(array[1,2,3]) as s(t), (select 1 as b union all select 3) y where s.t = y.b order by 1",
        "select * from unnest(array[1,2]) as s(t), (select 1 as b) y order by 1",
        "select * from unnest(array[1,2,3]) as s(t) join (select 1 as b union all select 3) y on s.t = y.b order by 1",
        "select pg_typeof(t) from unnest(array[1,2]) s(t) limit 1",
        "select pg_typeof(t) from unnest('{1,2}'::bigint[]) s(t) limit 1",
        "select * from generate_series(1,3) g(n), (select 2 as b) y where g.n = y.b",
        "select * from unnest('{16386,16390}'::oid[]) as s(t) join (select 16390::oid as o) c on s.t = c.o",
        "create table wt (id int primary key)",
        "insert into wt values (1), (2)",
        "with recursive w as (select oid from pg_class where relname = 'wt' union select oid from w) select count(*) from w",
        "with recursive w(n) as (select id from wt union all select n + 10 from w where n < 5) select n from w order by n",
        "select c.relname from unnest(array['wt']) as s(t) join pg_class c on c.relname = s.t",
    ]]);
}

#[test]
fn a_sequence_in_a_schema_as_a_column_default_and_check_names() {
    check(&[&[
        "drop schema if exists pgdiff_qs cascade",
        "create schema pgdiff_qs",
        "create sequence pgdiff_qs.s start 1000 increment 5",
        "create table pgdiff_qs.t (id int, n bigint default nextval('pgdiff_qs.s'))",
        "insert into pgdiff_qs.t (id) values (1), (2), (3)",
        "select id, n from pgdiff_qs.t order by id",
        "select last_value, is_called from pgdiff_qs.s",
        "select nextval('pgdiff_qs.s')",
        "create table pgdiff_qs.u (id serial primary key, n int)",
        "insert into pgdiff_qs.u (n) values (1), (2)",
        "select last_value, is_called from pgdiff_qs.u_id_seq",
        "select pg_get_serial_sequence('pgdiff_qs.u', 'id')",
        "select setval(pg_get_serial_sequence('pgdiff_qs.u', 'id'), 50)",
        "insert into pgdiff_qs.u (n) values (3)",
        "select id from pgdiff_qs.u order by id",
        "drop schema pgdiff_qs cascade",
        "create table ck (a int, b int, check (a > 0), check (a < b), check (b > 1 and b < 100), constraint named check (a <> 5))",
        "select conname from pg_constraint where conrelid = 'ck'::regclass order by 1",
        "create table ck2 (a int check (a > 0), b int check (b > a))",
        "select conname from pg_constraint where conrelid = 'ck2'::regclass order by 1",
        "create table dflt (j jsonb default '{}', t text[] default '{a,b}', e boolean default true, n numeric(6,2) default 1.5, d date default '2020-01-02', s text default 'it''s')",
        "select column_name, column_default from information_schema.columns where table_name = 'dflt' order by ordinal_position",
    ]]);
}

#[test]
fn update_set_default() {
    check(&[&[
        "create table ud (id int primary key, a int default 5, b text default 'x', s serial, u int, j jsonb default '{}', e int default 1 + 2)",
        "insert into ud (id, a, b, u) values (1, 10, 'y', 7), (2, 20, 'z', 8)",
        "update ud set a = default where id = 1",
        "select id, a, b, s from ud order by id",
        "update ud set a = 99, b = default where id = 2 returning id, a, b",
        "update ud set u = default, j = default, e = default",
        "select id, u, j, e from ud order by id",
        "update ud set s = default where id = 1",
        "update ud set s = default where id = 2",
        "select id, s from ud order by id",
        "update ud set id = default where id = 1",
        "update ud set nosuch = default",
        "update ud set a = default where id = 999",
        "update ud set a = default, a = 1",
        "create table ud2 (id int primary key, n int generated by default as identity, m int generated always as identity, k text)",
        "insert into ud2 (id, k) values (1, 'a'), (2, 'b')",
        "update ud2 set n = default where id = 1",
        "update ud2 set m = default where id = 2",
        "update ud2 set m = 5 where id = 2",
        "select id, n, m from ud2 order by id",
        "update ud2 set k = default where id = 1",
        "select id, k from ud2 order by id",
        "insert into ud (id) values (3) on conflict (id) do update set a = default",
        "insert into ud (id, a) values (3, 8) on conflict (id) do update set a = default, b = 'z'",
        "select id, a, b from ud where id = 3",
    ]]);
}

#[test]
fn identity_options() {
    check(&[&[
        "create table io (id int generated always as identity (start with 10 increment by 5), v text)",
        "insert into io (v) values ('a'), ('b'), ('c')",
        "select id, v from io order by id",
        "create table io2 (id bigint generated by default as identity (start with 100 increment by -2 minvalue 90 maxvalue 200), v text)",
        "insert into io2 (v) values ('a'), ('b')",
        "insert into io2 (id, v) values (5, 'explicit')",
        "select id from io2 order by id desc",
        "create table io4 (id int generated always as identity (start with 1 increment by 1 maxvalue 2 cycle), v text)",
        "insert into io4 (v) values ('a'), ('b'), ('c'), ('d')",
        "select id from io4 order by v",
        "create table io5 (id int generated always as identity (start with 1 maxvalue 2), v text)",
        "insert into io5 (v) values ('a'), ('b')",
        "insert into io5 (v) values ('c')",
        "select id from io5 order by id",
        "select column_name, identity_start, identity_increment, identity_maximum, identity_minimum, identity_cycle from information_schema.columns where table_name in ('io', 'io2', 'io4') and is_identity = 'YES' order by table_name",
        "select seqstart, seqincrement, seqmax, seqmin, seqcycle from pg_sequence where seqrelid = 'io2_id_seq'::regclass",
        "select last_value, is_called from io_id_seq",
        "select pg_get_serial_sequence('io', 'id') like '%io_id_seq'",
        "create table io6 (a int)",
        "alter table io6 add column id int generated always as identity (start with 7 increment by 3)",
        "insert into io6 (a) values (1), (2)",
        "select a, id from io6 order by a",
        "create table io6b (a int not null)",
        "alter table io6b alter column a add generated always as identity (start with 50)",
        "insert into io6b default values",
        "select a from io6b",
        "create table io7 (id int generated always as identity (increment by 0))",
        "create table io8 (id int generated always as identity (minvalue 5 start with 1))",
        "create table io10 (id int generated always as identity (cache 5 no cycle no minvalue no maxvalue))",
        "drop table io",
        "select count(*) from pg_class where relname = 'io_id_seq'",
        "alter table io2 alter column id drop identity",
        "select count(*) from pg_class where relname = 'io2_id_seq'",
        "insert into io2 (v) values ('after')",
        "truncate io4 restart identity",
        "insert into io4 (v) values ('x')",
        "select id from io4",
        "alter table io6 drop column id",
        "select count(*) from pg_class where relname = 'io6_id_seq'",
        "create sequence owned_s owned by io6.a",
        "alter table io6 drop column a",
        "select count(*) from pg_class where relname = 'owned_s'",
    ]]);
}

#[test]
fn function_parameter_defaults() {
    let ns = "(select oid from pg_namespace where nspname = current_schema())";
    let scripts: Vec<String> = vec![
        "create function fd(a int, b text default 'x', c int = 3) returns text language sql as $$ select a::text || b || c::text $$".into(),
        "select fd(1)".into(),
        "select fd(1, 'y')".into(),
        "select fd(1, 'y', 9)".into(),
        "select fd()".into(),
        "select fd(1, 2, 3, 4)".into(),
        "select fd(1, c => 7)".into(),
        "select fd(a => 2, c => 8)".into(),
        "select fd(b => 'z', a => 1)".into(),
        "select fd(b => 'z')".into(),
        "create function fbad(a int default 1, b int) returns int language sql as 'select 1'".into(),
        "create function fp(n int default 5) returns table(x int) language sql as 'select generate_series(1, n)'".into(),
        "select * from fp()".into(),
        "select * from fp(2)".into(),
        "create procedure pd(a int, b int default 10) language sql as 'select 1'".into(),
        "call pd(1)".into(),
        "call pd(1, 2)".into(),
        "call pd()".into(),
        "create function pl(a int, b int default 1) returns int language plpgsql as $$ begin return a + b; end $$".into(),
        "select pl(4), pl(4, 10)".into(),
        "create function ov(a int) returns text language sql as $$ select 'one' $$".into(),
        "create function ov(a int, b int default 2) returns text language sql as $$ select 'two' $$".into(),
        "select ov(1)".into(),
        "select ov(1, 5)".into(),
        "create function dn(a int default now()) returns int language sql as 'select 1'".into(),
        "create function dt(a timestamptz default now()) returns boolean language sql as 'select true'".into(),
        "select dt()".into(),
        format!("select proname, pronargs, pronargdefaults from pg_proc where pronamespace = {ns} and proname in ('fd', 'pd', 'ov', 'pl') order by proname, pronargs"),
        format!("select pg_get_function_identity_arguments(oid) from pg_proc where pronamespace = {ns} and proname = 'fd'"),
        format!("select replace(pg_get_function_arguments(oid), '::text', '') from pg_proc where pronamespace = {ns} and proname = 'fd'"),
        "create or replace function fd(a int, b text default 'w', c int default 3) returns text language sql as $$ select b $$".into(),
        "select fd(1)".into(),
        "drop function fd(int, text, int)".into(),
        "select fd(1)".into(),
    ];
    let refs: Vec<&str> = scripts.iter().map(String::as_str).collect();
    check(&[&refs]);
}

#[test]
fn create_table_like() {
    check(&[&[
        "create table src (id serial primary key, a int not null default 5, b text default 'x', c varchar(10), n numeric(8,2), u int unique, d int check (d > 0), tags text[] default '{}')",
        "create table l1 (like src)",
        "insert into l1 (id) values (1)",
        "insert into l1 (id, a) values (1, 1), (1, 2)",
        "select id, a, b from l1 order by a",
        "create table l2 (like src including defaults)",
        "insert into l2 (id) values (1), (2)",
        "select id, a, b, tags from l2 order by id",
        "create table l3 (like src including all)",
        "insert into l3 (id, a) values (1, 1)",
        "insert into l3 (id, a) values (1, 2)",
        "insert into l3 (id, a, d) values (2, 2, -1)",
        "insert into l3 (id, u) values (3, 7), (4, 7)",
        "select conname, contype from pg_constraint where conrelid = 'l3'::regclass order by 1",
        "select column_name, data_type, character_maximum_length, numeric_precision, numeric_scale, is_nullable from information_schema.columns where table_name = 'l3' order by ordinal_position",
        "create table l4 (extra int, like src including defaults, more text)",
        "select column_name from information_schema.columns where table_name = 'l4' order by ordinal_position",
        "create table l5 (like src, id text)",
        "create table l6 (like nosuch)",
        "create index src_b_idx on src (b)",
        "create table l7 (like src including indexes)",
        "select count(*) from pg_indexes where tablename = 'l7'",
        "create table l7b (like src including constraints)",
        "insert into l7b (id, a, d) values (1, 1, -5)",
        "create view sv as select id, a from src",
        "create table l8 (like sv)",
        "select column_name, is_nullable from information_schema.columns where table_name = 'l8' order by ordinal_position",
        "create table idsrc (id int generated always as identity, v text)",
        "create table l9 (like idsrc)",
        "insert into l9 (v) values ('x')",
        "create table l10 (like idsrc including identity)",
        "insert into l10 (v) values ('a'), ('b')",
        "select id, v from l10 order by id",
        "insert into l10 (id, v) values (9, 'c')",
        "create table l11 (like src excluding defaults including comments including storage)",
        "create table l12 (like src including nothing)",
        "create table l13 (like src, like idsrc)",
        "create table l14 (like l3 including all, extra int primary key)",
        "create table if not exists l1 (like src)",
    ]]);
}

/// citext: text that is equal, sorts and is unique by its lower case, as the extension's type is. A citext
/// compared with text of a type (a text column, `x::text`) is compared as text.
#[test]
fn citext_compares_by_lower_case() {
    check(&[&[
        "create extension if not exists citext",
        "create table u (id int primary key, email citext unique not null, name text, nick citext)",
        "insert into u values (1, 'Ada@Example.com', 'Ada', 'ACE'), (2, 'bob@x.io', 'bob', null), (3, 'ÉMILE@x.io', 'Émile', 'em')",
        "insert into u values (4, 'ADA@EXAMPLE.COM', 'dup', null)",
        "insert into u values (4, 'ada@example.com', 'dup', null) on conflict (email) do update set name = 'Ada L' returning id, email, name",
        "select id from u where email = 'ada@example.com'",
        "select id from u where email = 'BOB@X.IO' or email = 'émile@x.io' order by id",
        "select id from u where email in ('ADA@example.com', 'nobody') order by id",
        "select id from u where email <> 'bob@x.io' order by id",
        "select id from u where email like 'ada%'",
        "select id from u where email like '%@X.IO' order by id",
        "select id from u where email ilike 'ADA%'",
        "select id from u where email not like 'ada%' order by id",
        "select id, email from u order by email",
        "select min(email), max(email) from u",
        "select id from u where email > 'b' order by id",
        "select 'ABC'::citext = 'abc', 'ABC'::citext = 'abc'::text, 'ABC'::citext = 'abc'::citext, 'a'::citext < 'B'::citext, 'B'::citext < 'a'::citext",
        "select id from u where email = name order by id",
        "select id from u where nick = 'ace'",
        "select id, case email when 'BOB@x.io' then 'b' else 'other' end from u order by id",
        "select id, nullif(nick, 'Ace') is null from u order by id",
        "select a.id, b.id from u a join u b on a.nick = b.email order by 1, 2",
        "select count(*) from u a join u b on a.email = b.email",
        "select length(email), upper(email), email || '!' from u where id = 2",
        "create domain em as citext check (value ~ '^[^@]+@[^@]+$')",
        "create table d (id int primary key, addr em unique)",
        "insert into d values (1, 'A@b.c')",
        "insert into d values (2, 'a@B.C')",
        "insert into d values (3, 'nope')",
        "select id from d where addr = 'a@b.c'",
        "update u set email = 'BOB@X.IO' where id = 2 returning email",
        "update u set email = 'ada@example.com' where id = 2",
        "alter table u add column alias citext",
        "update u set alias = 'One' where id = 1",
        "select id from u where alias = 'one'",
        "create index u_nick on u (nick)",
        "select id from u where nick = 'EM'",
        "select a.attname, format_type(a.atttypid, a.atttypmod) from pg_attribute a where a.attrelid = 'u'::regclass and a.attnum > 0 order by a.attnum",
        "select column_name, data_type, udt_name from information_schema.columns where table_name = 'u' order by ordinal_position",
    ]]);
}

/// hstore: its text read and written as the extension does, its operators and functions, in a table, an index,
/// a default, a check, a generated column, a function, a trigger and a prepared statement.
#[test]
fn hstore_type() {
    check(&[&[
        "create extension if not exists hstore",
        "select 'a=>1, b=>2'::hstore, 'b=>2, a=>1, aa=>x, a=>9'::hstore, ''::hstore, 'a=>1,'::hstore",
        r#"select '"a b"=>"c d", k=>NULL, "q\"x"=>"y\\z", e=>""'::hstore, '  a  =>  1 ,b=>null, c=>"null"  '::hstore"#,
        "select 'a'::hstore",
        "select 'a=>'::hstore",
        "select '=>1'::hstore",
        "select 'a=>1 b=>2'::hstore",
        "select 'a=>1, b=>2'::hstore -> 'a', 'a=>1, b=>2'::hstore -> 'z', 'a=>1, b=>2, c=>NULL'::hstore -> array['a','c','z']",
        "select 'a=>1'::hstore || 'b=>2, a=>3'::hstore, 'a=>1'::hstore || 'b=>2', 'a=>1'::hstore || NULL, NULL::hstore -> 'a'",
        "select 'a=>1, b=>NULL'::hstore ? 'a', 'a=>1, b=>NULL'::hstore ? 'b', 'a=>1'::hstore ? 'z'",
        "select 'a=>1, b=>2'::hstore ?| array['z','b'], 'a=>1, b=>2'::hstore ?& array['a','z'], 'a=>1, b=>2'::hstore ?& array['a','b']",
        "select 'a=>1, b=>2'::hstore @> 'a=>1', 'a=>1, b=>2'::hstore @> 'a=>2', 'a=>1'::hstore <@ 'a=>1, b=>2', 'a=>NULL'::hstore @> 'a=>NULL'",
        // (an untyped literal after `-` is an hstore, so a bare key is a syntax error)
        "select 'a=>1, b=>2, c=>3'::hstore - 'b'",
        "select 'a=>1, b=>2, c=>3'::hstore - 'b'::text, 'a=>1, b=>2, c=>3'::hstore - array['a','c'], 'a=>1, b=>2, c=>3'::hstore - 'a=>1, b=>9'::hstore",
        "select hstore('k', 'v'), hstore('k', NULL), hstore(NULL, 'v'), tconvert('x', 'y')",
        "select hstore(array['a','1','b','2']), hstore('{{a,1},{b,2}}'::text[]), hstore(array['a','b'], array['1','2']), hstore(array['a','b'], NULL)",
        "select hstore(array['a','1','b'])",
        "select hstore('{{a,1,x},{b,2,y}}'::text[])",
        "select hstore(array['a','b'], array['1'])",
        "select hstore(array['a', NULL], array['1','2'])",
        "select hstore('[0:1]={a,b}'::text[], '[1:2]={1,2}'::text[])",
        "select hstore('[0:1]={a,b}'::text[], '[0:1]={1,2}'::text[]), hstore('{a,b}'::text[], '[1:2]={1,2}'::text[])",
        "select 'a=>1, b=>2'::hstore -> '[0:1]={a,b}'::text[], 'a=>1, b=>2'::hstore -> '{{a,z},{b,a}}'::text[]",
        "select akeys('b=>2, a=>1, cc=>NULL'), avals('b=>2, a=>1, cc=>NULL'), akeys(''), hstore_to_array('a=>1, b=>NULL'), hstore_to_matrix('a=>1, b=>NULL'), hstore_to_matrix('')",
        r#"select hstore_to_json('a=>1, b=>NULL, "c d"=>t'), hstore_to_jsonb('a=>1, b=>NULL'), 'a=>1, b=>x'::hstore::jsonb, 'a=>1'::hstore::json"#,
        "select hstore_to_json_loose('a=>1, b=>t, c=>1.50, d=>01, f=>x, g=>NULL, h=>-0.5, i=>f'), hstore_to_jsonb_loose('a=>1, b=>t, d=>01')",
        "select slice('a=>1, b=>2, c=>3'::hstore, array['b','c','z']), exist('a=>1', 'a'), defined('a=>NULL', 'a'), defined('a=>1', 'a'), isexists('a=>1', 'b'), isdefined('a=>1', 'a')",
        "select delete('a=>1, b=>2'::hstore, 'a'), delete('a=>1, b=>2'::hstore, array['a','b']), delete('a=>1, b=>2'::hstore, 'a=>1'::hstore)",
        "select fetchval('a=>1', 'a'), exists_any('a=>1', array['a']), exists_all('a=>1', array['a','b'])",
        "select * from each('a=>1, bb=>NULL, c=>3')",
        "select * from each('a=>1'::hstore || 'b=>2')",
        "select skeys('b=>2, a=>1')",
        "select svals('b=>2, a=>NULL')",
        "select * from skeys('b=>2, a=>1') as k",
        "select 'a=>1'::hstore = 'a=>1', 'a=>1, b=>2'::hstore = 'b=>2, a=>1'::hstore, 'a=>1'::hstore <> 'a=>2', 'a=>1'::hstore::text, length('a=>1'::hstore::text)",
        "select pg_typeof('a=>1'::hstore), pg_typeof('a=>1'::hstore -> 'a'), pg_typeof(akeys('a=>1')), pg_typeof('a=>1'::hstore || 'b=>2')",
        r#"select '{"a=>1","b=>2"}'::hstore[]"#,
        r#"select '[2:3]={"a=>1","b=>2"}'::hstore[], '{{"a=>1"},{"b=>2, a=>0"}}'::hstore[]"#,
        "select typname, typtype, typcategory from pg_type where typname in ('hstore', '_hstore') order by 1",
        "create table hs (id int primary key, h hstore default hstore('made', 'yes') || 'x=>1', note text, b text generated always as (h -> 'b') stored, check (not h ? 'bad'))",
        "insert into hs (id, note) values (0, 'd')",
        "insert into hs values (1, 'a=>1, b=>2', 'x'), (2, 'b=>3', 'y'), (3, NULL, 'z'), (4, '', 'e')",
        "insert into hs (id, h) values (5, 'bad=>1')",
        "insert into hs (id, h) values (6, 'nope')",
        "create index hs_gin on hs using gin (h)",
        "create index hs_gist on hs using gist (h)",
        "create index hs_expr on hs ((h -> 'b'))",
        "select id, h, b from hs order by id",
        "select id, h -> 'b' from hs where h ? 'b' order by id",
        "select id from hs where h @> 'b=>3'",
        "select id from hs where h = 'b=>2, a=>1'",
        "select id from hs where h in ('b=>3', 'k=>v') order by id",
        "select id from hs where h -> 'b' = '2'",
        "select id, h -> 'b' as b from hs order by h -> 'b' nulls last, id",
        "select h -> 'b', count(*) from hs group by h -> 'b' order by 1",
        "select h -> 'b', count(*) from hs group by 1 order by 1",
        "select id from hs where h ?| array['a','made'] and not h ?& array['a','b'] order by id",
        "select id, akeys(h), avals(h), array_length(akeys(h), 1) from hs order by id",
        "select sum((h -> 'b')::int), jsonb_agg(h::jsonb order by id) from hs",
        "select id, case when h ? 'a' then h -> 'a' else 'none' end, hstore_to_json(h) ->> 'b', h['b'] from hs order by id",
        "select id, k, v from hs, each(h) as e(k, v) where id <= 2 order by id, k",
        "update hs set h = h || 'c=>9' where id = 1 returning h -> 'c', h - 'a'::text",
        "update hs set h = h - 'a'",
        "update hs set h = coalesce(h, '') || hstore('n', note) where id > 0",
        "insert into hs (id, h) values (2, 'q=>1') on conflict (id) do update set h = hs.h || excluded.h returning h",
        "delete from hs where h ? 'made' returning id, akeys(h)",
        "select id, h, b from hs order by id",
        "alter table hs add column tags hstore",
        "update hs set tags = hstore(array['n', id::text])",
        "alter table hs alter column tags type text",
        "alter table hs alter column tags type hstore using tags::hstore",
        "select id, tags, tags -> 'n' from hs order by id",
        "select attname, format_type(atttypid, atttypmod) from pg_attribute where attrelid = 'hs'::regclass and attnum > 0 order by attnum",
        "create function hget(h hstore, k text) returns text language sql as $$ select h -> k $$",
        "create function hset(h hstore, k text, v text) returns hstore language plpgsql as $$ declare r hstore; begin r := h || hstore(k, v); if r ? 'zz' then r := r - 'zz'::text; end if; return r; end $$",
        "create function kv(h hstore) returns table (k text, v text) language sql as $$ select * from each(h) $$",
        "select hget('a=>5', 'a'), hset('a=>5, zz=>1', 'b', '6')",
        "select * from kv('x=>1, y=>2')",
        "create table hlog (h hstore, note text)",
        "create function htrg() returns trigger language plpgsql as $$ begin new.h := coalesce(new.h, '') || hstore('touched', 'yes'); if new.h ? 'drop' then new.h := new.h - 'drop'::text; end if; insert into hlog values (new.h - 'touched'::text, tg_op); return new; end $$",
        "create trigger tr before insert or update on hs for each row when (new.h is null or not new.h ? 'quiet') execute function htrg()",
        "insert into hs (id, h) values (10, 'a=>1'), (11, null), (12, 'drop=>1'), (13, 'quiet=>1')",
        "select id, h from hs where id >= 10 order by id",
        "select * from hlog order by h::text",
        "prepare hp(hstore, text) as select $1 -> $2, $1 ? $2, $1 - $2, $1 || 'z=>1'",
        "execute hp('a=>1, b=>2', 'a')",
        "prepare hq(hstore) as select id from hs where h @> $1 order by id",
        "execute hq('touched=>yes')",
        "prepare he(hstore) as select * from each($1 || 'b=>2')",
        "execute he('a=>1')",
        "create view hv as select id, h -> 'touched' as t, h ? 'a' as has_a from hs where id >= 10",
        "select * from hv order by id",
    ]]);
}

/// ltree: paths and the lquery patterns over them, their operators and functions, their order (label by label),
/// in a table with its indexes, a default, a check, a function and a prepared statement.
#[test]
fn ltree_type() {
    check(&[&[
        "create extension if not exists ltree",
        "select 'Top.Science.Astronomy'::ltree, ''::ltree, 'a-b.c_d.9'::ltree",
        "select 'a..b'::ltree",
        "select 'a.b.'::ltree",
        "select '.a'::ltree",
        "select 'a b'::ltree",
        "select 'a.b$c'::ltree",
        "select 'a.b.c'::ltree @> 'a.b.c.d', 'a.b.c'::ltree @> 'a.b', 'a.b.c'::ltree <@ 'a.b', 'a.b.c'::ltree <@ 'a.b.c', ''::ltree @> 'a.b'",
        "select 'a.b'::ltree < 'a.c', 'a.b'::ltree < 'a-b', 'a'::ltree < 'a.b', 'a.b'::ltree >= 'a.b', 'b'::ltree > 'a.z.z', 'a.b'::ltree = 'a.b', 'a.b'::ltree <> 'a.B'",
        "select 'a.b'::ltree || 'c.d'::ltree, 'a.b'::ltree || 'c', 'x' || 'a.b'::ltree, ''::ltree || 'a', 'a'::ltree || ''::ltree",
        "select nlevel('a.b.c'), nlevel(''), nlevel('top')",
        "select subltree('Top.Child1.Child2', 1, 2), subltree('a.b.c.d', 0, 4), subltree('a.b.c.d', 1, 99), subltree('a.b.c', 1, 1)",
        "select subltree('a.b', 3, 4)",
        "select subltree('a.b', 1, 0)",
        "select subpath('Top.Child1.Child2', 0, 2), subpath('Top.Child1.Child2', 1), subpath('a.b.c.d', -2), subpath('a.b.c.d', 1, -1), subpath('a.b.c.d', -3, 2), subpath('a.b.c.d', 1, 0)",
        "select subpath('a.b', 5)",
        "select subpath('a.b.c', -4)",
        "select subpath('a.b.c', -3), subpath('a.b.c', -3, 1)",
        "select index('0.1.2.3.5.4.5.6.8.5.6.8', '5.6'), index('0.1.2.3.5.4.5.6.8.5.6.8', '5.6', -4), index('a.b', 'c'), index('a.b.a.b', 'a.b', 1), index('a.b', 'a.b.c'), index('0.1.2.3.5.4.5.6.8.5.6.8', '6.8', -100)",
        "select text2ltree('a.b'), ltree2text('a.b'::ltree), pg_typeof(text2ltree('a')), pg_typeof(ltree2text('a')), pg_typeof('a'::ltree || 'b'), pg_typeof('a.*'::lquery)",
        "select lca('1.2.3'::ltree, '1.2.3.4.5.6'), lca('1.2.3'::ltree, '1.2.4', '1.9'), lca('a.b'::ltree, 'c.d'), lca('{1.2.3,1.2.3.4}'::ltree[])",
        "select lca('1'::ltree, '1.2') is null, lca(''::ltree, '1.2') is null, lca('1'::ltree, '1.2')",
        "select 'Top.Science.Astronomy'::ltree ~ '*.Science.*', 'Top.Science.Astronomy'::ltree ~ 'Top.*{1}.Astronomy', 'Top.Science.Astronomy'::ltree ~ 'Top.*{2}'",
        "select '*.Science.*'::lquery ~ 'Top.Science'::ltree, 'a.b.c'::ltree ~ 'a.*{2,}', 'a.b.c'::ltree ~ 'a.*{,1}', 'a.b.c'::ltree ~ 'a.*{1,2}', 'a.b.c'::ltree ~ '*{3}', 'a.b.c'::ltree ~ '*{4}'",
        "select 'a.Bcd.e'::ltree ~ 'a.bc*@.e', 'a.Bcd.e'::ltree ~ 'a.bc*.e', 'a.bcd.e'::ltree ~ 'a.bc.e', 'a.bcd.e'::ltree ~ 'a.x|bcd|y.e', 'a.bcd.e'::ltree ~ 'a.!bcd.e', 'a.zzz.e'::ltree ~ 'a.!bcd|x.e'",
        "select 'a.foo_bar_baz.e'::ltree ~ 'a.bar%.e', 'a.foo_bar_baz.e'::ltree ~ 'a.ba%.e', 'a.foo_bar_baz.e'::ltree ~ 'a.ba%*.e', 'a.foo_bar_baz.e'::ltree ~ 'a.baz_foo%.e', 'a.foo_BAR.e'::ltree ~ 'a.bar%@.e'",
        "select 'a.b.b.b.c'::ltree ~ 'a.b{3}.c', 'a.b.b.c'::ltree ~ 'a.b{3}.c', 'a.b.b.c'::ltree ~ 'a.b{1,}.c', 'a.c'::ltree ~ 'a.b{0,}.c', 'a.x.y.c'::ltree ~ 'a.!b{2}.c'",
        "select ''::ltree ~ '*', ''::ltree ~ '*{1,}', 'a'::ltree ~ 'a|b', 'a.b'::ltree ~ '*.b.*.*'",
        "select 'a.b.c'::ltree ? '{x.*, a.*}'::lquery[], 'a.b.c'::ltree ? array['x.*', 'y']::lquery[]",
        "select 'a'::ltree ~ ''",
        "select 'a'::ltree ~ 'a..b'",
        "select 'a'::ltree ~ 'a.*{3,1}'",
        "select 'a'::ltree ~ 'a.b**'",
        "select 'a'::ltree ~ 'a.*b'",
        "select '{a.b, c.d.e}'::ltree[] @> 'a.b.x'::ltree, '{a.b, c.d.e}'::ltree[] <@ 'c.d'::ltree, '{a.b, c.d.e}'::ltree[] ~ 'c.*'::lquery, 'a.b.x'::ltree <@ '{a.b, c.d.e}'::ltree[]",
        "select typname, typtype, typcategory from pg_type where typname in ('ltree', '_ltree', 'lquery', '_lquery') order by 1",
        "create table tree (id serial primary key, path ltree not null default 'Top'::ltree || 'New', kind text, depth int generated always as (nlevel(path)) stored, check (path <@ 'Top' or path ~ 'Top-x.*'))",
        "insert into tree (path, kind) values ('Top', 'r'), ('Top.Science', 'b'), ('Top.Science.Astronomy', 'l'), ('Top.Science.Astronomy.Astrophysics', 'l'), ('Top.Science.Astronomy.Cosmology', 'l'), ('Top.Hobbies', 'b'), ('Top.Hobbies.Amateurs_Astronomy', 'l'), ('Top.Collections', 'b'), ('Top.Collections.Pictures', 'b'), ('Top.Collections.Pictures.Astronomy', 'l'), ('Top.Collections.Pictures.Astronomy.Stars', 'l'), ('Top-x.a', 'z'), ('Top.a', 'z')",
        "insert into tree (kind) values ('d')",
        "insert into tree (path) values ('Elsewhere.x')",
        "insert into tree (path) values ('bad path')",
        "create index tree_gist on tree using gist (path)",
        "create index tree_gist2 on tree using gist (path gist_ltree_ops(siglen=100))",
        "create index tree_btree on tree using btree (path)",
        "create unique index tree_u on tree (path)",
        "create index tree_lvl on tree (nlevel(path))",
        "insert into tree (path) values ('Top.Science')",
        "select path, depth from tree where path <@ 'Top.Science' order by path",
        "select path from tree where path @> 'Top.Science.Astronomy' order by path",
        "select path from tree where path ~ '*.Astronomy.*' order by path",
        "select path from tree where path ~ '*.!pictures@.*.Astronomy.*' order by path",
        "select path from tree where path ? array['*.Stars', 'Top.Hobbies.*{1}']::lquery[] order by path",
        // (label by label: `Top-x` comes after `Top`'s children, though `-` sorts before `.`)
        "select path from tree order by path",
        "select path from tree order by path desc limit 3",
        "select path from tree order by path limit 2 offset 1",
        "select path from tree where path = 'Top.Science'",
        "select path from tree where path in ('Top.a', 'Top.Hobbies', 'nope') order by path",
        "select path from tree where path > 'Top.Science' and path < 'Top.a' order by path",
        "select path from tree where nlevel(path) = 2 order by path",
        "select subpath(path, 0, 2) as p, count(*) from tree group by subpath(path, 0, 2) order by 1",
        "select path || 'x' as p, nlevel(path) from tree where nlevel(path) = 2 order by path",
        "select array_agg(path order by path) from tree where depth <= 2",
        "select path, lag(path) over (order by path) from tree where depth = 2 order by path",
        "select t1.path, t2.path from tree t1 join tree t2 on t2.path <@ t1.path and nlevel(t2.path) = nlevel(t1.path) + 1 where t1.path = 'Top.Science' order by 2",
        "update tree set path = 'Top.Moved' || subpath(path, 1) where path <@ 'Top.Hobbies' returning path, path <@ 'Top.Moved', nlevel(path)",
        "select path from tree where path <@ 'Top.Moved' order by path",
        "with recursive up(p) as (select 'a.b.c.d'::ltree union all select subpath(p, 0, nlevel(p) - 1) from up where nlevel(p) > 1) select p from up order by nlevel(p)",
        "create function ancestors(p ltree) returns setof ltree language plpgsql as $$ declare i int; begin for i in 1..nlevel(p) loop return next subpath(p, 0, i); end loop; end $$",
        "create function below(root ltree) returns setof int language sql as $$ select id from tree where path <@ root order by id $$",
        "create function leaf(p ltree) returns ltree language plpgsql as $$ declare q ltree; begin q := p || 'x'; if q <@ p then return subpath(q, nlevel(q) - 1); end if; return q; end $$",
        "select * from ancestors('a.b.c')",
        "select * from below('Top.Science')",
        "select leaf('a.b')",
        "prepare lp(ltree) as select $1 <@ 'a', nlevel($1), $1 || 'z'",
        "execute lp('a.b')",
        "prepare lq(ltree, lquery) as select count(*) from tree where path <@ $1 and path ~ $2",
        "execute lq('Top', '*.Astronomy')",
        "create table t3 (p ltree, q ltree[] default '{}')",
        "insert into t3 values ('a.b', '{a,b.c}')",
        "select p, q, q[2], array_length(q, 1), p::text || '!', length(p::text), 'x.y'::text::ltree from t3",
        "select attname, format_type(atttypid, atttypmod) from pg_attribute where attrelid = 't3'::regclass and attnum > 0 order by attnum",
        // an array of them keeps its bounds and its dimensions
        "select '[0:1]={a.b,c}'::ltree[], '{{a,b},{c,d.e}}'::ltree[], '{a.*,b}'::lquery[]",
        "select '{{a,b},{c,bad path}}'::ltree[]",
    ]]);
}

/// A nondeterministic collation (`deterministic = false`): the strings ICU ties are equal in comparisons, IN,
/// CASE, NULLIF, IS DISTINCT FROM, joins, unique constraints and ON CONFLICT, and order as ICU orders them.
#[test]
fn nondeterministic_collations() {
    check(&[&[
        "create collation ci (provider = icu, locale = 'und-u-ks-level2', deterministic = false)",
        "create collation ai (provider = icu, locale = 'und-u-ks-level1', deterministic = false)",
        "select collname, collisdeterministic from pg_collation where collname in ('ci', 'ai') order by 1",
        "create table n (id int primary key, name text collate ci, tag text)",
        "insert into n values (1, 'Ada', 'x'), (2, 'bob', 'y'), (3, 'ÉMILE', 'z'), (4, null, 'w')",
        "select id from n where name = 'ada'",
        "select id from n where name = 'ADA' or name = 'BOB' order by id",
        "select id from n where name <> 'ada' order by id",
        "select id from n where name in ('ADA', 'émile') order by id",
        "select id from n where name not in ('ADA', 'émile') order by id",
        "select id from n where name < 'B' order by id",
        "select id from n where name <= 'ADA' order by id",
        "select id from n where name >= 'bob' order by id",
        "select id from n where name between 'a' and 'c' order by id",
        "select 'abc' = 'ABC' collate ci, 'abc' collate ci = 'ABC', 'abc' collate ci < 'ABD', 'résumé' = 'resume' collate ci, 'résumé' = 'RESUME' collate ai",
        "select id, case name when 'ADA' then 'a' when 'BOB' then 'b' else '?' end from n order by id",
        "select id, nullif(name, 'ada') from n order by id",
        "select id, name is distinct from 'ADA', name is not distinct from 'bob' from n order by id",
        "select id, name = any (array['ADA']) from n where id = 1",
        "select id from n order by name, id",
        "select min(name), max(name) from n",
        "select greatest('a' collate ci, 'B'), least('a' collate ci, 'B')",
        "create table m (k text collate ci unique, v int)",
        "insert into m values ('Key', 1)",
        "insert into m values ('KEY', 2)",
        "insert into m values ('key', 3) on conflict (k) do update set v = m.v + excluded.v returning k, v",
        "insert into m values ('other', 9) on conflict (k) do nothing",
        "select * from m order by v",
        "update m set k = 'OTHER' where k = 'key'",
        "update m set k = 'KEY!' where k = 'KEY' returning k",
        "select n.id, m.v from n join m on m.k = n.tag collate ci order by 1",
        "create unique index n_name on n (name)",
        "insert into n values (5, 'ADA', 'q')",
        "insert into n values (5, 'Zed', 'q')",
        "select id from n where name = 'zed'",
        "create table d (name text collate ci, n int)",
        "create unique index d_lower on d (name, n)",
        "insert into d values ('a', 1), ('A', 2)",
        "insert into d values ('A', 1)",
        "select count(*) from d",
        "select 'a' collate ci like 'A%'",
        "select name from n where name like 'a%'",
        "create collation nope (provider = libc, locale = 'C', deterministic = false)",
        "drop table d",
        "select 'x' collate ci = 'X' collate ai",
        "select id from n where name = 'ada' collate \"C\" order by id",
        "select count(*) from n where name = tag",
        "alter table n alter column tag type text collate ai",
        "select count(*) from n where name = tag",
    ]]);
}

/// A record used whole in PL/pgSQL (`to_jsonb(new)`, `old IS NULL`, `new IS DISTINCT FROM old`, a loop's
/// record): an audit trigger keeps the rows it sees, as in Postgres.
#[test]
fn records_used_whole_in_plpgsql() {
    check(&[&[
        "create table wr (id int primary key, name text, n numeric(6,2), at date, ok boolean)",
        "create table wr_audit (seq serial primary key, op text, row_id text, old jsonb, new jsonb)",
        "create function wr_audit_fn() returns trigger language plpgsql as $$ begin if tg_op = 'DELETE' then insert into wr_audit (op, row_id, old) values (tg_op, old.id::text, to_jsonb(old)); return old; end if; if tg_op = 'UPDATE' then insert into wr_audit (op, row_id, old, new) values (tg_op, new.id::text, to_jsonb(old), row_to_json(new)::jsonb); return new; end if; insert into wr_audit (op, row_id, new) values (tg_op, new.id::text, to_jsonb(new)); return new; end; $$",
        "create trigger wr_audit_trg after insert or update or delete on wr for each row execute function wr_audit_fn()",
        "insert into wr values (1, 'Ada', 1.5, '2026-01-02', true), (2, null, null, null, false)",
        "update wr set name = 'Ada L', n = n + 1 where id = 1",
        "delete from wr where id = 2",
        "select op, row_id, old, new from wr_audit order by seq",
        "create table wr_log (seq serial primary key, note text)",
        "create function wr_touch() returns trigger language plpgsql as $$ begin if old is null then insert into wr_log (note) values ('no old'); end if; new.name := upper(new.name); insert into wr_log (note) values ('row ' || (to_jsonb(new) ->> 'name')); if new is distinct from old then insert into wr_log (note) values ('changed'); end if; return new; end; $$",
        "create trigger wr_touch_trg before insert or update on wr for each row execute function wr_touch()",
        "insert into wr values (3, 'bo', 2, '2026-03-04', true)",
        "update wr set ok = ok where id = 3",
        "select note from wr_log order by seq",
        "select id, name from wr order by id",
        "create function wr_names() returns text language plpgsql as $$ declare r record; names text := ''; begin for r in select id, name from wr order by id loop names := names || (to_jsonb(r) ->> 'name') || ';'; end loop; return names; end; $$",
        "select wr_names()",
        // a record is null as a row is: when every field is, and not null when none is
        "create table wn (a int, b text)",
        "create table wn_log (seq serial primary key, note text)",
        "create function wn_fn() returns trigger language plpgsql as $$ begin if new is null then insert into wn_log (note) values ('null'); elsif new is not null then insert into wn_log (note) values ('not null'); else insert into wn_log (note) values ('some null'); end if; if old is null and not (old is not null) then insert into wn_log (note) values ('no old'); end if; return new; end $$",
        "create trigger wn_trg before insert on wn for each row execute function wn_fn()",
        "insert into wn values (null, null), (1, 'x'), (1, null)",
        "select note from wn_log order by seq",
    ]]);
}

/// A PL/pgSQL record as text is Postgres's row text (`format('%s', new)`, `new::text`, `'..' || old`), `rec.*` is
/// its fields (`VALUES (NEW.*)`, `ROW(OLD.*) = ROW(NEW.*)`, `SELECT r.*`); ALIAS FOR names a parameter or NEW; an
/// IF's condition may have a FROM, as `SELECT condition FROM ...`.
#[test]
fn plpgsql_records_as_rows() {
    check(&[&[
        "create table pr (tid int, balance int, note text)",
        "create table pr_log (seq serial primary key, line text)",
        "create function pr_trg() returns trigger language plpgsql as $$ begin insert into pr_log (line) values (format('%s %s', tg_op, new)); insert into pr_log (line) values (new::text); if tg_op = 'UPDATE' then if row(old.*) = row(new.*) then insert into pr_log (line) values ('same'); else insert into pr_log (line) values ('changed ' || old::text); end if; if old.* is distinct from new.* then insert into pr_log (line) values ('distinct'); end if; end if; return new; end $$",
        "create trigger pr_t before insert or update on pr for each row execute function pr_trg()",
        "insert into pr values (3, 30, 'a b'), (4, null, '')",
        "update pr set balance = balance where tid = 3",
        "update pr set note = 'x,y' where tid = 4",
        "select line from pr_log order by seq",
        "create table pr_copy (tid int, balance int, note text)",
        "create function pr_copy_trg() returns trigger language plpgsql as $$ begin insert into pr_copy values (new.*); insert into pr_copy select new.*; return null; end $$",
        "create trigger pr_c after insert on pr for each row execute function pr_copy_trg()",
        "insert into pr values (5, 50, 'q\"r')",
        "select * from pr_copy order by tid",
        "create function pr_rows() returns text language plpgsql as $$ declare r record; s text := ''; begin for r in select tid, note from pr order by tid loop s := s || format('%s;', r); end loop; return s; end $$",
        "select pr_rows()",
        // ALIAS FOR a parameter, and for NEW
        "create function pr_twice(int) returns int language plpgsql as $$ declare n alias for $1; begin return n * 2; end $$",
        "select pr_twice(21)",
        "create function pr_alias_trg() returns trigger language plpgsql as $$ declare ps alias for new; begin ps.note := upper(ps.note); return ps; end $$",
        "create trigger pr_a before insert on pr for each row execute function pr_alias_trg()",
        "insert into pr values (6, 60, 'low')",
        "select tid, note from pr where tid = 6",
        // a condition with a FROM: the query it is
        "create function pr_has(int) returns text language plpgsql as $$ begin if count(*) = 0 from pr where tid = $1 then return 'none'; end if; return 'some'; end $$",
        "select pr_has(3), pr_has(99)",
    ]]);
}

/// PL/pgSQL cursors as Postgres has them: bound ones with arguments (by position and by name), refcursors a function
/// opens and returns, read by another call or by the session's FETCH until the transaction ends, FOR over a bound
/// cursor under its portal name, SCROLL and NO SCROLL, MOVE, and a CONSTANT refcursor that has no name.
#[test]
fn plpgsql_cursors_and_portals() {
    check(&[&[
        "create table rc (a int, b int)",
        "insert into rc values (5, 10), (50, 100), (500, 1000)",
        "create function rc_open() returns refcursor language plpgsql as $$ declare rc refcursor; begin open rc for select a from rc order by a; return rc; end $$",
        "create function rc_use() returns int language plpgsql as $$ declare rc refcursor; x record; begin rc := rc_open(); fetch next from rc into x; return x.a; end $$",
        "select rc_use()",
        "select rc_use(), rc_use()",
        "create function rc_named(rc refcursor) returns refcursor language plpgsql as $$ begin open rc for select a from rc order by a; return rc; end $$",
        "begin",
        "select rc_named('pc1')",
        "fetch next in pc1",
        "fetch all from pc1",
        "select name, is_holdable from pg_cursors where name = 'pc1'",
        "commit",
        "fetch next from pc1",
        "create function rc_args(int, int) returns boolean language plpgsql as $$ declare c1 cursor (p1 int, p2 int) for select * from rc where a > p1 and b > p2; r record; begin open c1(p2 := $2, p1 := $1); fetch c1 into r; close c1; return found; end $$",
        "select rc_args(20000, 20000), rc_args(20, 20)",
        "create function rc_mixed(int, int) returns boolean language plpgsql as $$ declare c1 cursor (p1 int, p2 int) for select * from rc where a > p1 and b > p2; r record; begin open c1(p1 := $1, $2); fetch c1 into r; close c1; return found; end $$",
        "select rc_mixed(20, 20)",
        "create function rc_twice() returns void language plpgsql as $$ declare c1 cursor (p1 int, p2 int) for select * from rc where a > p1; begin open c1(p2 := 20, 21); end $$",
        "create function rc_short() returns void language plpgsql as $$ declare c1 cursor (p1 int, p2 int) for select * from rc where a > p1; begin open c1(p2 := 77); end $$",
        "create function rc_forc() returns text language plpgsql as $$ declare c cursor (lo int) for select a from rc where a >= lo order by a; c2 cursor for select b from rc order by b; s text := ''; begin c := 'c'; for r in c(50) loop s := s || r.a || ' from ' || c || ';'; end loop; for r in c(500) loop s := s || r.a || ';'; end loop; c2 := null; for r in c2 loop s := s || r.b || ';'; end loop; return s || coalesce(c2, 'null'); end $$",
        "select rc_forc()",
        "create function rc_scroll() returns setof int language plpgsql as $$ declare c scroll cursor for select a from rc order by a; x int; begin open c; fetch last from c into x; while found loop return next x; fetch prior from c into x; end loop; close c; end $$",
        "select * from rc_scroll()",
        "create function rc_noscroll() returns setof int language plpgsql as $$ declare c no scroll cursor for select a from rc order by a; x int; begin open c; fetch last from c into x; return next x; end $$",
        "select * from rc_noscroll()",
        "create function rc_move() returns setof int language plpgsql as $$ declare c cursor for select * from generate_series(1, 10); x int; begin open c; loop move relative 2 in c; exit when not found; fetch next from c into x; if found then return next x; end if; end loop; close c; end $$",
        "select * from rc_move()",
        "create function rc_back() returns int language plpgsql as $$ declare c refcursor; x int; begin open c scroll for execute 'select a from rc order by a'; move forward all in c; fetch backward from c into x; close c; return x; end $$",
        "select rc_back()",
        "create function rc_const() returns refcursor language plpgsql as $$ declare rc constant refcursor; begin open rc for select a from rc; return rc; end $$",
        "select rc_const()",
        "create function rc_const2() returns refcursor language plpgsql as $$ declare rc constant refcursor := 'my_cursor_name'; begin open rc for select a from rc; return rc; end $$",
        "select rc_const2()",
        "create function rc_bad() returns void language plpgsql as $$ declare c refcursor; begin for r in c loop raise notice '%', r; end loop; end $$",
        // a holdable cursor declared in a transaction that rolls back is closed with it
        "begin",
        "declare h1 cursor with hold for select a from rc order by a",
        "rollback",
        "fetch from h1",
    ]]);
}

/// GROUP BY, DISTINCT and DISTINCT ON of text in a nondeterministic collation, and of citext: by the key the
/// strings are equal by. Which of a group's strings is shown is any of them, in Postgres too, so what is
/// compared is counts, and the strings in lower case.
#[test]
fn groups_and_distinct_in_nondeterministic_collations() {
    check(&[&[
        "create extension if not exists citext",
        "create collation gd_ci (provider = icu, locale = 'und-u-ks-level2', deterministic = false)",
        "create table gd (id int primary key, name text collate gd_ci, mail citext, n int)",
        "insert into gd values (1, 'Ada', 'A@x.io', 1), (2, 'ADA', 'a@X.io', 2), (3, 'bob', 'b@x.io', 3), (4, null, null, 4), (5, 'Bob', 'c@x.io', 5), (6, null, 'B@X.IO', 6)",
        "select lower(name), count(*), sum(n) from gd group by name order by 1 nulls last",
        "select lower(mail::text), count(*) from gd group by mail order by 1 nulls last",
        "select lower(name), lower(mail::text), count(*) from gd group by name, mail order by 1 nulls last, 2 nulls last",
        "select count(*) from (select name from gd group by name) g",
        "select lower(name), count(*) from gd group by name having count(*) > 1 order by 1",
        "select lower(name), max(n) from gd where n < 6 group by 1 order by 1 nulls last",
        "select count(*) from (select distinct name from gd) d",
        "select count(*) from (select distinct mail from gd) d",
        "select count(*) from (select distinct name, mail from gd) d",
        "select lower(x) from (select distinct name as x from gd) d order by 1 nulls last",
        "select count(*) from (select distinct name, n > 3 from gd) d",
        "select id from (select distinct on (name) name, id from gd order by name, id) d order by id",
        "select id from (select distinct on (mail) mail, id from gd order by mail, id desc) d order by id",
        "select lower(name), count(*) from gd group by rollup (name) order by 1 nulls last, 2",
        "select lower(a.name), count(*) from gd a join gd b on a.name = b.name group by a.name order by 1",
        "select lower(name) from gd group by name order by count(*) desc, 1 nulls last limit 2",
        "select count(*) from (select name from gd union select name from gd) u",
        "select count(*) from (select name from gd union all select name from gd) u",
        "select count(*) from (select name from gd intersect select 'ada' collate gd_ci) i",
        "select count(*) from (select name from gd except select 'BOB' collate gd_ci) e",
        "select count(*) from (select mail from gd union select 'C@X.IO'::citext) u",
        "select count(distinct name), count(distinct mail), count(distinct lower(name)) from gd",
        "select id, count(*) over (partition by name), count(*) over (partition by mail) from gd order by id",
    ]]);
}

/// What the migration probe still refused: sum, min and max of money; count(t.*); an enum as a primary key; a
/// deferrable UNIQUE; a field of a function's OUT parameters; textcat as an aggregate's step; COMMIT in a
/// procedure.
#[test]
fn money_sums_row_counts_enum_keys_and_procedures() {
    check(&[&[
        "create table mo (id int primary key, g text, amt money)",
        "insert into mo values (1, 'a', '$12.50'), (2, 'a', '$7.25'), (3, 'b', '$100.00'), (4, 'b', null)",
        "select g, sum(amt), min(amt), max(amt) from mo group by g order by g",
        "select sum(amt), max(amt) from mo where id > 99",
        "select sum(amt) from mo",
        "create table o (id int primary key, slug text)",
        "create table me (org int, who text)",
        "insert into o values (1, 'a'), (2, 'b')",
        "insert into me values (1, 'x'), (1, 'y')",
        "select o.slug, count(m.*), count(*) from o left join me m on m.org = o.id group by o.slug order by 1",
        "select count(o.*) from o",
        "create type st as enum ('active', 'paused', 'done')",
        "create table kv (k st primary key, v text)",
        "insert into kv values ('paused', 'p'), ('active', 'a')",
        "insert into kv values ('active', 'dup')",
        "insert into kv values ('nope', 'x')",
        "select k, v from kv order by k",
        "select v from kv where k = 'paused'",
        "select v from kv where k > 'active' order by k",
        "update kv set v = 'A' where k = 'active' returning k, v",
        "insert into kv values ('done', 'd') on conflict (k) do update set v = 'again' returning k, v",
        "insert into kv values ('done', 'd') on conflict (k) do update set v = 'again' returning k, v",
        "delete from kv where k = 'paused' returning v",
        "create table kv2 (k st, n int, v text, primary key (k, n))",
        "insert into kv2 values ('done', 1, 'x'), ('active', 1, 'y'), ('active', 0, 'z')",
        "insert into kv2 values ('done', 1, 'dup')",
        "select k, n, v from kv2 order by k, n",
        "create table kref (k st references kv (k))",
        "insert into kref values ('active')",
        "insert into kref values ('paused')",
        "select k from kv order by k desc",
        "create table du (id int primary key, title text, constraint du_u unique (title) deferrable initially immediate)",
        "alter table du add constraint du_u2 unique (id, title) deferrable",
        "create table du2 (id int unique not deferrable, t text unique deferrable)",
        "insert into du values (1, 'a')",
        "insert into du values (2, 'a')",
        "create function st2(out total bigint, out big bigint) language sql as $$ select count(*), count(*) filter (where id > 1) from mo $$",
        "select (st2()).total, (st2()).big",
        "select * from st2()",
        "create aggregate cat(text) (sfunc = textcat, stype = text, initcond = '')",
        "select cat(g order by id) from mo",
        "select textcat('a', 'b')",
        "create table pc (id int)",
        "create procedure pc_fill(n int) language plpgsql as $$ begin insert into pc values (n); commit; insert into pc values (n + 1); end $$",
        "call pc_fill(1)",
        "select count(*) from pc",
        "begin",
        "call pc_fill(5)",
        "rollback",
        "select count(*) from pc",
    ]]);
}

/// EXCLUDE constraints: no two rows with, for each part, values its operator holds between. Checked for the rows
/// a statement writes, among themselves too, and for the rows already there when one is added.
#[test]
fn exclusion_constraints() {
    check(&[&[
        "create extension if not exists btree_gist",
        "create table bk (id int primary key, room text, during int4range, note text, exclude using gist (room with =, during with &&))",
        "insert into bk values (1, 'a', '[1,5)', 'x')",
        "insert into bk values (2, 'a', '[5,9)', 'next to it')",
        "insert into bk values (3, 'a', '[4,6)', 'clash')",
        "insert into bk values (4, 'b', '[4,6)', 'other room'), (5, 'b', '[5,7)', 'clash in one statement')",
        "insert into bk values (6, null, '[1,100)', 'no room'), (7, 'a', null, 'no time'), (8, null, '[1,100)', 'no room again')",
        "update bk set during = '[3,8)' where id = 1",
        "update bk set during = '[0,5)' where id = 1",
        "update bk set note = 'same key' where id = 2",
        "select id, room, during, note from bk order by id",
        "delete from bk where id = 2",
        "update bk set during = '[0,9)' where id = 1",
        "update bk set room = 'b' where id = 1",
        "insert into bk values (10, 'b', '[20,30)', 'far')",
        "update bk set during = int4range(lower(during) + 100, upper(during) + 100) where room = 'b'",
        "select id, room, during from bk order by id",
        "create table ex2 (a int, b int, exclude (a with =) where (b > 0))",
        "insert into ex2 values (1, 1), (1, 0), (1, -1)",
        "insert into ex2 values (1, 5)",
        "update ex2 set b = 7 where b = 0",
        "select count(*) from ex2",
        "alter table ex2 add constraint ex2_b exclude (b with =)",
        "insert into ex2 values (9, 0)",
        "alter table ex2 drop constraint ex2_b",
        "insert into ex2 values (9, 0)",
        "alter table ex2 add exclude (b with =)",
        "create table ex3 (c circle, n int, exclude using gist (n with <>))",
        "insert into ex3 values (null, 1), (null, 1)",
        "insert into ex3 values (null, 2)",
        "create table ex4 (a int, exclude (a with +))",
        "alter table bk rename column room to place",
        "insert into bk values (11, 'b', '[125,126)', 'after the rename')",
        "alter table bk drop column during",
        "insert into bk values (12, 'b', 'now free')",
    ]]);
}

/// What the Postgres regression suite stopped at most: planner statistics written to pg_class, arrays of two
/// dimensions written with ARRAY, WITH ... MERGE, typed tables, pg_tablespace_location.
#[test]
fn regression_suite_stoppers() {
    check(&[&[
        "create table st (id int)",
        "update pg_class set reltuples = 1000, relpages = 10 where relname = 'st'",
        "update pg_class set reltuples = 1000 where relname = 'no such table'",
        "select count(*) from st",
        "select array[[1,2],[3,4]], array[array[1,2],array[3,4]], array[['a','b']], array[[[1]],[[2]]]",
        "select array[[1,2],[3]]",
        "create table mt (id int primary key, v int)",
        "insert into mt values (1, 10)",
        "with src as (select 1 as id, 5 as d union all select 2, 7) merge into mt t using src s on t.id = s.id when matched then update set v = t.v + s.d when not matched then insert values (s.id, s.d)",
        "select * from mt order by id",
        "with a as (select 3 as id) merge into mt using a on mt.id = a.id when not matched then insert values (a.id, 0)",
        "select count(*) from mt",
        "select pg_tablespace_location(1663), pg_tablespace_location(1664)",
        "create type tt as (a int, b text)",
        "create table tt_t of tt",
        "insert into tt_t values (1, 'x')",
        "select * from tt_t",
        "create table tt_t2 of tt (primary key (a))",
        "insert into tt_t2 values (1, 'a')",
        "insert into tt_t2 values (1, 'b')",
        "create table tt_bad of int4",
        "create table tt_bad of no_such_type",
    ]]);
}

/// Runs a statement and gives back `ok`, or its SQLSTATE, message, DETAIL and HINT: a refusal compared word for word.
const G3_TRY: &str = "create function g3_try(q text) returns text language plpgsql as $$ declare m text; d text; h text; \
                      begin execute q; return 'ok'; exception when others then get stacked diagnostics m = message_text, \
                      d = pg_exception_detail, h = pg_exception_hint; \
                      return sqlstate || ': ' || m || ' | ' || coalesce(d, '') || ' | ' || coalesce(h, ''); end $$";

/// Typed tables (CREATE TABLE ... OF type): the type named with its schema or found along the search_path, kept as
/// the table's (pg_class.reloftype); the table depends on it, so DROP TYPE refuses while it is there and CASCADE drops
/// it, as in Postgres.
#[test]
fn typed_tables_keep_and_depend_on_their_type() {
    check(&[&[
        "drop schema if exists g3_app cascade",
        "drop schema if exists g3_s cascade",
        "drop schema if exists g3_o cascade",
        G3_TRY,
        "create schema g3_app",
        "create type g3_app.r as (a int, b text)",
        "create table g3_t1 of g3_app.r",
        "insert into g3_t1 values (1, 'x')",
        "select * from g3_t1",
        "create table g3_t2 of g3_app.nope",
        "select g3_try('create table g3_t2 of g3_app.nope')",
        "create type g3_app.e as enum ('a')",
        "select g3_try('create table g3_t2 of g3_app.e')",
        "select g3_try('create table g3_t2 of int4')",
        "select g3_try('create table g3_t2 of pg_catalog.text')",
        "select g3_try('create table g3_t2 of int')",
        "select c.relname, c.reloftype::regtype::text, t.typname from pg_class c join pg_type t on t.oid = c.reloftype where c.relname = 'g3_t1'",
        "select count(*) from pg_depend d join pg_class c on c.oid = d.objid where c.relname = 'g3_t1' and d.refobjid = 'g3_app.r'::regtype and d.deptype = 'n'",
        "drop type g3_app.r",
        "select g3_try('drop type g3_app.r')",
        "drop type g3_app.r cascade",
        "select count(*) from pg_class where relname = 'g3_t1'",
        "select to_regtype('g3_app.r')",
        "create type tt3 as (x int, y text)",
        "create table tt3_t of tt3",
        "create table tt3_u of tt3 (primary key (x))",
        "create view tt3_v as select * from tt3_t",
        "select g3_try('drop type tt3')",
        "drop table tt3_u",
        "select g3_try('drop type tt3')",
        "drop type tt3 cascade",
        "select to_regclass('tt3_t'), to_regclass('tt3_v'), to_regtype('tt3')",
        // a typed table in another schema than its type's: DROP SCHEMA and DROP TYPE of the type's schema refuse
        // while it is there (it and what is over it said after the type), and CASCADE drops them
        "create schema g3_s",
        "create schema g3_o",
        "create table g3_s.a_tab (id int)",
        "create type g3_s.tt as (a int, b text)",
        "create table g3_o.t of g3_s.tt",
        "create view g3_o.v as select * from g3_o.t",
        "create table g3_pub of g3_s.tt",
        "insert into g3_o.t values (1, 'x')",
        "select * from g3_o.v",
        "drop schema g3_s",
        "select g3_try('drop schema g3_s')",
        "select g3_try('drop type g3_s.tt')",
        "drop schema g3_s cascade",
        "select to_regclass('g3_o.t'), to_regclass('g3_o.v'), to_regclass('g3_pub'), to_regclass('g3_s.a_tab')",
        "select count(*) from pg_namespace where nspname in ('g3_s', 'g3_o')",
        "create schema g3_s",
        "create type g3_s.tt as (a int)",
        "create table g3_o.t2 of g3_s.tt",
        "create table g3_o.t3 of g3_s.tt",
        "drop type g3_s.tt",
        "select g3_try('drop type g3_s.tt')",
        "drop type g3_s.tt cascade",
        "select to_regclass('g3_o.t2'), to_regclass('g3_o.t3'), to_regtype('g3_s.tt')",
        "drop schema g3_s",
        "drop schema g3_o cascade",
        "select count(*) from pg_namespace where nspname in ('g3_s', 'g3_o')",
        // a plain name, along a search_path that isn't the default
        "set search_path = g3_app, public",
        "create type r2 as (c int)",
        "create table g3_t4 of r2",
        "insert into g3_t4 values (5)",
        "select * from g3_t4",
        "select c.relname, c.reloftype::regtype::text, n.nspname from pg_class c join pg_namespace n on n.oid = c.relnamespace where c.relname = 'g3_t4'",
        "drop type r2",
        "drop schema g3_app cascade",
    ]]);
}

/// Batch 5 of the regression suite's stoppers: WITH ... VALUES and TABLE, CREATE RECURSIVE VIEW, temporary
/// tables that inherit or are partitioned, MERGE into a table without a primary key and inside PL/pgSQL, shell
/// types, libc collation names.
#[test]
fn regression_suite_stoppers_5() {
    check(&[&[
        "create table w5 (a int)",
        "with t as (insert into w5 values (0) returning a) values (false)",
        "with t as (select 1 as x) values ((select x from t)), (2)",
        "with t as (select 7 as x) table w5",
        "select * from w5",
        "create recursive view nums (n) as values (1) union all select n + 1 from nums where n < 5",
        "select * from nums",
        "create or replace recursive view nums (n) as values (2) union all select n + 1 from nums where n < 4",
        "select * from nums",
        "create recursive view bad as select 1",
        "create temp table tp (a int, b text)",
        "create temp table tc (c int) inherits (tp)",
        "insert into tp values (1, 'p')",
        "insert into tc values (2, 'c', 3)",
        "select * from tp order by a",
        "select * from only tp",
        "create temp table tparted (a int) partition by list (a)",
        "create temp table tpart1 partition of tparted for values in (1)",
        "create temp table tpartd partition of tparted default",
        "insert into tparted values (1), (2)",
        "select tableoid::regclass, a from tparted order by a",
        "create table nk (a int, b text)",
        "insert into nk values (1, 'x'), (2, null)",
        "merge into nk using (values (1, 'y'), (3, 'z')) s(a, b) on nk.a = s.a when matched then update set b = s.b when not matched then insert values (s.a, s.b)",
        "merge into nk using (values (2)) s(a) on nk.a = s.a when matched then delete",
        "select * from nk order by a",
        "create table mk (id int primary key, v int)",
        "create function mk_put(k int, val int) returns void language plpgsql as $$ begin merge into mk using (select k as id) s on mk.id = s.id when matched then update set v = val when not matched then insert values (k, val); end $$",
        "select mk_put(1, 10), mk_put(1, 11), mk_put(2, 20)",
        "select * from mk order by id",
        "create type sh5",
        "create type sh5",
        "create type sh5 as (a int)",
        "select (row(1)::sh5).a",
        "drop type sh5",
        "select 'a' < 'B' collate \"en_US\"",
        "create collation lc5 (provider = libc, locale = 'en_US.utf8')",
        "select 'a' < 'B' collate lc5",
        // (review of #122) a WITH query MERGE reads that reads an earlier one; an aliased pg_class statistics
        // UPDATE; a nested ARRAY whose parts differ in shape but not in their elements' count
        "with a as (select 1 as id, 9 as d), b as (select * from a) merge into mk using b on mk.id = b.id when matched then update set v = b.d",
        "select * from mk order by id",
        "update pg_class as c set reltuples = 1000 where c.relname = 'w5'",
        "select array[array[[1,2],[3,4]], array[[5],[6],[7],[8]]]",
    ]]);
}

/// intarray's functions and operators, and tablefunc's crosstab (with and without its categories' query) and
/// normal_rand.
#[test]
fn intarray_and_crosstab() {
    check(&[&[
        "create extension if not exists intarray",
        "create extension if not exists tablefunc",
        "select icount('{1,2,3}'::int[]), sort('{3,1,2}'::int[]), sort('{3,1,2}'::int[], 'desc'), sort_asc('{3,1,2}'::int[]), sort_desc('{3,1,2}'::int[]), uniq('{1,1,2,2,1}'::int[]), uniq(sort('{3,1,3,2,1}'::int[]))",
        "select idx('{5,6,7}'::int[], 6), idx('{5,6,7}'::int[], 9), subarray('{1,2,3,4,5}'::int[], 2, 3), subarray('{1,2,3,4,5}'::int[], 3), subarray('{1,2,3,4,5}'::int[], -2), intset(7)",
        "select '{1,2}'::int[] + 3, '{1,2}'::int[] + '{3,4}'::int[], '{1,2,3,2}'::int[] - 2, '{5,1,2,3,2}'::int[] - '{2,9}'::int[]",
        "select '{3,1}'::int[] | 2, '{3,1}'::int[] | '{1,4}'::int[], '{3,1,2}'::int[] & '{2,3,5}'::int[]",
        "select icount('{1,null}'::int[])",
        "select sort('{1}'::int[], 'up')",
        // sorted in place: dimensions and bounds kept; uniq and `-` of an element keep them too, or shrink the first
        "select sort('{{4,3},{2,1}}'::int[]), sort('[0:2]={3,2,1}'::int[]), sort_desc('[2:3]={1,2}'::int[]), sort('[5:5]={9}'::int[])",
        "select uniq('[0:3]={1,1,2,2}'::int[]), uniq('{{1,1},{2,2}}'::int[]), uniq('[0:1]={1,2}'::int[]), '[0:3]={1,2,1,3}'::int[] - 1, '[0:1]={1,2}'::int[] - 9, '{{1,2},{3,4}}'::int[] - 4",
        // subarray: a start before the first element clamped, a length of 0 to the end
        "select subarray('{1,2,3}'::int[], -4), subarray('{1,2,3}'::int[], -5, 2), subarray('{1,2,3}'::int[], 2, 0), subarray('{1,2,3}'::int[], 1, -1), subarray('{1,2,3}'::int[], 5), subarray('{}'::int[], 1)",
        // an array with its bounds written out is an array on the right too
        "select '{1}'::int[] + '[0:1]={2,3}'::int[], '{1}'::int[] | '[0:1]={2,3}'::int[], '{1,2,3}'::int[] - '[0:1]={2,3}'::int[]",
        "create table it (id int primary key, tags int[])",
        "insert into it values (1, '{3,1,2}'), (2, '{5}')",
        "select id, sort(tags), icount(tags), tags + 9, tags - 1 from it order by id",
        "select id from it where tags && '{1,5}' order by id",
        "select id from it where tags @> '{1,2}' order by id",
        "create table ct (r text, c text, v int)",
        "insert into ct values ('a', 'x', 1), ('a', 'y', 2), ('b', 'x', 3), ('b', 'z', 4), ('c', 'y', 5)",
        "select * from crosstab('select r, c, v from ct order by 1, 2') as t(r text, c1 int, c2 int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select distinct c from ct order by 1') as t(r text, x int, y int, z int)",
        "select r, y from crosstab('select r, c, v from ct order by 1', 'select distinct c from ct order by 1') as t(r text, x int, y int, z int) where y is not null order by r",
        "select count(*), count(*) filter (where x between -10 and 20) from normal_rand(100, 5, 1) as n(x)",
        // a negative count is refused; none is no rows
        "select * from normal_rand(-1, 0, 1)",
        "select count(*) from normal_rand(0, 0, 1)",
        // crosstab's queries run read-only: what would change anything is refused, and changes nothing
        "select * from crosstab('insert into ct values (''d'', ''x'', 9) returning r, c, v') as t(r text, a int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'insert into ct values (''e'', ''w'', 1) returning c') as t(r text, x int)",
        "select * from crosstab('update ct set v = 0 returning r, c, v', 'select distinct c from ct order by 1') as t(r text, x int, y int, z int)",
        "select * from crosstab('with d as (delete from ct returning *) select r, c, v from d') as t(r text, a int)",
        "select * from crosstab('select r, c, v from ct order by 1 for update') as t(r text, a int)",
        "select * from crosstab('create table ct_new (a int)') as t(r text, a int)",
        "select * from crosstab('set search_path = public') as t(r text, a int)",
        "select * from crosstab('show search_path') as t(r text, a int)",
        "select count(*), sum(v) from ct",
        // the categories: one column, no null, none twice (by their text's first 62 bytes)
        "select * from crosstab('select r, c, v from ct order by 1', 'select c from ct order by 1') as t(r text, x int, y int, z int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select null::text') as t(r text, x int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select c, 1 from ct') as t(r text, x int, y int, z int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select c from ct where false') as t(r text, x int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select c, v from ct where false') as t(r text, x int)",
        "select * from crosstab('select r, c, v from ct where false', 'select c from ct where false') as t(r text, x int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select repeat(''a'', 62) || ''x'' union all select repeat(''a'', 62) || ''y''') as t(r text, x int, y int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select repeat(''a'', 61) || ''x'' union all select repeat(''a'', 61) || ''y''') as t(r text, x int, y int)",
        // as many value columns as categories, no more and no fewer
        "select * from crosstab('select r, c, v from ct order by 1', 'select distinct c from ct order by 1') as t(r text, x int, y int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select distinct c from ct order by 1') as t(r text, x int, y int, z int, w int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select distinct c from ct order by 1') as t(r text)",
        "select * from crosstab('select r, c from ct', 'select distinct c from ct order by 1') as t(r text, x int, y int, z int)",
        "select * from crosstab('select r, c from ct') as t(r text, a int)",
        "select * from crosstab('select r, c from ct where false') as t(r text, a int)",
        // columns between the row name and the category; categories matched by their text; null categories
        // and ones not listed skipped; null row names one row
        "select * from crosstab('select r, upper(r), c, v from ct order by 1', 'select distinct c from ct order by 1') as t(r text, u text, x int, y int, z int)",
        "create table ct2 (r text, c int, v text)",
        "insert into ct2 values ('a', 1, 'one'), ('a', null, 'none'), ('a', 3, 'three'), (null, 2, 'two'), (null, 1, 'uno'), ('b', 2, 'dos')",
        "select * from crosstab('select r, c::text, v from ct2 order by r nulls first', 'select 2 union all select 1') as t(r text, two text, one text)",
    ]]);
}

/// What a review of this branch found: a default worked out for each row is typed when it is made, an
/// identity isn't added over one, two parents' different ones conflict; NaN and the infinities are numeric
/// keys; and CASE and NULLIF in a nondeterministic collation work each operand out once.
#[test]
fn defaults_keys_and_collations_after_review() {
    check(&[&[
        "create table dt (i int default now() + interval '1 day')",
        "create table dt2 (b boolean default random())",
        "create table dt3 (d date default now() + interval '1 day', t text default random()::text, n numeric default random(), i int default random() * 10)",
        "insert into dt3 default values",
        "select d > current_date, t is not null, n < 1, i between 0 and 10 from dt3",
        "create table idn (id int not null)",
        "alter table idn alter column id set default random() * 10",
        "alter table idn alter column id add generated always as identity",
        "alter table idn alter column id drop default",
        "alter table idn alter column id add generated always as identity",
        "insert into idn default values",
        "select id from idn",
        "create table pa (a double precision default random())",
        "create table pb (a double precision default random() + 1)",
        "create table pc (a double precision default random())",
        "create table ch () inherits (pa, pb)",
        "create table ch2 (a double precision default 5) inherits (pa, pb)",
        "create table ch3 () inherits (pa, pc)",
        "insert into ch2 default values",
        "insert into ch3 default values",
        "select a from ch2",
        "select a < 1 from ch3",
        "create table np (k numeric primary key, v text)",
        "insert into np values ('NaN', 'nan'), ('Infinity', 'inf'), ('-Infinity', 'ninf'), (1.5, 'x'), (-2, 'y')",
        "insert into np values ('NaN', 'dup')",
        "insert into np values ('-Infinity', 'dup')",
        "select k, v from np order by k",
        "select v from np where k = 'NaN'",
        "select v from np where k > 1 order by k",
        "update np set v = 'z' where k = 'Infinity' returning k, v",
        "delete from np where k = '-Infinity' returning v",
        "select count(*) from np",
        "create collation rv_ci (provider = icu, locale = 'und-u-ks-level2', deterministic = false)",
        "create sequence rv_s",
        "select case (nextval('rv_s')::text || 'a') collate rv_ci when 'zz' then 'no' when '1A' then 'first' when '2a' then 'second' else 'none' end",
        "select nextval('rv_s')",
        "select nullif((nextval('rv_s')::text || 'x') collate rv_ci, 'never')",
        "select nextval('rv_s')",
        "select nullif('ABC' collate rv_ci, 'abc') is null, nullif('abc' collate rv_ci, 'abd'), nullif(null::text collate rv_ci, 'a') is null, nullif('a' collate rv_ci, null)",
        "select case 'B' collate rv_ci when 'a' then 1 when 'b' then 2 end, case null::text collate rv_ci when 'a' then 1 else 0 end",
        // TG_RELID is an oid
        "create table tg (id int primary key)",
        "create table tg_log (t text, r text)",
        "create function tg_fn() returns trigger language plpgsql as $$ begin insert into tg_log values (pg_typeof(tg_relid)::text, tg_relid::regclass::text); return new; end $$",
        "create trigger tg_trg before insert on tg for each row execute function tg_fn()",
        "insert into tg values (1)",
        "select * from tg_log",
    ]]);
}

/// A GIN index on a jsonb or an array column is made, listed and dropped, and the operators it would
/// answer give the same rows: it holds no entries here, the rows are read.
#[test]
fn gin_indexes_on_jsonb_and_arrays_are_kept() {
    check(&[&[
        "create table gd (id int primary key, body jsonb, tags text[], nums int[])",
        "create index gd_body on gd using gin (body)",
        "create index gd_path on gd using gin (body jsonb_path_ops)",
        "create index gd_tags on gd using gin (tags)",
        "create index gd_nums on gd using gin (nums)",
        "insert into gd values (1, '{\"a\": 1, \"t\": [\"x\"]}', '{red,blue}', '{1,2}'), (2, '{\"a\": 2}', '{green}', '{3}')",
        "select id from gd where body @> '{\"a\": 1}' order by id",
        "select id from gd where body ? 'a' order by id",
        "select id from gd where tags && array['green','red'] order by id",
        "select id from gd where tags @> array['blue'] order by id",
        "select id from gd where nums @> array[3] order by id",
        "select indexname from pg_indexes where tablename = 'gd' order by 1",
        "update gd set body = body || '{\"z\": true}' where id = 1",
        "delete from gd where id = 2",
        "select count(*) from gd",
        "create unique index gd_u on gd using gin (body)",
        "drop index gd_path",
        "select indexname from pg_indexes where tablename = 'gd' order by 1",
    ]]);
}

/// A primary key of a date, a time, a timestamp, a boolean, a numeric or a double precision, alone
/// or among several columns: rows are found, ordered, upserted and referenced by it as in Postgres.
#[test]
fn primary_keys_of_dates_times_and_numbers() {
    check(&[&[
        "create table kd (day date primary key, total numeric not null default 0)",
        "insert into kd values ('2026-01-02', 5), ('2026-01-01', 3)",
        "insert into kd values ('2026-01-01', 9)",
        "insert into kd values ('2026-01-01', 5) on conflict (day) do update set total = kd.total + excluded.total returning *",
        "select * from kd order by day",
        "select * from kd where day = '2026-01-02'",
        "select * from kd where day >= '2026-01-02'",
        "update kd set day = '2026-02-01' where day = '2026-01-02' returning *",
        "delete from kd where day = '2026-01-01' returning day",
        "create table kn (id numeric(20,0) primary key, memo text)",
        "insert into kn values (12345678901234567890, 'big'), (-5, 'neg'), (7, 'seven')",
        "select * from kn order by id",
        "select * from kn where id = 7.0",
        "insert into kn values (7.0, 'dup')",
        "create table kn2 (amt numeric(8,2) primary key)",
        "insert into kn2 values (1.5), (1.25), (10), (-0.1)",
        "select * from kn2 order by amt",
        "insert into kn2 values (1.50)",
        "create table kb (enabled boolean primary key, note text)",
        "insert into kb values (true, 'on'), (false, 'off')",
        "select * from kb order by enabled",
        "insert into kb values (true, 'again')",
        "create table kt (at timestamptz primary key, v double precision)",
        "insert into kt values ('2026-01-01 00:00+00', 1.5), ('2026-01-02 00:00+00', 2.5), ('2025-12-31 23:00-05', 3)",
        "select at at time zone 'UTC', v from kt order by at",
        "select count(*) from kt where at >= '2026-01-01 12:00+00'",
        "create table kts (at timestamp primary key, v int)",
        "insert into kts values ('2026-01-01 10:00', 1), ('2026-01-01 09:00', 2)",
        "select * from kts order by at",
        "create table kf (score double precision primary key, who text)",
        "insert into kf values (1.5, 'a'), (0.5, 'b'), (-2, 'c'), (1e10, 'd')",
        "select * from kf order by score",
        "insert into kf values (0.5, 'dup')",
        "select who from kf where score = -2",
        "create table km (at time primary key, what text)",
        "insert into km values ('09:00', 'standup'), ('08:30', 'coffee')",
        "select * from km order by at",
        "create table kc (day date, n numeric(6,1), f double precision, t time, who text, primary key (day, n, f, t))",
        "insert into kc values ('2026-01-01', 1.5, 2.5, '10:00', 'a'), ('2026-01-01', 1.5, 2.5, '09:00', 'b'), ('2025-01-01', 9, 0, '00:00', 'c')",
        "select * from kc order by day, n, f, t",
        "insert into kc values ('2026-01-01', 1.50, 2.5, '10:00', 'dup')",
        "create table kfk (id int primary key, day date references kd (day), amt numeric(8,2) references kn2 (amt))",
        "insert into kfk values (1, '2026-02-01', 1.25)",
        "insert into kfk values (2, '2030-01-01', 1.25)",
        "insert into kfk values (3, '2026-02-01', 99)",
        "delete from kd where day = '2026-02-01'",
        "select * from kfk",
        "select count(*), min(day), max(day) from kd",
        "create table ku (n numeric primary key)",
        "insert into ku values (1.50), (2), (0.001)",
        "select * from ku order by n",
    ]]);
}

/// A DEFAULT that Postgres works out afresh for each row (the clock plus an interval, random(), a
/// sequence's value in an expression, a function of the user's) is run for each row that takes it.
#[test]
fn defaults_worked_out_for_each_row() {
    check(&[&[
        "create sequence ds",
        "create function dseven() returns int language sql as 'select 7'",
        "create table dr (id int primary key, later timestamptz default now() + interval '7 days', r double precision default random(), n int default nextval('ds') * 10, f int default dseven() + 1, who text default upper(current_user) || '!', day date default current_date + 1)",
        "insert into dr (id) values (1), (2), (3)",
        "insert into dr values (4, default, default, default, default, default, default)",
        "insert into dr (id, n) values (5, 99)",
        "select id, later > now() + interval '6 days', later < now() + interval '8 days', r >= 0 and r < 1, n, f, who = upper(current_user) || '!', day = current_date + 1 from dr order by id",
        "select count(distinct r) from dr",
        "update dr set n = default, f = default where id = 5 returning n, f",
        "alter table dr alter column f set default dseven() * 2",
        "alter table dr alter column r drop default",
        "insert into dr (id) values (6)",
        "select id, r is null, f, n from dr where id = 6",
        "create table dr2 (like dr including defaults)",
        "insert into dr2 (id) values (1)",
        "select id, f, n from dr2",
        "alter table dr add column added timestamptz default now() - interval '1 hour'",
        "select count(*) filter (where added < now()) from dr",
        "create table drbad (id int, x int default id + 1)",
        "create table drbad2 (id int, x int default (select 1))",
        "create table drkid () inherits (dr)",
        "insert into drkid (id) values (100)",
        "select id, f, n from drkid",
        "insert into dr (id) select g from generate_series(10, 14) g",
        "select id, n from dr where id >= 10 order by id",
        "select nextval('ds')",
    ]]);
}

#[test]
fn generated_columns() {
    check(&[&[
        "create table gc (id int primary key, x int, y int generated always as (x * 2) stored, s text generated always as (upper(t) || '!') stored, t text)",
        "insert into gc (id, x, t) values (1, 5, 'a'), (2, null, 'b')",
        "select * from gc order by id",
        "insert into gc (id, x, y) values (3, 1, 9)",
        "insert into gc (id, x, y) values (3, 1, default)",
        "insert into gc values (5, 1, 2, 'x', 't')",
        "update gc set x = 10 where id = 1",
        "select id, x, y, s from gc order by id",
        "update gc set y = 1",
        "update gc set t = 'zz', y = default where id = 2",
        "select id, y, s from gc order by id",
        "insert into gc (id, x) values (3, 2) on conflict (id) do update set x = excluded.x + 1",
        "select id, x, y from gc order by id",
        "create table gbad1 (a int, b int generated always as (a * random()) stored)",
        "create table gbad2 (a int, b int generated always as (a + 1) stored, c int generated always as (b + 1) stored)",
        "create table gbad3 (a int, b int generated always as (nosuch + 1) stored)",
        "create table gbad4 (a int, b int generated always as ((select 1)) stored)",
        "create table gbad5 (a int, b int generated by default as (a) stored)",
        "create table gbad6 (a int, b text generated always as (a + 1) stored)",
        "create table gbad7 (a int, b int generated always as (a) virtual)",
        "alter table gc add column z int generated always as (id + x) stored",
        "select id, z from gc order by id",
        "alter table gc add column w int generated always as (nosuch) stored",
        "select attname, attgenerated, atthasdef from pg_attribute where attrelid = 'gc'::regclass and attnum > 0 order by attnum",
        "select column_name, is_generated, generation_expression, column_default from information_schema.columns where table_name = 'gc' order by ordinal_position",
        "select adnum, pg_get_expr(adbin, adrelid) from pg_attrdef where adrelid = 'gc'::regclass order by adnum",
        "create index gc_y_idx on gc (y)",
        "select id from gc where y = 20",
        "alter table gc drop column x",
        "alter table gc alter column y drop expression",
        "insert into gc (id, x, y) values (6, 1, 100)",
        "select id, y from gc where id = 6",
        "alter table gc alter column y drop expression",
        "select attname, attgenerated from pg_attribute where attrelid = 'gc'::regclass and attnum > 0 order by attnum",
        "create table gt (a text, ts tsvector generated always as (to_tsvector('english', a)) stored)",
        "insert into gt (a) values ('the quick brown fox')",
        "select a from gt where ts @@ to_tsquery('english', 'fox')",
        "create table gd (a int, b int generated always as (a) stored, c int generated always as (a + b) stored) ",
        "create table gr (a int, b int generated always as (a + 1) stored)",
        "insert into gr (a) values (1)",
        "alter table gr rename column a to a2",
        "insert into gr (a2) values (10)",
        "select a2, b from gr order by a2",
        "alter table gr alter column a2 type bigint",
        "alter table gr alter column b type bigint",
        "select a2, b from gr order by a2",
        "alter table gr rename column b to b2",
        "alter table gr alter column a2 set default 3",
        "insert into gr default values",
        "select a2, b2 from gr order by a2",
        "alter table gr alter column b2 set default 5",
        "alter table gr alter column b2 set not null",
        "insert into gr (a2) values (null)",
    ]]);
}

#[test]
fn foreign_key_actions() {
    check(&[
        &[
            // ON UPDATE / ON DELETE, each action on its own parent
            "create table p1 (id int primary key, name text)",
            "create table c1 (id int primary key, pid int references p1 on update cascade on delete cascade)",
            "insert into p1 values (1, 'a'), (2, 'b'), (3, 'c')",
            "insert into c1 values (10, 1), (11, 1), (12, 2), (13, null)",
            "update p1 set id = 100 where id = 1",
            "select id, pid from c1 order by id",
            "update p1 set name = 'bb' where id = 2",
            "select id, pid from c1 order by id",
            "update p1 set id = id + 10 where id > 1",
            "select id from p1 order by id",
            "select id, pid from c1 order by id",
            "update p1 set id = id",
            "delete from p1 where id = 100",
            "select id, pid from c1 order by id",
            "update p1 set id = 12 where id = 13",
            "update p1 set id = 200 where id = 12",
            "select id, pid from c1 order by id",
            "create table p2 (id int primary key)",
            "create table c2 (id int primary key, pid int references p2 on update set null on delete set null)",
            "insert into p2 values (1), (2)",
            "insert into c2 values (10, 1), (11, 2)",
            "update p2 set id = 5 where id = 1",
            "select id, pid from c2 order by id",
            "delete from p2 where id = 2",
            "select id, pid from c2 order by id",
            "create table p3 (id int primary key)",
            "create table c3 (id int primary key, pid int not null default 0 references p3 on update set default on delete set default)",
            "insert into p3 values (0), (1), (2)",
            "insert into c3 values (10, 1), (11, 2), (12, 0)",
            "update p3 set id = 7 where id = 1",
            "select id, pid from c3 order by id",
            "delete from p3 where id = 2",
            "select id, pid from c3 order by id",
            "delete from p3 where id = 0",
            "select id, pid from c3 order by id",
            "update p3 set id = 9 where id = 7",
            "create table p4 (id int primary key)",
            "create table c4 (id int primary key, pid int references p4 on update restrict on delete restrict)",
            "insert into p4 values (1), (2)",
            "insert into c4 values (10, 1)",
            "update p4 set id = 5 where id = 1",
            "delete from p4 where id = 1",
            "update p4 set id = 6 where id = 2",
            "select id from p4 order by id",
            "select id, pid from c4 order by id",
            // the default action is NO ACTION: a referenced key can't be changed or deleted
            "create table p5 (id int primary key)",
            "create table c5 (id int primary key, pid int references p5 on delete cascade)",
            "insert into p5 values (1), (2)",
            "insert into c5 values (10, 1), (11, 2)",
            "update p5 set id = 5 where id = 1",
            "select id from p5 order by id",
            "select id, pid from c5 order by id",
            "delete from p5 where id = 1",
            "select id, pid from c5 order by id",
            "create table p6 (id int primary key)",
            "create table c6 (id int primary key, pid int references p6 on delete set null)",
            "insert into p6 values (1)",
            "insert into c6 values (10, 1)",
            "update p6 set id = 5",
            "select id, pid from c6 order by id",
        ],
        &[
            // a deferrable NO ACTION key may move while its children are moved in the same transaction
            "create table p (id int primary key)",
            "create table c (id int primary key, pid int references p deferrable initially deferred)",
            "insert into p values (1), (2)",
            "insert into c values (10, 1)",
            "begin",
            "update p set id = 5 where id = 1",
            "update c set pid = 5 where id = 10",
            "commit",
            "select id from p order by id",
            "select id, pid from c order by id",
            "begin",
            "update p set id = 6 where id = 5",
            "commit",
            "select id from p order by id",
            "select id, pid from c order by id",
        ],
        &[
            // a child's key made of the reference, and its own children
            "create table pa (id int primary key)",
            "create table pb (id int primary key)",
            "create table j (a int references pa on update cascade, b int references pb on update cascade, n int, primary key (a, b))",
            "create table g (id int primary key, ja int, jb int, foreign key (ja, jb) references j on update cascade on delete cascade)",
            "insert into pa values (1), (2)",
            "insert into pb values (1), (2)",
            "insert into j values (1, 1, 0), (1, 2, 0), (2, 1, 0)",
            "insert into g values (100, 1, 1), (101, 2, 1)",
            "update pa set id = 10 where id = 1",
            "select a, b from j order by a, b",
            "select id, ja, jb from g order by id",
            "update pb set id = 20 where id = 1",
            "select a, b from j order by a, b",
            "select id, ja, jb from g order by id",
            "update pa set id = 2 where id = 10",
            "select a, b from j order by a, b",
            "delete from pa where id = 2",
            "select a, b from j order by a, b",
            "select id, ja, jb from g order by id",
        ],
        &[
            // a table that references itself
            "create table tree (id int primary key, parent int references tree on update cascade on delete set null)",
            "insert into tree values (1, null), (2, 1), (3, 2), (4, 2)",
            "update tree set id = id + 100",
            "select id, parent from tree order by id",
            "update tree set id = 500 where id = 102",
            "select id, parent from tree order by id",
            "delete from tree where id = 500",
            "select id, parent from tree order by id",
        ],
        &[
            // composite keys, and creation errors
            "create table cp (a int, b int, primary key (a, b))",
            "create table cc (id int primary key, a int, b int, foreign key (a, b) references cp on update cascade)",
            "insert into cp values (1, 1), (1, 2)",
            "insert into cc values (1, 1, 1), (2, 1, 2), (3, null, 1)",
            "update cp set b = 9 where b = 2",
            "select id, a, b from cc order by id",
            "update cp set a = 5",
            "select id, a, b from cc order by id",
            "create table bad1 (id int primary key references cp on update set null)",
            "create table bad2 (id int primary key, x int references cp (a) on update cascade)",
            "create table ok1 (id int primary key references cp (a, b) on update foo)",
            "create table bad3 (id int, x int not null references p1 on update set null)",
            "create table bad4 (id int, x int default 5 references p1 on update set default)",
            "insert into bad4 values (1, null)",
            "select conname, confupdtype, confdeltype from pg_constraint where contype = 'f' and conrelid in ('cc'::regclass) order by conname",
            "select constraint_name, update_rule, delete_rule from information_schema.referential_constraints where constraint_name like 'c%' order by 1",
        ],
    ]);
}

#[test]
fn regclass_in_a_list() {
    check(&[&[
        "create table rc1 (id int primary key)",
        "create table rc2 (id int primary key)",
        "select relname from pg_class where oid in ('rc1'::regclass) order by 1",
        "select relname from pg_class where oid in ('rc1'::regclass, 'rc2'::regclass) order by 1",
        "select relname from pg_class where oid not in ('rc1'::regclass) and relname like 'rc%' and relkind = 'r' order by 1",
        "select relname from pg_class where oid in ('rc1'::regclass, 0) order by 1",
        "select conname from pg_constraint where conrelid in ('rc2'::regclass) order by 1",
        "select 'rc1'::regclass in ('rc1'::regclass)",
    ]]);
}

#[test]
fn foreign_key_to_a_unique_column() {
    check(&[
        &[
            // a foreign key to a UNIQUE column
            "create table u1 (id int primary key, code text unique, n int, m int, unique (n, m), note text)",
            "create table k1 (id int primary key, ref text references u1 (code))",
            "insert into u1 values (1, 'a', 1, 1, 'x'), (2, 'b', 1, 2, 'y'), (3, null, 2, 1, 'z')",
            "insert into k1 values (10, 'a'), (11, 'b'), (12, null), (13, 'a')",
            "insert into k1 values (14, 'zz')",
            "update k1 set ref = 'zz' where id = 10",
            "update k1 set ref = 'b' where id = 10",
            "select id, ref from k1 order by id",
            "delete from u1 where id = 1",
            "delete from u1 where id = 3",
            "update u1 set code = 'c' where id = 1",
            "update u1 set code = 'c' where id = 3",
            "update u1 set note = 'w' where id = 1",
            "update u1 set id = 5 where id = 1",
            "select id, code from u1 order by id",
            "update u1 set code = null where id = 1",
            "insert into u1 values (6, 'q', 3, 3, 'q')",
            "delete from u1 where id = 6",
            "select count(*) from u1",
            // several columns, in another order
            "create table k2 (id int primary key, a int, b int, foreign key (b, a) references u1 (m, n))",
            "insert into k2 values (1, 1, 1), (2, 1, 2), (3, 2, null), (4, null, null)",
            "insert into k2 values (5, 9, 9)",
            "insert into k2 values (6, 2, 1)",
            "delete from u1 where n = 1 and m = 2",
            "select id, a, b from k2 order by id",
        ],
        &[
            // actions on a unique key
            "create table u (id int primary key, code text unique)",
            "create table kc (id int primary key, ref text references u (code) on update cascade on delete cascade)",
            "create table kn (id int primary key, ref text references u (code) on update set null on delete set null)",
            "create table kd (id int primary key, ref text default 'dflt' references u (code) on update set default on delete set default)",
            "create table kr (id int primary key, ref text references u (code) on update restrict on delete restrict)",
            "insert into u values (1, 'a'), (2, 'b'), (3, 'dflt')",
            "insert into kc values (10, 'a'), (11, 'b')",
            "insert into kn values (10, 'a'), (11, 'b')",
            "insert into kd values (10, 'a'), (11, 'b')",
            "insert into kr values (10, 'a')",
            "update u set code = 'a2' where id = 1",
            "select id, ref from kc order by id",
            "select id, ref from kn order by id",
            "select id, ref from kd order by id",
            "select id, ref from kr order by id",
            "update u set code = 'a3' where id = 1",
            "delete from u where id = 1",
            "select id, ref from kr order by id",
            "delete from kr",
            "delete from u where id = 1",
            "select id, ref from kc order by id",
            "select id, ref from kn order by id",
            "select id, ref from kd order by id",
            "delete from u where id = 2",
            "select id, ref from kc order by id",
            "select id, ref from kn order by id",
            "select id, ref from kd order by id",
            "update u set id = 30 where id = 3",
            "select id, code from u order by id",
            "select id, ref from kd order by id",
        ],
        &[
            // unique indexes, self reference, deferred, a key of a different type
            "create table w (id int primary key, email text, boss text, big bigint)",
            "create unique index w_email on w (email)",
            "create unique index w_big on w (big)",
            "alter table w add foreign key (boss) references w (email) on delete set null",
            "insert into w values (1, 'a@x', null, 10), (2, 'b@x', 'a@x', 20), (3, 'c@x', 'b@x', 30)",
            "insert into w values (4, 'd@x', 'nobody', 40)",
            "delete from w where id = 1",
            "select id, boss from w order by id",
            "create table w2 (id int primary key, wb int references w (big))",
            "insert into w2 values (1, 20), (2, 30)",
            "insert into w2 values (3, 99)",
            "delete from w where id = 2",
            "create table d (id int primary key, ref text references u2 (code) deferrable initially deferred)",
            "create table u2 (id int primary key, code text unique)",
            "create table d2 (id int primary key, ref text references u2 (code) deferrable initially deferred)",
            "begin",
            "insert into d2 values (1, 'later')",
            "insert into u2 values (1, 'later')",
            "commit",
            "select id, ref from d2 order by id",
            "begin",
            "insert into d2 values (2, 'never')",
            "commit",
            "select id, ref from d2 order by id",
        ],
        &[
            // cascades down a chain of UNIQUE references, and a child whose key is the reference
            "create table a (id int primary key, code text unique)",
            "create table b (id int primary key, pid text references a (code) on update cascade on delete cascade, name text unique)",
            "create table c (id int primary key, bname text references b (name) on update cascade on delete set null)",
            "create table e (code text primary key references a (code) on update cascade on delete cascade)",
            "insert into a values (1, 'x'), (2, 'y'), (3, 'z')",
            "insert into b values (10, 'x', 'bx'), (11, 'x', 'bx2'), (12, 'y', 'by')",
            "insert into c values (100, 'bx'), (101, 'bx2'), (102, 'by')",
            "insert into e values ('x'), ('y')",
            "update a set code = 'x' where id = 1",
            "update a set code = 'xx' where id = 1",
            "update b set name = 'renamed' where id = 10",
            "select id, pid, name from b order by id",
            "select id, bname from c order by id",
            "select code from e order by code",
            "update a set code = code || '2' where id in (1, 2)",
            "select id, code from a order by id",
            "select id, pid, name from b order by id",
            "select code from e order by code",
            "update a set code = 'y2' where id = 3",
            "delete from a where id = 1",
            "select id, pid, name from b order by id",
            "select id, bname from c order by id",
            "select code from e order by code",
            "update b set name = null where id = 12",
            "select id, bname from c order by id",
        ],
        &[
            // what can't be referenced, and what can't be dropped or changed while it is
            "create table r (id int primary key, a int unique, b int, c int, d int, unique (c, d), e text)",
            "create unique index r_part on r (b) where b > 0",
            "create unique index r_expr on r (lower(e))",
            "create table s1 (x int references r (b))",
            "create table s2 (x int references r (nope))",
            "create table s3 (x int, y int references r (c))",
            "create table s4 (x int, y int, foreign key (x, y) references r (a))",
            "create table s5 (x text references r (a))",
            "create table s6 (x int references r (c, d))",
            "create table s7 (x int references r (a, a))",
            "create table ok1 (x int references r (a), y int, z int, foreign key (y, z) references r (c, d))",
            "alter table r drop constraint r_a_key",
            "alter table r drop constraint r_c_d_key",
            "alter table r drop column a",
            "alter table r drop column d",
            "alter table r alter column a type bigint",
            "drop index r_part",
            "select conname, pg_get_constraintdef(oid) from pg_constraint where conrelid = 'ok1'::regclass order by conname",
            "select conname, contype, conkey, confkey from pg_constraint where conrelid = 'ok1'::regclass order by conname",
            "select constraint_name, unique_constraint_name, update_rule, delete_rule from information_schema.referential_constraints where constraint_schema = current_schema() order by 1",
            "select constraint_name, column_name, ordinal_position, position_in_unique_constraint from information_schema.key_column_usage where table_name = 'ok1' order by 1, 3",
            "select constraint_name, table_name, column_name from information_schema.constraint_column_usage where constraint_name like 'ok1%' order by 1, 3",
            "alter table ok1 drop constraint ok1_x_fkey",
            "alter table r drop constraint r_a_key",
            "select count(*) from pg_constraint where conrelid = 'r'::regclass and contype = 'u'",
            "alter table ok1 add foreign key (x) references r (a)",
            "insert into r values (1, 1, 1, 1, 1, 'a')",
            "insert into ok1 values (2, 1, 1)",
            "alter table ok1 add foreign key (x) references r (b)",
            "alter table ok1 add constraint ok1_x_fk2 foreign key (x) references r (id)",
            "alter table ok1 add constraint ok1_x_fk3 foreign key (x) references r (id) on update foo",
        ],
    ]);
}

#[test]
fn size_functions() {
    // the byte counts differ (Chronos stores rows its own way): what is compared is the shape,
    // and pg_size_pretty and pg_size_bytes exactly
    check(&[&[
        "select pg_size_pretty(0::bigint), pg_size_pretty(1023::bigint), pg_size_pretty(10239::bigint), pg_size_pretty(10240::bigint), pg_size_pretty(1234567::bigint), pg_size_pretty(-1234567::bigint)",
        "select pg_size_pretty(1073741824::bigint), pg_size_pretty(20479::bigint), pg_size_pretty(20480::bigint), pg_size_pretty(10485760::bigint), pg_size_pretty(9223372036854775807::bigint)",
        "select pg_size_pretty(1234567890123::numeric), pg_size_pretty(12345678.9::numeric), pg_size_pretty(-20480::numeric)",
        "select pg_size_pretty(null::bigint), pg_size_pretty(5::bigint)",
        "select pg_size_bytes('1 kB'), pg_size_bytes('1.5 MB'), pg_size_bytes('10'), pg_size_bytes('1 GB'), pg_size_bytes('-1 kB'), pg_size_bytes('2 tb'), pg_size_bytes('1e3 B'), pg_size_bytes(' 7  bytes ')",
        "select pg_size_bytes('junk')",
        "select pg_size_bytes('1 xB')",
        "select pg_size_bytes('')",
        "select pg_size_bytes(null)",
        "create table sz (id int primary key, t text)",
        "create index sz_t on sz (t)",
        "select pg_relation_size('sz'), pg_table_size('sz') >= 0, pg_total_relation_size('sz') >= 0",
        "insert into sz select g, repeat('x', 100) from generate_series(1, 1000) g",
        "select pg_relation_size('sz') > 0, pg_table_size('sz') >= pg_relation_size('sz'), pg_total_relation_size('sz') >= pg_table_size('sz'), pg_indexes_size('sz') > 0, pg_total_relation_size('sz') >= pg_indexes_size('sz')",
        "select pg_relation_size('sz') % 8192, pg_indexes_size('sz') % 8192, pg_total_relation_size('sz') % 8192",
        "select pg_size_pretty(pg_total_relation_size('sz')) ~ '^[0-9]+ (bytes|kB|MB)$'",
        "select pg_typeof(pg_relation_size('sz')), pg_typeof(pg_database_size(current_database())), pg_typeof(pg_size_pretty(1::bigint))",
        "select pg_relation_size('sz'::regclass) = pg_relation_size('sz'), pg_relation_size('sz', 'main') = pg_relation_size('sz')",
        "select pg_relation_size('sz_t') > 0, pg_relation_size('sz_pkey') > 0, pg_total_relation_size('sz_t') > 0",
        "select pg_database_size(current_database()) >= 0",
        "select pg_database_size('nosuch')",
        "select pg_relation_size('nosuch')",
        "select pg_table_size('nosuch')",
        "select pg_size_pretty(pg_relation_size(null)), pg_total_relation_size(null), pg_indexes_size(null)",
        "select relname, pg_size_pretty(pg_total_relation_size(c.oid)) ~ ' (bytes|kB|MB)$' from pg_class c where relname = 'sz'",
    ]]);
}

#[test]
fn bytea() {
    check(&[
        &[
            "create table bb (id int primary key, b bytea, n int)",
            "insert into bb values (1, '\\xdeadbeef', 1), (2, 'abc', 2), (3, E'\\\\x00ff', 3), (4, '', 4), (5, null, 5), (6, decode('68656c6c6f', 'hex'), 6), (7, '\\x', 7), (8, 'a\\000b', 8), (9, 'a\\\\b', 9)",
            "select id, b, length(b), octet_length(b), pg_typeof(b) from bb order by id",
            "select id, b || '\\x01'::bytea from bb where id < 4 order by id",
            "select id from bb where b = '\\xdeadbeef'",
            "select id from bb where b = 'abc'",
            "select id, b from bb where b < '\\xff' order by b, id",
            "select id, b from bb order by b desc, id",
            "select count(b), count(distinct b) from bb",
            "select encode(b, 'hex'), encode(b, 'base64'), encode(b, 'escape') from bb where id in (1, 2, 3, 8, 9) order by id",
            "select decode('aGk=', 'base64'), decode('YQ==', 'base64'), decode('DEAD', 'hex')",
            "select encode(decode(repeat('QUJD', 30), 'base64'), 'base64')",
            "select substring(b from 2 for 2), substr(b, 2), substr(b, 0, 2), substring(b from 10), position('\\xbe'::bytea in b), position('\\x'::bytea in b), position('\\xff'::bytea in b) from bb where id = 1",
            "select substring(b from 1 for -1) from bb where id = 1",
            "select get_byte(b, 0), get_byte(b, 3), set_byte(b, 0, 255), set_byte(b, 1, 300), bit_length(b) from bb where id = 1",
            "select get_byte(b, 4) from bb where id = 1",
            "select md5(b), encode(sha256(b), 'hex'), encode(sha384('abc'::bytea), 'hex'), encode(sha512('abc'), 'hex') from bb where id = 1",
            "select convert_to('héllo', 'UTF8'), convert_from('\\x68c3a96c6c6f', 'UTF8'), 'abc'::text::bytea, b::text, 'héllo'::bytea from bb where id = 1",
            "select convert_from('\\xff'::bytea, 'UTF8')",
            "select overlay(b placing '\\xff'::bytea from 2 for 1), overlay(b placing '\\xff0000'::bytea from 2) from bb where id = 1",
            "select to_jsonb(b), b is null, coalesce(b, '\\x00'::bytea) from bb where id in (1, 5) order by id",
            "select b, count(*) from bb group by b order by b",
            "select distinct b from bb order by b",
            "select string_agg(b, '\\x2c'::bytea) from bb where id < 4",
            "select 1::bytea",
            "select '\\xzz'::bytea",
            "select '\\xabc'::bytea",
            "select 'a\\'::bytea",
            "select length('\\x0102'::bytea), length('abc'::bytea), 'abc'::bytea = 'abc', '\\x616263'::bytea = 'abc'::bytea",
            "select decode('zz', 'hex')",
            "select decode('a', 'base64')",
            "select decode('!!!!', 'base64')",
            "select encode('a'::bytea, 'foo')",
            "select b from bb where b in ('\\xdeadbeef', '\\x00ff') order by 1",
            "select b from bb where b between '\\x00' and '\\x62' order by 1",
            "select greatest('\\x01'::bytea, '\\x02'), least('\\x01'::bytea, '\\x02'), nullif('\\x01'::bytea, '\\x01')",
            "select b, case when b = '\\x' then 'empty' else 'no' end from bb where id in (4, 7, 1) order by id",
        ],
        &[
            // a column: indexes, unique, defaults, update, casts, prepared parameters
            "create table blobs (id serial primary key, name text, data bytea not null default '\\x00', hash bytea unique)",
            "create index blobs_data on blobs (data)",
            "insert into blobs (name, data, hash) values ('a', '\\x0102', sha256('a')), ('b', decode('ff', 'hex'), sha256('b')), ('c', default, null)",
            "insert into blobs (name, data, hash) values ('dup', '', sha256('a'))",
            "insert into blobs (name, data) values ('nul', null)",
            "select id, name, data, encode(hash, 'hex') from blobs order by id",
            "select name from blobs where data = '\\x0102'",
            "select name from blobs where data > '\\x01' order by data",
            "select name from blobs where hash = sha256('b')",
            "update blobs set data = data || '\\xff' where name = 'a'",
            "update blobs set data = decode('cafe', 'hex') where name = 'c'",
            "select name, data, length(data) from blobs order by id",
            "select column_name, data_type, udt_name, column_default from information_schema.columns where table_name = 'blobs' order by ordinal_position",
            "select atttypid::regtype, attname from pg_attribute where attrelid = 'blobs'::regclass and attnum > 0 order by attnum",
            "alter table blobs add column extra bytea default '\\xbeef'",
            "select id, extra from blobs order by id",
            "alter table blobs alter column data type text",
            "select data from blobs order by id",
            "select format_type('bytea'::regtype, null), 'bytea'::regtype::oid",
            "select array_agg(b) from (values ('\\x01'::bytea), ('\\x02')) v(b)",
        ],
        &[
            // a bytea primary key, referenced
            "create table k (id bytea primary key, v int)",
            "create table kc (id int primary key, k bytea references k on delete cascade)",
            "insert into k values ('\\x01', 1), ('\\xff', 2), ('\\x', 3), ('\\x0100', 4), (decode('ab', 'hex'), 5)",
            "insert into k values ('\\x01', 9)",
            "insert into k values (null, 9)",
            "select id, v from k order by id",
            "select v from k where id = '\\xff'",
            "select v from k where id = decode('ff', 'hex')",
            "update k set v = v + 10 where id = '\\x01'",
            "insert into k values ('\\x01', 100) on conflict (id) do update set v = k.v + excluded.v",
            "insert into kc values (1, '\\x01'), (2, '\\xff'), (3, null)",
            "insert into kc values (4, '\\xee')",
            "delete from k where id = '\\x01'",
            "select id, k from kc order by id",
            "select id, v from k order by id",
            "update k set id = '\\x02' where id = '\\xff'",
            "create table kk (a bytea, b int, primary key (a, b))",
            "create table ku (a bytea unique, b int)",
            "insert into ku values ('\\x01', 1), ('\\x01', 2)",
            "select a from ku",
        ],
    ]);
}

#[test]
fn alter_type_keeps_the_new_length_and_precision() {
    check(&[&[
        "create table vt (id int primary key, name varchar(5) not null, n numeric(6,2), c char(3))",
        "insert into vt values (1, 'abc', 1.5, 'x')",
        "insert into vt values (2, 'abcdefgh', 1, 'x')",
        "alter table vt alter column name type varchar(10)",
        "insert into vt values (2, 'abcdefgh', 1, 'x')",
        "select format_type(atttypid, atttypmod) from pg_attribute where attrelid = 'vt'::regclass and attname = 'name'",
        "insert into vt values (3, 'abcdefghijkl', 1, 'x')",
        "alter table vt alter column name type varchar(3)",
        "alter table vt alter column name type varchar(8) using name::varchar(8)",
        "insert into vt values (3, 'abcdefghi', 1, 'x')",
        "alter table vt alter column name type text",
        "insert into vt values (3, 'abcdefghijklmnopqrstuvwxyz', 1, 'x')",
        "select format_type(atttypid, atttypmod) from pg_attribute where attrelid = 'vt'::regclass and attname = 'name'",
        "alter table vt alter column name type char(4)",
        "alter table vt alter column n type numeric(4,1)",
        "insert into vt values (4, 'ok', 12345.5, 'x')",
        "alter table vt alter column n type numeric(8,3)",
        "insert into vt values (4, 'ok', 12345.5, 'x')",
        "select id, n from vt order by id",
        "select format_type(atttypid, atttypmod) from pg_attribute where attrelid = 'vt'::regclass and attname in ('n', 'c') order by attname",
        "alter table vt alter column c type varchar(1)",
        "alter table vt alter column n type numeric",
        "select column_name, data_type, character_maximum_length, numeric_precision, numeric_scale from information_schema.columns where table_name = 'vt' order by ordinal_position",
    ]]);
}

#[test]
fn writable_ctes() {
    check(&[&[
        "create table t (id serial primary key, v int)",
        "create table log (id serial primary key, t_id int, n int)",
        "with ins as (insert into t (v) values (1), (2), (3) returning id, v) select id, v from ins order by id",
        "select id, v from t order by id",
        "with ins as (insert into t (v) values (4) returning id) select count(*) from ins",
        "with u as (update t set v = v + 10 where id = 1 returning id, v) select * from u",
        "with d as (delete from t where v < 3 returning *) select v from d order by v",
        "select id, v from t order by id",
        "with i(x, y) as (insert into t (v) values (5) returning id, v) select x, y from i",
        "with i as (insert into t (v) values (6) returning id, v * 2 as dbl) select dbl from i",
        // moves rows from one table to another
        "create table b (id int primary key, v int)",
        "with moved as (delete from t where v > 4 returning id, v) insert into b (id, v) select id, v from moved",
        "select id, v from b order by id",
        "select id, v from t order by id",
        // chains, and one that nothing reads still runs
        "with i as (insert into t (v) values (7) returning id), j as (insert into log (t_id, n) select id, 1 from i returning id) select (select id from i), (select id from j)",
        "select t_id, n from log order by id",
        "with i as (insert into t (v) values (99) returning id) select 1",
        "select count(*) from t where v = 99",
        "with i as (insert into t (v) values (98) returning id) select (select count(*) from i), (select max(id) from i) - (select min(id) from i)",
        // the main statement changes rows too
        "with d as (delete from t where v = 99 returning v) update log set n = (select count(*) from d)",
        "select t_id, n from log order by id",
        "with u as (update t set v = 0 where v = 98 returning id) delete from log where t_id in (select id from u)",
        "with i as (insert into b (id, v) values (1, 1), (50, 5) on conflict (id) do nothing returning id) select id from i order by id",
        // all or nothing
        "with i as (insert into b (id, v) values (1000, 1) returning id) insert into b (id, v) select id, 2 from i",
        "select count(*) from b where id = 1000",
        "with i as (insert into b (id, v) values (1001, 1) returning id) insert into b (id, v) select id + 1, 2 from i union all select 1001, 3",
        "select count(*) from b where id in (1001, 1002)",
        "begin",
        "with i as (insert into b (id, v) values (2000, 1) returning id) select * from i",
        "rollback",
        "select count(*) from b where id = 2000",
        // errors
        "with i as (insert into t (v) values (1)) select * from i",
        "select * from (with i as (insert into t (v) values (1) returning id) select * from i) x",
        "with i(a, b, c) as (insert into t (v) values (1) returning id) select * from i",
        "with i as (insert into nosuch values (1) returning *) select * from i",
        "with i as (insert into t (nosuch) values (1) returning id) select * from i",
        "with i as (insert into t (v) values (1) returning nosuch) select * from i",
    ]]);
}

#[test]
fn cursors() {
    check(&[
        &[
            "create table c (id int primary key, v text)",
            "insert into c select g, 'v' || g from generate_series(1, 7) g",
            // outside a transaction a cursor has to be WITH HOLD
            "declare k cursor for select id, v from c order by id",
            "begin",
            "declare k scroll cursor for select id, v from c order by id",
            "fetch next from k",
            "fetch 2 from k",
            "fetch from k",
            "fetch k",
            "fetch in k",
            "fetch prior from k",
            "fetch first from k",
            "fetch last from k",
            "fetch next from k",
            "fetch prior from k",
            "fetch absolute 3 from k",
            "fetch relative -1 from k",
            "fetch relative 0 from k",
            "fetch relative 3 from k",
            "fetch forward 2 from k",
            "fetch forward all from k",
            "fetch next from k",
            "fetch backward 3 from k",
            "fetch backward all from k",
            "fetch prior from k",
            "fetch next from k",
            "fetch absolute 0 from k",
            "fetch absolute -2 from k",
            "fetch absolute 100 from k",
            "fetch prior from k",
            "fetch absolute -100 from k",
            "fetch next from k",
            "fetch -2 from k",
            "fetch 0 from k",
            "fetch forward 0 from k",
            "fetch all from k",
            "fetch all from k",
            "fetch backward 2 from k",
            "move forward 2 from k",
            "fetch next from k",
            "move backward all from k",
            "fetch next from k",
            "move absolute 5 from k",
            "fetch next from k",
            "move last from k",
            "move next from k",
            "move prior from k",
            "fetch from k",
            // the rows as they were when it was declared
            "insert into c values (8, 'v8')",
            "move absolute 0 in k",
            "fetch all from k",
            "select count(*) from c",
            "close k",
            "fetch next from k",
            "commit",
        ],
        &[
            "create table c (id int primary key, v text)",
            "insert into c select g, 'v' || g from generate_series(1, 4) g",
            "begin",
            // no scroll: forward only
            "declare k no scroll cursor for select id from c order by id",
            "fetch next from k",
            "fetch prior from k",
            "rollback",
            "begin",
            "declare k cursor for select id from c order by id",
            "declare k cursor for select 1",
            "rollback",
            "begin",
            "declare a cursor for select id from c order by id",
            "declare b cursor for select v from c order by id desc",
            "fetch 2 from a",
            "fetch 2 from b",
            "fetch 1 from a",
            "close a",
            "fetch 1 from a",
            "rollback",
            "begin",
            "declare a cursor for select id from c order by id",
            "declare b cursor for select id from c order by id",
            "close all",
            "fetch 1 from b",
            "rollback",
            "begin",
            "close nosuch",
            "rollback",
            "begin",
            "fetch from nosuch",
            "rollback",
            "begin",
            "declare k cursor for select * from nosuch",
            "rollback",
            "begin",
            "declare k cursor for insert into c values (9, 'x')",
            "rollback",
            // a cursor ends with its transaction, unless it is WITH HOLD
            "begin",
            "declare gone cursor for select id from c order by id",
            "declare kept cursor with hold for select id from c order by id",
            "fetch 1 from gone",
            "fetch 1 from kept",
            "commit",
            "fetch 1 from gone",
            "fetch 1 from kept",
            "fetch prior from kept",
            "close kept",
            "declare late cursor with hold for select id from c order by id desc",
            "fetch 2 from late",
            "close late",
            "begin",
            "declare g cursor for select id from c order by id",
            "fetch 1 from g",
            "rollback",
            "fetch 1 from g",
            // a savepoint's rollback closes the cursors opened after it
            "begin",
            "declare before cursor for select id from c order by id",
            "savepoint sp",
            "declare after cursor for select id from c order by id",
            "rollback to sp",
            "fetch 1 from before",
            "fetch 1 from after",
            "rollback",
            // queries other than a plain select
            "begin",
            "declare v cursor for values (1, 'a'), (2, 'b')",
            "fetch all from v",
            "declare w cursor for with t as (select id from c where id > 2) select id * 10 as x from t order by 1",
            "fetch all from w",
            "declare u cursor for select id from c union all select id + 100 from c order by 1",
            "fetch 6 from u",
            "declare e cursor for select id from c where id > 100 order by id",
            "fetch next from e",
            "fetch prior from e",
            "fetch last from e",
            "fetch all from e",
            "declare n cursor for select null::int as a, 1.5 as b, true as c, '2020-01-02'::date as d",
            "fetch next from n",
            "rollback",
        ],
    ]);
}

#[test]
fn comments() {
    check(&[&[
        "create table c (id int primary key, v text)",
        "create view cv as select id, v from c",
        "create index ci on c (v)",
        "create sequence cs",
        "drop schema if exists cm cascade",
        "create schema cm",
        "comment on table c is 'the table'",
        "comment on column c.v is 'the column'",
        "comment on view cv is 'a view'",
        "comment on column cv.v is 'view column'",
        "comment on index ci is 'an index'",
        "comment on sequence cs is 'seq'",
        "comment on constraint c_pkey on c is 'the key'",
        "comment on schema cm is 'my schema'",
        "select obj_description('c'::regclass, 'pg_class')",
        "select obj_description('c'::regclass)",
        "select col_description('c'::regclass, 2), col_description('c'::regclass, 1)",
        "select col_description('c'::regclass, 0), col_description('c'::regclass, 99)",
        "select obj_description('cv'::regclass, 'pg_class'), obj_description('ci'::regclass, 'pg_class'), obj_description('cs'::regclass, 'pg_class')",
        "select obj_description('c'::regclass, 'pg_namespace') is null",
        "select d.objsubid, d.description, cls.relname from pg_description d join pg_class cls on cls.oid = d.objoid and d.classoid = 'pg_class'::regclass where cls.relname in ('c', 'cv', 'ci', 'cs') order by cls.relname, d.objsubid",
        "select classoid::regclass, objsubid, description from pg_description where objoid = (select oid from pg_constraint where conname = 'c_pkey')",
        "select obj_description('cm'::regnamespace, 'pg_namespace')",
        "select a.attname, col_description(a.attrelid, a.attnum) from pg_attribute a where a.attrelid = 'c'::regclass and a.attnum > 0 order by a.attnum",
        "select relname, obj_description(oid, 'pg_class') from pg_class where relname in ('c', 'cv', 'ci', 'cs') and relnamespace = (select oid from pg_namespace where nspname = current_schema()) order by relname",
        // replaced, quoted, dollar-quoted
        "comment on table c is 'again'",
        "select obj_description('c'::regclass, 'pg_class')",
        "comment on table c is 'it''s ''quoted'' and $x'",
        "select obj_description('c'::regclass, 'pg_class')",
        "comment on table c is $$dollar quoted$$",
        "select obj_description('c'::regclass, 'pg_class')",
        // taken away: NULL, or an empty string
        "comment on table c is ''",
        "select obj_description('c'::regclass, 'pg_class') is null",
        "comment on table c is 'back'",
        "comment on table c is null",
        "select obj_description('c'::regclass, 'pg_class') is null",
        "comment on table c is null",
        // renamed with the object (a view reading it would stop the rename here: see the docs)
        "drop view cv",
        "comment on table c is 'renamed'",
        "comment on column c.v is 'colnamed'",
        "alter table c rename to d",
        "select obj_description('d'::regclass, 'pg_class'), col_description('d'::regclass, 2)",
        "alter table d rename column v to w",
        "select col_description('d'::regclass, 2)",
        "select count(*) from pg_description where objoid = 'd'::regclass",
        "alter index ci rename to ci2",
        "select obj_description('ci2'::regclass, 'pg_class')",
        // gone with the column, the table
        "alter table d drop column w",
        "select count(*) from pg_description where objoid = 'd'::regclass",
        "alter table d add constraint d_chk check (id > 0)",
        "comment on constraint d_chk on d is 'k2'",
        "select count(*) from pg_description where classoid = 'pg_constraint'::regclass and objoid = (select oid from pg_constraint where conname = 'd_chk')",
        "drop table d",
        "create table d (id int primary key, constraint d_chk check (id > 0))",
        "select obj_description('d'::regclass, 'pg_class') is null",
        "select count(*) from pg_description where classoid = 'pg_constraint'::regclass and objoid = (select oid from pg_constraint where conname = 'd_chk')",
        // a schema's objects go with it
        "create table cm.t (a int)",
        "comment on table cm.t is 'in cm'",
        "comment on column cm.t.a is 'col in cm'",
        "select obj_description('cm.t'::regclass, 'pg_class'), col_description('cm.t'::regclass, 1)",
        "drop schema cm cascade",
        "create schema cm",
        "create table cm.t (a int)",
        "select obj_description('cm.t'::regclass, 'pg_class') is null, col_description('cm.t'::regclass, 1) is null",
        // errors
        "comment on table nosuch is 'x'",
        "comment on column d.nosuch is 'x'",
        "comment on column nosuch.x is 'x'",
        "comment on view d is 'x'",
        "comment on index d is 'x'",
        "comment on constraint nosuch on d is 'x'",
        "comment on schema nosuchs is 'x'",
        "comment on table d is 5",
        // in a transaction
        "begin",
        "comment on table d is 'in tx'",
        "select obj_description('d'::regclass, 'pg_class')",
        "rollback",
        "select obj_description('d'::regclass, 'pg_class') is null",
        "begin",
        "comment on table d is 'kept'",
        "commit",
        "select obj_description('d'::regclass, 'pg_class')",
        // nothing to find
        "select obj_description(0, 'pg_class') is null",
        "select obj_description(null, 'pg_class') is null",
        "drop schema cm cascade",
    ]]);
}

#[test]
fn schema_qualified_operators() {
    check(&[&[
        "select 'abc' operator(pg_catalog.~) '^a'",
        "select 'abc' operator(pg_catalog.!~) '^a'",
        "select 'abc' operator(pg_catalog.~*) 'B'",
        "select 1 operator(pg_catalog.=) 1, 2 operator(pg_catalog.<>) 2, 3 operator(pg_catalog.<=) 4",
        "select 1 operator(=) 1",
        "create table q (n text)",
        "insert into q values ('one'), ('two'), ('three')",
        "select n from q where n operator(pg_catalog.~) '^(t)' order by n",
        "select n from q where n operator(pg_catalog.~) '^(t' order by n",
    ]]);
}

#[test]
fn renaming_views() {
    check(&[&[
        "create table t (a int)",
        "insert into t values (1), (2)",
        "create view v as select a from t",
        "create view v2 as select a * 10 as b from t",
        "create materialized view mv as select a from t",
        "alter view v2 rename to v3",
        "select b from v3 order by b",
        "select b from v2",
        "alter view v3 rename to v4",
        "select b from v4 order by b",
        // the same through ALTER TABLE, which Postgres allows on a view
        "alter table v4 rename to v5",
        "select b from v5 order by b",
        "alter materialized view mv rename to mv2",
        "select a from mv2 order by a",
        "select a from mv",
        "alter view if exists nosuch rename to x",
        "alter view nosuch rename to x",
        "alter materialized view nosuch rename to x",
        "alter view t rename to x",
        "alter view mv2 rename to x",
        "alter materialized view v rename to x",
        "alter view v rename to t",
        "alter view v rename to v5",
        "alter view v rename to v",
        "alter view v rename to app.x",
        "select a from v order by a",
        "comment on view v5 is 'five'",
        "alter view v5 rename to v6",
        "select obj_description('v6'::regclass, 'pg_class')",
        "create schema s",
        "create view s.sv as select a from t",
        "alter view s.sv rename to sw",
        "select a from s.sw order by a",
        "select a from s.sv",
        "drop schema s cascade",
    ]]);
}

/// A smallint column holds 16 bits: what is written outside them is refused (22003), the column is a
/// smallint to the catalogs (which is what a dump or an ORM reads), and it keeps its width through
/// ALTER TABLE.
#[test]
fn smallints() {
    check(&[&[
        "create table s (id int primary key, n smallint, m int2 not null default 0, big int)",
        "insert into s values (1, 32767, -32768, 100000)",
        "select n, m, big from s",
        "insert into s (id, n) values (2, 32768)",
        "insert into s (id, n) values (3, -32769)",
        "insert into s (id, m) values (4, 40000)",
        "insert into s (id, n) values (5, null)",
        "update s set n = n + 1 where id = 1",
        "update s set n = 0 where id = 1",
        "update s set n = n + 1 where id = 1",
        "select n from s where id = 1",
        "select data_type, udt_name, numeric_precision from information_schema.columns where table_name = 's' order by ordinal_position",
        "select attname, atttypid::regtype, attlen from pg_attribute where attrelid = 's'::regclass and attnum > 0 order by attnum",
        "select attname, format_type(atttypid, atttypmod) from pg_attribute where attrelid = 's'::regclass and attnum > 0 order by attnum",
        // ALTER: a new column, a type change that fits and one that doesn't
        "alter table s add column w smallint default 7",
        "select w from s where id = 1",
        "alter table s alter column big type smallint",
        "update s set big = 5",
        "alter table s alter column big type smallint",
        "select data_type from information_schema.columns where table_name = 's' and column_name in ('big', 'w') order by column_name",
        "alter table s alter column n type int",
        "update s set n = 100000 where id = 1",
        "select n from s where id = 1",
        // LIKE and a copy of the table keep the width
        "create table s_like (like s including all)",
        "insert into s_like (id, n) values (1, 32768)",
        "insert into s_like (id, n) values (2, 32767)",
        "select data_type from information_schema.columns where table_name = 's_like' and column_name = 'm'",
        // an int2[] is an array, not a smallint
        "select array[1,2]::smallint[], '{3,4}'::int2[]",
        // an explicit cast checks the range too
        "select 100::smallint, 32767::int2",
        "select 32768::smallint",
        "select '40000'::smallint",
        "select (-32769)::int2",
    ]]);
}

/// `LIKE ... ESCAPE`: the escape character makes the next one literal (SQLAlchemy writes
/// `NOT LIKE 'pg/_%' ESCAPE '/'` to reflect a database's schemas), where a plain LIKE uses `\\`.
#[test]
fn like_with_an_escape_character() {
    check(&[&[
        "create table lk (id int primary key, s text)",
        "insert into lk values (1, '100%'), (2, '100x'), (3, 'a_b'), (4, 'axb'), (5, 'path\\to'), (6, 'x!'), (7, 'pg_temp'), (8, 'pgx'), (9, 'A_B')",
        "select s from lk where s like '100!%' escape '!' order by id",
        "select s from lk where s like 'a!_b' escape '!' order by id",
        "select s from lk where s like 'a_b' escape '!' order by id",
        "select s from lk where s not like 'pg/_%' escape '/' order by id",
        "select s from lk where s like 'pg/_%' escape '/' order by id",
        "select s from lk where s ilike 'a!_b' escape '!' order by id",
        "select s from lk where s not ilike 'a!_b' escape '!' order by id",
        // a backslash is an ordinary character once another escape is named
        "select s from lk where s like '%\\to' escape '!' order by id",
        "select s from lk where s like 'path\\to' escape '' order by id",
        "select s from lk where s like 'path\\\\to' order by id",
        // the escape character escapes itself
        "select s from lk where s like 'x!!' escape '!' order by id",
        "select s from lk where s like '%!!' escape '!' order by id",
        "select 'a%' like 'a!%' escape '!', 'ab' like 'a!%' escape '!'",
        "select 'a' like 'a' escape null",
        "select 'a' like null escape '!'",
        "select s from lk where s like '%' || $$_$$ || '%' escape '!' order by id",
        "select 'x' like 'x' escape 'ab'",
        "select 'abc' like 'ab!' escape '!'",
        // in the middle of an expression
        "select count(*) from lk where (s like 'a!_b' escape '!') = true",
        "select id, case when s like 'pg!_%' escape '!' then 'schema' else 'other' end from lk where id > 6 order by id",
    ]]);
}

/// The catalogs' int2vector and oidvector columns: their type names, text and casts.
#[test]
fn index_vectors() {
    check(&[&[
        "create table iv (a int, b int, c text, primary key (a, b))",
        "create unique index iv_c on iv (c)",
        "select pg_typeof(indkey), pg_typeof(indclass), pg_typeof(indoption), pg_typeof(indcollation) from pg_index where indrelid = 'iv'::regclass order by indexrelid::regclass::text",
        "select indkey::text, indoption::text from pg_index where indrelid = 'iv'::regclass order by indexrelid::regclass::text",
        "select indkey::int2[]::text, indkey[0]::text, array_length(indkey, 1) from pg_index where indrelid = 'iv'::regclass order by indexrelid::regclass::text",
        "select indkey::int2[], indoption::int2[] from pg_index where indrelid = 'iv'::regclass order by indexrelid::regclass::text",
        "select x::text from pg_index, unnest(indkey) as x where indrelid = 'iv'::regclass order by indexrelid::regclass::text, 1",
        "select i, indkey[i] from pg_index, generate_subscripts(indkey, 1) i where indrelid = 'iv'::regclass order by indexrelid::regclass::text, i",
        "select count(*) from pg_index where indrelid = 'iv'::regclass and 2 = any(indkey::int2[])",
        "select i from generate_subscripts(array[10,20,30], 1) i",
        "select i from generate_subscripts(array[10,20,30], 1, true) i",
        "select count(*) from generate_subscripts(array[10,20,30], 2)",
        "select count(*) from generate_subscripts(null::int[], 1)",
        "select i, (array['a','b'])[i] from generate_subscripts(array['a','b'], 1) as g(i)",
        "select pg_typeof(conkey), pg_typeof(confkey) from pg_constraint where conrelid = 'iv'::regclass and contype = 'p'",
        "select conkey::text from pg_constraint where conrelid = 'iv'::regclass and contype = 'p'",
    ]]);
}

/// Every setting Postgres has: SET checks a value as Postgres does (type, unit, range, spelling,
/// context), SHOW, `current_setting` and `pg_settings` read it back in Postgres's units, and a name
/// nobody has is 42704.
#[test]
fn settings() {
    check(&[&[
        "show work_mem",
        "set work_mem = 64",
        "show work_mem",
        "set work_mem = '64MB'",
        "show work_mem",
        "set work_mem = '1.5MB'",
        "show work_mem",
        "set work_mem = '10 MB'",
        "show work_mem",
        "set work_mem = '64mb'",
        "set work_mem = '1GB'",
        "show work_mem",
        "set work_mem = 1024",
        "show work_mem",
        "set work_mem = 10",
        "set work_mem = 'abc'",
        "set work_mem = '100 parsecs'",
        "set work_mem = -1",
        "set work_mem = '2147483647kB'",
        "show work_mem",
        "set work_mem = default",
        "show work_mem",
        // booleans, in every spelling
        "show enable_seqscan",
        "set enable_seqscan = 'off'",
        "show enable_seqscan",
        "set enable_seqscan = f",
        "set enable_seqscan = tr",
        "show enable_seqscan",
        "set enable_seqscan = 0",
        "show enable_seqscan",
        "set enable_seqscan = yes",
        "show enable_seqscan",
        "set enable_seqscan = 2",
        "set enable_seqscan = maybe",
        "set enable_seqscan to off",
        "show enable_seqscan",
        "reset enable_seqscan",
        "show enable_seqscan",
        // reals
        "show random_page_cost",
        "set random_page_cost = 1.1",
        "show random_page_cost",
        "set random_page_cost = '2'",
        "show random_page_cost",
        "set random_page_cost = 1e3",
        "show random_page_cost",
        "set random_page_cost = 'x'",
        "show cpu_tuple_cost",
        // enums, and the booleans some of them take
        "show constraint_exclusion",
        "set constraint_exclusion = on",
        "show constraint_exclusion",
        "set constraint_exclusion = 'PARTITION'",
        "show constraint_exclusion",
        "set constraint_exclusion = maybe",
        // (SHOW synchronous_commit is the database's own setting here: full, normal or off)
        "set synchronous_commit = off",
        "select current_setting('synchronous_commit')",
        "set synchronous_commit = 'Local'",
        "select current_setting('synchronous_commit')",
        "set synchronous_commit = true",
        "select current_setting('synchronous_commit')",
        "set synchronous_commit = 'sometimes'",
        "set log_statement = 'all'",
        "show log_statement",
        "set log_statement = 'everything'",
        "show default_table_access_method",
        "set default_table_access_method = heap",
        "set default_table_access_method = nope",
        // time, in the largest whole unit
        "show lock_timeout",
        "set lock_timeout = '5s'",
        "show lock_timeout",
        "set lock_timeout = 90000",
        "show lock_timeout",
        "set lock_timeout = '2min'",
        "show lock_timeout",
        "set lock_timeout = '36h'",
        "show lock_timeout",
        "set lock_timeout = '1d'",
        "show lock_timeout",
        "set lock_timeout = '0'",
        "show lock_timeout",
        "set lock_timeout = '1.5s'",
        "show lock_timeout",
        "set lock_timeout = '0.5ms'",
        "show lock_timeout",
        "set idle_in_transaction_session_timeout = '30s'",
        "show idle_in_transaction_session_timeout",
        "show checkpoint_timeout",
        "show shared_buffers",
        "show effective_cache_size",
        "show log_min_duration_statement",
        // what a session may not change
        "set max_connections = 10",
        "set port = 5433",
        "set shared_buffers = '1GB'",
        "set wal_level = minimal",
        "set autovacuum = off",
        "set server_version = '1'",
        "set max_connections = 'abc'",
        // names nobody has
        "set nonexistent_thing = 1",
        "show nonexistent_thing",
        "reset nonexistent_thing",
        "select current_setting('nonexistent_thing')",
        "select current_setting('nonexistent_thing', true)",
        "select set_config('nonexistent_thing', 'off', false)",
        // custom settings (a name with a dot)
        "set foo.bar = 1",
        "show foo.bar",
        "select current_setting('foo.bar')",
        // set_config and current_setting
        "select set_config('work_mem', '32MB', false), current_setting('work_mem')",
        "select set_config('enable_hashjoin', 'off', false), current_setting('enable_hashjoin')",
        "select set_config('work_mem', 'junk', false)",
        "select current_setting('work_mem', true), current_setting('DEFAULT_TABLE_ACCESS_METHOD')",
        // pg_settings
        "select name, setting, unit, source, vartype, context, min_val, max_val, enumvals, boot_val, reset_val, pending_restart::text from pg_settings where name in ('work_mem', 'enable_seqscan', 'constraint_exclusion', 'synchronous_commit', 'lock_timeout', 'random_page_cost') order by name",
        "select name, short_desc, category, extra_desc from pg_settings where name in ('work_mem', 'wal_level', 'max_connections') order by name",
        "select count(*) from pg_settings where name not like '%.%'",
        "select count(*) from pg_settings where vartype = 'bool' and name not like '%.%'",
        "select context, count(*) from pg_settings where name not like '%.%' group by context order by context",
        "select vartype, count(*) from pg_settings where name not like '%.%' group by vartype order by vartype",
        "reset work_mem",
        "select setting, source, reset_val from pg_settings where name = 'work_mem'",
        "set cpu_tuple_cost = 0.5",
        "select setting, source, reset_val, boot_val from pg_settings where name = 'cpu_tuple_cost'",
        "reset all",
        "show work_mem",
        "show cpu_tuple_cost",
        // a custom setting stays, empty, after RESET ALL and DISCARD ALL
        "select current_setting('foo.bar', true) is null, current_setting('foo.bar', true) = ''",
        "set foo.z = '1'",
        "discard all",
        "select current_setting('foo.z', true) is null, current_setting('foo.z', true) = ''",
    ]]);
}

/// A SET is undone with the transaction (or savepoint) it was made in, unless it is kept.
#[test]
fn settings_follow_transactions() {
    check(&[&[
        "set work_mem = '32MB'",
        "begin",
        "set work_mem = '16MB'",
        "show work_mem",
        "rollback",
        "show work_mem",
        "begin",
        "set work_mem = '8MB'",
        "commit",
        "show work_mem",
        "begin",
        "set local work_mem = '4MB'",
        "show work_mem",
        "commit",
        "show work_mem",
        "begin",
        "set work_mem = '20MB'",
        "savepoint s",
        "set work_mem = '21MB'",
        "set foo.x = 'inner'",
        "rollback to s",
        "show work_mem",
        "select current_setting('foo.x', true)",
        "set work_mem = '22MB'",
        "savepoint t",
        "set work_mem = '23MB'",
        "release t",
        "show work_mem",
        "commit",
        "show work_mem",
        // a failed transaction is rolled back with its settings
        "begin",
        "set work_mem = '99MB'",
        "select 1/0",
        "commit",
        "show work_mem",
        "begin",
        "select set_config('work_mem', '77MB', false)",
        "rollback",
        "show work_mem",
    ]]);
}

/// CREATE TABLE ... AS and SELECT ... INTO: a table made from a query's columns and rows (a plain
/// table after that, with no keys or defaults).
#[test]
fn create_table_as() {
    check(&[&[
        "create table src (id int primary key, n text, v int, d date)",
        "insert into src values (1, 'a', 10, '2024-01-01'), (2, 'b', 20, '2024-01-02'), (3, 'c', NULL, '2024-01-03')",
        "create table t1 as select id, n from src where v > 5",
        "select * from t1 order by id",
        "create table t2 (a, b) as select id, n from src",
        "select a, b from t2 order by a",
        "create table t3 (a) as select id, n from src",
        "select * from t3 order by a",
        "select column_name from information_schema.columns where table_name = 't3' order by ordinal_position",
        "create table t4 as select id, v * 2 as doubled, n || '!' as tagged, d + 1 as next_day from src",
        "select * from t4 order by id",
        "select column_name, data_type from information_schema.columns where table_name = 't4' order by ordinal_position",
        "create table t5 as select * from src with no data",
        "select count(*) from t5",
        "insert into t5 values (1, 'x', 1, '2024-05-05')",
        "select * from t5",
        "create table t6 as select * from src with data",
        "select count(*) from t6",
        "create table if not exists t1 as select 1",
        "select count(*) from t1",
        "create table t1 as select 1",
        "create table t7 as select id, id from src",
        "create table t8 (x, y, z) as select id, n from src",
        "create table t9 as select id from src where id = 1 union all select 99",
        "select * from t9 order by id",
        "create table t10 as with x as (select id from src) select count(*) as c from x",
        "select * from t10",
        "create table t11 as values (1, 'a'), (2, 'b')",
        "select * from t11 order by 1",
        "select column_name from information_schema.columns where table_name = 't11' order by ordinal_position",
        // a table like any other after that: rows in and out, columns added, no key
        "insert into t1 values (10, 'new')",
        "update t1 set n = 'upd' where id = 1",
        "delete from t1 where id = 2",
        "select * from t1 order by id",
        "alter table t1 add column extra int default 7",
        "select * from t1 order by id",
        "select pg_typeof(id), pg_typeof(n) from t1 limit 1",
        "select count(*) from information_schema.table_constraints where table_name = 't1'",
        "insert into t1 values (10, 'twice')",
        "select count(*) from t1 where id = 10",
        // SELECT INTO
        "select id, n into t13 from src where v is not null",
        "select * from t13 order by id",
        "select id into temp t14 from src",
        "select count(*) from t14",
        "select id into t13 from src",
        "select 1 as one, 'x' as two into t23",
        "select * from t23",
        // a failed statement leaves nothing behind, and a rolled back one neither
        "create table t21 as select 1/0",
        "select count(*) from t21",
        "begin",
        "create table t15 as select * from src",
        "select count(*) from t15",
        "rollback",
        "select count(*) from t15",
        // temporary tables
        "create temp table t16 as select id from src",
        "select count(*) from t16",
        "insert into t16 values (9)",
        "select count(*) from t16",
        // from views, joins and limits
        "create view sv as select id, n from src",
        "create table t17 as select * from sv order by id desc limit 2",
        "select * from t17 order by id",
        "create table t18 as select s.id, s.n, t.b as other from src s join t2 t on t.a = s.id",
        "select * from t18 order by id",
        "create table t19 as select nope from src",
        "create table t20 as select * from missing",
        "create table src as select 1",
        "create table t22 as select 1 as one, 'x' as two, now() > now() - interval '1 day' as ok",
        "select * from t22",
        // a query with parameters is not a table's business, and a NULL column is text
        "create table t24 as select null as nothing, 1.5::numeric as n, array[1,2] as a, '{}'::jsonb as j",
        "select nothing is null, n, a, j from t24",
        "select column_name, data_type from information_schema.columns where table_name = 't24' order by ordinal_position",
    ]]);
}

/// stddev, variance, corr, covar and regr_*: floats accumulate as Postgres does (so the last digits
/// agree), integers and numerics through Postgres's numeric arithmetic (so does their scale).
#[test]
fn statistical_aggregates() {
    check(&[&[
        "create table st (id int primary key, g int, x int, y int, f double precision, h double precision, n numeric(10,2), r real)",
        "insert into st values (1, 1, 1, 2, 1.5, 2.5, 1.25, 1.5), (2, 1, 2, 4, 2.5, 4.1, 2.50, 2.5), (3, 1, 3, 5, 3.5, 5.9, 3.75, 3.5), (4, 1, 4, 4, 4.5, 3.2, 10.00, 4.5), (5, 1, 5, 5, 5.5, 8.8, 0.10, 5.5)",
        "insert into st values (6, 2, 10, 3, 0.1, 0.7, 7.77, 0.1), (7, 2, NULL, 7, 0.2, NULL, NULL, 0.2), (8, 2, 30, 1, 0.3, 0.9, 1.11, 0.3), (9, 3, 42, 42, 42.0, 42.0, 42.00, 42.0), (10, 4, NULL, NULL, NULL, NULL, NULL, NULL)",
        "insert into st values (11, 5, 100000, 3, 1e10, 1e-10, 12345678.90, 3.4028235e30), (12, 5, -100000, 4, -1e10, 3e-10, -12345678.90, 1.0), (13, 5, 7, 5, 7.7, 7.7, 0.01, 7.7)",
        // integers and numerics give numerics, floats give doubles
        "select stddev(x), stddev_pop(x), stddev_samp(x), variance(x), var_pop(x), var_samp(x) from st",
        "select stddev(f), stddev_pop(f), stddev_samp(f), variance(f), var_pop(f), var_samp(f) from st",
        "select stddev(n), stddev_pop(n), stddev_samp(n), variance(n), var_pop(n), var_samp(n) from st",
        // (a real is held as a double here, so stddev(real) can differ in the last digits: not compared)
        "select stddev(y), var_samp(y) from st",
        "select pg_typeof(stddev(x)), pg_typeof(stddev(f)), pg_typeof(var_pop(n)), pg_typeof(stddev(r)), pg_typeof(corr(x, y)), pg_typeof(regr_count(x, y))",
        "select g, stddev(x), var_pop(f), variance(n) from st group by g order by g",
        "select g, stddev_samp(y), stddev_pop(y) from st group by g order by g",
        // no rows, one row, only nulls
        "select stddev(x), var_pop(x), corr(x, y), regr_count(x, y), covar_pop(x, y) from st where false",
        "select stddev(x), var_pop(x), var_samp(f), stddev_pop(f), var_pop(n), covar_samp(f, h), corr(f, h) from st where g = 3",
        "select stddev(x), var_pop(f), corr(x, y), regr_count(x, y), regr_slope(x, y) from st where g = 4",
        // the two-argument ones: (dependent, independent)
        "select corr(y, x), covar_pop(y, x), covar_samp(y, x) from st",
        "select corr(f, h), covar_pop(f, h), covar_samp(f, h) from st",
        "select regr_count(y, x), regr_avgx(y, x), regr_avgy(y, x), regr_sxx(y, x), regr_syy(y, x), regr_sxy(y, x) from st",
        "select regr_slope(y, x), regr_intercept(y, x), regr_r2(y, x) from st",
        "select regr_slope(h, f), regr_intercept(h, f), regr_r2(h, f), regr_avgx(h, f), regr_sxy(h, f) from st",
        "select regr_slope(y, x), regr_intercept(y, x), regr_r2(y, x), corr(y, x) from st where g = 1",
        "select g, corr(f, h), regr_slope(h, f), regr_intercept(h, f) from st group by g order by g",
        "select g, regr_r2(y, x), covar_samp(y, x) from st group by g order by g",
        // pairs with a null in either are skipped
        "select regr_count(x, h), corr(x, h), covar_pop(x, h) from st",
        // DISTINCT, FILTER and ORDER BY inside
        "select stddev(distinct x), var_pop(distinct f), variance(distinct n) from st",
        "select var_pop(f) filter (where g = 1), stddev(x) filter (where g = 2), corr(y, x) filter (where g < 3) from st",
        "select stddev(x order by id desc), var_pop(f order by id) from st where g = 1",
        // arithmetic on the result, and as a subquery / HAVING
        "select round(stddev(f)::numeric, 4), round(var_pop(f)::numeric, 4), stddev(x) * 2 from st where g = 1",
        "select g from st group by g having stddev(f) > 1 order by g",
        "select (select stddev(f) from st s2 where s2.g = s1.g) from st s1 where s1.id in (1, 6, 9) order by s1.id",
        // arguments that are expressions and casts
        "select stddev(x * 2), var_pop(f + 1), corr(x::float, y * 2.5) from st",
        "select stddev(x::numeric), var_pop(x::float), variance(x::bigint), stddev(x::smallint) from st",
        // wrong arguments
        "select stddev(x, y) from st",
        "select corr(x) from st",
        "select stddev(*) from st",
        "select stddev('a'::text) from st",
    ]]);
}

/// string_agg, array_agg, json_agg, stddev, corr and the rest as window functions: over the whole
/// partition, over a running frame, over a sliding one.
#[test]
fn list_and_statistical_aggregates_as_windows() {
    check(&[&[
        "create table wv (id int primary key, g int, x int, y int, f double precision, s text)",
        "insert into wv values (1, 1, 10, 3, 1.5, 'a'), (2, 1, 20, 1, 2.5, 'b'), (3, 1, 30, 4, 4.5, 'c'), (4, 1, NULL, 1, 3.5, NULL), (5, 2, 5, 9, 0.5, 'd'), (6, 2, 15, 2, 9.5, 'e'), (7, 3, 1, 1, 1.0, 'f')",
        "select id, string_agg(s, ',') over (partition by g) from wv order by id",
        "select id, string_agg(s, '-') over (partition by g order by id) from wv order by id",
        "select id, string_agg(s, '') over (order by id rows between 1 preceding and current row) from wv order by id",
        "select id, array_agg(x) over (partition by g order by id) from wv order by id",
        "select id, array_agg(s) over (order by id rows between unbounded preceding and 1 following) from wv order by id",
        "select id, json_agg(x) over (partition by g) from wv order by id",
        "select id, jsonb_agg(s) over (partition by g order by id rows between 1 preceding and 1 following) from wv order by id",
        "select id, jsonb_object_agg(s, x) filter (where x is not null) over (partition by g) from wv where s is not null order by id",
        "select id, stddev(f) over (partition by g) from wv order by id",
        "select id, stddev(x) over (partition by g) from wv order by id",
        "select id, var_pop(f) over (order by id) from wv order by id",
        "select id, var_samp(x) over (order by id rows between 2 preceding and current row) from wv order by id",
        "select id, corr(f, y) over (partition by g) from wv order by id",
        "select id, regr_slope(y, f) over (order by id rows between 1 preceding and current row) from wv order by id",
        "select id, covar_pop(y, x) over w, stddev_pop(f) over w from wv window w as (partition by g) order by id",
        "select id, regr_count(y, x) over (partition by g), regr_avgx(y, x) over (partition by g) from wv order by id",
        "select id, string_agg(s, ',') over (partition by g rows between current row and current row) from wv order by id",
        "select g, count(*), stddev(f), string_agg(s, ',') from wv group by g order by g",
        "select id, string_agg(distinct s, ',') over (partition by g) from wv",
        "select id, string_agg(s, ',' order by s) over (partition by g) from wv",
        "select id, percentile_cont(0.5) within group (order by f) over (partition by g) from wv",
        "select id, x - avg(x) over (partition by g) as dev, stddev(x) over (partition by g) as sd from wv order by id",
    ]]);
}

