#[test]
fn like_operators_quantifiers_and_substring_patterns() {
    check(&[&[
        r"select 'abc' ~~ 'a%', 'abc' !~~ 'a%', 'abc' ~~* 'A%', 'abc' !~~* 'A%', 'abc' ~~ 'b%', 'abc' !~~ 'b%'",
        r"select 'a%c' ~~ 'a\%c', 'abc' ~~ 'a\%c', 'a_c' ~~ 'a\_c', null ~~ 'a', 'a' ~~ null, 'a' !~~ null",
        r"select 'abc' ^@ 'a', 'abc' ^@ 'b', 'abc' ^@ '', '' ^@ 'a', null ^@ 'a', 'abc' ^@ null, 'héllo' ^@ 'hé'",
        r"select 'abc' like any (array['a%','b%']), 'abc' like all (array['a%','%c']), 'abc' ilike any (array['A%']), 'abc' not like all (array['x%','y%'])",
        r"select 'abc' like any ('{a%,b%}'), 'abc' like all ('{a%,%z}'), 'abc' not like any ('{a%,%z}'), 'abc' not like all ('{a%,%z}')",
        r"select 'abc' like any (array['x%', null]), 'abc' like any (array['a%', null]), 'abc' like all (array['a%', null]), 'abc' like all (array['x%', null])",
        r"select 'abc' like any (array[]::text[]), 'abc' like all (array[]::text[]), 'abc' not like any (array[]::text[]), 'abc' not like all (array[]::text[])",
        r"select null like any (array['a']), 'a' like any (null::text[]), 'a' like all (null::text[])",
        r"select 'abc' ~~ any (array['a%','z']), 'abc' !~~ all (array['z%','y%']), 'abc' ~~* all (array['A%','%C']), 'abc' !~~* any (array['a%','A%'])",
        r"select 'abc' some like ('x')",
        r"select 'abc' like some (array['x%','a%']), 'abc' ilike some (array['X%','A%']), 'abc' not ilike any (array['A%','B%']), 'abc' not ilike all (array['A%','B%'])",
        r"select 'a_c' like any (array['a\_c']), 'abc' like any (array['a\_c'])",
        r"select 'abc' ~ any (array['x','b']), 'abc' !~ all (array['x','y']), 'abc' ~* any (array['B']), 'abc' ~ all (array['a','b']), 'abc' ~ all (array['a','z']), 'abc' !~ any (array['a','z'])",
        r"select 'abc' ~ any (array['x', null]), 'abc' ~ any (array['b', null]), 'abc' ~ all (array['b', null]), 'abc' ~ all (array['z', null]), 'abc' ~ any (array[]::text[]), 'abc' ~ all (array[]::text[])",
        r"select 'abc' ~ any ('{a,z}'), 'abc' ~* all ('{A,B}'), 'abc' !~* any ('{A,Z}')",
        r"create table lk (id int primary key, name text, pats text[])",
        r"insert into lk values (1, 'alpha', '{a%,%z}'), (2, 'beta', '{b%,x%}'), (3, 'gamma', '{z%}'), (4, null, '{a%}'), (5, 'delta', null)",
        r"select id from lk where name like any (pats) order by id",
        r"select id from lk where name like all (pats) order by id",
        r"select id from lk where name not like all (pats) order by id",
        r"select id from lk where name ~ any (pats) order by id",
        r"select id from lk where name ilike any (array['A%', 'D%']) order by id",
        r"select id from lk where name like any (select p from (values ('a%'), ('g%')) v(p)) order by id",
        r"select id from lk where name like all (select p from (values ('a%'), ('%a')) v(p)) order by id",
        r"select id from lk where name ~~ 'a%' or name ^@ 'g' order by id",
        r"select id, name ~~ 'a%', name ^@ 'a' from lk order by id",
        r"select substring('abcdef' from '..$'), substring('Thomas' from '...$'), substring('Thomas' from 2 for 3)",
        r"select substring('foobar' from 'o(.)b'), substring('foobar', 'o.b'), substring('abc' from 'z'), substring('abc' from '')",
        r#"select substring('foobar' from '%#"o_b#"%' for '#'), substring('abcdef' similar '%#"cd#"%' escape '#'), substring('abcdef' from '#"ab#"%' for '#')"#,
        r"select substring('foobar' from 'o+(b)?(x)?'), substring('foobar' from '(x)?o+'), substring('foobar' from '(?:o+)(b)')",
        r"select substring('abc' from '('), substring('abc' from '[')",
        r#"select substring('abcdef' similar 'abc' escape '#'), substring('abcdef' similar '%' escape '#'), substring('abc' similar 'a#"b#"c#"d' escape '#')"#,
        r#"select substring('abcdef' similar '%#"cd#"%')"#,
        r#"select substring('abcdef' from '%#"cd#"%' for '')"#,
        r"select substring('abc' from 2), substring('abc' from 2 for 1), substring('abc', 2), substring('abc', 2, 1), substring('abc' for 2), substring('abc' from 0 for 2)",
        r"select substring('a2c' from '2'), substring('abc' from '2')",
        r"select substring('héllo wörld' from 'w(.)r'), substring('HeLLo' from '(?i)l+'), substring('foo123bar' from '\d+'), substring('foo123bar' from '([a-z]+)(\d+)')",
        r"select substring(null from 'a'), substring('a' from null::text), substring('abc' similar null escape '#')",
        r"select substring('abc'::bytea from 2), substring('abc'::bytea from 1 for 2)",
        r"select id, substring(name from '^(.)'), substring(name from 'a$') from lk order by id",
        r"select id from lk where substring(name from '^(.)') = 'b'",
        r"select substring('abc' from 'b' for '#')",
        r"select substring('abc' similar 'b' escape '##')",
    ]]);
}

#[test]
fn regexp_functions_with_start_n_flags_and_string_to_table() {
    check(&[&[
        r"select regexp_instr('abc123', '[0-9]+'), regexp_instr('abc123abc', 'abc', 2), regexp_instr('abcabc', 'abc', 1, 2), regexp_instr('abc123', '[0-9]+', 1, 1, 1), regexp_instr('abc', 'z')",
        r"select regexp_instr('abcabc', '(b)(c)', 1, 1, 0, 'i', 2), regexp_instr('ABC', 'b', 1, 1, 0, 'i'), regexp_instr('abc', 'b', 1, 1, 1, 'c', 0)",
        r"select regexp_substr('abc123', '[0-9]+'), regexp_substr('abcabc', 'abc', 2), regexp_substr('abcabc', 'abc', 1, 2), regexp_substr('ABC', 'b', 1, 1, 'i'), regexp_substr('abcd', '(b)(c)', 1, 1, '', 2), regexp_substr('abc','z')",
        r"select regexp_count('a1b2c3', '[0-9]'), regexp_count('a1b2c3', '[0-9]', 3), regexp_count('aAaA', 'a', 1, 'i'), regexp_count('abc', ''), regexp_count('', 'a')",
        r"select regexp_replace('aaa', 'a', 'b', 2), regexp_replace('aaa', 'a', 'b', 2, 2), regexp_replace('aaa', 'a', 'b', 1, 0), regexp_replace('aAa', 'a', 'b', 1, 0, 'i'), regexp_replace('abcabc', '(b)', '[\1]', 2, 2), regexp_replace('abc','z','y',1,1)",
        r"select regexp_replace('a1b22', '[0-9]+', '#', 'g'), regexp_replace('abc', '(b)', '[\1]')",
        r"select regexp_instr('abc', 'b', 0)",
        r"select regexp_substr('abc', 'b', 1, 0)",
        r"select regexp_count('abc', 'b', 0)",
        r"select regexp_instr('abc','b',1,1,2)",
        r"select regexp_instr(null,'a'), regexp_count('a',null), regexp_substr('a','a',null)",
        r"select string_to_table('a,b,c', ',')",
        r"select * from string_to_table('a,b,c', ',') with ordinality",
        r"select string_to_table('a,b,c', ',', 'b')",
        r"select string_to_table('abc', '')",
        r"select string_to_table(null, ',')",
        r"select string_to_table('abc', null)",
        r"select upper(string_to_table('a,b', ',')), string_to_table('x,y', ',') || '!'",
        r"select regexp_matches('a1b22', '[0-9]+', 'g')",
        r"select (regexp_matches('a1b22', '([a-z])([0-9]+)'))[2]",
        r"select regexp_matches('a1b22', '([a-z])([0-9]+)', 'g')",
        r"select regexp_matches('abc', 'z'), 1",
    ]]);
}

#[test]
fn jsonb_delete_insert_pretty_and_set_lax() {
    check(&[&[
        r#"select '{"a":1,"b":2}'::jsonb - 'a', '[1,2,3]'::jsonb - 1, '["a","b","a"]'::jsonb - 'a', '[1,2,3]'::jsonb - -1, '[1,2,3]'::jsonb - 5, '[1,2,3]'::jsonb - -5"#,
        r#"select '{"a":1,"b":2,"c":3}'::jsonb - array['a','b'], '{"a":1}'::jsonb - 'z', '["a","b","c"]'::jsonb - array['a','c'], '{"a":1}'::jsonb - array[]::text[]"#,
        r#"select '{"a":1}'::jsonb - 1"#,
        r"select '1'::jsonb - 'a'",
        r#"select '"x"'::jsonb - 1"#,
        r"select 'null'::jsonb - array['a']",
        r#"select '[1,"1",1]'::jsonb - '1', '["1"]'::jsonb - '1', '[[1],[2]]'::jsonb - 0"#,
        r#"select '{"a":{"b":[1,2]}}'::jsonb #- '{a,b,0}', '{"a":{"b":1}}'::jsonb #- '{a,b}', '{"a":1}'::jsonb #- '{x,y}', '[1,2,3]'::jsonb #- '{-1}', '[1,2,3]'::jsonb #- '{5}', '{"a":1}'::jsonb #- '{}'"#,
        r"select '[1,2]'::jsonb #- '{x}'",
        r"select '1'::jsonb #- '{a}'",
        r#"select '{"a":[1]}'::jsonb #- '{a,x}'"#,
        r#"select '{"a":1}'::jsonb #- null::text[]"#,
        r#"select '{"a":{"b":{"c":1,"d":2}}}'::jsonb #- '{a,b,c}', '{"a":[{"x":1},{"y":2}]}'::jsonb #- '{a,1,y}'"#,
        r#"select jsonb_insert('{"a":[0,1]}', '{a,1}', '9'), jsonb_insert('{"a":[0,1]}', '{a,1}', '9', true), jsonb_insert('{"a":1}', '{b}', '2'), jsonb_insert('[0,1]', '{-1}', '9'), jsonb_insert('[0,1]', '{-1}', '9', true), jsonb_insert('[0,1]', '{5}', '9'), jsonb_insert('[0,1]', '{-9}', '9'), jsonb_insert('[0,1]', '{5}', '9', true)"#,
        r#"select jsonb_insert('{"a":1}', '{a}', '2')"#,
        r"select jsonb_insert('1', '{a}', '2')",
        r"select jsonb_insert('[1]', '{x}', '2')",
        r#"select jsonb_insert('{"a":{"b":1}}', '{a,c}', '2'), jsonb_insert('{"a":1}', '{x,y}', '2'), jsonb_insert('{}', '{}', '2')"#,
        r#"select jsonb_insert('{"a":[1]}', '{a,0}', 'null'), jsonb_insert('{"a":[1]}', '{a,0}', '{"k":[1,2]}', true)"#,
        r#"select jsonb_pretty('{"a":[1,{"b":2}],"c":"x"}'), jsonb_pretty('[]'), jsonb_pretty('{}'), jsonb_pretty('1'), jsonb_pretty('"s"'), jsonb_pretty('null')"#,
        r#"select jsonb_pretty('{"bb":1,"a":[],"c":{},"aa":[[1,2],[]]}')"#,
        r#"select jsonb_pretty('[1,[2,[3,{"x":null}]]]')"#,
        r"select jsonb_pretty(null)",
        r#"select jsonb_set_lax('{"a":1}', '{a}', null, true, 'delete_key'), jsonb_set_lax('{"a":1}', '{a}', null), jsonb_set_lax('{"a":1}', '{a}', null, true, 'return_target'), jsonb_set_lax('{"a":1}', '{a}', null, true, 'use_json_null'), jsonb_set_lax('{"a":1}', '{b}', '2', false), jsonb_set_lax('{"a":1}', '{b}', '2')"#,
        r#"select jsonb_set_lax('{"a":1}', '{a}', null, true, 'raise_exception')"#,
        r#"select jsonb_set_lax('{"a":1}', '{a}', null, true, 'bogus')"#,
        r"select jsonb_set_lax(null, '{a}', '1'), jsonb_set_lax('{}', null, '1'), jsonb_set_lax('{}', '{a}', '1', null)",
        r"create table jt (id int primary key, doc jsonb)",
        r#"insert into jt values (1, '{"a":1,"b":[1,2],"c":{"d":1}}'), (2, '[1,2,3]'), (3, null)"#,
        r"select id, doc - 'a', doc #- '{c,d}' from jt order by id",
        r"select id, jsonb_pretty(doc) from jt where id = 1",
        r#"select id from jt where doc - 'a' = '{"b":[1,2],"c":{"d":1}}'"#,
        r"update jt set doc = doc - 'a' where id = 1",
        r"select doc from jt where id = 1",
        r"update jt set doc = doc #- '{b,0}' where id = 1",
        r"select doc from jt where id = 1",
        r"select 5 - 3, 2.5 - 1, date '2020-01-05' - 1, '[1]'::jsonb || '[2]'::jsonb",
    ]]);
}

