#[test]
fn text_extension_functions() {
    check(&[&[
        r"create extension if not exists pg_trgm",
        r"create extension if not exists fuzzystrmatch",
        r"create extension if not exists unaccent",
        r"select similarity('word','two words'), similarity('hello','hallo'), similarity('','abc'), similarity('abc','abc')",
        r"select word_similarity('word','two words'), strict_word_similarity('word','two words'), word_similarity('cat','the big cat sat')",
        r"select show_trgm('word'), show_trgm('two words'), show_trgm(''), show_trgm('a')",
        r"select show_trgm('Hello, World_1 ñandú')",
        r"select similarity(null,'a'), word_similarity('a',null), show_trgm(null)",
        r"select levenshtein('kitten','sitting'), levenshtein('','abc'), levenshtein('abc',''), levenshtein('same','same')",
        r"select levenshtein('kitten','sitting',1,2,3), levenshtein('kitten','sitting',2,1,1)",
        r"select levenshtein_less_equal('kitten','sitting',2), levenshtein_less_equal('kitten','sitting',3), levenshtein_less_equal('extensive','exhaustive',2), levenshtein_less_equal('extensive','exhaustive',4)",
        r"select levenshtein_less_equal('kitten','sitting',1,2,3,5)",
        r"select levenshtein(repeat('a',300),'b')",
        r"select levenshtein('kitten', 'sitting', -1, 1, 1)",
        r"select soundex('Robert'), soundex('Rupert'), soundex('Tymczak'), soundex(''), soundex('123'), soundex('Ashcraft')",
        r"select difference('Anne','Ann'), difference('Anne','Andrew'), difference('','')",
        r"select metaphone('Thompson',10), metaphone('Knight',4), metaphone('Schmidt',6), metaphone('',5)",
        r"select metaphone('abc',0)",
        r"select metaphone('abc',-1)",
        r"select metaphone(repeat('a',300),5)",
        r"select dmetaphone('Smith'), dmetaphone('Schmidt'), dmetaphone_alt('Smith'), dmetaphone_alt('Schmidt'), dmetaphone('Jose'), dmetaphone_alt('Jose')",
        r"select dmetaphone('Xavier'), dmetaphone('Thomas'), dmetaphone('Caesar'), dmetaphone('Wright')",
        r"select daitch_mokotoff('Schwartz'), daitch_mokotoff('Moskowitz'), daitch_mokotoff('Peterson'), daitch_mokotoff('')",
        r"select unaccent('Hôtel éléphant'), unaccent('ÀÉÎÕÜ àéîõü ñ ß æ'), unaccent(''), unaccent('plain')",
        r"select unaccent('unaccent', 'Hôtel')",
        r"select unaccent('nosuchdict', 'Hôtel')",
        r"select unaccent(null), soundex(null), levenshtein(null,'a'), difference('a',null)",
        r"select pg_typeof(levenshtein('a','b')), pg_typeof(soundex('a')), pg_typeof(daitch_mokotoff('a')), pg_typeof(unaccent('a'))",
        r"create table trg (id serial primary key, name text)",
        r"insert into trg(name) values ('Hôtel Paris'),('Hotel Berlin'),('Motel One'),('hostel'),('Grand Hotel')",
        r"create index trg_name_gin on trg using gin (name gin_trgm_ops)",
        r"create index trg_name_gist on trg using gist (name gist_trgm_ops)",
        r"select name, similarity(name,'hotel') s from trg order by s desc, name",
        r"select name from trg where unaccent(name) ilike '%hotel%' order by name",
        r"select name, levenshtein(lower(name),'hotel') d from trg order by d, name",
        r"select name, soundex(name) from trg order by name",
        r"select name from trg where difference(name,'hotel') >= 3 order by name",
        r"select pg_typeof(show_trgm('a')), pg_typeof(levenshtein('a','b')), pg_typeof(soundex('a')), pg_typeof(daitch_mokotoff('a')), pg_typeof(unaccent('a'))",
        r"drop extension if exists fuzzystrmatch, unaccent",
        r"drop extension pg_trgm cascade",
        r"drop extension if exists pg_trgm",
    ]]);
}

#[test]
fn trigram_operators() {
    check(&[&[
        r"create extension if not exists pg_trgm",
        r"select 'word' % 'two words', 'hello' % 'hallo', 'abc' % 'xyz', 'hotel' % 'hotell'",
        r"select 'word' <% 'two words', 'cat' <% 'the big cat sat', 'dog' <% 'the big cat sat'",
        r"select 'two words' %> 'word', 'the big cat sat' %> 'cat', 'the big cat sat' %> 'dog'",
        r"select 'word' <<% 'two words', 'cat' <<% 'the big cat sat', 'wo' <<% 'two words'",
        r"select 'two words' %>> 'word', 'the big cat sat' %>> 'cat'",
        r"select 'word' <-> 'two words', 'hello' <-> 'hallo', 'abc' <-> 'abc', 'abc' <-> 'xyz'",
        r"select 'word' <<-> 'two words', 'cat' <<-> 'the big cat sat', 'two words' <->> 'word'",
        r"select 'word' <<<-> 'two words', 'two words' <->>> 'word'",
        r"select null % 'a', 'a' % null, null <-> 'a', null <% 'a'",
        r"select 7 % 3, 7.5 % 2, (-7) % 3",
        r"create table trg2 (id serial primary key, name text, score int)",
        r"insert into trg2(name, score) values ('Hotel Paris', 3),('Hotel Berlin', 5),('Motel One', 7),('hostel', 9),('Grand Hotel', 11),('Paris Hilton', 13)",
        r"create index trg2_gin on trg2 using gin (name gin_trgm_ops)",
        r"select name from trg2 where name % 'hotle' order by name",
        r"select name from trg2 where name % 'hotel' order by name",
        r"select name, name <-> 'hotel' d from trg2 order by name <-> 'hotel', name",
        r"select name from trg2 where name <% 'paris' order by name",
        r"select name from trg2 where 'paris hotel' %> name order by name",
        r"select name, round((1 - (name <-> 'hotel'))::numeric, 3) from trg2 order by 2 desc, name limit 3",
        r"select name from trg2 where score % 2 = 1 and name % 'hotel' order by name",
        r"select a.name, b.name from trg2 a join trg2 b on a.name % b.name and a.id < b.id order by 1, 2",
        r"select name from trg2 where name ilike '%otel%' and name % 'hotel' order by name",
        r"select name % 'hotel' from trg2 order by id",
        r"select count(*) from trg2 where similarity(name, 'hotel') > 0.3",
    ]]);
}

/// Texts too long for pg_trgm's allocator: "out of memory" (54000) from 238,609,294 bytes, "invalid memory alloc
/// request size" (XX000, another class) just below. The errors are raised before anything is built, so they cost
/// the text and no more, on both sides. One statement each: Postgres folds an immutable operator (`<->`) while it
/// plans, before a stable one (`%`) runs, so two in a row would not fail in the order they are written.
#[test]
fn trigram_memory_limits() {
    check(&[&[
        r"create extension if not exists pg_trgm",
        r"select similarity(repeat(' ', 238609294), 'a')",
        r"select similarity('a', repeat(' ', 238609293))",
        r"select similarity(repeat(' ', 238609292), repeat(' ', 238609294))",
        r"select similarity(repeat(' ', 238609294), repeat(' ', 238609292))",
        r"select show_trgm(repeat(' ', 238609292))",
        r"select repeat(' ', 238609294) % 'a'",
        r"select repeat(' ', 238609292) <-> 'a'",
        r"select word_similarity('aa', repeat(' ', 238609292))",
        r"select repeat(' ', 238609292) <<% 'aa'",
        r"select 'aa' <<<-> repeat(' ', 238609292)",
    ]]);
}

