#[test]
fn aggregates_as_postgres_works_them_out() {
    check_text(&[&[
        "set extra_float_digits = 0",
        "create table agg_f4 (a int2, b float4)",
        "insert into agg_f4 values (56, 7.8), (100, 99.097), (0, 0.09561), (42, 324.78)",
        // sum(real) is a real; a real as numeric has its float4 digits
        "select sum(b) from agg_f4",
        "select b::numeric from agg_f4 order by 1",
        "select stddev_pop(b::numeric), var_samp(b::numeric) from agg_f4",
        // NaN and the infinities in numeric variance
        "select var_pop('inf'::numeric), var_samp('inf'::numeric), stddev_pop('nan'::numeric)",
        "select sum(x::numeric), avg(x::numeric), var_pop(x::numeric) from (values ('1'), ('infinity')) v(x)",
        // the floats' transition and combine functions
        "select float8_accum('{4,140,2900}'::float8[], 100)",
        "select float8_regr_accum('{4,140,2900,1290,83075,15050}'::float8[], 200, 100)",
        "select float8_combine('{3,60,200}'::float8[], '{2,180,200}'::float8[])",
        "select float8_combine('{0,0,0}'::float8[], '{2,180,200}'::float8[])",
        "select float8_regr_combine('{3,60,200,750,20000,2000}'::float8[], '{2,180,200,740,57800,-3400}'::float8[])",
        "select booland_statefunc(true, false), boolor_statefunc(true, false), booland_statefunc(null, true) is null",
        // bit strings
        "create table agg_bits (y bit(4))",
        "insert into agg_bits values (B'0101'), (B'0100'), (B'1100')",
        "select bit_and(y), bit_or(y), bit_xor(y) from agg_bits",
        // an array of fractions with nulls
        "select percentile_disc(array[[null,1,0.5],[0.75,0.25,null]]) within group (order by x) from generate_series(1, 9) x",
        // DISTINCT and ordered-set aggregates: groups in sorted order, as Postgres's GroupAggregate gives them
        "select x % 3, sum(distinct x) from generate_series(9, 1, -1) x group by x % 3",
        "select x % 4, mode() within group (order by x) from generate_series(9, 1, -1) x group by x % 4",
        // hypothetical-set aggregates' direct arguments
        "select rank('3') within group (order by x) from generate_series(1, 5) x",
        "select rank(3) within group (order by x) from (values ('fred'), ('jim')) v(x)",
        "select rank(x) within group (order by x) from generate_series(1, 5) x",
        "select rank(sum(x)) within group (order by x) from generate_series(1, 5) x",
        // aggregates where they can't be
        "select max(x) filter (where sum(x) > 0) from generate_series(1, 3) x",
        "select max(min(x)) from generate_series(1, 3) x",
        "select string_agg(distinct x::text, ',' order by x) from generate_series(1, 3) x",
        // a subquery of an outer query's columns, grouped
        "select array(select sum(x + y) s from generate_series(1, 3) y group by y order by s) from generate_series(1, 3) x",
        "select array(select percentile_disc(a) within group (order by x) from (values (0.3), (0.7)) v(a) group by a) \
         from generate_series(1, 5) g(x)",
        // an unqualified column of a table before a LATERAL subquery with grouping sets
        "select * from (values (1), (2)) v(a), lateral (select a, i, count(*) from generate_series(1, 3) i \
         group by cube(i)) s order by v.a, i",
        "select * from (values (1), (2)) v(x), lateral (select a, b, sum(v.x) from (values (1, 2)) w(a, b) \
         group by rollup (a, b)) s",
    ]]);
}

