#[test]
fn views_take_defaults_options_and_rules_as_postgres_does() {
    check(&[&[
        "create table vd_t (a int, b text default 'Table default', c text default 'Table default', d text)",
        "create view vd_v as select * from vd_t",
        "alter view vd_v alter b set default 'View default'",
        "alter view vd_v alter column d set default 'View default'",
        "alter view vd_v alter nope set default 'x'",
        "insert into vd_v values (1)",
        "insert into vd_v values (2), (3)",
        "insert into vd_v values (4, default, default, default)",
        "insert into vd_v (a, c) values (5, 'given')",
        "update vd_v set d = default where a = 5",
        "alter view vd_v alter d drop default",
        "insert into vd_v values (6, default, default, default)",
        "select * from vd_t order by a",
        "alter view vd_v set (check_option = here)",
        "alter view vd_v set (check_option = local)",
        "select check_option from information_schema.views where table_name = 'vd_v'",
        "alter view vd_v reset (check_option)",
        "select check_option from information_schema.views where table_name = 'vd_v'",
        "alter view vd_v set (nope = 1)",
        "alter view vd_v set (security_barrier = true)",
        "create view vd_ro as select a from vd_t limit 1",
        "alter view vd_ro set (check_option = local)",
        "select pg_relation_is_updatable('vd_v'::regclass, false), pg_relation_is_updatable('vd_ro'::regclass, false)",
        "select pg_column_is_updatable('vd_v'::regclass, 1::smallint, false)",
        "create view vd_up as select a, upper(b) from vd_t",
        "select pg_column_is_updatable('vd_up'::regclass, 2::smallint, false)",
        "select table_name, is_updatable, is_insertable_into from information_schema.views where table_name like 'vd%' order by 1",
        "create rule vd_ins as on insert to vd_ro do instead insert into vd_t (a) values (new.a)",
        "select table_name, is_insertable_into from information_schema.tables where table_name like 'vd%' order by 1",
        "select pg_relation_is_updatable('vd_ro'::regclass, false)",
        "create rule vd_upd as on update to vd_up where old.a > 0 do instead update vd_t set a = new.a where a = old.a",
        "update vd_up set a = 7 where a = 1",
        "drop view vd_up",
        "drop view vd_ro",
        "drop view vd_v",
        "drop table vd_t",
    ]]);
}

/// HAVING without GROUP BY or aggregates reads no rows; PREPARE's `unknown` and EXECUTE's argument types; COMMIT
/// AND CHAIN; a set-returning function in VALUES; FETCH ... WITH TIES's checks; SET (a, b) = (x); custom setting
/// names; a DateStyle that keeps what it leaves out; a prepared SELECT * whose table changed; DROP INDEX of a
/// temporary table's index.
#[test]
fn exact_dml_and_sessions() {
    check(&[
        &[
            "create table th (a int)",
            "insert into th values (0), (1)",
            "select 1 as one from th having 1 < 2",
            "select 1 as one from th where 1/a = 1 having 1 < 2",
            "select 1 as one from th where 1/a = 1 having 1 > 2",
        ],
        &[
            "prepare q7(unknown) as select $1 = 'x'::text",
            "execute q7('x')",
            "prepare q3(int, float8) as select $1 + $2",
            "execute q3(1, false)",
            "execute q3(1, 2)",
            "deallocate all",
        ],
        &[
            "create table tc (a int)",
            "begin",
            "insert into tc values (1)",
            "commit and chain",
            "insert into tc values (2)",
            "rollback and chain",
            "insert into tc values (3)",
            "commit",
            "select * from tc order by a",
            "commit and chain",
            "rollback and chain",
            "begin",
            "select 1/0",
            "commit and chain",
            "insert into tc values (4)",
            "commit",
            "select * from tc order by a",
        ],
        &[
            "create table tv (a int)",
            "insert into tv values (generate_series(1, 3))",
            "select * from tv order by a",
            "insert into tv (a) values (1, 2)",
        ],
        &[
            "create table tt (a int)",
            "select a from tt order by a fetch first 1 row with ties for update skip locked",
            "select a from tt order by a fetch first null rows with ties",
        ],
        &[
            "create table tu (a int, b int)",
            "insert into tu values (1, 2)",
            "update tu set (a, b) = (v.*) from (values (3, 4)) as v(i, j)",
            "update tu set (a, b) = (select 5, 6)",
            "select * from tu",
        ],
        &[
            "set custom.\"bad-guc\" = 42",
            "set custom.good_guc = 42",
            "show custom.good_guc",
            "set default_with_oids to f",
            "set default_with_oids to t",
        ],
        &[
            "set datestyle = 'ISO, YMD'",
            "set datestyle = 'SQL'",
            "show datestyle",
            "select '2006-08-13 12:34:56'::timestamp",
            "set datestyle = 'Postgres, YMD'",
            "select '2006-08-13 12:34:56'::timestamp, '2006-08-13'::date",
            "set datestyle = 'iso, sql'",
            "set datestyle = 'ISO, MDY'",
        ],
        &[
            "create table pc (a int)",
            "prepare pcs as select * from pc",
            "execute pcs",
            "alter table pc add column b int",
            "execute pcs",
            "alter table pc drop column b",
            "execute pcs",
            "deallocate pcs",
        ],
        &[
            "create temp table tmpi (a int)",
            "create index tmpi_a on tmpi (a)",
            "drop index tmpi_a",
            "create index tmpi_a on tmpi (a)",
        ],
    ]);
}

/// Batch 10's dates and times: typmod rounding of casts and literals, date_trunc of a date and its units, extract's
/// BC centuries and decades and its units on infinity, interval_hash, `::interval day to minute`, dynamic zone
/// abbreviations (MSK), timetz AT TIME ZONE, timestamptz(date, time), datestyle's order alone, and to_timestamp's
/// separators, Y,YYY, RM, IDDD, FFn and its errors.
#[test]
fn dates_and_times_batch10() {
    check_text(&[&[
        "set time zone 'UTC'",
        "select '2024-01-02 03:04:05.678'::timestamp(1), '2024-01-02 03:04:05.678'::timestamp(0)",
        "select timestamp(2) without time zone '2024-01-02 03:04:05.678', timestamp(1) with time zone '2024-01-02 03:04:05.678+00'",
        "select '1 day 02:03:04.5678'::interval(2), '12:34:56.789'::time(1)",
        "select date_trunc('MILLENNIUM', timestamp '1970-03-20 04:30'), date_trunc('CENTURY', timestamp '1970-03-20')",
        "select date_trunc('century', date '2004-08-10'), date_trunc('century', date '0055-08-10 BC'), date_trunc('decade', date '0002-12-31 BC')",
        "select date_trunc('dow', timestamp '2004-08-10')",
        "select date_trunc('bogus', timestamp '2004-08-10')",
        "select extract(century from date '0100-12-31 BC'), extract(decade from date '0001-01-01 BC'), extract(decade from date '0011-01-01 BC'), extract(millennium from date '1000-12-31 BC')",
        "select extract(timezone_m from date '2020-08-11')",
        "select extract(timezone_h from date '2020-08-11')",
        "select extract(microsec from date 'infinity')",
        "select extract(hour from date 'infinity')",
        "select extract(hour from timestamp 'infinity'), extract(years from timestamp '-infinity')",
        "select isfinite('infinity'::date), isfinite('today'::date)",
        "select interval_hash('30 days'::interval) = interval_hash('1 month'::interval), interval_hash('1 day'::interval), interval_hash_extended('1 day'::interval, 0)",
        "select '1 day 02:03:04'::interval day to minute, '3 mons 5 days'::interval year, '-00:00:14'::interval minute, '1 02:03:04.567'::interval day to second(1)",
        "select interval '1 2' day to minute",
        "select '2011-03-27 02:00:00 MSK'::timestamptz, '2011-03-27 01:59:59 MSK'::timestamptz, '2014-10-26 01:00:00 MSK'::timestamptz",
        "select '2011-03-26 23:00:00 UTC'::timestamptz at time zone 'MSK', '2011-03-27 02:00:00'::timestamp at time zone 'MSK'",
        "select time with time zone '01:02-08' at time zone 'UTC', time with time zone '01:02-08' at time zone interval '-10:00'",
        "select '15:36:39 MSK m2'::timetz",
        "select cast(time with time zone '01:02-08' as interval)",
        "select cast(interval '02:03' as time with time zone)",
        "select timestamptz(date '1994-01-01', time with time zone '11:00-5'), timestamptz(date '1994-01-01', time '11:00')",
        "select '2202020-10-05'::date::timestamp",
        "set datestyle to postgres, mdy",
        "set datestyle to dmy",
        "show datestyle",
        "select timestamp with time zone '27/12/2001 04:05:06.789-08'",
        "reset datestyle",
        "select to_timestamp('1,582nd VIII 21', 'Y,YYYth FMRM DD')",
        r#"select to_timestamp('15 "text between quote marks" 98 54 45', E'HH24 "\\"text between quote marks\\"" YY MI SS')"#,
        "select to_timestamp('97/Feb/16', 'YYMonDD')",
        "select to_timestamp('5527', 'IIWID'), to_timestamp('2005364', 'IYYYIDDD')",
        "select to_timestamp('2011-12-18 11:38 20', 'YYYY-MM-DD HH12:MI TZM'), to_timestamp('2011-12-18 11:38 -05:20', 'YYYY-MM-DD HH12:MI TZH:TZM')",
        "select i, to_timestamp('2018-11-02 12:34:56.123456', 'YYYY-MM-DD HH24:MI:SS.FF' || i) from generate_series(1, 6) i",
        "select to_timestamp('2000 ++ JUN', 'YYYY  MON'), to_timestamp(' 2000 +JUN', 'YYYY/MON'), to_timestamp('2000 + JUN', 'YYYY MON')",
        "select to_timestamp('2000 + + JUN', 'YYYY  MON')",
        "select to_timestamp('2005527', 'YYYYIWID')",
        "select to_timestamp('19971', 'YYYYMMDD')",
        "select to_timestamp('1997-11-Jan-16', 'YYYY-MM-Mon-DD')",
    ]]);
    check(&[&[
        "create table b10_ts (d1 timestamp(2) with time zone, i interval)",
        "begin",
        "insert into b10_ts (d1) values ('now')",
        "select count(*) from b10_ts where d1 = timestamp(2) with time zone 'now'",
        "commit",
        "insert into b10_ts (d1) values ('19970710 173201 America/Does_not_exist')",
        "insert into b10_ts (i) values ('2147483647 years')",
    ]]);
}

/// Batch 10's json, jsonb, jsonpath and SQL/JSON cases: what regress's json, jsonb, jsonb_jsonpath,
/// jsonpath_encoding and sqljson files print.
#[test]
fn json_regress_details() {
    check(&[&[
        // jsonpath's DETAILs and HINTs
        r#"select '"\u0000"'::jsonpath"#,
        r#"select '"\ud83d\ud83d"'::jsonpath"#,
        r#"select '"\ude04X"'::jsonpath"#,
        r#"select jsonb_path_query('"2017-03-10t12:34:56.789+3:10"', '$.datetime()')"#,
        r#"select jsonb_path_query('"aaaa"', '$.datetime("HH24")')"#,
        r#"select jsonb_path_query('["2017-03-10", "12:34:56"]', '$[*].datetime() ? (@ < "10.03.2017".datetime("dd.mm.yyyy"))')"#,
        // a function in the select list reading two FROM items by bare names
        r#"select x, y, jsonb_path_query('[true, false]', '$[*] ? (@ == $x)', jsonb_build_object('x', x, 'y', y)) from (values (jsonb 'true'), ('false')) x(x), (values (jsonb 'true'), ('false')) y(y)"#,
        // record functions in the select list, and their column
        r#"select jsonb_each('{"f1":[1,2,3],"f2":{"f3":1},"f4":null}')"#,
        r#"select jsonb_each_text('{"a":{"b":"c"},"n":null}') as q"#,
        r#"select json_each('{"f1":[1,2,3],"f4":null}')"#,
        r#"select (jsonb_each('{"a":1,"b":2}')).key"#,
        r#"select * from jsonb_array_elements('[1,true]') q"#,
        r#"select * from jsonb_array_elements_text('[1,"a"]') q"#,
        // object aggregates that keep keys apart or leave nulls out
        "select json_object_agg_unique(mod(i, 3), i) from generate_series(0, 5) i",
        "select jsonb_object_agg_unique(mod(i, 3), i) from generate_series(0, 5) i",
        "select json_object_agg_strict(i, nullif(i, 2)) from generate_series(1, 3) i",
        "select jsonb_object_agg_unique_strict(i, nullif(i, 2)) from generate_series(1, 3) i",
        // jsonb_build_object's keys
        "select jsonb_build_object('{a,b,c}'::text[], '{d,e,f}'::text[])",
        r#"select jsonb_build_object(json '{"a":1,"b":2}', 3)"#,
        // to_tsvector of json, and the flags
        r#"select to_tsvector('{"a": "aaa bbb ddd ccc", "b": ["eee fff ggg"], "c": {"d": "hhh iii"}}'::jsonb)"#,
        r#"select to_tsvector('null'::jsonb)"#,
        r#"select jsonb_to_tsvector('english', '{"a": "aaa in bbb"}'::jsonb, '""')"#,
        r#"select jsonb_to_tsvector('english', '{"a": "aaa in bbb"}'::jsonb, '{}')"#,
        r#"select jsonb_to_tsvector('english', '{"a": "aaa in bbb"}'::jsonb, '["all", null]')"#,
        // jsonb's numbers, subscripts and _int4
        r#"select '{"a":1e1000000}'::jsonb"#,
        r#"select ('[1, "2", null]'::jsonb)[1.0]"#,
        r#"select ('[1, "2", null]'::jsonb)[1:2]"#,
        r#"select ('[1, "2", null]'::jsonb)[1:]"#,
        "create type jrd_t as (i int, ia _int4, jsa jsonb[])",
        r#"select ia from jsonb_populate_record(null::jrd_t, '{"ia": [1, "2", null, 4]}')"#,
        r#"select jsa from jsonb_populate_record(null::jrd_t, '{"jsa": ["aaa", null, [1, 2, "3", {}], {"k": "v"}]}')"#,
        "drop type jrd_t",
        // SQL/JSON
        "select json_object('a': '123', 'b': json_object('a': 111, 'b': 'aaa'))",
        "select json_object('a': json_object('b': 1 returning text))",
        "select json_object('a': json_object('b': 1 returning text) format json)",
        r#"select json_array(json_array('{ "a" : 123 }' returning text))"#,
        "select json_object(returning bytea)",
        "select json_array(returning bytea format json encoding utf8)",
        "select json_object(returning text format json encoding utf8)",
        "select json_object(returning text format json encoding invalid_encoding)",
        "select json_object(returning bytea format json encoding utf16)",
        "select json_object(1: 1, '1': null with unique)",
        "select json_object(1: 1, '1': null with unique returning jsonb)",
        "select json_array(select i from (values (1), (2), (null), (4)) foo(i))",
        "select json_array(select i from (values (3), (1), (null), (2)) foo(i) order by i)",
        "select json_arrayagg(i), json_objectagg(i: i) from generate_series(1, 3) i",
        "select json_objectagg(k: v with unique keys) from (values (1, 1), (1, null), (2, 2)) foo(k, v)",
        "select json_objectagg(k: v absent on null with unique keys returning jsonb) from (values (1, 1), (1, null), (2, 2)) foo(k, v)",
        "select json_objectagg(k: v absent on null) from (values (1, 1), (0, null), (2, 2)) foo(k, v)",
        "select json_objectagg(null: 1 returning jsonb)",
        "select json_arrayagg(i null on null returning jsonb) over (order by i desc) from generate_series(1, 3) i",
        "select null::int is json",
        r#"select '{"a": 1, "a": 2}' is json with unique keys, '{"a": 1, "b": 2}' is json with unique keys"#,
        r#"select '{"a": 1, "a": 2}'::json is json object with unique keys"#,
        r#"select bytea '\x7b7d' is json, bytea '\x00' is json"#,
    ]]);
}

#[test]
fn partitioned_index_regress_details() {
    check(&[&[
        "create table ixp (a int, b int) partition by range (a)",
        "create index ixp_a_idx on ixp (a)",
        "create table ixp1 partition of ixp for values from (0) to (10)",
        "select relname, relkind, relhassubclass from pg_class where relname like 'ixp%' order by 1",
        "drop index concurrently ixp_a_idx",
        "alter index ixp_a_idx alter column a set (n_distinct = 100)",
        "alter table ixp_a_idx detach partition ixp1_a_idx",
        "alter table ixp_a_idx attach partition ixp1_a_idx for values from (10) to (20)",
        "alter index ixp attach partition ixp1_a_idx",
        "alter index ixp_a_idx attach partition ixp1",
        "create index ixp1_2 on ixp1 (a)",
        "alter index ixp_a_idx attach partition ixp1_2",
        "drop table ixp",
        // a partition's column list with constraints only
        "create table ixp (a int primary key, b int) partition by range (a)",
        "create table ixp_fail partition of ixp (b primary key) for values from (0) to (100)",
        "drop table ixp",
        "create table ixp (a int) partition by range (a)",
        "create table ixp1pk partition of ixp (a primary key) for values from (0) to (100)",
        "select conname from pg_constraint where conrelid = 'ixp1pk'::regclass",
        "drop table ixp",
        "create table ixp (i int) partition by hash (i)",
        "create table ixp0 partition of ixp (i) for values with (modulus 2, remainder 0)",
        "drop table ixp",
        // the index of a partition made ON ONLY is attached as it is: the partitions below it keep what they have
        "create table ixp (a int) partition by range (a)",
        "create table ixp2 partition of ixp for values from (100) to (1000) partition by range (a)",
        "create table ixp21 partition of ixp2 for values from (100) to (200)",
        "create index on only ixp2 (a)",
        "create index on ixp (a)",
        "select indexrelid::regclass::text, indisvalid from pg_index where indexrelid::regclass::text like 'ixp%' order by 1",
        "drop table ixp",
        // a partition's index in another collation is not the parent's
        "create table ixp (a text) partition by range (a)",
        "create table ixp2 (like ixp)",
        "create index on ixp2 (a collate \"POSIX\")",
        "create index on ixp2 (a collate \"C\")",
        "alter table ixp attach partition ixp2 for values from ('bbb') to ('ccc')",
        "create index on ixp (a collate \"C\")",
        "select relname, inhparent::regclass from pg_class left join pg_inherits on inhrelid = oid where relkind in ('i', 'I') and relname like 'ixp%' order by 1",
        "drop table ixp",
        // a plain unique index for a primary key
        "create table ixp (a int, b int) partition by range (a)",
        "create table ixp1 (a int not null, b int)",
        "create unique index on ixp1 (a)",
        "alter table ixp attach partition ixp1 for values from (1) to (1000)",
        "alter table only ixp add primary key (a)",
        "alter index ixp_pkey attach partition ixp1_a_idx",
        "drop table ixp",
    ]]);
}

/// TRUNCATE's foreign key checks and CASCADE's notices, as Postgres's ExecuteTruncateGuts and
/// heap_truncate_check_FKs give them; an inheritance parent's rows a level at a time.
#[test]
fn truncate_foreign_keys_and_inheritance_order() {
    check(&[&[
        "create table trx_a (col1 integer primary key)",
        "create table trx_b (a int references trx_a)",
        "create table trx_e (a int references trx_a)",
        "truncate table trx_a",
        "truncate table trx_a, trx_b",
        "truncate table trx_a cascade",
        "drop table trx_a, trx_b, trx_e",
        "create table trx_f (c int)",
        "create table trx_fa (x text) inherits (trx_f)",
        "create table trx_fb (y int) inherits (trx_f)",
        "create table trx_faa (z text) inherits (trx_fa)",
        "insert into trx_f values (1)",
        "insert into trx_fa values (2, 'two')",
        "insert into trx_fb values (3, 3)",
        "insert into trx_faa values (4, 'four', 'FOUR')",
        "select * from trx_f",
        "drop table trx_f cascade",
    ]]);
}

/// CREATE and ALTER SEQUENCE's errors, lastval after setval and after DROP, and ALTER SEQUENCE of a
/// table, as Postgres gives them.
#[test]
fn sequence_errors_and_lastval() {
    check(&[&[
        "create sequence sqx_x cache 0",
        "create sequence sqx_x owned by nobody",
        "create sequence sqx_x owned by pg_class.relname",
        "create sequence sqx_x as nosuchtype",
        "create sequence sqx_x as text",
        "create table sqx_t (a int)",
        "alter sequence sqx_t cycle",
        "drop table sqx_t",
        "create sequence sqx_s",
        "select nextval('sqx_s')",
        "select setval('sqx_s', 99)",
        "select lastval()",
        "create sequence sqx_s2",
        "select nextval('sqx_s2')",
        "drop sequence sqx_s2",
        "select lastval()",
        "create unlogged sequence sqx_u",
        "drop sequence sqx_u, sqx_s",
        "create table sqx_ser (f1 text, f2 serial, f3 smallint)",
        "insert into sqx_ser (f1, f3) values ('bogus', 32768)",
        "insert into sqx_ser (f1) values ('ok')",
        "select f2 from sqx_ser",
        "drop table sqx_ser",
    ]]);
}

