/// CREATE TEMP TABLE ... ON COMMIT ... AS, and ON COMMIT DROP of an inheritance parent.
#[test]
fn temp_tables_on_commit_as() {
    check(&[&[
        "begin",
        "create temp table tox (col) on commit delete rows as select 1",
        "select * from tox",
        "commit",
        "select * from tox",
        "drop table tox",
        "begin",
        "create temp table tox (col) on commit drop as select 1",
        "commit",
        "select * from tox",
        "create table tox (col) on commit delete rows as select 1",
        "begin",
        "create temp table toi (a int) on commit drop",
        "create temp table toi1 () inherits (toi) on commit delete rows",
        "insert into toi1 values (1)",
        "commit",
        "select relname from pg_class where relname ~ '^toi'",
        "begin",
        "create temp table toi (a int) on commit delete rows",
        "create temp table toi1 () inherits (toi) on commit drop",
        "insert into toi1 values (1)",
        "insert into toi values (1)",
        "commit",
        "select * from toi",
        "drop table toi",
    ]]);
}

/// Batch 10: values the bit, text, name, char, array, enum and range tests of Postgres's suite check.
#[test]
fn exact_types_values() {
    check(&[&[
        "select position(B'' in B''), position(B'0' in B''), position(B'101101' in B'001011011011011000')",
        "select bit_count('\\x1234567890'::bytea)",
        "select concat(variadic null::int[]) is null, concat(variadic '{}'::int[]) = ''",
        "select concat_ws(',', variadic array[1, 2, 3]), concat_ws(',', variadic null::int[])",
        "select format('%s, %s', variadic array['a', 'b'])",
        "select format(string_agg('%s', ','), variadic array_agg(i)) from generate_series(1, 20) g(i)",
        "select concat_ws(',', variadic 10)",
        "select parse_ident('foo.boo'), parse_ident('foo.boo[]', strict => false)",
        "select parse_ident('foo.boo[]')",
        "select parse_ident(' .aaa')",
        "select parse_ident(' aaa . ')",
        "select parse_ident(' first . \"  second  \" .\"   third   \". \"  ' || repeat('x', 66) || '\"')::name[]",
        "create table name_t (f1 name)",
        "insert into name_t values ('1234567890ABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890ABCDEFGHIJKLMNOPQR'), ('')",
        "select f1 from name_t where f1 = '1234567890ABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890ABCDEFGHIJKLMNOPQR'",
        "select f1 from name_t where f1 < '1234567890ABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890ABCDEFGHIJKLMNOPQR'",
        "select pg_input_is_valid('abcde', 'char(4)'), pg_input_is_valid('abcd  ', 'char(4)')",
        "select message, sql_error_code from pg_input_error_info('abcde', 'char(4)')",
        "select 'a'::\"char\", '\\101'::\"char\", '\\377'::\"char\", '\\377'::\"char\"::text, '\\000'::\"char\"::text",
        "select 'a'::text::\"char\", ''::text::\"char\"",
        "select cast('doh!' as char(10)), cast(name 'namefield' as char(10))",
        "select regexp_match('abc', 'Bd', 'ig')",
        "select 'abcdefg' similar to '_bcd#%' escape '##'",
        "create type rainbow as enum ('red', 'orange', 'yellow')",
        "select pg_input_is_valid('red', 'rainbow'), pg_input_is_valid('mauve', 'rainbow')",
        "select message, sql_error_code from pg_input_error_info('mauve', 'rainbow')",
        "alter type rainbow add value 'plutoplutoplutoplutoplutoplutoplutoplutoplutoplutoplutoplutoplutopluto'",
        "select max(a), min(a) from (values ('{1,2,3}'::int[]), ('{1,2,3,4}'::int[]), ('{}'::int[])) v(a)",
        "select width_bucket(op::numeric, array[1, 3, 5, 10.0]::numeric[]), width_bucket(op::float8, array[0, 5.5, 9.99]::float8[]) \
         from (values (-5.2), (1), (2), (5.5), (10), (10.0000000000001)) v(op)",
        "select width_bucket(5, array[3]), width_bucket(5, '{}')",
        "select width_bucket(5, array[3, 4, null])",
        "select width_bucket(5, array[array[1, 2], array[3, 4]])",
        "select array_remove(array[1.0, 2.1, 3.3], 1)",
        "select array_shuffle('{1,2,3,4,5,6}'::int[]) <@ '{1,2,3,4,5,6}', array_dims(array_shuffle('[-1:2][2:3]={{1,2},{3,NULL},{5,6},{7,8}}'::int[]))",
        "select array_length(array_sample('{1,2,3,4,5,6}'::int[], 3), 1), array_dims(array_sample('[-1:2][2:3]={{1,2},{3,NULL},{5,6},{7,8}}'::int[], 3))",
        "select array_sample('{1,2,3,4,5,6}'::int[], 7)",
        "select c = '{\"foobar\"}'::_name from (values ('{foobar}'::name[])) v(c)",
        "create table arr_t (i integer array[4], f char(5)[], g varchar(5)[])",
        "insert into arr_t values ('{1,2}', '{\"abc\",\"abcde\"}', '{\"abc\",\"abcde\"}')",
        "insert into arr_t (f) values ('{\"too long\"}')",
        "select i, f, g from arr_t",
        "select range_adjacent(numrange(2.0, 3.0), numrange(3.1, 4.0)), range_adjacent(numrange(2.0, 3.0, '(]'), numrange(1.0, 2.0, '(]'))",
        "select range_minus(numrange(10.1, 12.2, '[]'), numrange(110.0, 120.2, '(]')), range_minus(numrange(10.1, 12.2, '[]'), numrange(0.0, 120.2, '(]'))",
        "select range_contains(numrange(1, 5), numrange(2, 3)), range_contained_by(numrange(2, 3), numrange(1, 5))",
        "select 'empty'::int4range::int4multirange, int4range(1, 3)::int4multirange, textrange('a', null)::textmultirange",
        "select multirange(int4range(1, 2)), multirange(numrange(1.5, 2))",
        "select '{[1,2)}'::int4multirange < '{[1,3)}'::int4multirange, '{}'::int4multirange <= '{[1,2)}'::int4multirange",
    ]]);
}

#[test]
fn constraint_triggers() {
    check(&[&[
        "create table ct_log (n serial, what text)",
        "create table ct_t (a int)",
        "create table ct_ref (a int)",
        "create function ct_note() returns trigger language plpgsql as $$
         begin insert into ct_log(what) values (tg_name || ':' || new.a); return null; end $$",
        "create constraint trigger ct_late after insert on ct_t deferrable initially deferred
           for each row execute function ct_note()",
        "create constraint trigger ct_now after insert on ct_t from ct_ref
           for each row when (new.a > 0) execute function ct_note()",
        "create constraint trigger ct_bad before insert on ct_t for each row execute function ct_note()",
        "create or replace constraint trigger ct_now after insert on ct_t for each row execute function ct_note()",
        "create constraint trigger ct_bad after insert on ct_t for each statement execute function ct_note()",
        "create constraint trigger ct_bad after insert on ct_t not deferrable initially deferred
           for each row execute function ct_note()",
        "create constraint trigger ct_bad after insert on ct_t from ct_missing for each row execute function ct_note()",
        "begin",
        "insert into ct_t values (1), (-2)",
        "select what from ct_log order by n",
        "commit",
        "select what from ct_log order by n",
        "begin",
        "set constraints ct_late immediate",
        "insert into ct_t values (3)",
        "select what from ct_log order by n",
        "commit",
        "begin",
        "insert into ct_t values (4)",
        "set constraints all immediate",
        "select what from ct_log order by n",
        "rollback",
        "begin",
        "savepoint s",
        "insert into ct_t values (5)",
        "rollback to savepoint s",
        "commit",
        "select what from ct_log order by n",
        "begin",
        "set constraints ct_now deferred",
        "rollback",
        "begin",
        "set constraints ct_nothing deferred",
        "rollback",
        "select tgname, tgdeferrable, tginitdeferred, tgconstraint <> 0, tgconstrrelid::regclass from pg_trigger
           where tgrelid = 'ct_t'::regclass order by 1",
        "select conname, contype, condeferrable, condeferred, confrelid, conkey from pg_constraint
           where conrelid = 'ct_t'::regclass order by 1",
        // (the definition names its table's schema, which is the oracle script's own: not compared)
        "select replace(pg_get_triggerdef(oid), current_schema() || '.', 'S.') from pg_trigger where tgrelid = 'ct_t'::regclass order by tgname",
        "drop trigger ct_late on ct_t",
        "select count(*) from pg_constraint where conrelid = 'ct_t'::regclass",
    ]]);
}

#[test]
fn constraint_triggers_on_partitions() {
    check(&[&[
        "create table cp_log (n serial, what text)",
        "create function cp_note() returns trigger language plpgsql as $$
         begin insert into cp_log(what) values (tg_name || ' on ' || tg_table_name || ':' || new.a); return null; end $$",
        "create table cp (a int, b text) partition by range (a)",
        "create table cp1 partition of cp for values from (0) to (10)",
        "create constraint trigger cp_t after insert on cp deferrable for each row execute function cp_note()",
        "create table cp2 partition of cp for values from (10) to (20)",
        "begin",
        "set constraints cp_t deferred",
        "insert into cp values (1, 'x'), (11, 'y')",
        "select what from cp_log order by n",
        "commit",
        "select what from cp_log order by n",
        "select t.tgrelid::regclass, c.conname, c.conrelid::regclass, c.contype from pg_trigger t
           join pg_constraint c on c.oid = t.tgconstraint where t.tgname = 'cp_t' order by t.tgrelid::regclass::text",
    ]]);
}

#[test]
fn triggers_fire_for_referential_actions() {
    check(&[
        &[
            "create table ra_log (n serial, what text)",
            "create table ra_p (a int primary key)",
            "create table ra_c (a int references ra_p on delete cascade on update cascade, b text)",
            "create table ra_n (a int references ra_p on delete set null, b text)",
            "create function ra_row() returns trigger language plpgsql as $$
             begin insert into ra_log(what) values (tg_name || ':' || coalesce(old.a::text, '-') || '>' ||
               coalesce(new.a::text, '-')); return null; end $$",
            "create function ra_stmt() returns trigger language plpgsql as $$
             begin insert into ra_log(what) values (tg_name || ':' || tg_op || ':' || tg_when); return null; end $$",
            "create trigger ra_c_row after update or delete on ra_c for each row execute function ra_row()",
            "create trigger ra_c_before before update or delete on ra_c for each statement execute function ra_stmt()",
            "create trigger ra_c_after after update or delete on ra_c for each statement execute function ra_stmt()",
            "create trigger ra_n_row after update on ra_n for each row execute function ra_row()",
            "insert into ra_p values (1), (2), (3)",
            "insert into ra_c values (1, 'x'), (1, 'y'), (2, 'z')",
            "insert into ra_n values (3, 'w')",
            "update ra_p set a = 10 where a = 1",
            "delete from ra_p where a in (2, 3)",
            "select what from ra_log order by n",
            "select * from ra_c order by a, b",
            "select * from ra_n",
        ],
        &[
            "create table rt_log (n serial, what text)",
            "create table rt_p (a int primary key)",
            "create table rt_c (a int references rt_p on delete cascade on update cascade)",
            "create function rt_new() returns trigger language plpgsql as $$
             begin insert into rt_log(what) select 'new ' || string_agg(a::text, ',' order by a) from nt; return null; end $$",
            "create function rt_old() returns trigger language plpgsql as $$
             begin insert into rt_log(what) select 'old ' || string_agg(a::text, ',' order by a) from ot; return null; end $$",
            "create trigger rt_u after update on rt_c referencing new table as nt for each statement execute function rt_new()",
            "create trigger rt_d after delete on rt_c referencing old table as ot for each statement execute function rt_old()",
            "insert into rt_p values (1), (2), (3)",
            "insert into rt_c values (1), (1), (2), (3)",
            "update rt_p set a = a + 10 where a < 3",
            "delete from rt_p where a > 10",
            "select what from rt_log order by n",
            "select * from rt_c",
        ],
        &[
            "create table rs_log (n serial, what text)",
            "create table rs (a int primary key, b int references rs on delete cascade)",
            "create function rs_old() returns trigger language plpgsql as $$
             begin insert into rs_log(what) select string_agg(a::text, ',' order by a) from ot; return null; end $$",
            "create trigger rs_d after delete on rs referencing old table as ot for each statement execute function rs_old()",
            "insert into rs values (1, null), (2, 1), (3, 2), (4, 3)",
            "delete from rs where a = 1",
            "select what from rs_log order by n",
        ],
    ]);
}

#[test]
fn foreign_keys_to_partitioned_tables() {
    check(&[&[
        "create table fp (a int primary key) partition by range (a)",
        "create table fp1 partition of fp for values from (0) to (10)",
        "create table fp2 partition of fp for values from (10) to (20) partition by range (a)",
        "create table fp21 partition of fp2 for values from (10) to (15)",
        "create table fp_d partition of fp default",
        "create table ff (a int references fp)",
        "insert into fp values (1), (11), (30)",
        "insert into ff values (1), (11), (30)",
        "select co.conname, cf.relname, p.conname, co.conislocal, co.coninhcount from pg_constraint co
           join pg_class cf on cf.oid = co.confrelid left join pg_constraint p on p.oid = co.conparentid
           where co.conrelid = 'ff'::regclass order by 1",
        "delete from fp where a = 1",
        "update fp set a = 12 where a = 11",
        "alter table fp detach partition fp1",
        "alter table fp2 detach partition fp21",
        "drop table fp21",
        "drop table fp_d",
        "delete from ff",
        "alter table fp detach partition fp1",
        "drop table fp1",
        "create table fq (a int) partition by list (a)",
        "alter table only fq add foreign key (a) references fp",
        "alter table fq add foreign key (a) references fp not valid",
        "create table fr6 (a int primary key)",
        "create table ff6 (a int references fr6) partition by list (a)",
        "alter table ff6 attach partition fr6 for values in (1)",
        "create table fpk (a int, b int, primary key (a, b))",
        "create table ffk (a int, b int, foreign key (a, b) references fpk) partition by list (a)",
        "create table ffk1 partition of ffk for values in (1)",
        "insert into fpk values (1, 2)",
        "insert into ffk values (1, 2)",
        "delete from fpk",
    ]]);
}

/// pg_get_object_address, pg_identify_object, pg_identify_object_as_address and pg_describe_object, as object_address.sql
/// tests them: the errors for every kind of name, and what each kind of object is identified and described as (the
/// oids themselves differ, so only the text is compared).
#[test]
fn object_addresses() {
    check(&[&[
        "drop schema if exists oa_nsp cascade",
        "create schema oa_nsp",
        "create table oa_nsp.gentable (a serial primary key constraint a_chk check (a > 0), b text default 'hello')",
        "create view oa_nsp.genview as select * from oa_nsp.gentable",
        "create index oa_gen_b on oa_nsp.gentable (b)",
        "create function oa_nsp.f(integer) returns integer language sql as 'select $1'",
        "create type oa_nsp.genenum as enum ('one', 'two')",
        "select pg_get_object_address('stone', '{}', '{}')",
        "select pg_get_object_address('table', '{}', '{}')",
        "select pg_get_object_address('table', '{NULL}', '{}')",
        "select pg_get_object_address('toast table', '{one}', '{}')",
        "select pg_get_object_address('view column', '{one}', '{}')",
        "select pg_get_object_address('table', '{eins}', '{}')",
        "select pg_get_object_address('table', '{oa_nsp, zwei}', '{}')",
        "select pg_get_object_address('index', '{eins, zwei, drei}', '{integer}')",
        "select pg_get_object_address('table column', '{eins}', '{}')",
        "select pg_get_object_address('table column', '{oa_nsp, zwei}', '{}')",
        "select pg_get_object_address('table column', '{eins, zwei, drei}', '{}')",
        "select pg_get_object_address('aggregate', '{eins}', '{}')",
        "select pg_get_object_address('aggregate', '{eins}', '{integer}')",
        "select pg_get_object_address('function', '{oa_nsp, zwei}', '{}')",
        "select pg_get_object_address('procedure', '{eins, zwei, drei}', '{integer}')",
        "select pg_get_object_address('type', '{eins}', '{}')",
        "select pg_get_object_address('type', '{oa_nsp, zwei}', '{}')",
        "select pg_get_object_address('cast', '{eins}', '{}')",
        "select pg_get_object_address('cast', '{eins}', '{integer}')",
        "select pg_get_object_address('table constraint', '{eins}', '{}')",
        "select pg_get_object_address('table constraint', '{oa_nsp, zwei}', '{}')",
        "select pg_get_object_address('domain constraint', '{eins}', '{integer}')",
        "select pg_get_object_address('conversion', '{oa_nsp, zwei}', '{}')",
        "select pg_get_object_address('default value', '{eins}', '{}')",
        "select pg_get_object_address('operator', '{eins}', '{integer}')",
        "select pg_get_object_address('operator class', '{eins}', '{}')",
        "select pg_get_object_address('operator family', '{oa_nsp, zwei}', '{}')",
        "select pg_get_object_address('rule', '{eins, zwei, drei}', '{}')",
        "select pg_get_object_address('trigger', '{oa_nsp, gentable, zwei}', '{}')",
        "select pg_get_object_address('text search dictionary', '{oa_nsp, zwei}', '{}')",
        "select pg_get_object_address('policy', '{eins}', '{}')",
        "select pg_get_object_address('user mapping', '{eins}', '{}')",
        "select pg_get_object_address('user mapping', '{eins}', '{integer}')",
        "select pg_get_object_address('default acl', '{eins}', '{integer}')",
        "select pg_get_object_address('transform', '{eins}', '{integer}')",
        "select pg_get_object_address('operator of access method', '{eins}', '{}')",
        "select pg_get_object_address('function of access method', '{eins, zwei, drei}', '{}')",
        "select pg_get_object_address('publication namespace', '{eins}', '{integer}')",
        "select pg_get_object_address('publication relation', '{oa_nsp, zwei}', '{integer}')",
        "select * from pg_get_object_address('operator of access method', '{btree,integer_ops,1}', '{int4,bool}')",
        "select * from pg_get_object_address('function of access method', '{btree,integer_ops,99}', '{int4,int4}')",
        "select pg_get_object_address('language', '{one}', '{}')",
        "select pg_get_object_address('language', '{one,two}', '{}')",
        "select pg_get_object_address('large object', '{123}', '{}')",
        "select pg_get_object_address('large object', '{123,456}', '{}')",
        "select pg_get_object_address('large object', '{blargh}', '{}')",
        "select pg_get_object_address('schema', '{one}', '{}')",
        "select pg_get_object_address('role', '{one}', '{}')",
        "select pg_get_object_address('database', '{one}', '{}')",
        "select pg_get_object_address('tablespace', '{one}', '{}')",
        "select pg_get_object_address('foreign-data wrapper', '{one}', '{}')",
        "select pg_get_object_address('server', '{one}', '{}')",
        "select pg_get_object_address('extension', '{one}', '{}')",
        "select pg_get_object_address('event trigger', '{one}', '{}')",
        "select pg_get_object_address('access method', '{one}', '{}')",
        "select pg_get_object_address('publication', '{one}', '{}')",
        "select pg_get_object_address('subscription', '{one,two}', '{}')",
        "do $$ declare t text; begin for t in values ('toast table'), ('index column') loop begin \
         perform pg_get_object_address(t, '{one}', '{}'); exception when invalid_parameter_value then \
         raise warning 'error for %: %', t, sqlerrm; end; end loop; end $$",
        // what each kind of object is identified and described as, and the address its identity gives back
        "select i.type, i.schema, i.name, i.identity, x.object_names, x.object_args, \
         pg_describe_object(a.classid, a.objid, a.objsubid), \
         (b.classid, b.objid, b.objsubid) = (a.classid, a.objid, a.objsubid) as roundtrip \
         from (values ('table', '{oa_nsp, gentable}'::text[], '{}'::text[]), \
         ('index', '{oa_nsp, oa_gen_b}', '{}'), ('sequence', '{oa_nsp, gentable_a_seq}', '{}'), \
         ('view', '{oa_nsp, genview}', '{}'), ('table column', '{oa_nsp, gentable, b}', '{}'), \
         ('function', '{oa_nsp, f}', '{int4}'), \
         ('function', '{pg_catalog, pg_identify_object}', '{pg_catalog.oid, pg_catalog.oid, int4}'), \
         ('type', '{pg_catalog._int4}', '{}'), ('type', '{oa_nsp.genenum}', '{}'), \
         ('table constraint', '{oa_nsp, gentable, a_chk}', '{}'), \
         ('default value', '{oa_nsp, gentable, b}', '{}'), ('rule', '{oa_nsp, genview, _RETURN}', '{}'), \
         ('schema', '{oa_nsp}', '{}'), ('language', '{plpgsql}', '{}'), ('access method', '{btree}', '{}'), \
         ('operator', '{+}', '{int4, int4}'), ('operator family', '{btree, integer_ops}', '{}'), \
         ('operator class', '{btree, int4_ops}', '{}'), ('collation', '{default}', '{}'), \
         ('conversion', '{pg_catalog, koi8_r_to_mic}', '{}'), ('text search configuration', '{english}', '{}'), \
         ('text search dictionary', '{simple}', '{}'), ('tablespace', '{pg_default}', '{}')) o (ty, n, g), \
         pg_get_object_address(o.ty, o.n, o.g) a, \
         pg_identify_object(a.classid, a.objid, a.objsubid) i, \
         pg_identify_object_as_address(a.classid, a.objid, a.objsubid) x, \
         pg_get_object_address(x.type, x.object_names, x.object_args) b \
         order by i.type collate \"C\", i.identity collate \"C\"",
        // an address that names nothing: its type, and nothing else
        "select row(pg_identify_object('pg_class'::regclass, 0, 0)), \
         row(pg_identify_object_as_address('pg_class'::regclass, 'pg_class'::regclass, 100)), \
         pg_describe_object('pg_class'::regclass, 0, 0)",
        "select row(pg_identify_object(c::regclass, 0, 0)), row(pg_identify_object_as_address(c::regclass, 0, 0)), \
         pg_describe_object(c::regclass, 0, 0) from unnest(array['pg_proc', 'pg_type', 'pg_cast', 'pg_collation', \
         'pg_constraint', 'pg_conversion', 'pg_attrdef', 'pg_language', 'pg_largeobject', 'pg_operator', \
         'pg_opclass', 'pg_opfamily', 'pg_am', 'pg_amop', 'pg_amproc', 'pg_rewrite', 'pg_trigger', 'pg_namespace', \
         'pg_statistic_ext', 'pg_ts_parser', 'pg_ts_dict', 'pg_ts_template', 'pg_ts_config', 'pg_authid', \
         'pg_auth_members', 'pg_database', 'pg_tablespace', 'pg_foreign_data_wrapper', 'pg_foreign_server', \
         'pg_user_mapping', 'pg_default_acl', 'pg_extension', 'pg_event_trigger', 'pg_parameter_acl', 'pg_policy', \
         'pg_publication', 'pg_publication_namespace', 'pg_publication_rel', 'pg_subscription', 'pg_transform']) c",
        "select pg_describe_object(0, 0, 0)",
        "select pg_describe_object('pg_class'::regclass, 'pg_class'::regclass, 0), \
         pg_describe_object('pg_class'::regclass, 'pg_class'::regclass, 2)",
        "drop schema oa_nsp cascade",
    ]]);
}

/// Collations' errors carry Postgres's hints, and a column of `x COLLATE c` (or of a CASE whose ELSE is a column) is
/// called what x is.
#[test]
fn collation_hints_and_column_names() {
    check(&[&[
        "drop table if exists cm_t",
        "create table cm_t (a int, x text collate \"C\", y text collate \"POSIX\")",
        "insert into cm_t values (1, 'abc', 'b'), (2, 'b', 'abc')",
        "select x || y from cm_t order by 1",
        "select x from cm_t where x || y > 'a'",
        "create table cm_u as select x || y as b from cm_t",
        "select a, x collate \"POSIX\" from cm_t order by 1",
        "select a, case x when 'abc' then 'abcd' else x end from cm_t order by 1",
        "select a, case x when 'abc' then 'abcd' else 'z' end from cm_t order by 1",
        "drop table cm_t",
    ]]);
}

