/// A composite type of a schema other than public is a composite type (not an enum known by its name): as a
/// column, as an array's element, as a function's argument, found along the search_path, and read from text. An
/// enum and a range of that schema are theirs too.
#[test]
fn composite_types_in_other_schemas() {
    check(&[&[
        "drop schema if exists mgb_s cascade",
        "create schema mgb_s",
        "create type mgb_s.c as (a int, b text)",
        "create type mgb_s.mood as enum ('ok', 'meh')",
        "create type mgb_s.r as range (subtype = int)",
        "create table mgb_t (id int primary key, v mgb_s.c, vs mgb_s.c[], m mgb_s.mood, ms mgb_s.mood[], r mgb_s.r)",
        "insert into mgb_t values (1, '(1,x)', array['(2,y)'::mgb_s.c], 'ok', '{ok,meh}', '[1,5)')",
        "insert into mgb_t values (2, row(3, 'z'), null, 'meh', null, null)",
        "insert into mgb_t values (3, '(bad)', null, null, null, null)",
        "insert into mgb_t values (4, '(1,x)', '{\"(7,q)\",\"(8,\\\"a b\\\")\"}', null, null, null)",
        "insert into mgb_t values (5, null, null, 'nope', null, null)",
        "select id, v, vs, m, ms, r from mgb_t order by id",
        "select id, (v).a, (v).b from mgb_t order by id",
        "update mgb_t set v = row(9, 'u') where id = 1",
        "select v from mgb_t where id = 1",
        "create function mgb_s.f(x mgb_s.c) returns int language sql as 'select (x).a'",
        "select mgb_s.f('(5,z)')",
        "select mgb_s.f(v) from mgb_t where id = 1",
        "drop table mgb_t",
        "set search_path = mgb_s, public",
        "create table mgb_t2 (v c, m mood)",
        "insert into mgb_t2 values ('(1,2)', 'ok')",
        "select * from mgb_t2",
        "select '(3,4)'::c",
        "drop table mgb_s.mgb_t2",
        "drop schema mgb_s cascade",
    ]]);
}

/// A composite type made in a script and read back by a fresh process (the registry is rebuilt from the stored
/// types): a composite of composites that sort the other way round by name is there too.
#[test]
fn composites_of_composites_in_any_name_order() {
    check(&[&[
        "drop schema if exists mgb_z cascade",
        "create schema mgb_z",
        "create type mgb_z.zz as (a int)",
        "create type mgb_z.aa as (z mgb_z.zz, t text)",
        "create table mgb_n (id int, v mgb_z.aa)",
        "insert into mgb_n values (1, row(row(1), 'x'))",
        "select id, v, ((v).z).a from mgb_n",
        "drop table mgb_n",
        "drop schema mgb_z cascade",
    ]]);
}

/// A sequence keeps its CACHE (pg_sequences.cache_size, pg_sequence.seqcache); one made without it has 1.
#[test]
fn sequence_cache_is_kept() {
    check(&[&[
        "create sequence mgb_sq cache 20",
        "select sequencename, cache_size from pg_sequences where sequencename = 'mgb_sq'",
        "select seqcache from pg_sequence where seqrelid = 'mgb_sq'::regclass",
        "alter sequence mgb_sq cache 5",
        "select cache_size from pg_sequences where sequencename = 'mgb_sq'",
        "alter sequence mgb_sq increment by 2",
        "select cache_size from pg_sequences where sequencename = 'mgb_sq'",
        "create sequence mgb_sq2",
        "select cache_size from pg_sequences where sequencename = 'mgb_sq2'",
        "create sequence mgb_sq3 cache 0",
    ]]);
}

/// ntile gives an integer (row_number, rank and dense_rank a bigint), and a CHECK on a function call prints as
/// Postgres writes it.
#[test]
fn window_result_types_and_check_text() {
    check(&[&[
        "select pg_typeof(n), pg_typeof(r), pg_typeof(k), pg_typeof(d) from (select ntile(2) over () n, row_number() over () r, rank() over () k, dense_rank() over () d from (values (1), (2)) v(a)) w",
        "create table mgb_ck (title text, n int, constraint mgb_ck_len check (char_length(title) >= 1))",
        "select pg_get_constraintdef(oid) from pg_constraint where conname = 'mgb_ck_len'",
        "select pg_get_constraintdef(oid, true) from pg_constraint where conname = 'mgb_ck_len'",
    ]]);
}

/// COMMENT ON an enum type or a function is kept and read back by obj_description and pg_description.
#[test]
fn comments_on_types_and_functions() {
    check(&[&[
        "create type mgb_e as enum ('a', 'b')",
        "comment on type mgb_e is 'an enum'",
        "select obj_description('mgb_e'::regtype::oid, 'pg_type')",
        "select description from pg_description where objoid = 'mgb_e'::regtype::oid and classoid = 'pg_type'::regclass",
        "create function mgb_f(int) returns int language sql as 'select 1'",
        "comment on function mgb_f(int) is 'a function'",
        "select obj_description('mgb_f(int)'::regprocedure::oid, 'pg_proc')",
        "comment on function mgb_f(int) is null",
        "select obj_description('mgb_f(int)'::regprocedure::oid, 'pg_proc')",
        "comment on function mgb_nosuch(int) is 'x'",
        "comment on type mgb_nosuch is 'x'",
        "comment on type mgb_e is 'again'",
        "drop type mgb_e",
        "select count(*) from pg_description where description = 'again'",
    ]]);
}

#[test]
fn schema_qualified_extension_functions_and_user_aggregates() {
    check(&[&[
        "drop extension if exists \"uuid-ossp\"",
        "create extension \"uuid-ossp\" schema public",
        "select length(public.uuid_generate_v4()::text)",
        "select length(uuid_generate_v4()::text)",
        "create table sq_t0 (id uuid default public.uuid_generate_v4(), n int)",
        "insert into sq_t0 (n) values (1)",
        "select n, length(id::text) from sq_t0",
        "create function sq_cat(text, text) returns text language sql as $$ select $1 || ',' || $2 $$",
        "create aggregate public.sq_agg(text) (sfunc = sq_cat, stype = text, initcond = '')",
        "create table sq_t (x text)",
        "insert into sq_t values ('a'), ('b'), ('c')",
        "select public.sq_agg(x) from sq_t",
        "select sq_agg(x) from sq_t",
        "select pg_catalog.count(*), pg_catalog.sum(length(x)) from sq_t",
        "select pg_catalog.upper('x')",
        "select public.upper('x')",
        "select public.nosuch_fn(1)",
        "select 7 operator(pg_catalog.*) 2, 7 operator(pg_catalog./) 2, 7 operator(pg_catalog.%) 2",
        "select 2 operator(pg_catalog.^) 3, 7 operator(pg_catalog.-) 2",
        "select pg_catalog.row_number() over (order by x) from sq_t",
        "drop table sq_t0",
        "drop extension \"uuid-ossp\"",
    ]]);
}

#[test]
fn trigger_functions_returning_coalesce_of_new_and_old() {
    check(&[
        &[
            "create table tc_t (id int primary key, v text)",
            "create function tc_f() returns trigger language plpgsql as $$ begin return coalesce(new, old); end $$",
            "create trigger tc_trg before insert or update or delete on tc_t for each row execute function tc_f()",
            "insert into tc_t values (1, 'a'), (2, 'b')",
            "update tc_t set v = 'c' where id = 1",
            "select * from tc_t order by id",
            "delete from tc_t where id = 2",
            "select * from tc_t order by id",
        ],
        &[
            "create table tc_u (id int, v text)",
            "create function tc_g() returns trigger language plpgsql as $$ begin \
             return case when tg_op = 'DELETE' then old else new end; end $$",
            "create trigger tc_trg before insert or delete on tc_u for each row execute function tc_g()",
            "insert into tc_u values (1, 'x')",
            "delete from tc_u",
            "select count(*) from tc_u",
        ],
        &[
            "create table tc_w (id int)",
            "create function tc_h() returns trigger language plpgsql as $$ begin return 1; end $$",
            "create trigger tc_trg before insert on tc_w for each row execute function tc_h()",
            "insert into tc_w values (1)",
            "create function tc_i() returns trigger language plpgsql as $$ begin return coalesce(null, null); end $$",
            "create table tc_x (id int)",
            "create trigger tc_trg before insert on tc_x for each row execute function tc_i()",
            "insert into tc_x values (1)",
            "select count(*) from tc_x",
        ],
        &[
            "create table tc_y (id int, v text)",
            "create function tc_j() returns trigger language plpgsql as $$ begin \
             new.v := 'set by trigger'; return coalesce(new, old); end $$",
            "create trigger tc_trg before insert on tc_y for each row execute function tc_j()",
            "insert into tc_y values (1, 'a')",
            "select * from tc_y",
        ],
    ]);
}

#[test]
fn select_for_update_skip_locked_and_nowait_without_contention() {
    check(&[
        &[
            "create table sl_q (id serial primary key, st text default 'new', n int)",
            "insert into sl_q (n) select g from generate_series(1, 5) g",
            "begin",
            "select id from sl_q order by id limit 2 for update skip locked",
            "select id from sl_q order by id for update nowait",
            "select id from sl_q where id > 3 order by id for share skip locked",
            "select id from sl_q order by id offset 1 limit 1 for no key update skip locked",
            "commit",
            "with next as (select id from sl_q where st = 'new' order by id limit 2 for update skip locked) \
             update sl_q set st = 'done' from next where sl_q.id = next.id returning sl_q.id",
            "update sl_q set st = 'x' where id in (select id from sl_q where st = 'new' order by id limit 1 \
             for update skip locked) returning id",
            "select id, st from sl_q order by id",
            "select id from sl_q for update skip locked nowait",
            "select id from sl_q for update nowait skip locked",
            "select id from sl_q order by id fetch first 1 row only for key share skip locked",
            "select * from (select id from sl_q order by id limit 2 for update skip locked) s order by id",
        ],
        &[
            "create table sl_nopk (a int, b text)",
            "insert into sl_nopk values (1, 'x'), (2, 'y'), (2, 'y')",
            "begin",
            "select * from sl_nopk order by a for update nowait",
            "select * from sl_nopk order by a for update skip locked",
            "select a from sl_nopk where a = 2 for update of sl_nopk nowait",
            "commit",
        ],
    ]);
}

#[test]
fn tsvector_update_trigger_and_gist_over_text_search_types() {
    check(&[
        &[
            "create table tv_d (id int primary key, title text, body text, tsv tsvector)",
            "create trigger tv_trg before insert or update on tv_d for each row execute function \
             tsvector_update_trigger(tsv, 'pg_catalog.english', title, body)",
            "insert into tv_d values (1, 'The quick brown fox', 'jumps over the lazy dogs')",
            "insert into tv_d values (2, null, 'only body text here')",
            "insert into tv_d values (3, 'only title', null)",
            "insert into tv_d values (4, 'a', 'the')",
            "insert into tv_d values (5, 'ends with the', 'then a new beginning')",
            "select id, tsv from tv_d order by id",
            "update tv_d set title = 'changed title running' where id = 1",
            "update tv_d set id = 9 where id = 2",
            "select id, tsv from tv_d order by id",
            "select id from tv_d where tsv @@ to_tsquery('english', 'dog') order by id",
            "create index tv_gist on tv_d using gist (tsv)",
            "create index tv_gin on tv_d using gin (tsv)",
            "select id from tv_d where tsv @@ to_tsquery('english', 'chang & titl') order by id",
            "select id from tv_d where tsv @@ to_tsquery('english', 'fox | beginn') order by id",
            "select id, ts_rank(tsv, to_tsquery('english', 'fox')) from tv_d where tsv @@ to_tsquery('english', 'fox')",
        ],
        &[
            "create table tv_e (id int, title text, cfg regconfig, tsv tsvector)",
            "create trigger tv_trg before insert or update on tv_e for each row execute function \
             tsvector_update_trigger_column(tsv, cfg, title)",
            "insert into tv_e values (1, 'running dogs', 'english', null)",
            "insert into tv_e values (2, 'running dogs', 'simple', null)",
            "select id, tsv from tv_e order by id",
            "insert into tv_e values (3, 'running dogs', null, null)",
        ],
        &[
            "create table tv_f (id int, q tsquery)",
            "create index tv_f_gist on tv_f using gist (q)",
            "insert into tv_f values (1, 'x & y'), (2, 'z | w'), (3, 'v'), (4, '!x')",
            "select id from tv_f where q @> to_tsquery('x') order by id",
            "select id from tv_f where q @> to_tsquery('x & y') order by id",
            "select id from tv_f where q @> to_tsquery('a') order by id",
            "select id from tv_f where q <@ to_tsquery('x & y & z') order by id",
            "select id from tv_f where to_tsquery('x | v') @> q order by id",
            "select id from tv_f order by id",
        ],
        &[
            "create table tv_g (id int, title text, tsv tsvector, n int)",
            "create trigger tv_bad1 before insert on tv_g for each row execute function tsvector_update_trigger(tsv)",
            "insert into tv_g values (1, 't', null, 1)",
            "drop trigger tv_bad1 on tv_g",
            "create trigger tv_bad2 before insert on tv_g for each row execute function \
             tsvector_update_trigger(nosuch, 'pg_catalog.english', title)",
            "insert into tv_g values (2, 't', null, 1)",
            "drop trigger tv_bad2 on tv_g",
            "create trigger tv_bad3 before insert on tv_g for each row execute function \
             tsvector_update_trigger(tsv, 'english', title)",
            "insert into tv_g values (3, 't', null, 1)",
            "drop trigger tv_bad3 on tv_g",
            "create trigger tv_bad4 before insert on tv_g for each row execute function \
             tsvector_update_trigger(tsv, 'pg_catalog.english', n)",
            "insert into tv_g values (4, 't', null, 1)",
            "drop trigger tv_bad4 on tv_g",
            "create trigger tv_bad5 before insert on tv_g for each row execute function \
             tsvector_update_trigger(title, 'pg_catalog.english', title)",
            "insert into tv_g values (5, 't', null, 1)",
            "drop trigger tv_bad5 on tv_g",
            "create trigger tv_bad6 after insert on tv_g for each row execute function \
             tsvector_update_trigger(tsv, 'pg_catalog.english', title)",
            "insert into tv_g values (6, 't', null, 1)",
        ],
    ]);
}

#[test]
fn group_by_composite_fields_and_set_returning_functions() {
    check(&[&[
        "create type gb_pt as (a int, b text)",
        "create table gb_t (id int, v gb_pt, arr int[])",
        "insert into gb_t values (1, row(1,'x'), '{1,2}'), (2, row(1,'y'), '{3}'), (3, row(2,'z'), '{3,4}')",
        "select (v).a, count(*) from gb_t group by 1 order by 1",
        "select (v).a, count(*) from gb_t group by (v).a order by 1",
        "select (v).a as k, count(*) from gb_t group by k order by 1",
        "select (t.v).a, count(*) from gb_t t group by (t.v).a order by 1",
        "select (v).b, (v).a, count(*) from gb_t group by 1, 2 order by 1, 2",
        "select (v).a + 1, count(*) from gb_t group by 1 order by 1",
        "select (v).a, sum(id) from gb_t group by 1 having count(*) > 1 order by 1",
        "select (v).a, (v).b from gb_t group by (v).a order by 1",
        "select unnest(arr) s, count(*) from gb_t group by 1 order by 1",
        "select unnest(arr) s, count(*) from gb_t group by s order by 1",
        "select unnest(arr), count(*) from gb_t group by unnest(arr) order by 1",
        "select unnest(arr) + 1 s, count(*) from gb_t group by 1 order by 1",
        "select id, unnest(arr) s from gb_t group by 1, 2 order by 1, 2",
        "select count(*) from gb_t group by unnest(arr) order by 1",
        "select generate_series(1, id) g, count(*) from gb_t group by 1 order by 1",
        "select unnest(arr) s, count(*) from gb_t where id > 1 group by 1 having count(*) > 1 order by 1",
        "select unnest(arr), count(*) from gb_t where unnest(arr) > 1 group by 1",
    ]]);
}

