#[test]
fn real_beside_another_number_is_double_precision() {
    check_text(&[&[
        "select pg_typeof(9.8::real * 3), pg_typeof(9.8::real + 0), pg_typeof(9.8::real * 3::smallint), pg_typeof(9.8::real * 3::bigint), pg_typeof(9.8::real * 3.0), pg_typeof(9.8::real * 3::real), pg_typeof(9.8::real * 3::float8)",
        "select 9.8::real * 3, 9.8::real + 0, 9.8::real * 3::smallint, 9.8::real * 3::bigint, 9.8::real * 3.0, 9.8::real * 3::real, 9.8::real * 3::float8",
        "select 3 * 9.8::real, 3::bigint - 9.8::real, 3 / 9.8::real, 3::numeric + 9.8::real, 9.8::real - 3, 9.8::real / 3",
        "select pg_typeof(3 * 9.8::real), pg_typeof(3::numeric + 9.8::real), pg_typeof(9.8::real / 3), pg_typeof(-9.8::real), pg_typeof(abs(-9.8::real))",
        "select pg_typeof(ceil(9.8::real)), pg_typeof(floor(9.8::real)), pg_typeof(trunc(9.8::real)), pg_typeof(sign(9.8::real)), ceil(9.8::real), floor(9.8::real), trunc(9.8::real)",
        "create table rn_t (x real, y float8, s smallint, n numeric)",
        "insert into rn_t values (9.8, 9.8, 3, 3.5), (0.1, 0.1, 2, 0.25)",
        "select pg_typeof(sum(x)), pg_typeof(avg(x)), pg_typeof(min(x)), pg_typeof(max(x)), sum(x), avg(x), min(x), max(x) from rn_t",
        "select pg_typeof(sum(x * 2)), sum(x * 2), pg_typeof(sum(s * x)), sum(s * x), pg_typeof(sum(x * n)), sum(x * n) from rn_t",
        "select pg_typeof(x + s), x + s, pg_typeof(x * y), x * y from rn_t order by y",
        "select pg_typeof(case when true then x else 0 end), pg_typeof(case when true then 0 else x end), pg_typeof(case when true then x else n end), pg_typeof(case when true then n else x end), pg_typeof(case when true then x else y end) from rn_t limit 1",
        "select pg_typeof(coalesce(x, 0)), pg_typeof(coalesce(n, x)), pg_typeof(greatest(3, x)), pg_typeof(greatest(x, 3)), pg_typeof(least(n, x)), pg_typeof(array[x, 3]), pg_typeof(array[n, x]) from rn_t limit 1",
        "select pg_typeof(nullif(x, 3)), pg_typeof(nullif(s, x)), pg_typeof(nullif(n, x)), pg_typeof(nullif(y, x)), pg_typeof(nullif(x, y)) from rn_t limit 1",
        "select x in (9.8, 3), x in (9.8), x not in (9.8, 3), x = 9.8, x = y, x = n, x in (9.8::float8, 3), x in ('9.8', 3) from rn_t order by y",
        "select * from rn_t where x in (9.8, 1)",
        "select * from rn_t where x = 9.8",
        "select pg_typeof(x), pg_typeof(x::text), x::text, (x * 1)::text from rn_t order by y",
        "select (0.1::real + 0.2::real) = 0.3::real, (0.1::real + 0.2::real)::float8, 0.1::real * 3::real, 16777216::real + 1::real",
        "select sum(x), sum(x)::float8 from (select 0.1::real x from generate_series(1, 1000)) v",
        "select 1e38::real * 10::real",
    ]]);
}

#[test]
fn sum_of_bigint_is_numeric() {
    check_text(&[&[
        "select sum(x) from (values (9223372036854775807::bigint), (9223372036854775807::bigint)) v(x)",
        "select pg_typeof(sum(x)), pg_typeof(avg(x)), sum(x), avg(x) from (values (1::bigint), (2::bigint)) v(x)",
        "select pg_typeof(sum(x)), pg_typeof(avg(x)), sum(x), avg(x) from (values (1::int), (2::int)) v(x)",
        "select pg_typeof(sum(x)), pg_typeof(avg(x)), sum(x), avg(x) from (values (1::smallint), (2::smallint)) v(x)",
        "select avg(x) from (values (9223372036854775807::bigint), (9223372036854775806::bigint)) v(x)",
        "select sum(x), avg(x) from (values (-9223372036854775807::bigint), (-9223372036854775807::bigint)) v(x)",
        "select sum(x)::text, sum(x) + 1, sum(x) * 2, sum(x) / 2 from (values (9223372036854775807::bigint), (9223372036854775807::bigint)) v(x)",
        "select sum(x), pg_typeof(sum(x)) from (values (2147483647::int), (2147483647::int), (2147483647::int)) v(x)",
        "select sum(x) from (select 1::bigint x where false) v",
        "select sum(distinct x), sum(x) filter (where x > 1) from (values (9223372036854775807::bigint), (9223372036854775807::bigint), (1::bigint)) v(x)",
        "create table sb_t (g int, a bigint, b int, c smallint)",
        "insert into sb_t values (1, 9223372036854775807, 2147483647, 32767), (1, 9223372036854775807, 2147483647, 32767), (2, 1, 1, 1)",
        "select sum(a), sum(b), sum(c), pg_typeof(sum(a)), pg_typeof(sum(b)), pg_typeof(sum(c)), avg(a), avg(b) from sb_t",
        "select g, sum(a), sum(b) from sb_t group by g order by g",
        "select a, sum(a) over (order by g, a rows between unbounded preceding and current row), pg_typeof(sum(a) over ()) from sb_t order by g, a",
        "create view sb_v as select sum(a) s from sb_t",
        "select s, pg_typeof(s) from sb_v",
        "create table sb_c as select sum(a) s from sb_t",
        "select s, pg_typeof(s) from sb_c",
    ]]);
}

#[test]
fn text_search_default_parser_cuts_tokens_as_postgres_does() {
    check(&[&[
        "select to_tsvector('english', '8e296abc')",
        "select to_tsvector('english', 'see http://x.y/z')",
        "select to_tsvector('simple', 'see http://x.y/z now')",
        "select to_tsvector('simple', 'foo-bar baz_qux 123abc abc123 1.5e3 3.14 -5 +7 a@b.com user@example.com/path')",
        "select to_tsvector('simple', '/usr/local/bin file.txt c:\\dir www.example.com example.com/a/b?x=1#f')",
        "select to_tsvector('simple', '2001-01-01 12:34:56 1,000.50 x_y 1a 1_a ab_12')",
        "select to_tsvector('simple', 'hello&amp;world <b>bold</b> <a href=\"http://x.org\">link</a>')",
        "select to_tsvector('simple', 'e296 8e296 8e 8e+2 8e+296abc 1e5x 2e-3 .5 5. 5.e')",
        "select to_tsvector('simple', '192.168.1.1 foo@bar.baz ftp://host/path http://a.b:80/c?d=e')",
        "select to_tsvector('simple', 'state-of-the-art well-known 1-2-3 3-d version 1.2.3 v1.2.3-beta')",
        "select to_tsvector('simple', 'a.b.c a..b a-.b x--y')",
        "select to_tsvector('english', 'node.js and C++ and C# and .NET and foo/bar and a:b')",
        "select to_tsvector('english', 'ISO-8859-1 UTF-8 mp3 mp3player 3rd 1st 2nd')",
        "select to_tsvector('simple', '<script>var a = 1;</script> visible <style>p { x }</style> text <!-- c --> end')",
        "select to_tsvector('simple', 'a&#x41;b &lt;tag&gt; &bogus x&y')",
        "select * from ts_parse('default', '8e296abc see http://x.y/z foo-bar')",
        "select * from ts_parse('default', 'x@y.com/p ~/home/me ./rel ../up /abs/path.txt c.txt')",
        "select * from ts_debug('simple', '8e296abc see http://x.y/z foo-bar 1.5 -7')",
        "select ts_headline('english', 'see http://x.y/z or 8e296abc here <b>bold</b>', to_tsquery('abc'))",
    ]]);
}

#[test]
fn char_n_is_padded_in_xml_mappings_and_where_a_branch_gives_it() {
    check(&[&[
        "create table cx_t (id int primary key, c char(5), v varchar(5))",
        "insert into cx_t values (1, 'ab', 'ab'), (2, 'cd   ', 'cd')",
        "select query_to_xml('select c, v from cx_t order by id', true, true, '')::text",
        "select table_to_xml('cx_t', true, false, '')::text",
        "select xmlelement(name e, c), xmlforest(c as a, v as b) from cx_t order by id",
        "select xmlagg(xmlelement(name e, c order by id)) from cx_t",
        "select c::xml from cx_t order by id",
        "select c || 'x', coalesce(c, 'z'), nullif(c, 'q'), greatest(c, 'a'), least(c, 'zz') from cx_t order by id",
        "select case when id = 1 then c else 'z' end, case id when 2 then c end from cx_t order by id",
        "select coalesce(c, 'z') = 'ab', coalesce(c, 'z') = 'ab   ' from cx_t order by id",
        "select string_agg(c, ','), array_to_string(array_agg(c), ',') from cx_t",
        "begin",
        "declare cx_k cursor for select c, id from cx_t order by id",
        "fetch all from cx_k",
        "close cx_k",
        "commit",
    ]]);
}

#[test]
fn catalog_only_alters_leave_indexes_and_constraints_working() {
    check(&[&[
        "create table d2_p (id int primary key, k int unique)",
        "insert into d2_p select g, g from generate_series(1, 50) g",
        "create table d2_c (id int primary key, p int references d2_p(id), a int, b text, c int unique, ck int check (ck > 0), v varchar(5))",
        "insert into d2_c select g, g, g % 5, 'b' || g, g, g, 'v' || (g % 10) from generate_series(1, 50) g",
        "create index d2_c_a on d2_c (a)",
        "create index d2_c_lb on d2_c (lower(b)) where a > 1",
        "alter table d2_c rename column a to a2",
        "alter table d2_c rename column b to b2",
        "select indexname, replace(indexdef, current_schema() || '.', '') from pg_indexes where tablename = 'd2_c' order by indexname",
        "select a2, count(*) from d2_c group by a2 order by a2",
        "select id from d2_c where a2 = 3 order by id limit 3",
        "select id from d2_c where lower(b2) = 'b7'",
        "alter table d2_c rename column ck to ck2",
        "select conname, pg_get_constraintdef(oid) from pg_constraint where conrelid = 'd2_c'::regclass order by conname",
        "insert into d2_c values (100, 999, 1, 'x', 100, 1, 'v')",
        "insert into d2_c values (101, 1, 1, 'x', 5, 1, 'v')",
        "insert into d2_c values (102, 1, 1, 'x', 102, -1, 'v')",
        "delete from d2_p where id = 1",
        "alter table d2_c drop column b2",
        "select indexname from pg_indexes where tablename = 'd2_c' order by indexname",
        "select id, a2, c from d2_c where id = 3",
        "alter table d2_c add column e int default 7",
        "alter table d2_c add column f text",
        "select id, e, f from d2_c where id < 3 order by id",
        "alter table d2_c alter column e set default 9",
        "insert into d2_c (id, p, a2, c, ck2) values (200, 1, 1, 200, 1)",
        "select id, e from d2_c where id in (1, 200) order by id",
        "alter table d2_c alter column e drop default",
        "insert into d2_c (id, p, a2, c, ck2) values (201, 1, 1, 201, 1)",
        "select id, e from d2_c where id = 201",
        "alter table d2_c rename constraint d2_c_c_key to d2_c_uq",
        "insert into d2_c (id, p, a2, c, ck2) values (202, 1, 1, 5, 1)",
        "select conname from pg_constraint where conrelid = 'd2_c'::regclass order by conname",
        "alter table d2_c alter column v type varchar(20)",
        "alter table d2_c alter column v type text",
        "select id, v from d2_c where id = 12",
        "alter table d2_c drop column a2",
        "select indexname from pg_indexes where tablename = 'd2_c' order by indexname",
        "select count(*) from d2_c",
    ]]);
}

