#[test]
fn add_column_with_a_stable_default_gives_the_rows_there_one_value() {
    check(&[&[
        "create table d2n (id int primary key)",
        "insert into d2n values (1), (2), (3)",
        "alter table d2n add column ts timestamptz default now()",
        "alter table d2n add column dt date default current_date",
        "alter table d2n add column who text default current_user",
        "select count(distinct ts), bool_and(ts is not null), bool_and(dt = current_date), min(who) = current_user from d2n",
        "insert into d2n (id) values (4)",
        "select id, ts is not null, dt = current_date from d2n order by id",
        "alter table d2n alter column ts drop default",
        "insert into d2n (id) values (5)",
        "select id, ts is null from d2n where id >= 4 order by id",
        "begin",
        "alter table d2n add column ts2 timestamptz default now()",
        "select count(*) from d2n where ts2 = now()",
        "commit",
    ]]);
}

/// A table, view or materialized view has at most 1600 columns, dropped ones counting (54011), by
/// CREATE TABLE, ADD COLUMN, inheritance, CREATE TABLE AS and CREATE VIEW.
#[test]
fn relations_have_at_most_1600_columns() {
    let cols = |n: usize| (1..=n).map(|i| format!("c{i} int")).collect::<Vec<_>>().join(", ");
    let (too_many, fits) =
        (format!("create table cc_big ({})", cols(1601)), format!("create table cc_ok ({})", cols(1600)));
    check(&[&[
        &too_many,
        &fits,
        "select count(*) from pg_attribute where attrelid = 'cc_ok'::regclass and attnum > 0",
        "alter table cc_ok add column one_more int",
        "create table cc_kid (extra int) inherits (cc_ok)",
        "create table cc_ctas as select *, 1 as extra from cc_ok",
        "create view cc_v as select *, c1 as extra from cc_ok",
        "create materialized view cc_mv as select *, c1 as extra from cc_ok",
        "create view cc_v_ok as select * from cc_ok",
        "drop view cc_v_ok",
        "alter table cc_ok drop column c1",
        "alter table cc_ok add column again int",
        "create table cc_small (a int)",
        "alter table cc_small add column b int, add column c int",
        "select count(*) from pg_attribute where attrelid = 'cc_small'::regclass and attnum > 0",
    ]]);
}

