#[test]
fn user_aggregates_sort_and_deduplicate_their_distinct_input() {
    check(&[&[
        "create function d3_cat(a text, b text) returns text language sql as $$ select case when a is null then b else a || ', ' || b end $$",
        "create aggregate d3_gc(text) (sfunc = d3_cat, stype = text)",
        "select d3_gc(distinct x) from (values ('b'), ('a'), ('c'), ('a')) v(x)",
        "select d3_gc(x) from (values ('b'), ('a'), ('c'), ('a')) v(x)",
        "select d3_gc(x order by x desc) from (values ('b'), ('a'), ('c'), ('a')) v(x)",
        "select d3_gc(distinct x order by x desc) from (values ('b'), ('a'), ('c'), ('a')) v(x)",
        "select d3_gc(x) filter (where x <> 'c') from (values ('b'), ('a'), ('c'), ('a')) v(x)",
        "select d3_gc(distinct x) filter (where x <> 'c') from (values ('b'), ('a'), ('c'), ('a')) v(x)",
        "select g, d3_gc(distinct x) from (values (1, 'b'), (1, 'a'), (2, 'c'), (1, 'a'), (2, 'c'), (2, 'b')) v(g, x) group by g order by g",
        "create function d3_two(a text, b text, c text) returns text language sql as $$ select coalesce(a || ';', '') || b || '/' || c $$",
        "create aggregate d3_agg2(text, text) (sfunc = d3_two, stype = text)",
        "select d3_agg2(distinct x, y) from (values ('b', '1'), ('a', '2'), ('a', '1'), ('a', '2'), ('b', '1')) v(x, y)",
        "select d3_agg2(x, y) from (values ('b', '1'), ('a', '2'), ('a', '1'), ('a', '2'), ('b', '1')) v(x, y)",
    ]]);
}

