#[test]
fn alter_column_type_rewrites_values_as_a_cast_does() {
    check_text(&[&[
        "create table d3_n (a int, p int)",
        "insert into d3_n values (1, 41), (2, 7), (3, null)",
        "alter table d3_n alter column p type numeric(10,2)",
        "select a, p::text, pg_typeof(p)::text from d3_n order by a",
        "create table d3_v (a int, v text, c text, ts timestamp, tz timestamptz, iv interval, b bit varying, d numeric)",
        "insert into d3_v values (1, 'abc', 'ab', '2024-01-02 03:04:05.678912', '2024-01-02 03:04:05.678912+00', '1 day 03:04:05.678912', '1011', 12.3456)",
        "alter table d3_v alter column v type varchar(5)",
        "alter table d3_v alter column c type char(5)",
        "alter table d3_v alter column ts type timestamp(2)",
        "alter table d3_v alter column tz type timestamptz(0)",
        "alter table d3_v alter column iv type interval(1)",
        "alter table d3_v alter column d type numeric(6,1)",
        "select v, c, '[' || c || ']', length(c), ts::text, tz::text, iv::text, d::text from d3_v",
        "alter table d3_v alter column b type bit(4)",
        "select b::text from d3_v",
        "alter table d3_v alter column v type varchar(2)",
        "create table d3_u (a int primary key, p int, s text)",
        "insert into d3_u values (1, 41, 'x'), (2, 7, 'yy')",
        "create index d3_u_p on d3_u (p)",
        "create unique index d3_u_s on d3_u (s)",
        "alter table d3_u alter column p type numeric(10,2) using p * 1.5",
        "select a, p::text from d3_u order by a",
        "select a from d3_u where p = 61.5",
        "alter table d3_u alter column s type char(4)",
        "select a, '[' || s || ']' from d3_u where s = 'x' order by a",
        "alter table d3_u add constraint d3_ck check (p < 100)",
        "alter table d3_u alter column p type numeric(4,1)",
        "select a, p::text from d3_u order by a",
        "alter table d3_u alter column p type numeric(2,0)",
        "create table d3_f (a int, b smallint)",
        "insert into d3_f values (1, 2)",
        "alter table d3_f alter column b type numeric(5,2) using b::numeric / 3",
        "select b::text from d3_f",
        "alter table d3_f alter column b type int using round(b)",
        "select b::text, pg_typeof(b)::text from d3_f",
    ]]);
}

#[test]
fn citext_through_concatenation_and_text_functions_is_text() {
    check(&[&[
        "create extension if not exists citext",
        "select concat_ws('|', x, 'z') from (values ('Foo'::citext), ('baz'), ('Bar')) v(x) order by 1",
        "select x || '' from (values ('Foo'::citext), ('baz'), ('Bar')) v(x) order by 1",
        "select x || 'z' as y from (values ('Foo'::citext), ('baz'), ('Bar')) v(x) order by y",
        "select 'z' || x as y from (values ('Foo'::citext), ('baz'), ('Bar')) v(x) order by y",
        "select concat(x, '') as y from (values ('Foo'::citext), ('baz'), ('Bar')) v(x) order by y",
        "select lower(x) as y from (values ('Foo'::citext), ('baz'), ('Bar')) v(x) order by y",
        "select x from (values ('Foo'::citext), ('baz'), ('Bar')) v(x) order by x",
        "select coalesce(x, 'a') as y from (values ('Foo'::citext), ('baz'), ('Bar')) v(x) order by y",
        "select (x || '') = 'foo', (x || '') = 'Foo' from (values ('Foo'::citext)) v(x)",
        "select substr(x, 1, 2) as y from (values ('Foo'::citext), ('baz'), ('Bar')) v(x) order by y",
        "select max(x), min(x) from (values ('Foo'::citext), ('baz'), ('Bar')) v(x)",
        "create table d3_cz (id int, e citext)",
        "insert into d3_cz values (1, 'Foo'), (2, 'bar'), (3, 'Baz')",
        "select id, e || '!' as y from d3_cz order by y",
        "select id from d3_cz where e || '' = 'foo'",
        "select id from d3_cz where e = 'FOO'",
    ]]);
}

#[test]
fn owned_sequences_resolve_by_name_through_the_search_path() {
    check(&[&[
        "drop schema if exists d3_sb cascade",
        "drop table if exists public.d3_t2",
        "create schema d3_sb",
        "create table d3_sb.t (id bigserial primary key, n text)",
        "set search_path = d3_sb",
        "select nextval('t_id_seq')",
        "select currval('t_id_seq')",
        "select setval('t_id_seq', 10)",
        "select nextval('t_id_seq')",
        "select 't_id_seq'::regclass::text",
        "select pg_get_serial_sequence('t', 'id')",
        "select pg_get_serial_sequence('d3_sb.t', 'id')",
        "select lastval()",
        "alter sequence t_id_seq restart with 100",
        "select nextval('t_id_seq')",
        "select nextval('d3_sb.t_id_seq')",
        "insert into t (n) values ('a') returning id",
        "select last_value, is_called from t_id_seq",
        "set search_path = public",
        "select nextval('d3_sb.t_id_seq')",
        "select pg_get_serial_sequence('d3_sb.t', 'id')",
        "create table d3_t2 (id serial primary key, n text)",
        "alter sequence d3_t2_id_seq restart with 50",
        "insert into d3_t2 (n) values ('a') returning id",
        "select nextval('d3_t2_id_seq'), nextval('public.d3_t2_id_seq')",
        "drop table public.d3_t2",
        "drop schema d3_sb cascade",
    ]]);
}

#[test]
fn composite_columns_expand_and_survive_subqueries() {
    check(&[&[
        "create type d3_pt as (x int, y text)",
        "create table d3_tpt (id int primary key, p d3_pt)",
        "insert into d3_tpt values (1, row(1, 'a')), (2, row(2, 'b'))",
        "select id, (p).* from d3_tpt order by id",
        "select (p).x, (p).y from d3_tpt order by id",
        "select * from (select id, p from d3_tpt) q order by id",
        "select (q.p).y from (select id, p from d3_tpt) q order by id",
        "select id, (select (t.p).y) from d3_tpt t order by id",
        "select id, (select (q.p).y) from (select id, p from d3_tpt order by id limit 5) q order by id",
        "select * from d3_tpt t, lateral (select (t.p).y as yy) l order by id",
        "select * from (select id, p from d3_tpt order by id limit 5) q, lateral (select (q.p).y as yy) l order by id",
        "select * from (select id, p from d3_tpt) q, lateral (select (q.p).y as yy) l order by id",
        "select * from (select id, p from d3_tpt) q cross join lateral (select (q.p).y as yy, (q.p).x as xx) l order by id",
        "select (l.p).x from (select id, p from d3_tpt) q, lateral (select q.p) l order by id",
        "select * from (select id, p from d3_tpt) q, lateral (select (p).y as yy) l order by id",
        "select q.id, l.* from d3_tpt q left join lateral (select (q.p).x as xx) l on true order by id",
        "with c as (select id, p from d3_tpt) select * from c, lateral (select (c.p).y as yy) l order by id",
        "with c as (select id, p from d3_tpt) select id, l.yy from c cross join lateral (select (p).y as yy) l order by id",
        "create view d3_vp as select id, p from d3_tpt",
        "select (p).x, (d3_vp.p).y from d3_vp order by id",
        "select (p).* from d3_vp order by id",
        "select * from d3_vp, lateral (select (d3_vp.p).y as yy) l order by id",
        "select (u.p).y from (select p from d3_tpt union all select p from d3_tpt) u order by 1",
        "select * from (select id, p from d3_tpt union all select id + 10, p from d3_tpt) q, lateral (select (q.p).y as yy) l order by id",
        "create function d3_mkpt(i int) returns d3_pt language sql as $$ select row(i, 'f')::d3_pt $$",
        "select (d3_mkpt(3)).x, (d3_mkpt(3)).*",
        "select * from d3_mkpt(4)",
        "select (f).y from (select d3_mkpt(id) as f from d3_tpt) s order by 1",
        "select (row(1, 'z')::d3_pt).*",
        "select (x).* from (select p as x from d3_tpt) s order by 1",
        "select * from (select id, row(id, 'z')::d3_pt as r from d3_tpt) q, lateral (select (q.r).y as yy) l order by id",
    ]]);
}

#[test]
fn citext_keys_and_listening_channels() {
    check(&[&[
        "create extension if not exists citext",
        "create table d3_ck (e citext primary key, n int)",
        "insert into d3_ck values ('Foo', 1), ('bar', 2)",
        "insert into d3_ck values ('FOO', 3)",
        "select e::text, n from d3_ck order by e",
        "select n from d3_ck where e = 'BAR'",
        "insert into d3_ck values ('FOO', 3) on conflict (e) do update set n = excluded.n + 10 returning e::text, n",
        "update d3_ck set e = 'BAR' where n = 1",
        "select conname, contype from pg_constraint where conrelid = 'd3_ck'::regclass order by 1",
        "select indexrelid::regclass::text, indisprimary, indisunique from pg_index where indrelid = 'd3_ck'::regclass",
        "select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'd3_ck'::regclass",
        "select column_name, is_nullable from information_schema.columns where table_name = 'd3_ck' order by ordinal_position",
        "create table d3_ck2 (a citext, b citext, primary key (a, b))",
        "insert into d3_ck2 values ('x', 'y')",
        "insert into d3_ck2 values ('X', 'Y')",
        "create table d3_ck3 (e citext unique not null, f citext)",
        "create index d3_ck3_f on d3_ck3 (f)",
        "create unique index d3_ck3_u on d3_ck3 (lower(f::text))",
        "insert into d3_ck3 values ('a', 'q'), ('b', 'Q')",
        "create table d3_ck4 (id int)",
        "insert into d3_ck4 values (1), (2)",
        "alter table d3_ck4 add column e citext",
        "update d3_ck4 set e = 'v' || id",
        "alter table d3_ck4 add primary key (e)",
        "insert into d3_ck4 values (3, 'V1')",
        "listen d3_foo",
        "listen d3_bar",
        "select pg_listening_channels()",
        "select * from pg_listening_channels()",
        "unlisten d3_foo",
        "select pg_listening_channels()",
        "unlisten *",
        "select count(*) from pg_listening_channels()",
    ]]);
}

#[test]
fn domain_and_exclusion_constraints_are_in_pg_constraint() {
    check(&[&[
        "create domain d3_pos as int check (value > 0)",
        "create domain d3_nn as text not null check (value <> '') check (length(value) < 10)",
        "create type d3_mood as enum ('sad', 'ok')",
        "select typname, typtype, typnotnull from pg_type where typname in ('d3_pos', 'd3_nn', 'd3_mood') order by typname",
        "select conname, contype, contypid::regtype::text, conrelid, convalidated, conislocal, coninhcount, connoinherit, pg_get_constraintdef(oid) from pg_constraint where contypid <> 0 and contypid::regtype::text like 'd3_%' order by conname",
        "select count(*) from pg_constraint where contypid = 'd3_nn'::regtype",
        "create extension if not exists btree_gist",
        "create table d3_ex (id int primary key, room int, during int4range, exclude using gist (room with =, during with &&))",
        "select conname, contype, conkey, pg_get_constraintdef(oid) from pg_constraint where conrelid = 'd3_ex'::regclass order by conname",
        "select constraint_name, constraint_type from information_schema.table_constraints where table_name = 'd3_ex' and constraint_type <> 'CHECK' order by 1",
        "select count(*) from information_schema.key_column_usage where table_name = 'd3_ex'",
        "create table d3_ex2 (a int, b int, exclude using btree (a with =) where (b > 0))",
        "select pg_get_constraintdef(oid), conkey from pg_constraint where conrelid = 'd3_ex2'::regclass",
        "select relname, relchecks from pg_class where relname in ('d3_ex', 'd3_ex2') order by 1",
    ]]);
}

/// Isolation levels: the default is READ COMMITTED, BEGIN and SET TRANSACTION choose one for the transaction (before
/// its first query), SET SESSION CHARACTERISTICS and default_transaction_isolation for the next ones, and SHOW,
/// current_setting and pg_settings say which. (SERIALIZABLE is refused by Chronos, so it isn't here.)
#[test]
fn isolation_levels_are_chosen_and_shown_as_postgres_does() {
    check(&[&[
        "show transaction_isolation",
        "show default_transaction_isolation",
        "begin",
        "show transaction_isolation",
        "select current_setting('transaction_isolation'), current_setting('default_transaction_isolation')",
        "commit",
        "begin isolation level repeatable read",
        "show transaction isolation level",
        "select current_setting('transaction_isolation')",
        "select 1",
        "set transaction isolation level read committed",
        "rollback",
        "begin",
        "set transaction isolation level repeatable read",
        "show transaction_isolation",
        "commit",
        "begin isolation level read uncommitted, read write",
        "show transaction_isolation",
        "commit",
        "set session characteristics as transaction isolation level repeatable read",
        "show default_transaction_isolation",
        "begin",
        "show transaction_isolation",
        "commit",
        "begin isolation level read committed",
        "show transaction_isolation",
        "commit",
        "set default_transaction_isolation = 'read committed'",
        "select name, setting from pg_settings where name like '%isolation%' order by name",
        "begin; savepoint s; set transaction isolation level repeatable read",
        "rollback",
        "set transaction isolation level repeatable read",
        "reset default_transaction_isolation",
        "show default_transaction_isolation",
    ]]);
}

/// varchar, varchar(n), char(n) and their arrays are their own types, as Postgres's catalog has them: pg_typeof,
/// pg_attribute's type and typmod, and format_type of them (though their values are held as text).
#[test]
fn varchar_and_char_columns_are_their_own_types() {
    check(&[&[
        "create table f3_t (id int primary key, a varchar, b varchar(10), c char(3), d character varying(5)[], e char(2)[], f text, g character, h varchar[], i character varying)",
        "insert into f3_t values (1, 'x', 'y', 'z', '{a}', '{b}', 't', 'g', '{h}', 'i')",
        "select pg_typeof(a), pg_typeof(b), pg_typeof(c), pg_typeof(d), pg_typeof(e), pg_typeof(f), pg_typeof(g), pg_typeof(h), pg_typeof(i) from f3_t",
        "select attname, atttypid, atttypid::regtype, atttypmod, format_type(atttypid, atttypmod), attndims, attlen from pg_attribute where attrelid = 'f3_t'::regclass and attnum > 0 order by attnum",
        "select format_type(1043, null), format_type(1043, -1), format_type(1043, 14), format_type(1042, null), format_type(1042, -1), format_type(1042, 7), format_type(1015, 14), format_type(1015, -1), format_type(1014, 7)",
        "select typname, typlen, typcategory, typelem, typarray from pg_type where oid in (1042, 1043, 1014, 1015) order by oid",
        "select t.typname from pg_attribute a join pg_type t on t.oid = a.atttypid where a.attrelid = 'f3_t'::regclass and a.attnum > 0 order by a.attnum",
    ]]);
}

/// information_schema.columns shows a varchar as `character varying` (with its length, where it has one) and a
/// char(n) as `character`, their udt names varchar and bpchar; their arrays are ARRAYs of _varchar and _bpchar.
#[test]
fn information_schema_shows_varchar_and_char_columns() {
    check(&[&[
        "create table f3_i (id int primary key, a varchar, b varchar(10), c char(3), d varchar(5)[], e char(2)[], f text, g char)",
        "select column_name, data_type, character_maximum_length, udt_name from information_schema.columns where table_name = 'f3_i' order by ordinal_position",
        "alter table f3_i alter column f type varchar(20)",
        "alter table f3_i alter column b type varchar",
        "alter table f3_i add column h character varying",
        "select column_name, data_type, character_maximum_length, udt_name from information_schema.columns where table_name = 'f3_i' order by ordinal_position",
        "select attname, format_type(atttypid, atttypmod) from pg_attribute where attrelid = 'f3_i'::regclass and attnum > 0 order by attnum",
    ]]);
}

/// What expressions of varchars and char(n)s are, by Postgres's rules: `||` and the text functions give text, a cast
/// gives its type, COALESCE, CASE, GREATEST, LEAST and NULLIF keep a varchar (or char(n)) that all their values are,
/// min and max of a varchar are text's, of a char(n) a char(n); an element of a varchar[] is a varchar.
#[test]
fn varchar_and_char_expressions_have_postgres_result_types() {
    check(&[&[
        "create table f3_e (id int primary key, a varchar, b varchar(10), c char(3), f text, h varchar(4)[])",
        "insert into f3_e values (1, 'x', 'y', 'z', 't', '{h}')",
        "select pg_typeof(b || b), pg_typeof(upper(a)), pg_typeof(c || 'x'), pg_typeof(lower(c)), pg_typeof(a::text), pg_typeof(substr(b, 1)) from f3_e",
        "select pg_typeof(f::varchar), pg_typeof(f::varchar(3)), pg_typeof(f::char(2)), pg_typeof('x'::character varying(10)), pg_typeof(f::character varying), pg_typeof(1::varchar) from f3_e",
        "select pg_typeof(coalesce(a, 'x')), pg_typeof(coalesce(b, a)), pg_typeof(coalesce(b, f)), pg_typeof(coalesce(c, 'q')), pg_typeof(coalesce(c, c)) from f3_e",
        "select pg_typeof(case when id = 1 then a else 'q' end), pg_typeof(case when id = 1 then b end), pg_typeof(case when id = 1 then b else f end) from f3_e",
        "select pg_typeof(nullif(b, 'x')), pg_typeof(greatest(a, b)), pg_typeof(least(c, c)), pg_typeof(h[1]), pg_typeof(a collate \"C\") from f3_e",
        "select pg_typeof(min(a)), pg_typeof(max(b)), pg_typeof(min(c)), pg_typeof(max(c)) from f3_e",
        "select f::varchar(1), f::varchar, 'abcdef'::varchar(3), 'ab  '::varchar, length('ab  '::varchar) from f3_e",
        "select a, b from f3_e where b = 'y'::varchar and a = 'x'::character varying",
    ]]);
}

/// A varchar's and a char(n)'s type is kept through a subquery, a WITH query, UNION (where every part agrees; a varchar
/// beside text is text), a view, a materialized view and CREATE TABLE AS, as Postgres keeps it.
#[test]
fn varchar_and_char_types_last_through_queries_views_and_tables_made_of_them() {
    check(&[&[
        "create table f3_q (id int primary key, a varchar, b varchar(10), c char(3), f text)",
        "insert into f3_q values (1, 'x', 'y', 'z', 't')",
        "select pg_typeof(x), pg_typeof(y) from (select b, c from f3_q) s(x, y)",
        "with w as (select a, b from f3_q) select pg_typeof(a), pg_typeof(b) from w",
        "select pg_typeof(x) from (select b from f3_q union select b from f3_q) s(x)",
        "select pg_typeof(x) from (select b from f3_q union select f from f3_q) s(x)",
        "select pg_typeof(x) from (select a from f3_q union all select 'lit') s(x)",
        "select pg_typeof(x) from (select c from f3_q union select c from f3_q) s(x)",
        "create view f3_v as select a, b, c, f, coalesce(b, 'x') as cb, b || 'x' as bx from f3_q",
        "select attname, format_type(atttypid, atttypmod) from pg_attribute where attrelid = 'f3_v'::regclass and attnum > 0 order by attnum",
        "select column_name, data_type, character_maximum_length, udt_name from information_schema.columns where table_name = 'f3_v' order by ordinal_position",
        "select pg_typeof(a), pg_typeof(b), pg_typeof(c) from f3_v",
        "create table f3_ctas as select a, b, c, f, b || 'x' as bx from f3_q",
        "select attname, format_type(atttypid, atttypmod) from pg_attribute where attrelid = 'f3_ctas'::regclass and attnum > 0 order by attnum",
        "create table f3_ctas2 as select b from f3_q union select b from f3_q",
        "select attname, format_type(atttypid, atttypmod) from pg_attribute where attrelid = 'f3_ctas2'::regclass and attnum > 0 order by attnum",
        "create materialized view f3_mv as select a, b, c from f3_q",
        "select attname, format_type(atttypid, atttypmod) from pg_attribute where attrelid = 'f3_mv'::regclass and attnum > 0 order by attnum",
        "select c, length(c), c = 'z  ' from f3_mv",
    ]]);
}

/// A varchar column of no length holds and compares as text does: its values as given, trailing blanks kept, nothing
/// refused for its length, and its default literal written as a varchar's.
#[test]
fn varchar_of_no_length_holds_and_compares_as_text() {
    check(&[&[
        "create table f3_n (id int primary key, a varchar default 'd', b character varying)",
        "insert into f3_n values (1, 'ab  ', repeat('x', 3000)), (2, 'ab', 'ab')",
        "insert into f3_n (id) values (3)",
        "select id, a, length(a), a = 'ab', length(b) from f3_n order by id",
        "select id from f3_n where a = 'ab  ' order by id",
        "select pg_get_expr(adbin, adrelid) from pg_attrdef where adrelid = 'f3_n'::regclass",
        "select column_default from information_schema.columns where table_name = 'f3_n' and column_name = 'a'",
        "select count(*) from f3_n group by a order by 1",
    ]]);
}

/// A column a view reads (through `*` too), or a materialized view, or a SQL-standard function body, can't be
/// dropped (2BP01) and its type can't change (0A000); with CASCADE they go, with the views that read them. A view that
/// reads no column of it (`count(*)`, a whole row), a function with a string body, an index, a CHECK and a statistics
/// object don't stop it.
#[test]
fn dropping_a_column_a_view_or_function_reads_is_refused() {
    check(&[&[
        "create table f2t (a int, b int, c int)",
        "insert into f2t values (1, 2, 3)",
        "create view f2v as select * from f2t",
        "create view f2w as select b from f2t where c > 0",
        "create view f2n as select count(*) from f2t",
        "create view f2r as select x from f2t x",
        "alter table f2t add column d int",
        "alter table f2t drop column d",
        "alter table f2t drop column a",
        "select * from f2v",
        "alter table f2t drop column c",
        "alter table f2t alter column b type bigint",
        "alter table f2t alter column a type text",
        "alter table f2t drop column a cascade",
        "select count(*) from pg_views where viewname in ('f2v', 'f2w', 'f2n', 'f2r')",
        "select * from f2w",
        "alter table f2t drop column b cascade",
        "select viewname from pg_views where viewname like 'f2_' order by 1",
        "select * from f2n",
        "create table f2g (a int, b int generated always as (a * 2) stored, c int check (c > a))",
        "alter table f2g drop column a",
        "alter table f2g alter column a type bigint",
        "create table f2i (a int, b int, c int)",
        "create index f2i_x on f2i ((c + 1))",
        "create statistics f2i_st on a, b from f2i",
        "alter table f2i add constraint f2i_ck check (b > a)",
        "alter table f2i drop column a",
        "alter table f2i drop column c",
        "select count(*) from pg_statistic_ext where stxname = 'f2i_st'",
        "create table f2f (a int, b int)",
        "create function f2fa() returns int begin atomic select a from f2f; end",
        "create function f2fr() returns int return (select max(b) from f2f)",
        "create function f2fs() returns int language sql as 'select b from f2f'",
        "alter table f2f drop column a",
        "alter table f2f alter column a type bigint",
        "alter table f2f drop column b",
        "alter table f2f drop column a cascade",
        "select proname from pg_proc where proname like 'f2f_' order by 1",
        "create table f2m (a int, b int)",
        "create materialized view f2mv as select a from f2m",
        "alter table f2m drop column a",
        "alter table f2m alter column a type bigint",
        "alter table f2m drop column b",
        "alter table f2m drop column a cascade",
        "select count(*) from pg_matviews where matviewname = 'f2mv'",
        "create table f2c (a int, b int)",
        "create view f2c1 as select a from f2c",
        "create view f2c2 as select * from f2c1",
        "alter table f2c drop column a",
        "alter table f2c drop column a cascade",
        "select count(*) from pg_views where viewname like 'f2c_'",
    ]]);
}

/// Long IN lists and constant arrays are looked up in a hash set, and correlated scalar and aggregate subqueries
/// answered from a hash table by their key: the answers are the ones comparing each row with each value gave, NULLs
/// and keys no row has included.
#[test]
fn hashed_in_lists_and_correlated_aggregates_answer_as_before() {
    let list: String = (1..=40).map(|i| (i * 3).to_string()).collect::<Vec<_>>().join(", ");
    let q = |s: &str| s.replace("LIST", &list);
    let words: String = (1..=30).map(|i| format!("'v{}'", i * 2)).collect::<Vec<_>>().join(", ");
    let script = [
        "create table f2h (id int, k int, v text)".to_string(),
        "insert into f2h select g, g % 7, 'v' || g from generate_series(1, 200) g".into(),
        "insert into f2h values (null, null, null)".into(),
        q("select count(*) from f2h where id in (LIST)"),
        q("select count(*) from f2h where id not in (LIST)"),
        q("select count(*) from f2h where id not in (LIST, null)"),
        q("select id, id in (LIST, null), id not in (LIST, null) from f2h where id < 12 or id is null order by id"),
        q("select count(*) from f2h where id = any('{LIST}'::int[])"),
        q("select count(*) from f2h where id <> all(array[LIST]::bigint[])"),
        q("select count(*) from f2h where id::numeric in (LIST)"),
        format!("select count(*) from f2h where v in ('V9', 'v12 ', {})", words),
        "create table f2k (k int, n int)".into(),
        "insert into f2k select g % 5, g from generate_series(1, 50) g".into(),
        "insert into f2k values (null, 7)".into(),
        "select k, (select max(n) from f2k b where b.k = a.k), (select count(*) from f2k b where b.k = a.k) \
         from f2h a where id < 15 or id is null order by id"
            .into(),
        "select id, (select array_agg(n order by n) from f2k b where b.k = a.k and n > 40) from f2h a where id < 9 \
         order by id"
            .into(),
        "select id, (select n from f2k b where b.n = a.id) from f2h a where id < 60 order by id".into(),
        "select id, (select sum(n) from f2k b where b.k = a.k having count(*) > 0) from f2h a where id < 6 order by id"
            .into(),
    ];
    let script: Vec<&str> = script.iter().map(String::as_str).collect();
    check(&[&script]);
}

/// The row-count and checksum queries docs/migrating-from-postgres.md gives for checking a migration: the
/// queries that generate them from the catalog, and the checksum of a table of many types, give the same text
/// on both (the schema's name, which differs here, taken out).
#[test]
fn migration_checksum_queries_match_postgres() {
    check_text(&[&[
        "create type mig_mood as enum ('ok', 'sad')",
        "create table mig_ck (id bigint primary key, name text, price numeric(10, 2), qty int, ratio real, \
         score double precision, ok boolean, born date, seen timestamptz, at time, tags text[], doc jsonb, \
         raw bytea, uid uuid, mood mig_mood, code char(4), label varchar(20))",
        "insert into mig_ck values \
         (1, 'Ada', 9.99, 3, 0.1, 1e-7, true, '2026-01-31', '2026-10-15 12:34:56.789+00', '23:59:59.5', \
          '{a,\"b c\",NULL}', '{\"k\": [1, 2.50, null], \"a\": \"x\"}', '\\x00ff', \
          'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11', 'ok', 'ab', 'Ünïcödé, \"quoted\"'), \
         (2, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null), \
         (3, 'tab\there', -0.50, -2147483648, 3.4e38, -1.5e300, false, '0001-01-01', '1999-12-31 23:59:59+00', \
          '00:00', '{}', '[]', '', '00000000-0000-0000-0000-000000000000', 'sad', '', '')",
        "select count(*), md5(string_agg(r, ',' order by r)) from (select concat_ws(chr(1), \
         coalesce(id::text, '<NULL>'), coalesce(name::text, '<NULL>'), coalesce(price::text, '<NULL>')) as r \
         from mig_ck) s",
        "select replace(format('select %L as t, count(*) from %I.%I', table_schema || '.' || table_name, \
         table_schema, table_name), quote_ident(table_schema) || '.', '') from information_schema.tables \
         where table_type = 'BASE TABLE' and table_schema not in ('pg_catalog', 'information_schema') \
         and table_name = 'mig_ck' order by 1",
        "select replace(format(\
           'select %L as t, count(*), md5(string_agg(r, %L order by r)) from (select concat_ws(chr(1), %s) as r from %I.%I) s', \
           c.table_schema || '.' || c.table_name, ',', \
           string_agg(format('coalesce(%I::text, %L)', c.column_name, '<NULL>'), ', ' order by c.ordinal_position), \
           c.table_schema, c.table_name), quote_ident(c.table_schema) || '.', '') \
         from information_schema.columns c join information_schema.tables t using (table_schema, table_name) \
         where t.table_type = 'BASE TABLE' and c.table_schema not in ('pg_catalog', 'information_schema') \
         and c.table_name = 'mig_ck' group by c.table_schema, c.table_name order by 1",
        // what that generates, run
        "select 'mig_ck' as t, count(*), md5(string_agg(r, ',' order by r)) from (select concat_ws(chr(1), \
         coalesce(id::text, '<NULL>'), coalesce(name::text, '<NULL>'), coalesce(price::text, '<NULL>'), \
         coalesce(qty::text, '<NULL>'), coalesce(ratio::text, '<NULL>'), coalesce(score::text, '<NULL>'), \
         coalesce(ok::text, '<NULL>'), coalesce(born::text, '<NULL>'), coalesce(seen::text, '<NULL>'), \
         coalesce(at::text, '<NULL>'), coalesce(tags::text, '<NULL>'), coalesce(doc::text, '<NULL>'), \
         coalesce(raw::text, '<NULL>'), coalesce(uid::text, '<NULL>'), coalesce(mood::text, '<NULL>'), \
         coalesce(code::text, '<NULL>'), coalesce(label::text, '<NULL>')) as r from mig_ck) s",
        // and each row's text, so a difference shows where it is
        "select concat_ws(chr(1), coalesce(id::text, '<NULL>'), coalesce(price::text, '<NULL>'), \
         coalesce(ratio::text, '<NULL>'), coalesce(score::text, '<NULL>'), coalesce(seen::text, '<NULL>'), \
         coalesce(at::text, '<NULL>'), coalesce(tags::text, '<NULL>'), coalesce(doc::text, '<NULL>'), \
         coalesce(raw::text, '<NULL>'), coalesce(code::text, '<NULL>')) from mig_ck order by id",
    ]]);
}

/// A transaction's writes past what its commit merges row by row in memory (its world then takes its state whole, see
/// `Core::merge_published`) read as Postgres's: its own rows in it, savepoints rolled back and released, a unique
/// value taken again refused, ROLLBACK, CREATE TABLE AS, and the table after COMMIT.
#[test]
fn big_transactions_read_and_commit_as_postgres_does() {
    check(&[&[
        "create table g2_t (id int primary key, g int, u text unique)",
        "create index g2_t_g on g2_t (g)",
        "begin",
        "insert into g2_t select i, i % 97, 'u' || i from generate_series(1, 15000) i",
        "select count(*), sum(g) from g2_t",
        "savepoint a",
        "insert into g2_t select i, i % 7, 'u' || i from generate_series(15001, 30000) i",
        "select count(*) from g2_t where g = 3",
        "rollback to savepoint a",
        "select count(*) from g2_t where g = 3",
        "savepoint b",
        "update g2_t set g = g + 1 where id <= 12000",
        "release savepoint b",
        "select count(*), sum(g) from g2_t where g = 4",
        "select id from g2_t where u = 'u14000'",
        "commit",
        "select count(*), sum(g), max(u) from g2_t",
        "select id, g from g2_t where id between 11999 and 12001 order by id",
        "select count(*) from g2_t where g = 5",
        "begin",
        "delete from g2_t where id > 1000",
        "insert into g2_t select i, 0, 'v' || i from generate_series(20001, 40000) i",
        "select count(*), count(*) filter (where g = 0) from g2_t",
        "rollback",
        "select count(*), sum(g) from g2_t",
        "begin",
        "insert into g2_t select i, 1, 'w' || i from generate_series(50001, 65000) i",
        "insert into g2_t values (70000, 1, 'u5')",
        "commit",
        "select count(*) from g2_t",
        "create table g2_c as select i as id, i % 10 as k from generate_series(1, 20000) i",
        "select count(*), sum(k), max(id) from g2_c",
    ]]);
}

/// An error lets go of the locks taken since the innermost savepoint at once (Postgres's AbortSubTransaction), the
/// ones before it staying the transaction's; a RELEASEd savepoint's locks are its parent's, kept past a later error
/// and ROLLBACK TO: what pg_locks shows of the transaction's advisory locks along the way.
#[test]
fn an_error_lets_go_of_the_locks_taken_since_the_innermost_savepoint() {
    let mine = "select objid from pg_locks where locktype = 'advisory' and objid in (9101, 9102, 9103) order by objid";
    check(&[&[
        "begin",
        "select 1 from (select pg_advisory_xact_lock(9101)) l",
        "savepoint s",
        "select 1 from (select pg_advisory_xact_lock(9102)) l",
        "select 1/0",
        "rollback to s",
        mine,
        "savepoint t",
        "select 1 from (select pg_advisory_xact_lock(9103)) l",
        "release t",
        "savepoint u",
        "select 1/0",
        "rollback to u",
        mine,
        "rollback",
        mine,
    ]]);
}

/// `SELECT ... WHERE ... ORDER BY indexed columns LIMIT n` reads the index in order and stops at its rows: the same
/// rows, in the same order, as sorting the table gives, forwards and backwards, with OFFSET, conditions on other
/// columns, an index whose first columns are pinned by equalities, expressions and casts in the output, a function
/// that changes something run for the rows OFFSET skips too, and a prepared statement run with other values.
#[test]
fn ordered_index_reads_stop_at_the_limit() {
    check(&[&[
        "create table i2o (id int primary key, a int, b text, c char(4), d numeric(6,2), e int, f bigint)",
        "create index i2o_a on i2o (a)",
        "create index i2o_eb on i2o (e, b)",
        "create index i2o_f on i2o (f)",
        "insert into i2o select g, case when g % 50 = 0 then null else 1000 - g end, 'v' || lpad(g::text, 4, '0'), \
         'x' || (g % 3), g / 7.0, g % 4, (g - 150) * 61489012345 from generate_series(1, 300) g",
        "select id, a, b from i2o where a between 750 and 790 order by a limit 7",
        "select id, a, b from i2o where a between 750 and 790 order by a desc limit 7",
        "select id, a from i2o where a > 900 order by a limit 5 offset 3",
        "select id, a from i2o where a > 0 order by a desc limit 5",
        "select id, a from i2o order by a limit 4 offset 290",
        "select id, a from i2o where a < 800 and id % 3 = 0 order by a limit 6 offset 2",
        "select id, a, c, d, a * 2 as twice, d::text || '!' as t from i2o where a >= 950 order by a limit 6",
        "select id from i2o where a between 1 and 999 and false order by a limit 3",
        "select id from i2o where a < 300 order by a limit 0",
        "select id from i2o where a between 700 and 710 order by a limit 5 offset 100",
        "select id, b from i2o where e = 2 order by b limit 5",
        "select id, b from i2o where e = 2 and b > 'v0100' order by b desc limit 5",
        "select id, f from i2o where f < 0 order by f limit 3",
        "select id, f from i2o where f > 0 order by f desc limit 3",
        "select p, q from i2o as x(p, q) where q > 980 order by q limit 4",
        "select x.a from i2o x where x.a > 990 order by x.a limit 3",
        "select * from i2o where a > 995 order by a limit 2",
        "create sequence i2o_s",
        "select id, nextval('i2o_s') from i2o where a > 900 order by a limit 2 offset 3",
        "select currval('i2o_s')",
        "prepare i2o_q(int, int) as select id, a, b from i2o where a between $1 and $2 order by a limit 4",
        "execute i2o_q(800, 900)",
        "execute i2o_q(990, 2000)",
        "execute i2o_q(5, 1)",
        "prepare i2o_r(int) as select id, a from i2o where a > $1 order by a desc limit 3 offset 1",
        "execute i2o_r(100)",
        "execute i2o_r(997)",
        "update i2o set a = a + 5000 where id in (2, 3)",
        "delete from i2o where id = 4",
        "execute i2o_r(100)",
        "select id, a from i2o where a > 990 order by a limit 4",
    ]]);
}

/// Aggregates fold each row in as it is read (the rows aren't gathered first), reading only the columns they need:
/// the same counts, sums, averages and groups over many rows, with nulls, negative and the widest integers, rows
/// written before a column was added (which hold its default) and after one was dropped, and a condition on a column
/// no aggregate reads.
#[test]
fn aggregates_over_many_rows_fold_them_as_they_are_read() {
    check(&[&[
        "create table i2a (id int primary key, a int, b text, c bigint, d int)",
        "insert into i2a select g, case when g % 7 = 0 then null else g % 1000 - 500 end, md5(g::text), \
         case when g = 1 then -9223372036854775808 when g = 2 then 9223372036854775807 else g * -3 end, g % 13 \
         from generate_series(1, 20000) g",
        "select count(*), count(a), sum(a), avg(a), min(a), max(a) from i2a",
        "select count(*), min(c), max(c) from i2a",
        "select sum(c) from i2a where id > 2",
        "select d, count(*), sum(a), max(c) from i2a group by d order by d",
        "select count(*), sum(a) from i2a where b like 'a%'",
        "select count(*), sum(d) from i2a where id % 2 = 0",
        "alter table i2a add column e int default 7",
        "insert into i2a (id, a, b, c, d, e) select g, g, 'n', g, g % 13, g % 5 from generate_series(20001, 20500) g",
        "select count(*), sum(e), avg(e), sum(a) from i2a",
        "select e, count(*) from i2a group by e order by e",
        "alter table i2a drop column b",
        "select count(*), sum(a), sum(d), sum(e) from i2a",
        "select d, sum(e) from i2a where a > 0 group by d order by d",
    ]]);
}

/// A few rows found by key (`id IN (...)`) are read as they are found: rows of keys no row has, a key given twice,
/// NULL among them and a condition on another column too, as Postgres answers.
#[test]
fn key_lookups_of_a_few_rows_answer_as_postgres() {
    check(&[&[
        "create table i2k (id int primary key, a int, b text)",
        "insert into i2k select g, g % 10, 'b' || g from generate_series(1, 2000) g",
        "select * from i2k where id in (5, 17, 1999, 4000, 17) order by id",
        "select id, b from i2k where id in (3, 300, null) order by id",
        "select count(*), sum(a) from i2k where id in (1, 2, 3, 4, 5) and a > 2",
        "select b from i2k where id in (10, 20, 30) and b like '%0' order by b",
        "select id from i2k where id not in (1, 2) and id < 5 order by id",
    ]]);
}

// ---- cluster J1: last small fixes before the beta

/// `(outer.c).f` in a LATERAL subquery (or any subquery) of an outer row whose composite column is NULL: the null of
/// the row type, whose fields are null, as Postgres reads it, not a null of text (42809 "column notation .city applied
/// to type text"). A type of another schema, and of public; rows before and after the null one.
#[test]
fn null_composite_outer_columns_keep_their_type_in_subqueries() {
    check(&[&[
        "drop schema if exists j1s cascade",
        "create schema j1s",
        "create type j1s.addr as (street text, city text, zip varchar(10))",
        "create table j1_th (id int, h j1s.addr)",
        "insert into j1_th values (1, row('a', 'b', 'c')), (2, null), (3, row('d', null, 'f'))",
        "select * from j1_th x, lateral (select (x.h).city) l order by id",
        "select * from j1_th x, lateral (select (x.h).city as c, (x.h).zip as z) l order by id",
        "select * from (select id, h from j1_th) q, lateral (select (q.h).city as c) l order by id",
        "select x.id, l.* from j1_th x left join lateral (select (x.h).street as s where (x.h).zip is not null) l on true order by 1",
        "select id, (select (x.h).city) from j1_th x order by id",
        "select id from j1_th x where exists (select 1 where (x.h).city is null) order by id",
        "select * from j1_th x, lateral (select x.h is null as gone, (x.h).street is null as none) l order by id",
        "create type j1_paddr as (street text, city text)",
        "create table j1_tp (id int, h j1_paddr)",
        "insert into j1_tp values (1, null), (2, row('a', 'b'))",
        "select * from j1_tp x, lateral (select (x.h).city) l order by id",
        "select * from j1_tp x cross join lateral (select coalesce((x.h).city, 'none') as c) l order by id",
        "drop table j1_th",
        "drop schema j1s cascade",
    ]]);
}

/// pg_blocking_pids(): none for a backend that waits for nothing, or for a pid that is no backend; NULL for NULL;
/// an integer[] (Studio's Sessions reads it beside pg_stat_activity).
#[test]
fn blocking_pids_of_backends_that_wait_for_nothing() {
    check(&[&[
        "select pg_blocking_pids(pg_backend_pid()), pg_blocking_pids(0), pg_blocking_pids(-1), pg_blocking_pids(null)",
        "select pg_typeof(pg_blocking_pids(1)), cardinality(pg_blocking_pids(1)), pg_blocking_pids('7')",
    ]]);
}

// ---- cluster K3: review findings on PR #122

/// A READ ONLY transaction runs CLUSTER, REINDEX and LOCK TABLE in any mode, as Postgres's does (they don't change
/// what the database holds), and writes temporary tables by a data-changing WITH too; one that writes another
/// table is refused (25006).
#[test]
fn read_only_transactions_run_maintenance_and_write_temporary_tables() {
    check(&[&[
        "create table rom (a int primary key, b int)",
        "create index rom_b on rom (b)",
        "insert into rom values (1, 2), (2, 1)",
        "create temp table rot (a int)",
        "begin read only",
        "cluster rom using rom_b",
        "reindex table rom",
        "lock table rom",
        "lock table rom in share row exclusive mode",
        "with x as (insert into rot values (5) returning a) select * from x",
        "with x as (update rot set a = 6 returning a) select * from x",
        "select * from rot",
        "commit",
        "begin read only",
        "with x as (insert into rom values (5, 5) returning a) select * from x",
        "rollback",
        "begin read only",
        "with x as (select 1) insert into rom select 6, 6 from x",
        "rollback",
        "select * from rom order by a",
        "drop table rot",
    ]]);
}

/// `UPDATE pg_class SET reltuples ...` changes nothing here, but is refused to a role that isn't a superuser as
/// any write to the catalog is.
#[test]
fn planner_statistics_updates_keep_the_catalogs_privileges() {
    check(&[&[
        "drop role if exists k3_pcu",
        "create role k3_pcu",
        "create table pcu (a int)",
        "update pg_class set reltuples = 10 where relname = 'pcu'",
        "set role k3_pcu",
        "update pg_class set reltuples = 10 where relname = 'pcu'",
        "update pg_catalog.pg_class c set relpages = 1 where c.relname = 'pcu'",
        "reset role",
        "drop table pcu",
        "drop role k3_pcu",
    ]]);
}

/// crosstab as tablefunc checks it: the categories' query gives one column of distinct, non-null categories; the
/// output has as many columns as the source and the categories make; categories match by their text; the queries
/// may not change rows; without categories the row name's and the values' types must be the source's. And
/// normal_rand refuses a negative count.
#[test]
fn crosstab_checks_its_queries_as_tablefunc() {
    check(&[&[
        "create extension if not exists tablefunc",
        "create table ct (r text, c text, v int)",
        "insert into ct values ('a', 'x', 1), ('a', 'y', 2), ('b', 'x', 3), ('b', 'z', 4), ('c', 'y', 5)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select c from (values (''x''), (''x''), (''y'')) v(c)') as t(r text, a int, b int, c int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select c from (values (''x''), (null), (''y'')) v(c)') as t(r text, a int, b int, c int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select distinct c from ct order by 1') as t(r text, x int, y int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select distinct c from ct order by 1') as t(r text, x int, y int, z int, w int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select distinct c, 1 from ct order by 1') as t(r text, x int, y int, z int)",
        "select * from crosstab('insert into ct values (''q'', ''x'', 9) returning r, c, v', 'select distinct c from ct order by 1') as t(r text, x int, y int, z int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'insert into ct values (''q'', ''x'', 9) returning c') as t(r text, x int, y int, z int)",
        "select * from crosstab('insert into ct values (''q'', ''x'', 9) returning r, c, v') as t(r text, x int, y int)",
        "select count(*) from ct",
        "select * from crosstab('select r, c, v from ct order by 1', 'select distinct c from ct order by 1') as t(r text, x text, y int, z int)",
        "select * from crosstab('select r, c, v from ct order by 1', 'select distinct c from ct order by 1') as t(r int, x int, y int, z int)",
        "select * from crosstab('select r, c, v from ct order by 1') as t(r text, x text, y int)",
        "select * from crosstab('select r, c, v from ct order by 1') as t(r text, x bigint, y bigint)",
        "select * from crosstab('select r, c, v from ct order by 1') as t(r text, x int, y int)",
        "select * from crosstab('select r, c from ct order by 1') as t(r text, x int, y int)",
        "create table ct2 (r text, c int, v int)",
        "insert into ct2 values ('a', 1, 10), ('a', 2, 20)",
        "select * from crosstab('select r, c, v from ct2 order by 1', 'select x from (values (''01''), (''2'')) v(x)') as t(r text, a int, b int)",
        "select * from crosstab('select r, c, v from ct2 order by 1', 'select x from (values (1::numeric), (2.0)) v(x)') as t(r text, a int, b int)",
        "create table ct3 (r text, e text, c text, v int)",
        "insert into ct3 values ('a', 'e1', 'x', 1), ('a', 'e1', 'y', 2), ('b', 'e2', 'y', 3)",
        "select * from crosstab('select r, e, c, v from ct3 order by 1', 'select distinct c from ct3 order by 1') as t(r text, e text, x int, y int)",
        "select * from crosstab('select r, e, c, v from ct3 order by 1', 'select distinct c from ct3 order by 1') as t(r text, e int, x int, y int)",
        "select * from crosstab('select r, c, v from ct where false', 'select distinct c from ct order by 1') as t(r text, x int)",
        "select * from crosstab('select r, c, v from ct where false', 'select c from ct where false') as t(r text, x int)",
        "select * from crosstab('select r, c, v from ct', 'select c from ct where false') as t(r text, x int)",
        "select * from normal_rand(-1, 0, 1)",
        "select count(*) from normal_rand(0, 0, 1)",
        "select pg_tablespace_location(0), pg_tablespace_location(1663), pg_tablespace_location(1664)",
        "select pg_tablespace_location(999999)",
        "select pg_tablespace_location(null)",
    ]]);
}

/// intarray's operators take an integer[] however it is written (a function's result too), smallint[] and
/// smallint as Postgres coerces them, and nothing else: bigint and bigint[] have no such operator.
#[test]
fn intarray_operators_take_integer_arrays_only() {
    check(&[&[
        "create extension if not exists intarray",
        "select array_append(ARRAY[1], 2) + 3",
        "select coalesce(ARRAY[1], ARRAY[2]) + 4",
        "select array_append(ARRAY[1], 2) - 1, array_append(ARRAY[3], 1) | 2, array_append(ARRAY[1], 2) & ARRAY[2]",
        "select ARRAY[1::bigint]::bigint[] + 2",
        "select ARRAY[1::smallint]::smallint[] + 2",
        "select ARRAY[1]::integer[] + 2::bigint",
        "select ARRAY[1]::integer[] + 2::smallint",
        "select ARRAY[1]::integer[] + ARRAY[2::bigint]",
        "select '{1,2}'::int[] | 3::bigint",
        "select '{1,2}'::int[] & 3",
        "select icount(ARRAY[1, NULL]::integer[])",
        "select ARRAY[1, null]::int[] + 3",
        "select array_length(ARRAY[1, 2], 1) + 1",
    ]]);
}

/// Explicit bounds in an array's text as Postgres 16's array_in reads them: a number as strtol reads it (its
/// tail ignored), wrapped into an int; INT_MAX as a lower bound is too large.
#[test]
fn explicit_array_bounds_read_as_postgres_16() {
    check(&[&[
        "select '[1-2]={7}'::int[]",
        "select '[1:2+]={7,8}'::int[]",
        "select '[+1:2]={7,8}'::int[]",
        "select '[-1:0]={7,8}'::int[]",
        "select '[2147483648:2147483648]={1}'::int[]",
        "select '[2147483647:2147483647]={1}'::int[]",
        "select '[-2147483649:-2147483649]={1}'::int[]",
        "select '[1:-]={7}'::int[]",
        "select '[ 1:2]={7,8}'::int[]",
        "select '[1: 2]={7,8}'::int[]",
        "select '[1:2147483647]={1}'::int[]",
    ]]);
}

/// A typed table: OF a type named with its schema or found on the search_path; it needs USAGE on the type, and
/// the type can't be dropped while the table is there.
#[test]
fn typed_tables_name_and_depend_on_their_type() {
    check(&[&[
        "drop schema if exists k3app cascade",
        "drop role if exists k3_tu",
        "create schema k3app",
        "create type k3app.r as (x int, y text)",
        "create table tt of k3app.r",
        "insert into tt values (1, 'a')",
        "select x, y from tt",
        "drop type k3app.r",
        "create role k3_tu",
        "grant usage, create on schema k3app to k3_tu",
        "revoke usage on type k3app.r from public",
        "set role k3_tu",
        "create table k3app.tu of k3app.r",
        "reset role",
        "grant usage on type k3app.r to k3_tu",
        "set role k3_tu",
        "create table k3app.tu of k3app.r",
        "reset role",
        "drop table k3app.tu",
        "drop table tt",
        "drop type k3app.r",
        "drop owned by k3_tu",
        "drop role k3_tu",
        "create type k3app.r2 as (z int)",
        "set search_path = k3app, public",
        "create table tt2 of r2",
        "select z from k3app.tt2",
        "drop type k3app.r2",
        "drop schema k3app cascade",
    ]]);
}

/// PL/pgSQL's cursors and the session's DECLAREd ones share one namespace, and one PL/pgSQL opened after a
/// savepoint is closed by ROLLBACK TO it.
#[test]
fn plpgsql_cursors_share_the_sessions_names_and_savepoints() {
    check(&[&[
        "create function k3_open(n text) returns refcursor language plpgsql as $$ declare r refcursor := n; begin open r for select 42; return r; end $$",
        "begin",
        "declare c1 cursor for select 1",
        "select k3_open('c1')",
        "rollback",
        "begin",
        "select k3_open('pd')",
        "declare pd cursor for select 1",
        "rollback",
        "begin",
        "savepoint s1",
        "select k3_open('pc')",
        "fetch pc",
        "rollback to savepoint s1",
        "fetch pc",
        "rollback",
        "begin",
        "savepoint s1",
        "select k3_open('pe')",
        "release savepoint s1",
        "savepoint s2",
        "rollback to savepoint s2",
        "fetch pe",
        "rollback",
        "drop function k3_open",
    ]]);
}

/// The cursors DECLAREd in SQL and the ones PL/pgSQL opens are one namespace, as Postgres's portals: OPEN of a name
/// a DECLARE holds is refused (42P03, already in use), as is DECLARE of one an OPEN holds, and FETCH from either side
/// reads the same cursor. A refcursor opened after a savepoint closes when the transaction rolls back to it.
#[test]
fn sql_and_plpgsql_cursors_are_one_namespace() {
    check(&[&[
        "create function cn_fetch(r refcursor) returns int language plpgsql as $$ declare x int; begin fetch r into x; return x; end $$",
        "create function cn_open(n text) returns refcursor language plpgsql as $$ declare r refcursor := n; begin open r for select 10 union all select 20; return r; end $$",
        "begin",
        "declare cn_c cursor for select 1 as x union all select 2",
        "do $$ declare r refcursor := 'cn_c'; begin open r for select 9; end $$",
        "rollback",
        "begin",
        "declare cn_c cursor for select 1 as x union all select 2",
        "select cn_fetch('cn_c')",
        "fetch cn_c",
        "select cn_open('cn_p')",
        "fetch cn_p",
        "select cn_fetch('cn_p')",
        "close cn_p",
        "select cn_open('cn_p')",
        "fetch all cn_p",
        "select name from pg_cursors order by name",
        "declare cn_p cursor for select 1",
        "rollback",
        "begin",
        "declare cn_h cursor with hold for select 5 union all select 6",
        "commit",
        "select cn_fetch('cn_h')",
        "fetch cn_h",
        "do $$ declare r refcursor := 'cn_h'; begin open r for select 9; end $$",
        "close cn_h",
        "begin",
        "select cn_open('cn_k1')",
        "savepoint s",
        "select cn_open('cn_k2')",
        "rollback to s",
        "fetch cn_k1",
        "fetch cn_k2",
        "rollback",
        "begin",
        "select cn_open('cn_k1')",
        "savepoint s",
        "select cn_open('cn_k2')",
        "release s",
        "savepoint s2",
        "fetch cn_k2",
        "rollback to s2",
        "fetch cn_k2",
        "fetch cn_k1",
        "rollback",
        "begin",
        "savepoint s",
        "select cn_open('cn_k4')",
        "savepoint s2",
        "rollback to s",
        "fetch cn_k4",
        "rollback",
    ]]);
}

/// Statistics objects: in a schema that exists; gone with a column their expressions read; following their table
/// and its columns through renames; an owner the role may SET ROLE to; and in the role's lifecycle (DROP ROLE
/// refuses while it owns one, REASSIGN and DROP OWNED take them).
#[test]
fn statistics_objects_follow_their_tables_and_owners() {
    check(&[&[
        "drop schema if exists k3st cascade",
        "drop role if exists k3_so1",
        "drop role if exists k3_so2",
        "create schema k3st",
        "create table k3st.sx (a int, b int)",
        "create statistics k3st.sx1 on (a + 1) from k3st.sx",
        "create statistics k3st.sx2 on a, (b * 2) from k3st.sx",
        "create statistics k3st.sx2b on (b + 1) from k3st.sx",
        "create statistics k3_nosuch.sx3 on a, b from k3st.sx",
        "alter table k3st.sx drop column a",
        "select stxname from pg_statistic_ext where stxrelid = 'k3st.sx'::regclass order by 1",
        "alter table k3st.sx add column a int",
        "create statistics k3st.sx4 on a, b from k3st.sx",
        "alter table k3st.sx rename to sx_r",
        "select stxname, stxrelid::regclass::text from pg_statistic_ext where stxnamespace = 'k3st'::regnamespace order by 1",
        "alter table k3st.sx_r rename column b to bb",
        "select pg_get_statisticsobjdef(oid) from pg_statistic_ext where stxnamespace = 'k3st'::regnamespace order by stxname",
        "create statistics k3st.sx5 on (a + bb) from k3st.sx_r",
        "alter table k3st.sx_r rename column a to aa",
        "select pg_get_statisticsobjdef_columns(oid) from pg_statistic_ext where stxname = 'sx5'",
        "create role k3_so1",
        "create role k3_so2",
        "grant usage, create on schema k3st to k3_so1, k3_so2",
        "alter table k3st.sx_r owner to k3_so1",
        "alter statistics k3st.sx4 owner to k3_so1",
        "set role k3_so1",
        "alter statistics k3st.sx4 owner to k3_so2",
        "create statistics k3st.sx6 on aa, bb from k3st.sx_r",
        "reset role",
        "drop role k3_so1",
        "reassign owned by k3_so1 to k3_so2",
        "select s.stxname, r.rolname from pg_statistic_ext s join pg_roles r on r.oid = s.stxowner where s.stxnamespace = 'k3st'::regnamespace and r.rolname like 'k3%' order by 1",
        "drop owned by k3_so2",
        "select count(*) from pg_statistic_ext where stxnamespace = 'k3st'::regnamespace",
        "drop owned by k3_so1",
        "drop role k3_so1",
        "drop role k3_so2",
        "drop schema k3st cascade",
    ]]);
}

/// Publications follow their tables and columns through renames, refuse a mutable function (a built-in one too)
/// in a row filter, and are in their owner's lifecycle.
#[test]
fn publications_follow_their_tables_and_owners() {
    check(&[&[
        "drop publication if exists k3p",
        "drop schema if exists k3pub cascade",
        "drop role if exists k3_po",
        "create schema k3pub",
        "create table k3pub.pt (a int, b int)",
        "create publication k3p for table k3pub.pt (a, b) where (a > 1)",
        "create publication k3p2 for table k3pub.pt where (random() < 0.5)",
        "create publication k3p3 for table k3pub.pt where (a::float8 < extract(epoch from now()))",
        "create publication k3p4 for table k3pub.pt where (b::text <> gen_random_uuid()::text)",
        "alter table k3pub.pt rename to pt2",
        "select pubname, schemaname, tablename, attnames, rowfilter from pg_publication_tables where pubname = 'k3p'",
        "alter table k3pub.pt2 rename column a to aa",
        "select pubname, schemaname, tablename, attnames, rowfilter from pg_publication_tables where pubname = 'k3p'",
        "create schema k3pub2",
        "alter table k3pub.pt2 set schema k3pub2",
        "select pubname, schemaname, tablename from pg_publication_tables where pubname = 'k3p'",
        "create role k3_po",
        "alter publication k3p owner to k3_po",
        "drop role k3_po",
        "drop owned by k3_po",
        "select count(*) from pg_publication where pubname = 'k3p'",
        "drop role k3_po",
        "drop schema k3pub cascade",
        "drop schema k3pub2 cascade",
    ]]);
}

/// DROP SERVER ... CASCADE by the server's owner drops the foreign tables on it, whoever owns them, as Postgres
/// drops an object's dependents; all at once.
#[test]
fn dropping_a_server_drops_its_foreign_tables_whoever_owns_them() {
    check(&[&[
        "drop foreign data wrapper if exists k3w cascade",
        "drop role if exists k3_fa",
        "drop role if exists k3_fb",
        "create role k3_fa",
        "create role k3_fb",
        "create foreign data wrapper k3w",
        "create server k3s foreign data wrapper k3w",
        "alter server k3s owner to k3_fa",
        "create foreign table k3ft (a int) server k3s",
        "alter foreign table k3ft owner to k3_fb",
        "set role k3_fb",
        "drop server k3s cascade",
        "reset role",
        "select count(*) from pg_class where relname = 'k3ft'",
        "set role k3_fa",
        "drop server k3s cascade",
        "reset role",
        "select count(*) from pg_class where relname = 'k3ft'",
        "select count(*) from pg_foreign_server where srvname = 'k3s'",
        "drop foreign data wrapper k3w",
        "drop role k3_fa",
        "drop role k3_fb",
    ]]);
}

/// Event triggers: CREATE EVENT TRIGGER registers one (pg_event_trigger), and DDL fires it at ddl_command_start, sql_drop
/// and ddl_command_end with its command tag, filtered by WHEN TAG IN; DML fires none, nor does one that is disabled; and
/// what CREATE EVENT TRIGGER refuses. (In a database of the test's own: an event trigger fires for every DDL command of
/// its database, other tests' among them.)
#[test]
fn event_triggers_fire_and_are_listed() {
    let dbname = format!("pgdiff_evt_{}", std::process::id());
    // (each its own statement: CREATE DATABASE can't run in the transaction a batch of them is)
    let admin = Client::connect(&oracle("postgres"), NoTls).and_then(|mut c| {
        c.batch_execute(&format!("drop database if exists {dbname}"))?;
        c.batch_execute(&format!("create database {dbname}"))?;
        Ok(c)
    });
    assert!(
        admin.is_ok() || std::env::var_os("CHRONOS_REQUIRE_ORACLE").is_none(),
        "CHRONOS_REQUIRE_ORACLE is set but database {dbname} couldn't be made: {:?}",
        admin.err()
    );
    let log = "select ev, tag, count(*) from evt_log group by ev, tag order by ev, tag";
    compare_in(
        &dbname,
        &[&[
            "create table evt_log (ev text, tag text)",
            "create function evt_note() returns event_trigger language plpgsql as $$ begin insert into evt_log values (tg_event, tg_tag); end $$",
            "create event trigger evt_start on ddl_command_start execute function evt_note()",
            "create event trigger evt_end on ddl_command_end execute procedure evt_note()",
            "create event trigger evt_drop on sql_drop execute function evt_note()",
            "create event trigger evt_tagged on ddl_command_start when tag in ('create view', 'DROP VIEW') execute function evt_note()",
            "select evtname, evtevent, evtenabled, evttags, evtfoid::regproc from pg_event_trigger order by 1",
            "create table evt_t (a int)",
            "create view evt_v as select a from evt_t",
            "alter table evt_t add column b int",
            "create index evt_i on evt_t (a)",
            "drop view evt_v",
            "insert into evt_t values (1, 2)",
            "update evt_t set b = 3",
            log,
            // disabled: fires no more
            "alter event trigger evt_start disable",
            "select evtname, evtenabled from pg_event_trigger order by 1",
            "delete from evt_log",
            "create table evt_t2 (a int)",
            log,
            // what CREATE EVENT TRIGGER refuses
            "create event trigger evt_x on no_such_event execute function evt_note()",
            "create event trigger evt_x on ddl_command_start when tag in ('no such command') execute function evt_note()",
            "create event trigger evt_x on ddl_command_start when tag in ('create database') execute function evt_note()",
            "create event trigger evt_x on ddl_command_start execute function no_such_function()",
            "create event trigger evt_end on ddl_command_end execute function evt_note()",
            "drop event trigger no_such_trigger",
            "drop event trigger if exists no_such_trigger",
            "drop event trigger evt_start",
            "drop event trigger evt_end",
            "drop event trigger evt_drop",
            "drop event trigger evt_tagged",
            "select count(*) from pg_event_trigger",
            // what only an event trigger's function may call
            "select * from pg_event_trigger_ddl_commands()",
            "select * from pg_event_trigger_dropped_objects()",
        ]],
        false,
    );
    if let Ok(mut c) = admin {
        let _ = c.batch_execute(&format!("drop database if exists {dbname}"));
    }
}
